#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
} Record;

Record* createRecords(int numRecords) {
    int i;
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed!\n");
        return NULL;
    }

    // Initialize the 'offset' array with consecutive integers
    long* offset = (long*)malloc((numRecords + 1) * sizeof(long));
    for (i = 0; i <= numRecords; i++) {
        offset[i] = i;
    }

    // Populate the 'key' array with unique integers
    int* key = (int*)malloc(numRecords * sizeof(int));
    srand(time(NULL));  // Initialize random number generator
    for (i = 0; i < numRecords; i++) {
        do {
            key[i] = rand() % 100 + 1;
        } while (key[i] != findDuplicateKey(key, i));
    }

    // Set the value of each record's 'int' field to a random value
    for (i = 0; i < numRecords; i++) {
        records[i].value = rand() % 100 + 1;
    }

    free(offset);
    return records;
}

void releaseRecords(Record* records, int numRecords) {
    free(records);
}

int findDuplicateKey(int* key, int i) {
    for (int j = 0; j < i; j++) {
        if (key[i] == key[j]) {
            return key[i];
        }
    }
    return -1;
}
