#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_HOSTNAME_LENGTH 256
#define MAX_IP_ADDRESS_LENGTH 16
#define DNS_CACHE_TTL 5 * 60 // 5 minutes

typedef struct {
    char* hostname;
    char* ip_address;
} DNSRecord;

DNSRecord dns_cache[MAX_HOSTNAME_LENGTH];
int dns_cache_index = 0;

// Function to perform DNS resolution and return the IP address in a u_char array
u_char* perform_dns_resolution(char* hostname, int authorized) {
    if (!authorized) {
        printf("Error: Unauthorized access\n");
        return NULL;
    }

    // Check cache for resolved IP
    for (int i = 0; i < dns_cache_index; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0) {
            printf("DNS Cache Hit: %s -> %s\n", hostname, dns_cache[i].ip_address);
            return (u_char*)dns_cache[i].ip_address;
        }
    }

    // Perform DNS resolution
    struct hostent* host = gethostbyname(hostname);
    if (host == NULL) {
        printf("Error: DNS Resolution failed for %s\n", hostname);
        return NULL;
    }

    char* ip_address = inet_ntoa(*((struct in_addr*)host->h_addr));
    u_char* result = (u_char*)malloc(strlen(ip_address) + 1);
    strcpy((char*)result, ip_address);

    // Cache resolved IP
    if (dns_cache_index < MAX_HOSTNAME_LENGTH) {
        dns_cache[dns_cache_index].hostname = hostname;
        dns_cache[dns_cache_index].ip_address = result;
        dns_cache_index++;
    }

    printf("DNS Resolution: %s -> %s\n", hostname, ip_address);

    return result;
}

// Function to handle asynchronous DNS resolution
void* perform_dns_resolution_async(char* hostname, void (*callback)(u_char*)) {
    pthread_t thread;

    // Create a new thread for DNS resolution
    if (pthread_create(&thread, NULL, (void*)perform_dns_resolution, (void*)hostname) != 0) {
        printf("Error: Unable to create thread\n");
        return NULL;
    }

    // Set the callback function
    pthread_setcanceltype(PTHREAD_CANCEL_ENABLE, NULL);
    pthread_setcancelstate(PTHREAD_CANCEL_ENABLE, NULL);

    return &thread;
}

void dns_resolution_callback(u_char* ip_address) {
    printf("DNS Resolution Callback: %s\n", ip_address);
}
