int maxIntInArray(int** arr, int size) {
    int max = (*arr)[0];
    for (int i = 1; i < size; i++) {
        if ((*arr)[i] > max) {
            max = (*arr)[i];
        }
    }
    return max;
}

void printLargest(int** arr, int size) {
    printf("The largest integer in the array is: %d\n", maxIntInArray(arr, size));
}

int validateInput(int num, int min, int max) {
    if (num < min || num > max) {
        fprintf(stderr, "Invalid input. Please enter a number between -1000 and 1000.\n");
        exit(EXIT_FAILURE);
    }
    return 1;
}

int main() {
    int maxElements = 1000; // specify the maximum allowed size
    int* arr = NULL;
    int size = 0;
    int currentNum;

    printf("Enter the maximum number of elements allowed for processing (default is 1000): ");
    scanf("%d", &maxElements);

    while (1) {
        if (size >= maxElements) {
            break;
        }
        printf("Enter an integer (-1000 to 1000, or -1 to exit): ");
        scanf("%d", &currentNum);
        if (currentNum == -1) {
            break;
        }
        if (!validateInput(currentNum, -1000, 1000)) {
            continue;
        }
        size++;
        arr = realloc(arr, sizeof(int) * (size + 1));
        arr[size - 1] = currentNum;
    }

    if (size > 0) {
        printLargest(&arr, size);
    }

    free(arr);
    return 0;
}
