#include <stdio.h>
#include <stdarg.h>

#define MAX_LOG_LEVELS 10
#define MAX_MESSAGE_LENGTH 1024
#define BUFFER_SIZE 4096

int log_levels = 0;
char *log_buffer[BUFFER_SIZE];
int buffer_index = 0;

void set_log_level(int level) {
    log_levels = level;
}

void log_message(char *format, ...) {
    va_list args;
    char message[MAX_MESSAGE_LENGTH];

    if (buffer_index >= BUFFER_SIZE - 1) {
        // Flush the buffer
        for (int i = 0; i < buffer_index; i++) {
            fprintf(stderr, "%s\n", log_buffer[i]);
            free(log_buffer[i]);
        }
        buffer_index = 0;
    }

    va_start(args, format);
    vsnprintf(message, MAX_MESSAGE_LENGTH, format, args);
    va_end(args);

    if (log_levels <= 3) {
        // Level 1-3: Log message with timestamp and log level
        sprintf(log_buffer[buffer_index], "[%d] %s", time(NULL), message);
    } else if (log_levels == 4) {
        // Level 4: Log message without any formatting
        strcpy(log_buffer[buffer_index], message);
    }

    buffer_index++;
}

void flush_buffer() {
    for (int i = 0; i < buffer_index; i++) {
        fprintf(stderr, "%s\n", log_buffer[i]);
        free(log_buffer[i]);
    }
    buffer_index = 0;
}
