int validate_oauth_token(const char *json_string) {
    json_object* token = json_object_from_string(json_string);
    if (!token || !json_object_object_get_ex(token, "access_token", &json_object)) {
        return 0;
    }

    int expires_in = json_object_get_int(json_object);

    if (expires_in <= 0) {
        return 0;
    }

    const char* token_type = json_object_get_string(json_object);
    if (strcmp(token_type, "Bearer") != 0) {
        return 0;
    }

    json_object* refresh_token = json_object_object_get_ex(token, "refresh_token", &json_object);
    if (refresh_token && json_object_get_type(refresh_token) == json_type_null)
        json_object_put(refresh_token);

    json_object_put(token);
    return 1;
}
