        StringBuilder report = new StringBuilder();

        try {
            String pokemonName = getPokemonName(pokemon);
            String pokemonType = getPokemonType(pokemon);

            report.append("Pokémon Name: ").append(pokemonName).append("\n");
            report.append("Type: ").append(pokemonType).append("\n\n");

            switch (pokemonType) {
                case "Fire":
                    report.append("Weaknesses: Water, Rock").append("\n");
                    report.append("Strengths: Fire, Bug, Steel, Fairy").append("\n");
                    break;
                case "Water":
                    report.append("Weaknesses: Electric, Grass, Ice").append("\n");
                    report.append("Strengths: Water, Fire, Bug, Steel, Fairy").append("\n");
                    break;
                case "Grass":
                    report.append("Weaknesses: Fire, Bug, Ice, Poison, Flying").append("\n");
                    report.append("Strengths: Grass, Bug, Ground, Electric, Fighting, Fairy").append("\n");
                    break;
                default:
                    report.append("Unknown type. Cannot determine weaknesses and strengths.");
            }

            report.append("\nCompatibility Report:\n");

            for (String partnerType : partnerTypes) {
                if (isCompatible(pokemonType, partnerType)) {
                    report.append(partnerType).append(" is compatible with ").append(pokemonName).append("\n");
                } else {
                    report.append(partnerType).append(" is not compatible with ").append(pokemonName).append("\n");
                }
            }
        } catch (Exception e) {
            report.append("Error: ").append(e.getMessage());
        }

        return report.toString();
    }

