        // implementation of library function to retrieve Pokemon type
    }

    private boolean isCompatible(String pokemonType, String partnerType) {
        if (pokemonType.equals(partnerType)) {
            return true;
        }

        switch (pokemonType) {
            case "Fire":
                if (partnerType.equals("Water") || partnerType.equals("Rock")) {
                    return false;
                }
                break;
            case "Water":
                if (partnerType.equals("Electric") || partnerType.equals("Grass")) {
