#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    const char* name;
    void (*function)(void);
    void* parameters;
} Algorithm;

Algorithm* getAvailableAlgorithms() {
    // Load platform-specific configuration file
    FILE* file = fopen("algorithms.cfg", "r");
    if (file == NULL) {
        return NULL;  // No configuration file, fallback to default algorithms
    }

    // Parse configuration file and create list of available algorithms
    Algorithm* algorithms = (Algorithm*)malloc(10 * sizeof(Algorithm));  // Initialize with a reasonable size
    int algorithmCount = 0;

    char line[256];
    while (fgets(line, 256, file)) {
        // Parse line to extract algorithm name and function pointer
        const char* nameStart = strstr(line, "name=");
        const char* funcStart = strstr(line, "function=");
        if (!nameStart || !funcStart) continue;

        Algorithm newAlgorithm;
        newAlgorithm.name = nameStart + 5;  // Skip "name="
        newAlgorithm.function = NULL;  // Fill in later

        // Load algorithm function and parameters
        FILE* funcFile = fopen(funcStart + 9, "r");  // Skip "function="
        if (funcFile == NULL) continue;

        fseek(funcFile, 0, SEEK_END);
        size_t size = ftell(funcFile);
        char* code = malloc(size + 1);
        fread(code, 1, size, funcFile);
        code[size] = '\0';
        fclose(funcFile);

        // Compile and load algorithm function
        void (*algorithmFunction)(void) = (void (*)(void))dlopen(code, RTLD_NOW | RTLD_LOCAL);
        if (!algorithmFunction) {
            free(code);
            continue;
        }
        newAlgorithm.function = algorithmFunction;
        free(code);

        algorithms[algorithmCount] = &newAlgorithm;
        algorithmCount++;
    }

    fclose(file);
    free(algorithms);
    return NULL;  // No algorithms found
}
