void insertAfter(std::vector<std::unique_ptr<int>>& vec, int target) {
    for (auto it = vec.begin(); it != vec.end(); ++it) {
        if (*it.get() == target) {
            vec.insert(it + 1, std::make_unique<int>(target));
            return;
        }
    }
    vec.push_back(std::make_unique<int>(target));
}
