public bool BulkInsertRecords(List<YourRecordClass> records, string connectionString, string tableName)
{
    try
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            connection.Open();
            using (SqlBulkCopy bulkCopy = new SqlBulkCopy(connection))
            {
                bulkCopy.CommandText = tableName;
                bulkCopy.WriteToServer(new DataTable());
                int retryCount = 3; // specify the number of retries here
                for (int i = 0; i < records.Count; i += 10000) // batch size
                {
                    DataTable table = new DataTable();
                    for (int j = i; j <= Math.Min(i + 10000 - 1, records.Count - 1); j++)
                    {
                        DataRow row = table.NewRow();
                        row["column1"] = records[j].Property1;
                        row["column2"] = records[j].Property2;
                        // map your record properties to the column names
                        table.Rows.Add(row);
                    }
                    bulkCopy.WriteToServer(table);
                }
            }
        }
    }
    catch (SqlException ex)
    {
        for (int i = 0; i < retryCount; i++)
        {
            try
            {
                // retry the insertion operation
                // you may need to re-execute the code within this block
                return true;
            }
            catch (SqlException)
            {
                if (i == retryCount - 1) // log the error after max retries
                {
                    // log the exception
                    throw;
                }
            }
        }
    }
    return false;
}
