class Resource(BaseModel):
    id: int
    data: str

async def update_resource(id: int, updated_data: Resource):
    # validate updated data using a separate validation service
    await validate_data(updated_data)

    try:
        # update the resource in the collection
        resources.update({id: updated_data})
    except KeyError:
        raise HTTPException(status_code=404, detail="Resource not found")

async def delete_resource(id: int):
    if id not in resources:
        return {"message": "Resource not found"}

    try:
        # delete the resource from the collection
        del resources[id]
        await clean_up_secondary_resources(id)
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

    return {"message": "Resource deleted successfully"}

async def clean_up_secondary_resources(id: int):
    # trigger a background process to clean up associated secondary resources
    # ...

@app.put("/resources/{id}")
async def update_resource_handler(id: int, updated_data: Resource):
    await update_resource(id, updated_data)
    return JSONResponse(content={"message": "Resource updated successfully"}, media_type="application/json")

@app.delete("/resources/{id}")
async def delete_resource_handler(id: int):
    response = await delete_resource(id)
