using System;
using System.Collections.Generic;
using System.Xml.Linq;

public class XmlProcessor
{
    public List<object> ProcessElements(XDocument xml, string nodeName, Func<XElement, object> processor)
    {
        var results = new List<object>();

        if (xml == null || xml.Root == null) throw new ArgumentException("Invalid XML document");

        foreach (var element in xml.Descendants(nodeName))
        {
            try
            {
                var result = processor(element);
                results.Add(result);
            }
            catch (Exception ex)
            {
                throw new Exception($"Error processing '{nodeName}' element: {ex.Message}");
            }
        }

        if (results.Count == 0) throw new ArgumentException($"No elements found with name '{nodeName}'");
        if (results.Count > 1) throw new ArgumentException($"More than one element found with name '{nodeName}'");

        return results;
    }
}
