import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class Main {

    private static final int LOG_INTERVAL = 100; // Adjust this value to suit your logging needs

    public List<String> processBatch(List<String> strings) {
        List<String> hashes = new ArrayList<>();
        MessageDigest md5;
        try {
            md5 = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            return null; // Handle exception as needed
        }

        for (int i = 0; i < strings.size(); i++) {
            String s = strings.get(i);
            if (s == null || s.isEmpty()) {
                hashes.add(null); // or an empty string, depending on your requirements
                continue;
            }
            byte[] hashBytes = md5.digest(s.getBytes());
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            hashes.add(sb.toString());

            if ((i + 1) % LOG_INTERVAL == 0) {
                System.out.println("Processed " + (i + 1) + " strings...");
            }
        }

        return hashes;
    }
}']

