function user_request_handler($request) {
    $response = array('message' => '', 'token' => '');

    if (!isset($request['sub_action']) || empty($request['sub_action'])) {
        $request['sub_action'] = '';
    }

    switch ($request['sub_action']) {
        case 'create':
            $user_data = array(
                'id' => '',
                'name' => '',
                'email' => '',
                'password' => ''
            );

            foreach (array('name', 'email', 'password') as $field) {
                if (!empty($request[$field])) {
                    $user_data[$field] = $request[$field];
                }
            }

            if (!Validate::email($user_data['email'])) {
                $response['message'] = 'error';
                $response['details'] = 'Invalid email address.';
                return json_encode($response);
            }

            if (!Validate::password($user_data['password'])) {
                $response['message'] = 'error';
                $response['details'] = 'Password must be at least 8 characters long and contain at least one uppercase letter, one lowercase letter, and one digit.';
                return json_encode($response);
            }

            if (SessionManager::is_rate_limited()) {
                $response['message'] = 'error';
                $response['details'] = 'Rate limit exceeded. Please try again later.';
                return json_encode($response);
            }

            if (User::find_by_email($user_data['email'])) {
                $response['message'] = 'error';
                $response['details'] = 'Email address already in use.';
                return json_encode($response);
            }

            $token = SessionManager::create_token();
            SessionManager::set_session_token($token);

            User::save($user_data, $token);

            $response['message'] = 'success';
            $response['token'] = $token;
            break;
        case 'update':
            if (!isset($request['id'])) {
                $response['message'] = 'error';
                $response['details'] = 'Invalid request. ID required for updates.';
                return json_encode($response);
            }

            $user_data = array(
                'name' => '',
                'email' => ''
            );

            foreach (array('name', 'email') as $field) {
                if (!empty($request[$field])) {
                    $user_data[$field] = $request[$field];
                }
            }

            if (!Validate::name($user_data['name'])) {
                $response['message'] = 'error';
                $response['details'] = 'Invalid name. Name must be between 2 and 50 characters long.';
                return json_encode($response);
            }

            if (User::find_by_email($user_data['email']) && User::find_by_email($user_data['email']) !== $request['id']) {
                $response['message'] = 'error';
                $response['details'] = 'Email address already in use.';
                return json_encode($response);
            }

            if (User::update($request['id'], $user_data)) {
                $token = SessionManager::create_token();
                SessionManager::set_session_token($token);

                $response['message'] = 'success';
                $response['token'] = $token;
            } else {
                $response['message'] = 'error';
                $response['details'] = 'Failed to update user account.';
            }
            break;
        case 'delete':
            if (!isset($request['id'])) {
                $response['message'] = 'error';
                $response['details'] = 'Invalid request. ID required for deletion.';
                return json_encode($response);
            }

            User::delete($request['id']);

            $response['message'] = 'success';
            break;
        default:
            $response['message'] = 'error';
            $response['details'] = 'Invalid sub-action.';
    }

    return json_encode($response);
}
