import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class StateLoader {
    private static final Lock lock = new ReentrantLock();
    private static final int MAX_ATTEMPTS = 3;
    private static final String LOG_TAG = "StateLoader";

    public MoSTState loadStateFromFile(String filePath) {
        try {
            for (int attempt = 0; attempt <= MAX_ATTEMPTS; attempt++) {
                lock.lock();
                try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filePath))) {
                    MoSTState state = (MoSTState) ois.readObject();
                    lock.unlock();
                    return state;
                } catch (ClassNotFoundException e) {
                    Log.e(LOG_TAG, "Invalid file format", e);
                } catch (IOException e) {
                    if (attempt < MAX_ATTEMPTS) {
                        // Wait for a short period before retrying
                        Thread.sleep(100);
                    } else {
                        Log.e(LOG_TAG, "Failed to load state after maximum attempts", e);
                    }
                }
            }
        } catch (Exception e) {
            Log.e(LOG_TAG, "Unexpected error while loading state", e);
        } finally {
            lock.unlock();
        }
        return null;
    }
}
