const fs = require('fs');
const path = require('path');

function readAsyncFile(filePath) {
  return new Promise((resolve, reject) => {
    const isValidPath = path.isAbsolute(filePath);
    if (!isValidPath || !fs.existsSync(filePath)) {
      reject(`Error: File not found at ${filePath}`);
      return;
    }

    fs.readFile(filePath, (err, data) => {
      if (err) {
        reject(err);
        return;
      }
      resolve(data.toString());
    });
  });
}

module.exports = readAsyncFile;
