["```
function runTests(moduleName, testLabel, maxConcurrency) {
  const blueslipMock = require('blueslip').mock;

  async function runTest(label, cb) {
    try {
      console.log(`Running test ${label}...`);
      await cb(blueslipMock);
      console.log(`Test ${label} passed!`);
    } catch (err) {
      console.error(`Test ${label} failed:`, err);
    } finally {
      blueslipMock.reset();
    }
  }

  async function runTestsConcurrently(tests, concurrency) {
    const results = [];
    let currentConcurrency = 0;

    function queueTest(test) {
      return new Promise((resolve, reject) => {
        setTimeout(() => {
          resolve(runTest(test.label, test.cb));
        }, 0);
      });
    }

    async function runConcurrentTests() {
      while (currentConcurrency < concurrency) {
        let testToRun = tests.shift();

        if (!testToRun) break;

        currentConcurrency++;
        queueTest(testToRun)
          .then((result) => results.push(result))
          .catch((err) => {
            console.error('Error running concurrent tests:', err);
          })
          .finally(() => {
            currentConcurrency--;
          });
      }
    }

    await runConcurrentTests();
    return results;
  }

  try {
    const module = require(moduleName);
    const testFunctions = Object.values(module).filter((func) => typeof func === 'function');

    if (testFunctions.length === 0) {
      console.error(`No tests found in ${moduleName} module.`);
      return;
    }

    await runTestsConcurrently(testFunctions.map(({ label, cb }, index) => ({
      label: `${moduleName}:${index}`,
      cb,
    })), maxConcurrency);

    console.log(`${moduleName} testing completed successfully!`);
  } catch (err) {
    console.error(`Error loading ${moduleName} module:`, err);
  }
}
