function extractBibleBookNames(text) {
  const bibleBooks = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', 'Joshua', 'Judges', 'Ruth', '1Samuel', '2Samuel', '1Kings', '2Kings', '1Chronicles', '2Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms', 'Proverbs', 'Ecclesiastes', 'SongOfSolomon', 'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'];
  const chapterRegex = /\s*(\w+)\s*\d+:\d+\s*/;
  const bookRegex = /\b(\w+)\b/;
  let bookCounts = {};

  for (let match of text.matchAll(chapterRegex)) {
    const bookNameMatch = match[1].match(bookRegex);
    if (bookNameMatch && bibleBooks.includes(bookNameMatch[0])) {
      bookNameMatch.forEach(name => {
        bookCounts[name] = (bookCounts[name] || 0) + 1;
      });
    }
  }

  return bookCounts;
}
