function streamCollector(stream) {
  const data = [];
  let paused = false;

  stream.on('data', (chunk) => {
    if (!paused) {
      data.push(chunk);
    }
  });

  stream.on('pause', () => {
    paused = true;
  });

  stream.on('resume', () => {
    paused = false;
    stream.resume();
  });

  function collectData() {
    return new Promise((resolve, reject) => {
      const graph = require('graphlib');
      const g = new graph.Graph();

      for (let i = 0; i < 10; i++) {
        const vertex = { id: `v${i}`, label: Math.random().toString(36).substr(2) };
        g.addVertex(vertex.id, vertex);
      }

      for (let i = 0; i < 10; i++) {
        for (let j = i + 1; j < 10; j++) {
          const edge = { id: `e${i}-${j}`, weight: Math.random() };
          g.addEdge(edge.id, `v${i}`, `v${j}`, edge);
        }
      }

      g.write('dot', 'output.dot');

      resolve();
    });
  }

  function saveData() {
    return new Promise((resolve, reject) => {
      // implement your graph database operations here
      // and add the collected data to the graph
      // for example:
      const db = require('graphdb');
      db.addVertices(data);
      db.addEdge('edge1', 'vertex1', 'vertex2');

      resolve();
    });
  }

  stream.on('end', () => {
    collectData().then(saveData).catch((err) => console.error(err));
  });

  return { start: () => stream.start(), pause: () => stream.pause(), resume: () => stream.resume() };
}
