["```
function copyBytes(chunks, offset, size) {
  if (!Array.isArray(chunks)) throw new Error('Invalid input: chunks must be an array');
  if (typeof offset !== 'number' || offset < 0) throw new Error('Invalid input: offset must be a non-negative integer');
  if (typeof size !== 'number') throw new Error('Invalid input: size must be a number');
  if (size < 0) throw new Error('Invalid input: size cannot be negative');

  const maxBufferSize = 1024 * 1024; // configurable maximum buffer size
  let outputBuffer = Buffer.alloc(0);
  const configuredMaxSize = process.env.COPY_BYTES_MAX_SIZE || maxBufferSize;

  for (const chunk of chunks) {
    if (!Buffer.isBuffer(chunk)) throw new Error('Invalid input: chunks must be Buffers');

    if (offset >= chunk.length) continue; // skip this chunk since it's not needed
    const end = Math.min(offset + size, chunk.length);
    outputBuffer = Buffer.concat([outputBuffer, chunk.slice(offset, end)]);

    offset -= end - chunk.length;
    size -= end - chunk.length;

    if (size <= 0) break; // no more bytes to copy

    if (outputBuffer.length > configuredMaxSize) {
      const oldBuffer = outputBuffer;
      outputBuffer = Buffer.alloc(configuredMaxSize);
      outputBuffer.copy(oldBuffer, 0, Math.max(0, oldBuffer.length - configuredMaxSize));
    }
  }

  if (process.env.DEBUG_COPY_BYTES === 'true') console.log(`Copied ${size} bytes`);

  return outputBuffer;
}
