['```
function traverseDOMTree(selector, callback) {
  const traversalQueue = [];
  const resultQueue = [];

  function processNodes(parentNode, nodes, selector) {
    if (!nodes.length) return;

    for (const node of nodes) {
      if (node.nodeType === Node.ELEMENT_NODE && matchesSelector(node, selector)) {
        resultQueue.push(node);
      }

      if (node.childNodes.length > 0) {
        traversalQueue.push({ parentNode, childNodes: node.childNodes });
      }
    }

    callback();
  }

  function matchesSelector(node, selector) {
    return node.classList.contains(selector.split(":")[1]);
  }

  async function processTraversalQueue() {
    while (traversalQueue.length > 0) {
      const { parentNode, childNodes } = traversalQueue.shift();

      await processNodes(parentNode, childNodes, selector);
    }
  }

  await processTraversalQueue();

  return resultQueue;
}

module.exports = traverseDOMTree;
