class ModuleLoader {
  constructor() {
    this.modules = {};
    this.loadOrder = [];
    this.dependencies = {};
  }

  addModule(name, dependencies) {
    this.modules[name] = { dependencies: [], script: null };
    if (dependencies) {
      this.dependencies[dependencies] = this.modules[dependencies];
    }
  }

  setLoadOrder(order) {
    this.loadOrder = order;
  }

  loadModules() {
    return new Promise((resolve, reject) => {
      const loader = async () => {
        for (const moduleName of this.loadOrder) {
          await this.loadModule(moduleName);
        }
        resolve();
      };
      loader().catch(reject);
    });
  }

  loadModule(name) {
    return new Promise((resolve, reject) => {
      if (!this.modules[name].script) {
        const script = document.createElement('script');
        script.src = `modules/${name}.js`;
        document.head.appendChild(script);

        script.onload = () => {
          this.modules[name].script = null;
          resolve();
        };

        script.onerror = (err) => {
          reject(new Error(`Failed to load module: ${name}`));
        };
      } else {
        resolve();
      }
    });
  }

  executeModules() {
    return new Promise((resolve, reject) => {
      this.loadModules().then(() => {
        for (const moduleName of this.loadOrder) {
          if (!this.modules[moduleName].script) {
            throw new Error(`Module ${moduleName} not loaded`);
          }
        }
        resolve();
      }).catch(reject);
    });
  }

  run() {
    return this.executeModules().then(() => {
      // Run modules here
    }).catch((err) => {
      console.error(err);
    });
  }
}

// Example usage:
const loader = new ModuleLoader();

loader.addModule('module1', ['dependency1']);
loader.addModule('module2');
loader.setLoadOrder(['module2', 'module1']);

loader.run();
