['```java
import java.util.*;

public int processUserInteractions(List<Map<String, Object>> interactions) {
    Map<String, Map<String, Long>> sessions = new HashMap<>();
    long totalProcessingTime = 0;

    for (Map<String, Object> interaction : interactions) {
        String userId = (String) interaction.get("user_id");
        long timestamp = (Long) interaction.get("timestamp");

        if (!sessions.containsKey(userId)) {
            Map<String, Long> session = new HashMap<>();
            sessions.put(userId, session);
        }

        Map<String, Long> userSession = sessions.get(userId);

        if (!userSession.containsKey(timestamp)) {
            userSession.put(timestamp, timestamp);
        } else {
            long lastTimestamp = userSession.get(userSession.size() - 1);
            long idleTime = timestamp - lastTimestamp;
            userSession.put(idleTime, idleTime);

            if (idleTime > 30000L) { // 30 seconds
                Map<String, Long> sessionSummary = new HashMap<>();
                sessionSummary.put("start", userSession.get(0));
                sessionSummary.put("end", userSession.size() - 1);
                sessionSummary.put("duration", userSession.size());
                sessions.put(userId, sessionSummary);

                userSession.clear();
            }
        }

        totalProcessingTime += System.currentTimeMillis();
    }

    int totalSessions = sessions.values().stream()
        .filter(map -> map instanceof Map)
        .mapToInt(map -> (int) ((Map<String, Long>) map).size())
        .sum();

    long sumDuration = sessions.values().stream()
        .filter(map -> map instanceof Map)
        .mapToInt(map -> (int) ((Map<String, Long>) map).getOrDefault("duration", 0))
        .sum();

    System.out.println("Processing time: " + totalProcessingTime);
    return new Object[]{totalSessions, sumDuration / (double) totalSessions};
}']

