import java.io.IOException;
import java.net.URI;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.LinkedBlockingQueue;

public class ConnectionPool {
    private final int poolSize;
    private final URI remoteAddress;
    private final Selector selector;
    private final List<ChannelWrapper> availableChannels = new ArrayList<>();
    private final LinkedBlockingQueue<ChannelWrapper> inactiveChannels = new LinkedBlockingQueue<>();

    public ConnectionPool(int poolSize, URI remoteAddress) {
        this.poolSize = poolSize;
        this.remoteAddress = remoteAddress;
        this.selector = Selector.open();
        for (int i = 0; i < poolSize; i++) {
            ChannelWrapper channelWrapper = new ChannelWrapper(Selector.open(), remoteAddress);
            availableChannels.add(channelWrapper);
            channelWrapper.register(selector, SelectionKey.OP_CONNECT);
        }
    }

    public void connect() throws IOException {
        while (!availableChannels.isEmpty()) {
            ChannelWrapper channelWrapper = availableChannels.remove(0);
            channelWrapper.connect();
        }
    }

    public void close() {
        selector.wakeup();
        try {
            selector.close();
        } catch (IOException e) {
            // handle exception
        }
    }

    private class ChannelWrapper {
        private final NioChannel nioChannel;
        private boolean connected;

        public ChannelWrapper(Selector selector, URI remoteAddress) throws IOException {
            this.nioChannel = new NioChannel(selector, remoteAddress);
        }

        public void register(Selector selector, int ops) {
            try {
                nioChannel.register(selector, ops);
            } catch (IOException e) {
                // handle exception
            }
        }

        public void connect() throws IOException {
            try {
                nioChannel.connect();
                connected = true;
            } catch (IOException e) {
                // handle exception
                availableChannels.add(this);
                return;
            }
        }
    }

    private class NioChannel {
        private final SocketChannel socketChannel;

        public NioChannel(Selector selector, URI remoteAddress) throws IOException {
            this.socketChannel = SocketChannel.open();
            socketChannel.configureBlocking(false);
            socketChannel.connect(new InetSocketAddress(remoteAddress.getHost(), remoteAddress.getPort()));
        }
    }
}
