public class ThemeCacheManager {
    private Map<String, Bitmap> themeCache = new HashMap<>();
    private File cacheRootDirectory;
    private String defaultThemeDirectoryName;

    public ThemeCacheManager(String defaultThemeDirectoryName) {
        this.defaultThemeDirectoryName = defaultThemeDirectoryName;
        initializeDefaultThemeCache();
    }

    private void initializeDefaultThemeCache() {
        if (!isDefaultThemeCacheInitialized()) {
            File defaultThemeDirectory = new File(cacheRootDirectory, defaultThemeDirectoryName);
            if (!defaultThemeDirectory.exists()) {
                defaultThemeDirectory.mkdir();
            }
        }
    }

    public Bitmap getBitmap(String themeName) {
        return themeCache.computeIfAbsent(themeName, this::loadBitmap);
    }

    private Bitmap loadBitmap(String themeName) {
        File bitmapFile = new File(cacheRootDirectory, themeDirectoryName() + "/" + themeName + ".png");
        if (!bitmapFile.exists()) {
            // handle missing or corrupted file
            return null;
        }
        try (InputStream is = new FileInputStream(bitmapFile)) {
            Bitmap bitmap = BitmapFactory.decodeStream(is);
            return bitmap;
        } catch (IOException e) {
            // handle loading error
            return null;
        } finally {
            if (bitmap != null) {
                themeCache.put(themeName, bitmap);
            }
        }
    }

    private String themeDirectoryName() {
        return defaultThemeDirectoryName == null ? "default" : defaultThemeDirectoryName;
    }

    public void recycleBitmaps() {
        for (Bitmap bitmap : themeCache.values()) {
            if (bitmap != null) {
                bitmap.recycle();
                bitmap = null;
            }
        }
    }

    private boolean isDefaultThemeCacheInitialized() {
        return cacheRootDirectory != null && defaultThemeDirectoryName != null;
    }

    public void setCacheRootDirectory(File cacheRootDirectory) {
        this.cacheRootDirectory = cacheRootDirectory;
        initializeDefaultThemeCache();
    }

    public void setDefaultThemeDirectoryName(String defaultThemeDirectoryName) {
        this.defaultThemeDirectoryName = defaultThemeDirectoryName;
        initializeDefaultThemeCache();
    }
}
