class EnvironmentManager {
    private $config;

    public function __construct($configFile = 'environment.config.php') {
        $this->loadConfig($configFile);
    }

    public function getEnvironmentVariable($name) {
        return isset($this->config[$name]) ? $this->config[$name] : null;
    }

    private function loadConfig($file) {
        if (file_exists($file)) {
            $this->config = require $file;
        } else {
            throw new Exception("Configuration file not found: $file");
        }
    }
}

class DynamicLoader {
    public function __construct(EnvironmentManager $environmentManager) {
        $this->environmentManager = $environmentManager;
    }

    public function loadClient($clientName, $serviceName) {
        $config = $this->environmentManager->getEnvironmentVariable("clients.{$clientName}.{$serviceName}");

        if (empty($config)) {
            throw new Exception("Client configuration not found for service: $serviceName");
        }

        return new $config['class']($config);
    }
}

class APIClientFactory {
    public function createAPIClient($clientId, $serviceName) {
        $loader = new DynamicLoader(new EnvironmentManager());
        return $loader->loadClient($clientId, $serviceName);
    }
}

