function updateUserProfile($userId) {
    $apiUrls = array(
        'email' => 'https://email-api.com/users/'.$userId.'/update',
        'phone' => 'https://phone-api.com/numbers/'.$userId,
        'subscription' => 'https://subscription-api.com/statuses/'.$userId
    );

    try {
        // Start transaction
        $pdo = new PDO('mysql:host=localhost;dbname=database', 'user', 'password');
        $pdo->beginTransaction();

        foreach ($apiUrls as $key => $url) {
            $ch = curl_init($url);
            curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
            curl_setopt($ch, CURLOPT_MAXREDIRS, 3);
            curl_setopt($ch, CURLOPT_TIMEOUT, 5);

            do {
                $response = json_decode(curl_exec($ch), true);
                curl_close($ch);

                if ($response['status'] === 'error') {
                    // Handle error, log and retry
                    logError('Failed to update '. $key . ' for user ' . $userId);
                    sleep(5); // Rate limit
                    continue;
                }
            } while (false);
        }

        // Commit transaction
        $pdo->commit();

        return 'User profile updated successfully';
    } catch (\Exception $e) {
        // Rollback transaction on error
        $pdo->rollBack();
        logError('Failed to update user profile: '. $e->getMessage());
        return 'Update failed';
    }
}
