import jwt
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime, timedelta
from functools import wraps
from itsdangerous import URLSafeTimedSerializer
from flask_caching import Cache

app = Flask(__name__)
app.config["SQLALCHEMY_DATABASE_URI"] = "sqlite:///users.db"
db = SQLAlchemy(app)

# define the serializer and secret key for token generation
s = URLSafeTimedSerializer("supersecretkey")

# create a cache to store user data
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

# rate limiting decorator
def ratelimit(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if "user_id" not in request.headers:
            return jsonify({"error": "Unauthorized"}), 401
        user_id = int(request.headers["user_id"])
        cache_hit = cache.get(f"user_{user_id}_requests")
        if cache_hit:
            requests_made = int(cache_hit)
        else:
            requests_made = 0
        if requests_made >= 5:
            return jsonify({"error": "Rate limit exceeded"}), 429
        response = func(*args, **kwargs)
        new_requests_made = requests_made + 1
        cache.set(f"user_{user_id}_requests", str(new_requests_made), timeout=60)  # reset after 1 minute
        return response
    return wrapper

@app.route('/login', methods=['POST'])
@ratelimit
def login():
    data = request.get_json()
    if not data or "username" not in data or "password" not in data:
        return jsonify({"error": "Invalid request"}), 400
    username = data["username"]
    password = data["password"]
    user = User.query.filter_by(username=username).first()
    if user and user.check_password(password):
        token = s.dumps({'user_id': user.id}).decode('utf-8')
        return jsonify({"token": token}), 200
    else:
        return jsonify({"error": "Invalid username or password"}), 401

@app.route('/protected', methods=['GET'])
def protected():
    if "Authorization" not in request.headers:
        return jsonify({"error": "Unauthorized"}), 401
    token = request.headers["Authorization"].split()[1]
    try:
        user_id = s.loads(token, max_age=3600).get('user_id')
    except jwt.ExpiredSignatureError:
        return jsonify({"error": "Token has expired. Please refresh."}), 401
    except jwt.InvalidSignatureError:
        return jsonify({"error": "Invalid token"}), 401
