<?php
function updateUserPassword($username, $oldPassword, $newPassword) {
    // Connect to database
    $db = new mysqli("localhost", "root", "password", "database");

    if ($db->connect_error) {
        die("Connection failed: " . $db->connect_error);
    }

    // Check if user exists
    $query = "SELECT * FROM users WHERE username = ?";
    $stmt = $db->prepare($query);
    $stmt->bind_param("s", $username);
    $stmt->execute();
    $result = $stmt->get_result();

    if ($result->num_rows == 0) {
        return false;
    }

    // Check current password
    $row = $result->fetch_assoc();
    $hashedOldPassword = password_hash($oldPassword, PASSWORD_DEFAULT);
    if (!password_verify($hashedOldPassword, $row['password'])) {
        return false; // Incorrect old password
    }

    // Update user's password
    $query = "UPDATE users SET password = ? WHERE username = ?";
    $stmt->close();
    $stmt = $db->prepare($query);
    $stmt->bind_param("ss", $newPassword, $username);
    $stmt->execute();

    // Clear cache for the updated user
    $cache = new Memcached('localhost');
    $cache->delete("user_password_{$username}");

    return true;
}
?>
