#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int state;
    struct Node* next;
} Node;

Node* constructFSAList(int* initialStates, int numInitialStates, int** states, int numRows, int lastState) {
    if (numRows == 0) return NULL;

    Node* head = NULL;
    for (int i = 0; i < numInitialStates; i++) {
        Node* newNode = malloc(sizeof(Node));
        if (!newNode) return NULL;

        newNode->state = initialStates[i];
        newNode->next = head;
        head = newNode;
    }

    for (int i = 0; i <= lastState; i++) {
        for (int j = 0; j < numRows && states[i][j] != -1; j++) {
            if (states[i][j] == lastState) continue;

            Node* node = NULL;
            for (Node* temp = head; temp; temp = temp->next) {
                if (temp->state == states[i][j]) {
                    node = temp;
                    break;
                }
            }

            if (!node) return NULL; // unreferenced state

            Node* newNode = malloc(sizeof(Node));
            if (!newNode) return NULL;

            newNode->state = states[i][j];
            newNode->next = node->next;
            node->next = newNode;
        }
    }

    for (Node* temp = head; temp && temp->next; ) {
        Node* nextTemp = temp->next;
        free(temp);
        temp = nextTemp;
    }

    return head;
}

