typedef struct {
    int id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    int id;
    double total_weighted_sum;
    int count;
} UserMetrics;

double dynamic_weight_function(int transaction_type, int user_id) {
    // implement your own weight function here
}

void process_transactions(Transaction* transactions, int num_transactions, UserMetrics** user_metrics, int num_users, time_t current_time) {
    int i;
    for (i = 0; i < num_transactions; i++) {
        Transaction transaction = transactions[i];

        // filter by age
        if (difftime(current_time, transaction.timestamp) > 300) continue;

        // limit concurrent transactions
        int concurrent_transactions = 0;
        time_t max_timestamp = transaction.timestamp;
        for (int j = 0; j < num_transactions; j++) {
            Transaction t = transactions[j];
            if (difftime(current_time, t.timestamp) <= 300 && difftime(max_timestamp, t.timestamp) > 0) concurrent_transactions++;
            if (difftime(current_time, t.timestamp) > 0) max_timestamp = t.timestamp;
        }
        if (concurrent_transactions >= 100) continue;

        // calculate weighted sum
        transaction.weighted_sum = transactions[i].amount * dynamic_weight_function(transactions[i].type, transactions[i].user_id);

        // maintain sliding window
        time_t start_time = current_time - 3;
        int num_transactions_in_window = 0;
        double total_weighted_sum_in_window = 0;
        for (int j = i; j >= 0 && difftime(transactions[j].timestamp, start_time) > 0; j--) {
            Transaction t = transactions[j];
            if (difftime(t.timestamp, start_time) <= 0) break;
            total_weighted_sum_in_window += t.weighted_sum;
            num_transactions_in_window++;
        }

        // update user metrics
        int user_id = transactions[i].user_id;
        UserMetrics* user_metric = user_metrics[user_id];
        user_metric->total_weighted_sum += transaction.weighted_sum;
        user_metric->count++;

        double max_weighted_sum = 0;
        time_t max_weighted_sum_timestamp = 0;
        for (int j = i; j >= 0 && difftime(transactions[j].timestamp, start_time) > 0; j--) {
            Transaction t = transactions[j];
            if (difftime(t.timestamp, start_time) <= 0) break;
            double weighted_sum = total_weighted_sum_in_window - transaction.weighted_sum + t.weighted_sum;
            if (weighted_sum > max_weighted_sum) {
                max_weighted_sum = weighted_sum;
                max_weighted_sum_timestamp = t.timestamp;
            }
        }

        // update metrics
        int total_count = 0;
        double average_weighted_sum = 0;
        for (int j = 0; j < num_users; j++) {
            UserMetrics* user_metric = user_metrics[j];
            total_count += user_metric->count;
            average_weighted_sum += user_metric->total_weighted_sum / user_metric->count;
        }
    }
}

// Example usage
int main() {
    int num_transactions = 1000;
    Transaction transactions[num_transactions];
    for (int i = 0; i < num_transactions; i++) {
        transactions[i].id = i;
        transactions[i].weight = 1.0;
        transactions[i].timestamp = time(NULL) - i % 30;
    }

    int num_users = 100;
    UserMetrics* user_metrics[num_users];
    for (int i = 0; i < num_users; i++) {
        user_metrics[i] = malloc(sizeof(UserMetrics));
        user_metrics[i]->id = i;
        user_metrics[i]->total_weighted_sum = 0.0;
        user_metrics[i]->count = 0;
    }

    time_t current_time = time(NULL);
    process_transactions(transactions, num_transactions, user_metrics, num_users, current_time);

    // Return the maximum weighted sum and the corresponding transaction ID from the last 3 seconds
    int max_weighted_sum_id = 0;
    double max_weighted_sum = 0.0;
    for (int i = 0; i < num_transactions; i++) {
        if (difftime(current_time, transactions[i].timestamp) <= 3 && transactions[i].weighted_sum > max_weighted_sum) {
            max_weighted_sum = transactions[i].weighted_sum;
            max_weighted_sum_id = transactions[i].id;
        }
    }

    // Return the average weighted sum and the total count of transactions processed in the last 5 minutes
    double average_weighted_sum = 0.0;
    int total_count = 0;
    for (int i = 0; i < num_users; i++) {
        UserMetrics* user_metric = user_metrics[i];
        average_weighted_sum += user_metric->total_weighted_sum / user_metric->count;
        total_count += user_metric->count;
    }

    return 0;
}
