            cout << "Cooldown not ready. Waiting..." << endl;
        }

        // Simulate latency and desynchronization
        srand((int)time(0));
        int latency = rand() % 100;
        if (latency > 50) {
            character.setAttack(attackId);
            cout << "Server-side attack triggered." << endl;
