using UnityEngine;

public class RandomValueGenerator
{
    public float minValue;
    public float maxValue;

    public RandomValueGenerator(float minValue, float maxValue)
    {
        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        return UnityEngine.Random.Range(minValue, maxValue + 1f);
    }

    public int GetRandomInt()
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value cannot be greater than max value.");

        return UnityEngine.Random.Range((int)minValue, (int)(maxValue + 1));
    }

    public float GetRandomFloatExclusive()
    {
        return UnityEngine.Random.Range(minValue + 0.00001f, maxValue);
    }

    public int GetRandomIntExclusive()
    {
        if (minValue >= maxValue)
            throw new ArgumentException("Min value cannot be greater than or equal to max value.");

        return UnityEngine.Random.Range((int)(minValue + 1), (int)maxValue);
    }

    public override string ToString()
    {
        if (minValue == maxValue)
            return "Range: [" + minValue + ", " + maxValue + "]";

        return "Range: (" + minValue + ", " + maxValue + ")";
    }
}
