const { AsyncReduce } = require('./AsyncReduce');

async function processArray(arr, initialValue, callback, timeout = 5000) {
    try {
        const result = await AsyncReduce(arr, initialValue, callback, timeout);
        console.log(`Result: ${result}`);
    } catch (error) {
        console.error(`Error: ${error.message}`);
    }
}

class AsyncReduce {
    constructor() {}

    async reduce(array, initialValue, callback, timeout) {
        let value = initialValue;
        for await (const num of array) {
            try {
                value = await this.delayedOperation(value, num, callback);
            } catch (err) {
                throw err;
            }
        }
        return value;
    }

    async delayedOperation(initialValue, num, callback) {
        return new Promise((resolve, reject) => {
            setTimeout(() => {
                try {
                    const result = callback(initialValue, num);
                    resolve(result);
                } catch (err) {
                    reject(err);
                }
            }, timeout);
        });
    }
}

// Test the function
const array = [1, 2, 3, 4, 5];
const callback = (acc, current) => acc + current;
processArray(array, 0, callback);
