typedef struct {
    int id;
    char *name;
    double value;
} Item;

typedef struct {
    int count;
    Item **items;
} Bundle;

Bundle* load_bundle(const char *file_path, const char *format) {
    Bundle *bundle = (Bundle *)malloc(sizeof(Bundle));
    if (!bundle) {
        return NULL;
    }

    bundle->count = 0;
    bundle->items = NULL;

    if (strcmp(format, "json") == 0) {
        json_object *obj = json_object_from_file(file_path);
        if (!obj) {
            free(bundle);
            return NULL;
        }

        int size = json_object_get_array_size(obj);
        bundle->count = size;
        bundle->items = (Item **)malloc(size * sizeof(Item *));
        for (int i = 0; i < size; i++) {
            Item *item = (Item *)malloc(sizeof(Item));
            item->id = json_object_get_int(json_object_array_get_idx(obj, i));
            item->name = strdup(json_object_to_json_string_ext(obj, i, JSON_C_TO_JSMON));
            item->value = json_object_get_double(json_object_array_get_idx(obj, i));
            bundle->items[i] = item;
        }
    } else if (strcmp(format, "xml") == 0) {
        xmlNode *root = xmlDocReadFile(file_path, NULL);
        if (!root) {
            free(bundle);
            return NULL;
        }

        int size = count_nodes(root);
        bundle->count = size;
        bundle->items = (Item **)malloc(size * sizeof(Item *));
        for (int i = 0; i < size; i++) {
            Item *item = (Item *)malloc(sizeof(Item));
            item->id = get_node_attribute(root, i, "id");
            item->name = strdup(get_node_text(root, i));
            item->value = get_node_double(root, i);
            bundle->items[i] = item;
        }
    } else if (strcmp(format, "csv") == 0) {
        FILE *file = fopen(file_path, "r");
        if (!file) {
            free(bundle);
            return NULL;
        }

        int size = count_lines(file);
        bundle->count = size;
        bundle->items = (Item **)malloc(size * sizeof(Item *));
        for (int i = 0; i < size; i++) {
            Item *item = (Item *)malloc(sizeof(Item));
            item->id = csv_get_int(file, i);
            item->name = strdup(csv_get_string(file, i));
            item->value = csv_get_double(file, i);
            bundle->items[i] = item;
        }
    }

    return bundle;
}

void free_bundle(Bundle *bundle) {
    for (int i = 0; i < bundle->count; i++) {
        free(bundle->items[i]->name);
        free(bundle->items[i]);
    }
    free(bundle->items);
    free(bundle);
}
