char* append_slash(char* str, size_t limit, char* buffer) {
    if (!str || !buffer) return NULL;

    size_t len = strlen(str);
    if (len >= limit) return NULL;

    char* new_str = realloc(buffer, len + 2);
    if (!new_str) {
        log_error("Realloc failed");
        return NULL;
    }
    buffer = new_str;

    memcpy(buffer, str, len);
    buffer[len] = '/';
    buffer[len + 1] = '\0';

    return buffer;
}
