#define MAX_LINE_LENGTH 1024
#define MAX_NUMBERS_PER_LINE 1000
#define AVERAGE_CALCULATION 3

int main(int argc, char *argv[]) {
    FILE *fp = fopen(argv[1], "r");
    if (fp == NULL) {
        printf("Error opening file %s.\n", argv[1]);
        return 1;
    }

    int num_lines = 0;
    int num_skipped = 0;
    double total_time = 0.0;

    char *line = NULL;
    size_t line_length = 0;
    ssize_t read_chars;

    while ((read_chars = getline(&line, &line_length, fp)) != -1) {
        char *token = strtok(line, " ");
        int numbers[AVERAGE_CALCULATION] = {0};
        int count = 0;
        double sum = 0.0;

        for (token; token && count < AVERAGE_CALCULATION; token = strtok(NULL, " ")) {
            double num = atof(token);
            if (num > 1000 || num < 0) {
                num_skipped++;
                continue;
            }
            numbers[count++] = num;
            sum += num;
        }

        if (count >= AVERAGE_CALCULATION) {
            int avg = (int)(sum / count);
            char buffer[32];
            sprintf(buffer, ",%d", avg);
            strcat(line + read_chars - line_length, buffer);
            printf("%s\n", line);
        } else {
            int avg = (int)sum;
            char buffer[32];
            sprintf(buffer, ",%d", avg);
            strcat(line + read_chars - line_length, buffer);
            printf("%s\n", line);
        }
    }

    free(line);

    fclose(fp);

    return 0;
}
