    srand(time(NULL)); // Seed the RNG with current time

    char rand_str[random_len];
    for (int i = 0; i < random_len; i++) {
        rand_str[i] = (rand() % 52) + ('a' - 10); // Generate alphanumeric characters
    }
    rand_str[random_len] = '\0'; // Null-terminate the string

    time_t now = time(NULL);
    char timestamp[15];
    strftime(timestamp, 15, "%Y%m%d%H%M%S", localtime(&now)); // Format timestamp in YYYYMMDDHHMMSS format

    int len = strlen(filename) + random_len + strlen(timestamp) + 3; // Calculate total length of new filename
    if (len > 255) {
        return NULL; // Return error code if total length exceeds 255 characters
    }

    char* new_filename = malloc(len);
    sprintf(new_filename, "%s.%s.%s", filename, rand_str, timestamp);

    return new_filename;
}
