#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>

// Function to securely initialize an AES-256-CBC cipher with a given password
AES_CTX* init_AES_cipher(const char* password) {
    int iterations = 10000;
    unsigned char salt[] = {0x12, 0x34, 0x56, 0x78}; // Salt bytes for PBKDF2

    // Check password strength and length
    if (strlen(password) < 8 || !isalpha(password[0]) && !isdigit(password[0])) {
        return NULL;
    }

    // Derive the encryption key and IV from the password using PBKDF2 with SHA-256
    unsigned char* derived_key = (unsigned char*)malloc(32);
    unsigned char* derived_iv = (unsigned char*)calloc(AES_BLOCK_SIZE, 1);

    if (!derived_key || !derived_iv) {
        free(derived_key);
        free(derived_iv);
        return NULL;
    }

    int ret = PBKDF2(password, strlen(password), salt, sizeof(salt), derived_key, 32, iterations, &derived_iv[0]);
    if (ret != 1) {
        ERR_error_string(ERR_get_error(), NULL);
        free(derived_key);
        free(derived_iv);
        return NULL;
    }

    // Initialize the AES-256-CBC cipher context
    AES_CTX* ctx = (AES_CTX*)malloc(sizeof(AES_CTX));
    if (!ctx) {
        free(derived_key);
        free(derived_iv);
        return NULL;
    }

    ret = EVP_CipherInit(ctx, &AES_256_CBC(), derived_key, derived_iv, 1);
    if (ret != 1) {
        ERR_error_string(ERR_get_error(), NULL);
        free(derived_key);
        free(derived_iv);
        free(ctx);
        return NULL;
    }

    return ctx;
}

// Function to properly clean up resources when the cipher is no longer needed
void cleanup_AES_cipher(AES_CTX* ctx) {
    if (ctx) {
        EVP_CipherFinal_ex(ctx, NULL, NULL);
        AES_CTX_free(ctx);
    }
}
