#include <string.h>

int compressPng(const char *inputFile, const char *outputDir, int level) {
    FILE *zipFile = fopen(outputDir, "w");
    if (zipFile == NULL) return 1;

    z_stream stream;
    stream.zalloc = Z_NULL;
    stream.zfree = Z_NULL;
    stream.opaque = Z_NULL;

    int reti = deflateInit2(&stream, level, Z_DEFLATED, 31, Z_DEFAULT_MEM, Z_DEFAULT_STRATEGY);
    if (reti != Z_OK) return 1;

    zipFile = gzopen(inputFile, "rb");
    if (zipFile == NULL) {
        deflateEnd(&stream);
        fclose(zipFile);
        return 1;
    }

    gzipFile(zipFile, &stream);

    deflateEnd(&stream);
    fclose(zipFile);
    return 0;
}

void gzipFile(FILE *file, z_stream *stream) {
    char in[1024];
    do {
        size_t len = fread(in, 1, 1024, file);
        if (len == 0)
            break; // eof

        stream->next_in = (Bytef*)in;
        stream->avail_in = len;

        do {
            stream->next_out = (Bytef*)in;
            stream->avail_out = 1024;

            int reti = deflate(stream, Z_FINISH);
            if ((reti < 0) && (stream->data_type == Z_STREAM_END))
                break; // error in deflate data stream
            else if (reti > 0)
                continue; // not finished

        } while (stream->avail_out == 0);

    } while (!gzeof(file));
}

int gzeof(FILE *file) {
    return feof(file);
}
