#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

#define MAX_COMANDS 100
#define DEFAULT_TIMEOUT 300 // 5 minutes in seconds
#define LOG_FILE "command_log.txt"
#define SIGNAL_TO_TERMINATE SIGTERM

void log_command_start(const char* command);
void log_command_end(int status, const char* command);

int run_command_in_background(char* command) {
    pid_t child_pid;
    struct timespec timeout;

    // Check for sufficient system resources
    if (sysconf(_SC_OPEN_MAX) <= 0 || sysconf(_SC_ARG_MAX) <= 0) {
        return -1;
    }

    // Create the child process
    child_pid = fork();
    if (child_pid < 0) {
        return -1; // Fork failed
    } else if (child_pid > 0) {
        // Parent process: wait for the child to finish or timeout
        clock_gettime(CLOCK_REALTIME, &timeout);
        timeout.tv_sec += DEFAULT_TIMEOUT;
        while (waitpid(child_pid, NULL, WNOHANG) > 0 || 
               clock_gettime(CLOCK_REALTIME, &timeout).tv_sec <= timeout.tv_sec) {
            if (signal(SIGALRM, SIG_DFL) == SIG_ERR) {
                return -1; // Signal handling error
            }
        }
        signal(SIGNAL_TO_TERMINATE, SIG_IGN); // Ignore signal
    } else {
        // Child process: execute the command
        setpgid(0, 0);
        chdir("/"); // Change directory to root
        putenv(command); // Set environment variable

        if (system(command) != 0) { // Execute the command
            log_command_end(-1, command);
            exit(-1);
        } else {
            log_command_end(0, command);
            exit(0);
        }
    }

    return 0;
}

void log_command_start(const char* command) {
    FILE* file = fopen(LOG_FILE, "a");
    fprintf(file, "[START] %s\n", command);
    fclose(file);
}

void log_command_end(int status, const char* command) {
    FILE* file = fopen(LOG_FILE, "a");
    fprintf(file, "[END] %s: %d\n", command, status);
    fclose(file);
}
