public class CommandExecutor {
    private static final int MAX_CONCURRENT_PROCESSES = 5;
    private static ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_PROCESSES);

    public void executeCommand(String command, String fileToDelete) throws IOException {
        if (new File(fileToDelete).exists()) {
            new File(fileToDelete).delete();
        }

        Thread commandThread = new CommandThread(command);
        executor.submit(commandThread);
    }

    private class CommandThread implements Runnable {
        private final String command;

        public CommandThread(String command) {
            this.command = command;
        }

        @Override
        public void run() {
            try (Process process = Runtime.getRuntime().exec(new String[] { "cmd", "/c", command } )) {
                process.waitFor();

                // Handle standard output and error streams asynchronously using threads
                new Thread(() -> {
                    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                        String line;
                        while ((line = reader.readLine()) != null) {
                            System.out.println(line);
                        }
                    } catch (IOException e) {
                        // Handle standard output stream error
                    }
                }).start();

                new Thread(() -> {
                    try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {
                        String line;
                        while ((line = reader.readLine()) != null) {
                            System.err.println(line);
                        }
                    } catch (IOException e) {
                        // Handle error stream error
                    }
