    if (jobj == NULL) return 0;

    char *access_token = json_object_get_string(json_object.GetObjectItem(jobj, "access_token"));
    int expires_in = json_object_get_int(json_objectGetObjectItem(jobj, "expires_in"));
    char *token_type = json_object_get_string(json_object_GetStringItem(jobj, "token_type"));
    json_object *refresh_token_obj = json_object_GetStringItem(jobj, "refresh_token");

    if (access_token == NULL || strlen(access_token) != 36 || !json_is_uuid_version4(access_token)) return 0;
    if (expires_in < 1 || expires_in > 604799) return 0;
    if (strcmp(token_type, "Bearer") != 0) return 0;

    if (refresh_token_obj != NULL && refresh_token_obj->type == json_type_string && strlen(json_object_get_string(refresh_token_obj)) == 36 && !json_is_uuid_version4(json_object_get_string(refresh_token_obj))) return 0;

    json_object_put(jobj);
    return 1;
}
