using System;
using System.IO;
using System.Text;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class ChunkedCompressor
{
    public async Task<List<MyObject>> ProcessLargeByteArrayAsync(byte[] largeByteArray)
    {
        List<byte[]> chunks = SplitIntoChunks(largeByteArray, 4096);
        List<MyObject> result = new List<MyObject>();

        foreach (byte[] chunk in chunks)
        {
            byte[] compressedChunk = Compress(chunk);
            string jsonPayload = await SendCompressedDataToServerAsync(compressedChunk);

            if (!string.IsNullOrEmpty(jsonPayload))
            {
                List<MyObject> parsedResponse = JsonConvert.DeserializeObject<List<MyObject>>(jsonPayload);
                result.AddRange(parsedResponse);
            }
        }

        return result;
    }

    private byte[] Compress(byte[] chunk)
    {
        using (MemoryStream ms = new MemoryStream())
        {
            using (GZipStream gzipStream = new GZipStream(ms, CompressionMode.Compress))
            {
                gzipStream.Write(chunk, 0, chunk.Length);
                gzipStream.Flush();
            }

            return ms.ToArray();
        }
    }

    private string SendCompressedDataToServerAsync(byte[] compressedChunk)
    {
        HttpClient client = new HttpClient();
        ByteArrayContent content = new ByteArrayContent(compressedChunk);

        content.Headers.ContentType = new MediaTypeHeaderValue("application/octet-stream");
        content.Headers.ContentLength = compressedChunk.Length;

        HttpResponseMessage response = await client.PostAsync("https://example.com/api/processData", content);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync();
    }

    private List<byte[]> SplitIntoChunks(byte[] largeByteArray, int chunkSize)
    {
        List<byte[]> chunks = new List<byte[]>();

        for (int i = 0; i < largeByteArray.Length; i += chunkSize)
        {
            byte[] chunk;
            if (i + chunkSize > largeByteArray.Length)
                chunk = new byte[largeByteArray.Length - i];
            else
                chunk = new byte[chunkSize];

            Array.Copy(largeByteArray, i, chunk, 0, chunk.Length);
            chunks.Add(chunk);
        }

        return chunks;
    }
}
