using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public static class TextInputProcessor
{
    public static string ComputeAggregateHash(Stream input)
    {
        using (var md5 = MD5.Create())
        {
            var buffer = new byte[4096]; // adjust the buffer size as needed
            long totalBytesRead = 0;
            string aggregateHash = null;

            while (true)
            {
                int bytesRead = input.Read(buffer, 0, buffer.Length);
                if (bytesRead == 0) break; // end of stream

                using (var ms = new MemoryStream(buffer, 0, bytesRead))
                {
                    byte[] chunkHash = md5.ComputeHash(ms);
                    totalBytesRead += bytesRead;

                    if (aggregateHash == null)
                        aggregateHash = BitConverter.ToString(chunkHash).Replace("-", string.Empty);
                    else
                        aggregateHash = Sha256Hash(aggregateHash, BitConverter.ToString(chunkHash).Replace("-", string.Empty));
                }
            }

            return aggregateHash;
        }
    }

    private static string Sha256Hash(string hash1, string hash2)
    {
        using (var sha256 = SHA256.Create())
        {
            byte[] buffer = Convert.FromBase64String(hash1);
            byte[] newBuffer = ConcatenateByteArrays(buffer, Convert.FromBase64Bytes(hash2));
            return BitConverter.ToString(sha256.ComputeHash(newBuffer)).Replace("-", string.Empty);
        }
    }

    private static byte[] ConcatenateByteArrays(byte[] array1, byte[] array2)
    {
        var result = new byte[array1.Length + array2.Length];
        Array.Copy(array1, 0, result, 0, array1.Length);
        Array.Copy(array2, 0, result, array1.Length, array2.Length);
        return result;
    }
}
