using System;
using System.Security.Cryptography;
using System.Text;

public class AESCBCDecrypter
{
    public static (byte[], bool) Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, byte[] hmacKey)
    {
        using Aes aes = Aes.Create();
        aes.Key = encryptionKey;
        aes.IV = initializationVector;

        var plaintextSegments = new List<byte[]>();
        int currentSegmentOffset = 0;

        for (int i = 0; i < ciphertext.Length; i++)
        {
            while (i + 16 > ciphertext.Length)
            {
                plaintextSegments.Add(new byte[0]);
                break;
            }

            using MemoryStream ms = new MemoryStream(ciphertext, currentSegmentOffset, 16);
            using CryptoStream cs = new CryptoStream(ms, aes.CreateEncryptor(), CryptoStreamMode.Read);
            var segment = new byte[16];
            cs.Read(segment, 0, segment.Length);

            plaintextSegments.Add(segment);
            currentSegmentOffset += 16;
        }

        using MemoryStream ms = new MemoryStream();
        using CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write);

        foreach (var segment in plaintextSegments)
        {
            cs.Write(segment, 0, segment.Length);
        }

        byte[] decryptedPlaintext = ms.ToArray();

        using HMACSHA256 hmac = HMACSHA256.Create();
        hmac.Key = hmacKey;

        byte[] integrityHash = hmac.ComputeHash(decryptedPlaintext);
        bool isIntegritySuccessful = true;

        for (int i = 0; i < ciphertext.Length - decryptedPlaintext.Length; i++)
        {
            if (ciphertext[i] != integrityHash[i])
            {
                isIntegritySuccessful = false;
                break;
            }
        }

        return (decryptedPlaintext, isIntegritySuccessful);
    }
}
