public class SerializationHelper {
    public static Object deserializeByteArray(byte[] byteArray) throws IOException, ClassNotFoundException {
        if (byteArray == null || byteArray.length == 0) {
            return null; // or throw an exception depending on your requirements
        }

        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(byteArray))) {
            return ois.readObject();
        } catch (IOException | ClassNotFoundException e) {
            String errorMessage = "Error deserializing byte array: " + e.getMessage();
