// Load and execute a specified JavaScript file within the context of a web page
function loadAndExecuteJsFile(jsFilePath, callback) {
    if (!jsFilePath) {
        console.error("Invalid or missing JavaScript file path");
        return;
    }

    // Use XMLHttpRequest to load the JavaScript file asynchronously
    const xhr = new XMLHttpRequest();
    xhr.open('GET', jsFilePath, true);
    xhr.onload = function() {
        if (xhr.status === 200) {
            // Execute the loaded script using eval()
            try {
                eval(xhr.responseText);
            } catch (error) {
                console.error("Error executing JavaScript file: " + error.message);
            }
        } else {
            console.error("Failed to load JavaScript file: " + xhr.statusText);
        }
    };
    xhr.send();
}

// Example usage
loadAndExecuteJsFile('script.js', function() {
    // This callback will be executed once the script is loaded and executed
    console.log("Script execution complete");
});
