void loadResourceBundle(const char* file_path, int* bundle_size) {
    // Load resource bundle from file
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        printf("Error opening file!\n");
        return;
    }

    // Parse file format based on extension
    const char* ext = strrchr(file_path, '.');
    if (!strcmp(ext, ".json")) {
        // Load JSON resource bundle
        *bundle_size = 0;
        ResourceItem* bundle = NULL;

        json_object* root = json_unpack(json_file_reader(file), "{s:i,s:s}");
        while (root != NULL) {
            // Handle each item in the resource bundle
            int id = json_object_get_int(root, "id");
            char* name = json_object_get_string(root, "name");

            // Allocate memory for each item
            ResourceItem* item = malloc(sizeof(ResourceItem));
            item->id = id;
            item->name = strdup(name);

            // Add to bundle array
            if (bundle == NULL) {
                bundle = item;
            } else {
                *bundle_size += 1;
                bundle = realloc(bundle, (*bundle_size + 1) * sizeof(ResourceItem));
                bundle[*bundle_size - 1] = item;
            }

            root = json_object_get_array(root, "next");
        }
    } else if (!strcmp(ext, ".xml")) {
        // Load XML resource bundle
