      .on('exit', (code, signal) => {
        if (code || signal) {
          const errMsg = `Command failed with exit code ${code} or signal ${signal}`;
          console.error(errMsg);
          throw new Error(errMsg);
        }
      })
      .on('error', (err) => {
        console.error(`An error occurred while executing the command: ${err}`);
        throw err;
      });
  } catch (err) {
    console.error(err);
    return null;
  }
}
