public void addVertexAndEdge(Vertex v, Edge e) {
    try {
        // Validate vertex and edge properties against schema rules
        if (!validateProperties(v, e)) {
            throw new InvalidDataException("Invalid vertex or edge properties");
        }

        // Start a transaction to ensure data consistency
        startTransaction();

        // Add vertex to the database (using batch processing if configured)
        if (isBatchProcessingEnabled()) {
            addVertexToBatchQueue(v);
        } else {
            addVertexToDatabase(v);
        }

        // Add edge to the database (using batch processing if configured)
        if (isBatchProcessingEnabled()) {
            addEdgeToBatchQueue(e);
        } else {
            addEdgeToDatabase(e);
        }

        // Commit the transaction
        commitTransaction();
    } catch (InvalidDataException ex) {
        // Handle invalid data exception by rolling back the transaction and logging the error
        rollbackTransaction();
        logger.error("Invalid data exception during vertex or edge insertion", ex);
    } catch (DatabaseException ex) {
        // Handle database exceptions by retrying the operation up to a maximum number of attempts
        int maxAttempts = 3;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                if (attempt > 1) {
                    Thread.sleep(1000); // Wait before retrying
                }
                addVertexAndEdge(v, e);
                break;
            } catch (DatabaseException ex2) {
                logger.error("Database exception during vertex or edge insertion. Retrying...", ex2);
            }
        }

        if (attempt > maxAttempts) {
            // Log the final error and consider it a failure
            logger.error("Failed to insert vertex or edge after maximum attempts", ex);
        }
    } catch (Exception ex) {
        // Handle any other unexpected exceptions by rolling back the transaction and logging the error
        rollbackTransaction();
        logger.error("Unexpected exception during vertex or edge insertion. Rolling back transaction.", ex);
    }
}

private boolean validateProperties(Vertex v, Edge e) {
