use log::{info, error};

#[tokio::main]
async fn main() {
    env_logger::init();
    let (tx, rx) = channel(10);

    for i in 0..10 {
        tx.send(i).await.unwrap();
    }

    while let Some(item) = rx.recv().await {
        match process_item(item) {
            Ok(_) => info!("Item processed"),
            Err(err) => error!("Error processing item: {}", err),
        }
    }
}

async fn process_item(item: i32) -> Result<(), Box<dyn std::error::Error>> {
    let (tx, rx) = channel(1);

    tokio::spawn(async move {
        match item {
            0..=5 => file_operation().await,
            _ => network_operation().await,
        }
        .map_err(|e| e.to_string())
        .and_then(|_| rx.recv().await)
        .unwrap_or_default();
    });

    let mut count = 0;
    loop {
        tokio::select! {
            res = tx.recv() => {
                if let Some(res) = res {
                    info!("Received: {}", res);
                    count += 1;
                } else {
                    break;
                }
            }
        }
    }

    info!("Total received: {}", count);

    Ok(())
}

async fn file_operation() -> Result<String, String> {
    // Your file operation code here
    // For demonstration purposes only:
    tokio::time::sleep(std::time::Duration::from_secs(2)).await;
    Ok("File operation completed".to_string())
}

async fn network_operation() -> Result<String, String> {
    let mut timeout = std::time::Instant::now();
    loop {
        if timeout <= std::time::Instant::now() {
            return Err("Network operation timed out".to_string());
        }
        // Your network operation code here
        // For demonstration purposes only:
        tokio::time::sleep(std::time::Duration::from_secs(5)).await;
        Ok("Network operation completed".to_string())
    }
}
