use std::env;
use std::fs::create_dir_all;
use std::path::{Path, PathBuf};
use std::process::exit;

pub fn setup_config_dir() -> Result<(), &str> {
    let username = env::var("USER")?;
    let app_id = "my_app"; // replace with your app's identifier

    let config_dir_name = format!("{}/{}", username, app_id);
    let config_dir_path = Path::new(home_dir()).join(config_dir_name);

    if !config_dir_path.exists() {
        create_dir_all(&config_dir_path)?;
        env::set_var("CONFIG_DIR", &config_dir_path.display().to_string());
    } else if env::var("CONFIG_DIR").is_err() {
        env::set_var("CONFIG_DIR", &config_dir_path.display().to_string());
    }

    Ok(())
}

fn home_dir() -> PathBuf {
    match std::env::var("HOME") {
        Ok(home) => PathBuf::from(home),
        Err(_) => {
            if let Some(user) = get_username() {
                format!("{}{}", user, "/")
                    .try_into()
                    .unwrap_or_else(|e| panic!("Failed to create home dir path: {}", e))
            } else {
                return PathBuf::new();
            }
        }
    }
}

fn get_username() -> Option<String> {
    use nix::sys::user;
    match user::username() {
        Ok(username) => Some(username.to_string()),
        Err(_) => None,
    }
}
