import json
import importlib.util

class ConfigManager:
    _config_classes = {}
    _environment_config = None

    @classmethod
    def register_config_class(cls, config_class_name):
        spec = importlib.util.spec_from_file_location(config_class_name, f"{config_class_name}.py")
        module = importlib.util.module_from_spec(spec)
        module.__package__ = cls.__module__
        module.config_class = getattr(module, 'ConfigClass', None)
        if module.config_class:
            cls._config_classes[config_class_name] = module.config_class

    @classmethod
    def load_config(cls, config_file):
        try:
            with open(config_file, 'r') as f:
                data = json.load(f)
            return cls.deserialize(data)
        except (FileNotFoundError, json.JSONDecodeError) as e:
            raise Exception(f"Failed to load configuration: {e}")

    @classmethod
    def deserialize(cls, data):
        if not isinstance(data, dict):
            return None

        config_class_name = data.get('config_class')
        if config_class_name:
            if config_class_name in cls._config_classes:
                try:
                    return cls._config_classes[config_class_name](**data)
                except Exception as e:
                    raise Exception(f"Failed to deserialize configuration: {e}")
            else:
                raise ValueError(f"Unknown config class: {config_class_name}")

        # Handle nested structure deserialization
        for key, value in data.items():
            if isinstance(value, dict):
                data[key] = cls.deserialize(value)
            elif isinstance(value, list):
                data[key] = [cls.deserialize(item) for item in value]

        return ConfigObject(**data)

    @classmethod
    def set_environment(cls, environment):
        if not environment:
            raise ValueError("Environment must be provided")

        cls._environment_config = environment

    @classmethod
    def get_environment(cls):
        return cls._environment_config


class ConfigObject:
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

    def to_dict(self):
        return {key: getattr(self, key) for key in dir(self) if not key.startswith('_')}

# Usage example
ConfigManager.register_config_class('MyAppConfig')

config_file = 'myapp.json'
config_data = ConfigManager.load_config(config_file)
print(config_data.to_dict())

environment = 'production'
ConfigManager.set_environment(environment)

# Access environment-specific configuration
env_config = ConfigManager.get_environment()
print(env_config)
