#include <openssl/evp.h>
#include <openssl/des.h>

EVP_CIPHER_CTX* des_ciphers(int mode, int key_size, int num_passes) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    if(mode == 0) { // ECB
        EVP_EncryptInit_ex(ctx, EVP_des_ecb(), NULL, NULL);
    } else if(mode == 1) { // EDE
        EVP_CipherInit_ex(ctx, EVP_des_ede_cbc(), NULL, NULL, NULL);
    } else if(mode == 2) { // EDE3
        EVP_CipherInit_ex(ctx, EVP_des_ede3_cbc(), NULL, NULL, NULL);
    } else if(mode == 3) { // CFB
        EVP_CipherInit_ex(ctx, EVP_des_cfb64(), NULL, NULL, NULL);
    }

    if(key_size > 56) key_size = 112;

    DES_key_schedule des_key;
    unsigned char* key = OPENSSL_malloc(key_size/8);
    RAND_bytes(key, key_size/8);
    DES_set_key_checked(des_key, key, key_size);
    EVP_CipherInit_ex(ctx, NULL, NULL, &des_key, NULL);
    EVP_CIPHER_CTX_set_key_length(ctx, key_size);

    if(num_passes > 1) {
        for(int i = 0; i < num_passes; i++) {
            unsigned char* input = (unsigned char*)OPENSSL_malloc(1024);
            int in_len = 1024;
            // Input data stream processing
            EVP_CipherUpdate(ctx, input, &in_len);
            // Output buffer overflow prevention
            unsigned char* output = (unsigned char*)OPENSSL_malloc(in_len);
            EVP_CipherFinal_ex(ctx, output, &in_len);
        }
    } else {
        int in_len = 1024;
        unsigned char* output = (unsigned char*)OPENSSL_malloc(1024);
        // Single-pass encryption
        EVP_CipherUpdate(ctx, output, &in_len);
    }

    return ctx;
}

void des_ciphers_free(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}
