    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    for (const auto& str : strings) {
        unsigned char hash[16];
        unsigned int hashLen;

        if (!str.empty()) {
            const auto data = str.c_str();
            size_t dataSize = str.size();

            // Set up the MD5 context
            EVP_MD_CTX_init(&ctx);
            EVP_set_default_padding(ctx, EVP_PADDING_PKCS7);
            EVP_SignInit(ctx, EVP_md5(), nullptr, 0);
            EVP_SignUpdate(ctx, data, dataSize);
            EVP_SignFinal(ctx, hash, &hashLen);
        } else {
            // Handle null or empty strings
            EVP_MD_CTX_init(&ctx);
            EVP_set_default_padding(ctx, EVP_PADDING_PKCS7);
            EVP_SignInit(ctx, EVP_md5(), nullptr, 0);
            EVP_SignFinal(ctx, hash, &hashLen);
        }

        char result[33];
        std::string md5Str;

        // Convert the MD5 hash to a hexadecimal string
        for (int i = 0; i < 16; ++i) {
            sprintf(result + 2 * i, "%02x", hash[i]);
        }

        md5Str = result;

        // Log each hashing operation
        // ...

        md5Hashes.push_back(md5Str);
    }

    EVP_CIPHER_CTX_free(ctx);

    return md5Hashes;
}
