int manageMemory(int numRecords, char* filename) {
    // Allocate memory dynamically for each array
    long* offset = (long*)malloc(numRecords * sizeof(long));
    int* key = (int*)malloc(numRecords * sizeof(int));
    Record* record = (Record*)malloc(numRecords * sizeof(Record));

    if (!offset || !key || !record) {
        free(offset);
        free(key);
        free(record);
        return 1; // Memory allocation failed
    }

    // Initialize the 'offset' array with consecutive integers starting from 0
    for (int i = 0; i < numRecords; i++) {
        offset[i] = i;
    }

    // Populate the 'key' array with unique integers chosen randomly from a specified range
    srand(time(NULL));
    int minKey = 1, maxKey = 100; // Adjust these values as per your requirements
    for (int i = 0; i < numRecords; i++) {
        key[i] = rand() % (maxKey - minKey + 1) + minKey;
    }

    // Set the value of each record's 'int' field to a random value within a given range
    for (int i = 0; i < numRecords; i++) {
        record[i].value = rand() % 100; // Adjust this value as per your requirements
    }

    // Generate new filename with modified extension and timestamp
    char* newFilename = (char*)malloc(strlen(filename) + 10); // +10 for the random sequence and timestamp
    sprintf(newFilename, "%s_%c", filename, 'a' + rand() % 26); // Adjust this as per your requirements
    struct tm* timeInfo = localtime(&time(NULL));
    char timestamp[9];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", timeInfo);
    strcat(newFilename, "_");
    strcat(newFilename, timestamp);

    free(newFilename);

    // Release all allocated memory when the function is done using the records
    free(offset);
    free(key);
    free(record);

    return 0; // Success
}
