#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    float x;
    float y;
} point;

point* init_points(int n) {
    point* points = (point*)malloc(n * sizeof(point));
    for (int i = 0; i < n; i++) {
        points[i].x = (float)i / n;
        points[i].y = (float)i % n;
    }
    return points;
}

char* init_strings(int n, int length) {
    char* strings = (char*)malloc(n * sizeof(char));
    for (int i = 0; i < n; i++) {
        srand((unsigned)time(NULL));
        for (int j = 0; j < length; j++) {
            strings[i * length + j] = (char)(rand() % 26 + 'a');
        }
        strings[i * length] = '\0';
    }
    return strings;
}

double* init_doubles(int n) {
    double* doubles = (double*)malloc(n * sizeof(double));
    for (int i = 0; i < n; i++) {
        doubles[i] = (double)i / n + rand() % 10 / 100.0;
    }
    return doubles;
}

int read_file(const char* filename, int* sequence) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        printf("Failed to open the file.\n");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        *sequence = atoi(line);
        fclose(file);
        return 0;
    }

    printf("Failed to read a valid sequence from the file.\n");
    fclose(file);
    return -1;
}

int main() {
    int n = 100; // dynamic array size
    int length = 10; // random string length

    double* doubles = init_doubles(n);
    char* strings = init_strings(n, length);
    point* points = init_points(n);

    int sequence;
    read_file("sequence.txt", &sequence);

    if (sequence < 0 || sequence > n) {
        printf("Invalid sequence: %d.\n", sequence);
    }

    // manage memory and handle errors
    for (int i = 0; i < n; i++) {
        free(strings + i * length);
    }
    free(strings);
    free(points);
    free(doubles);

    return 0;
}
