// Function to discover and return available network drivers/protocols
NetworkDriver** discover_drivers(int target_env) {
    // Initialize an empty list of drivers
    NetworkDriver** list = NULL;

    // Load environment-specific configuration file for target environment
    FILE* config_file = fopen("env_config.txt", "r");
    if (config_file == NULL) {
        printf("Error: Unable to load configuration file.\n");
        return list;
    }

    // Iterate through the configuration file and add drivers to the list
    while (!feof(config_file)) {
        NetworkDriver* driver = malloc(sizeof(NetworkDriver));
        fscanf(config_file, "%s %p %d", driver->name, &driver->init, &driver->param);

        if (target_env == KERN_ENV && driver->param != NULL) {
            // Kernel-mode version available, prioritize it
            int is_available = kernel_mode_check(driver->name, driver->param);
            if (!is_available) {
                free(driver);
                continue;
            }
        } else if (target_env == USER_ENV && driver->param == NULL) {
            // User-mode version available, use it
            int is_available = user_mode_check(driver->name, driver->init);
            if (!is_available) {
                free(driver);
                continue;
            }
        }

        // Add the driver to the list
        list = realloc(list, sizeof(NetworkDriver*) * (list != NULL ? list[0].name : 1));
        list[list != NULL ? list[0]++ : 0] = driver;
    }

    fclose(config_file);
    return list;
}

