import java.io.ByteArrayInputStream;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class StringHasher {
    private static final int BUFFER_SIZE = 1024 * 64; // 64KB buffer size for optimized I/O operations

    public List<String> processBatch(List<String> inputStrings) {
        List<String> hashResults = new ArrayList<>();
        MessageDigest md5Digest;

        try {
            md5Digest = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            // Handle MD5 algorithm not found
            return null; // or throw an exception depending on the requirement
        }

        for (String inputString : inputStrings) {
            if (inputString == null || inputString.isEmpty()) {
                continue; // skip processing empty or null strings
            }

            byte[] inputBytes = inputString.getBytes();
            ByteArrayInputStream inputStream = new ByteArrayInputStream(inputBytes);
            byte[] hashBytes;

            try {
                md5Digest.reset();
                MessageDigestOutputStream md5Stream = new MessageDigestOutputStream(md5Digest, BUFFER_SIZE);
                IOUtils.copy(inputStream, md5Stream);

                // Get the digest result as a byte array
                hashBytes = md5Stream.getDigest();

                // Convert the byte array to hexadecimal string and add it to the results list
                String hashResult = bytesToHex(hashBytes);
                hashResults.add(hashResult);
            } catch (IOException e) {
                // Handle I/O error during hashing operation
                // Log the error for monitoring purposes
                logError("Error hashing string: " + inputString, e);
            }
        }

        return hashResults;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            String hex = Integer.toHexString(0xFF & b);
            if (hex.length() < 2)
                result.append('0').append(hex);
            else
                result.append(hex);
        }
        return result.toString();
    }

    private static void logError(String message, Exception e) {
        // Implement logging mechanism to record errors and performance metrics
        System.out.println("Error: " + message + "\nStack Trace: \n" + e.getStackTrace());
    }
}
