int generateUniqueFilename(const std::string& filename) {
    if (filename.empty() || !std::any_of(filename.begin(), filename.end(), ::isalnum)) {
        return -1; // error code: invalid input filename
    }

    srand(time(0)); // seed random number generator

    std::string timestamp = std::to_string(std::time(nullptr));
    int attackCooldown = 9 * 1000; // in milliseconds
    int lastAttackTime = 0;

    std::string chosenAttack;
    if (lastAttackTime + attackCooldown <= time(0) * 1000) {
        std::vector<std::string> attacks = {"attack1", "attack2"}; // more attacks can be added here
        std::uniform_int_distribution<> dist(0, attacks.size() - 1);
        chosenAttack = attacks[dist(rand)];
    } else {
        chosenAttack = "waiting_for_cooldown";
    }

    std::string randomSequence;
    for (int i = 0; i < filename.length(); i++) {
        randomSequence += static_cast<char>(rand() % 52 + 48); // alphanumeric characters
    }

    char buffer[256];
    sprintf(buffer, "%s_%s", filename.c_str(), timestamp.c_str());
    std::string newFilename = buffer;

    newFilename.append(randomSequence);
    if (chosenAttack != "waiting_for_cooldown") {
        newFilename.append("_").append(chosenAttack);
    }

    // log attack selection and timestamp to central server
    std::cout << "Attacked with " << chosenAttack << " at " << timestamp << std::endl;

    return 0; // success
}
