using System;
using System.Collections.Generic;

public class PerformanceOptimizedValueGenerator
{
    private static readonly Random _random = new Random();
    private double _minValue;
    private double _maxValue;

    public PerformanceOptimizedValueGenerator(double minValue, double maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("minValue must be less than or equal to maxValue");

        _minValue = minValue;
        _maxValue = maxValue;
    }

    public double GetRandomDouble()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public long GetRandomLong()
    {
        if (_minValue > _maxValue)
            throw new ArgumentException("minValue must be less than or equal to maxValue");

        return _random.Nextlong((_int)(_minValue), (_int)(_maxValue));
    }

    public double GetRandomDoubleExclusive()
    {
        return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public long GetRandomLongExclusive()
    {
        if (_minValue >= _maxValue)
            throw new ArgumentException("minValue must be less than maxValue");

        return _random.Nextlong((_int)_minValue, (_int)_maxValue);
    }

    public override string ToString()
    {
        return $"Range: {(_minValue == _maxValue ? $"({_minValue})" : $"[{_minValue}, {_maxValue}]")";
    }

    public List<double> GenerateSequence(int count)
    {
        var result = new List<double>();

        for (int i = 0; i < count; i++)
            result.Add(GetRandomDouble());

        return result;
    }
}
