typedef struct {
    int value;
} record;

record* allocateAndInitializeArrays(int numRecords) {
    // Pre-allocate memory for arrays
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));
    record* records = (record*)malloc(numRecords * sizeof(record));

    if (!offsets || !keys || !records) {
        // Handle allocation failure
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand(time(NULL)); // Initialize random seed

    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % 1000; // Initialize offset values randomly
        keys[i] = rand() % 10; // Initialize key values randomly
        records[i].value = rand() % 100; // Initialize record values randomly
    }

    return records;
}

void freeArrays(record* records) {
    if (!records)
        return;

    free((void*)records);
}

// Serialize data into a file
int serializeDataToFile(const char* filename, const record* records, int numRecords) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        // Handle file opening failure
        return -1;
    }

    for (int i = 0; i < numRecords; i++) {
        fwrite(&records[i], sizeof(record), 1, file);
    }

    fclose(file);
    return 0;
}

