    char** strings = (char**)allocate_and_init(dataset_size * sizeof(char*));
    vector_t** vectors = (vector_t**)allocate_and_init(dataset_size * sizeof(vector_t*));

    // Initialize logging mechanism
    FILE* log_file = fopen("data_processing.log", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file.\n");
        return 1;
    }

    // Populate data structures with dataset values
    for (size_t i = 0; i < dataset_size; ++i) {
        doubles[i] = allocate_and_init(sizeof(double));
        strings[i] = (char*)allocate_and_init(MAX_STR_LENGTH * sizeof(char));
        vectors[i] = allocate_and_init(sizeof(vector_t));

        // Handle missing or malformed data
        if (!doubles[i]) {
            fprintf(log_file, "Error allocating double array at index %zu.\n", i);
            continue;
        }

        if (!strings[i]) {
            fprintf(log_file, "Error allocating string array at index %zu.\n", i);
            continue;
        }

        if (!vectors[i]) {
            fprintf(log_file, "Error allocating vector array at index %zu.\n", i);
            continue;
        }
    }

    // Serialize data to files
    for (size_t i = 0; i < dataset_size; ++i) {
        FILE* file = fopen(sprintf("data_%zu.bin", i), "wb");
        if (!file) {
            fprintf(stderr, "Error opening output file.\n");
            return 1;
        }

        fwrite(&doubles[i], sizeof(double), 1, file);
        fwrite(strings[i], sizeof(char), strlen(strings[i]) + 1, file);
        fwrite(vectors[i], sizeof(vector_t), 1, file);

        fclose(file);
    }

    // Clean up
    for (size_t i = 0; i < dataset_size; ++i) {
        free(doubles[i]);
        free(strings[i]);
        free(vectors[i]);
    }
    free(doubles);
    free(strings);
    free(vectors);

    return 0;
}
