std::pair<int, bool> loadAndModifyResourceBundle(std::forward_list<std::string>& resourceBundle,
                                                  const std::string& targetString,
                                                  const std::string& insertionString) {
    // Load the resource bundle
    std::map<std::string, std::string> jsonMap;
    std::ifstream jsonFile("resource.json");
    if (!jsonFile.is_open()) {
        std::cerr << "Failed to open JSON file." << std::endl;
        return {1, false};
    }
    try {
        jsonFile >> jsonMap;
    } catch (std::runtime_error& e) {
        std::cerr << "Error parsing JSON: " << e.what() << std::endl;
        return {2, false};
    }

    if (!jsonMap.empty()) {
        // Convert the JSON map to a CSV string
        std::stringstream csvStream;
        for (const auto& pair : jsonMap) {
            csvStream << pair.first << "," << pair.second << "\n";
        }
        const std::string csvString = csvStream.str();

        // Load the CSV resource bundle
        std::ifstream csvFile("resource.csv");
        if (!csvFile.is_open()) {
            std::cerr << "Failed to open CSV file." << std::endl;
            return {3, false};
        }
        try {
            for (std::string line; std::getline(csvFile, line);) {
                size_t comma = line.find(',');
                resourceBundle.emplace_back(line.substr(0, comma));
            }
        } catch (std::runtime_error& e) {
            std::cerr << "Error parsing CSV: " << e.what() << std::endl;
            return {4, false};
        }

        // Modify the forward list
        auto it = resourceBundle.begin();
        bool modified = false;
        while (it != resourceBundle.end()) {
            if (it->compare(targetString) == 0) {
                resourceBundle.insert_after(it++, insertionString);
                modified = true;
                break;
            }
            ++it;
        }
        if (!modified) {
            resourceBundle.push_back(insertionString);
        }

    } else {
        // Load the XML resource bundle
        std::ifstream xmlFile("resource.xml");
        if (!xmlFile.is_open()) {
            std::cerr << "Failed to open XML file." << std::endl;
            return {5, false};
        }
        try {
            // Parse the XML string and add it to the forward list
        } catch (std::runtime_error& e) {
            std::cerr << "Error parsing XML: " << e.what() << std::endl;
            return {6, false};
        }

    }

    return {0, true};
}
