typedef struct {
    int key;
    int value;
    char* filename;
} record_t;

record_t** manage_memory(int num_records) {
    // Allocate memory for arrays
    long* offset_array = (long*)malloc(num_records * sizeof(long));
    int* key_array = (int*)malloc(num_records * sizeof(int));
    record_t* record_array = (record_t*)malloc(num_records * sizeof(record_t));

    // Initialize offset array
    for (int i = 0; i < num_records; i++) {
        offset_array[i] = i;
    }

    // Generate unique keys
    int key_range = 10000;
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        int key = rand() % key_range;
        while (find_key(key_array, i) != -1) {
            key = rand() % key_range;
        }
        key_array[i] = key;
    }

    // Generate filenames
    char* original_filename = "example.txt";
    size_t original_length = strlen(original_filename);
    for (int i = 0; i < num_records; i++) {
        char* filename = malloc(original_length + 20); // 20 bytes for random extension and timestamp
        strcpy(filename, original_filename);
        srand(time(NULL));
        for (size_t j = 0; j < original_length; j++) {
            if (!isalnum(original_filename[j])) {
                filename[j] = 'X';
            } else {
                filename[j] = original_filename[j];
            }
        }
        // Add random extension and timestamp
        srand(time(NULL));
        for (size_t j = 0; j < 10; j++) {
            filename[original_length + j] = (char)('A' + rand() % 26);
        }
        size_t timestamp_len = strftime(filename + original_length + 10, 20, "%Y%m%d%H%M%S", NULL);
        filename[original_length + 10 + timestamp_len] = '\0';
        record_array[i].filename = filename;
    }

    // Set record values
    for (int i = 0; i < num_records; i++) {
        int value_range = 100;
        record_array[i].value = rand() % value_range;
    }

    return &record_array;
}

int find_key(int* key_array, int index) {
    for (int i = 0; i <= index; i++) {
        if (key_array[i] == -1) continue;
        if (key_array[i] == key_array[index]) return i;
    }
    return -1;
}
