    printf("Peak memory consumption: %d MB.\n", (int)malloc_usage());

    my_free(records);
    return 0;
}

size_t malloc_usage() {
    size_t total = 0;
    void* ptr = sbrk(0);
    while (ptr != MAP_END) {
        size_t len = *(size_t*)ptr - (size_t)ptr;
        total += len;
        ptr += len + sizeof(size_t);
    }
    return total;
}
