#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>

// Define a file structure with metadata
typedef struct {
    char* name;
    int size;
    time_t modified_date;
} File;

// Function to manage memory for the list of 'file' structures
File** allocate_file_structures(int num_files) {
    // Allocate memory dynamically for each file structure
    File** files = (File**)malloc(num_files * sizeof(File*));

    // Initialize each file with default values
    for (int i = 0; i < num_files; i++) {
        files[i] = (File*)malloc(sizeof(File));
        files[i]->name = NULL;
        files[i]->size = -1;
        files[i]->modified_date = time(NULL);
    }

    return files;
}

// Function to read file names from a directory listing
void read_file_names(DIR* dir, File** files, int num_files) {
    // Iterate over the directory entries and validate file names
    struct dirent* entry;
    for (int i = 0; i < num_files; i++) {
        entry = readdir(dir);
        if (entry == NULL) break;

        char* name = malloc(strlen(entry->d_name) + 1);
        strcpy(name, entry->d_name);

        // Validate file name against standard naming conventions
        if (!validate_file_name(name)) {
            printf("Invalid file name: %s\n", name);
            free(name);
            continue;
        }

        files[i]->name = name;
    }

    closedir(dir);
}

// Function to read actual file size from the filesystem
void read_file_sizes(DIR* dir, File** files, int num_files) {
    // Iterate over the directory entries and read file sizes
    struct dirent* entry;
    for (int i = 0; i < num_files; i++) {
        entry = readdir(dir);
        if (entry == NULL) break;

        char path[1024];
        sprintf(path, "./%s", files[i]->name);
        FILE* file = fopen(path, "rb");
        if (file != NULL) {
            fseek(file, 0L, SEEK_END);
            files[i]->size = ftell(file);
            fclose(file);
        } else {
            printf("Error reading file size: %s\n", path);
        }
    }

    closedir(dir);
}

// Function to set the 'modified_date' field for each file
void read_modified_dates(DIR* dir, File** files, int num_files) {
    // Iterate over the directory entries and read modification dates
    struct dirent* entry;
    for (int i = 0; i < num_files; i++) {
        entry = readdir(dir);
        if (entry == NULL) break;

        char path[1024];
        sprintf(path, "./%s", files[i]->name);
        struct stat stats;
        if (stat(path, &stats) == 0) {
            files[i]->modified_date = stats.st_mtime;
        } else {
            printf("Error reading modification date: %s\n", path);
        }
    }

    closedir(dir);
}

// Function to generate a summary report for each file
void generate_summary_report(File** files, int num_files) {
    // Iterate over the files and generate reports
    for (int i = 0; i < num_files; i++) {
        printf("%-20s %10d %16.2f\n", files[i]->name, files[i]->size, (double)files[i]->modified_date / 1000000.0);
    }
}

// Function to release all allocated memory when done
void free_file_structures(File** files, int num_files) {
    // Free each file structure and its metadata
    for (int i = 0; i < num_files; i++) {
        if (files[i]->name != NULL) free(files[i]->name);
        free(files[i]);
    }

    free(files);
}

// Example usage:
int main() {
    DIR* dir;
    file = opendir("./");
    if (file == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return 1;
    }

    File** files = allocate_file_structures(10); // Adjust the number of files as needed

    read_file_names(file, files, 10);
    read_file_sizes(file, files, 10);
    read_modified_dates(file, files, 10);

    generate_summary_report(files, 10);

    free_file_structures(files, 10);

    closedir(dir);
    return 0;
}
