// Define constants
#define RECORD_SIZE sizeof(record_t)
#define KEY_RANGE 100 // Initial key range (inclusive)

// Record structure
typedef struct {
    int key;
    int value;
} record_t;

// Function to manage memory and records
void* manage_memory(int num_records) {
    // Calculate total required memory in bytes
    size_t total_memory = sizeof(long)*num_records + sizeof(int)*num_records + sizeof(record_t)*num_records;

    // Check if total memory exceeds system limit
    if (total_memory > sysconf(_SC_PAGE_SIZE) * sysconf(_SC_PHYS_PAGES)) {
        fprintf(stderr, "Error: Requested allocation exceeds system limits.\n");
        return NULL;
    }

    // Allocate memory for offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for offsets:");
        return NULL;
    }

    // Initialize offsets with consecutive integers
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
    }

    // Track last used index for each block of memory
    int* blocks = (int*)malloc(num_records * sizeof(int));
    if (!blocks) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for blocks:");
        free(offsets);
        return NULL;
    }
    for (int i = 0; i < num_records; i++) {
        blocks[i] = i;
    }

    // Allocate memory for key array and initialize with random keys
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for keys:");
        free(offsets);
        free(blocks);
        return NULL;
    }
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < num_records; i++) {
        int key;
        do {
            key = rand() % (KEY_RANGE + 1);
        } while (key == 0 || find_key(key, keys) >= 0); // Ensure unique key
        keys[i] = key;
    }

    // Allocate memory for record array and initialize with random values
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        // Handle memory allocation failure
        perror("Failed to allocate memory for records:");
        free(offsets);
        free(blocks);
        free(keys);
        return NULL;
    }
    srand(time(NULL)); // Seed random number generator
    for (int i = 0; i < num_records; i++) {
        record_t* rec = &records[i];
        rec->key = keys[i];
        rec->value = rand() % 100;
    }

    return records;
}

// Function to find the index of a key in the key array
int find_key(int key, int* keys) {
    for (int i = 0; i < num_records; i++) {
        if (keys[i] == key) {
            return i;
        }
    }
    return -1;
}

// Function to release all allocated memory and cleanup auxiliary tracking structures
void release_memory(void* records) {
    // Free record array
    free(records);

    // Free blocks array
    free(blocks);

    // Free keys array
    free(keys);

    // Free offsets array
    free(offsets);
}
