['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Task structure to hold task information and associated data
typedef struct {
    int priority;
    void (*task)(void *);
    void *data;
} Task;

// Thread-safe queue for storing tasks
pthread_mutex_t task_queue_lock = PTHREAD_MUTEX_INITIALIZER;
struct {
    Task *tasks;
    size_t capacity;
    size_t count;
} task_queue;

// Function to manage concurrent background tasks using threads and synchronization primitives
int manage_concurrent_tasks(int num_threads) {
    // Initialize thread pool with the given number of threads
    pthread_t *threads = (pthread_t *)malloc(num_threads * sizeof(pthread_t));
    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, NULL)) {
            return -1;
        }
    }

    // Start thread pool
    for (int i = 0; i < num_threads; i++) {
        pthread_detach(threads[i]);
    }

    // Return success
    return 0;
}

// Worker thread function to execute tasks from the task queue
void *worker_thread(void *) {
    while (1) {
        Task task;
        pthread_mutex_lock(&task_queue_lock);
        if (!task_queue.tasks || !task_queue.count) {
            pthread_mutex_unlock(&task_queue_lock);
            break;
        }
        task = task_queue.tasks[0];
        task_queue.tasks++;
        task_queue.count--;
        pthread_mutex_unlock(&task_queue_lock);

        // Execute the task
        task.task(task.data);

        // Release resources and reset task status
        free(task.data);
    }

    return NULL;
}

// Function to submit a new task to the task queue
int submit_task(Task *task) {
    if (pthread_mutex_lock(&task_queue_lock)) {
        return -1;
    }

    // Add the task to the end of the task queue
    task_queue.tasks = realloc(task_queue.tasks, (task_queue.count + 1) * sizeof(Task));
    task_queue.tasks[task_queue.count] = *task;
    task_queue.count++;

    pthread_mutex_unlock(&task_queue_lock);

    return 0;
}

// Function to cancel a task from the task queue
int cancel_task(int priority) {
    Task task;
    pthread_mutex_lock(&task_queue_lock);
    for (size_t i = 0; i < task_queue.count; i++) {
        if (task_queue.tasks[i].priority == priority) {
            // Remove the task from the task queue
            task_queue.tasks = realloc(task_queue.tasks, (task_queue.count - 1) * sizeof(Task));
            memcpy(&task_queue.tasks[i], &task_queue.tasks[i + 1], (task_queue.count - i - 1) * sizeof(Task));
            task_queue.count--;
            break;
        }
    }

    pthread_mutex_unlock(&task_queue_lock);

    return 0;
}

int main() {
    // Initialize the task queue
    task_queue.capacity = 10;
    task_queue.tasks = (Task *)malloc(task_queue.capacity * sizeof(Task));
    task_queue.count = 0;

    // Manage concurrent tasks using multiple threads
    manage_concurrent_tasks(5);

    // Submit tasks to the task queue
    Task task1, task2, task3;
    task1.priority = 1;
    task1.task = &task_function_1;
    task1.data = NULL;
    submit_task(&task1);
    task2.priority = 2;
    task2.task = &task_function_2;
    task2.data = NULL;
    submit_task(&task2);
    task3.priority = 3;
    task3.task = &task_function_3;
    task3.data = NULL;
    submit_task(&task3);

    // Cancel a task from the task queue
    cancel_task(1);

    return 0;
}

// Function to execute tasks of different priorities and data
void task_function_1(void *data) {
    printf("Task with priority 1 executed.\n");
}

void task_function_2(void *data) {
    printf("Task with priority 2 executed.\n");
}

void task_function_3(void *data) {
