#include <random>
#include <cmath>

class NetworkTrafficSimulator {
private:
    int minPacketSize;
    int maxPacketSize;
    double meanInterarrivalTime;
    double stdDeviation;

public:
    NetworkTrafficSimulator(int minPacketSize, int maxPacketSize)
        : minPacketSize(minPacketSize), maxPacketSize(maxPacketSize) {
        if (minPacketSize > maxPacketSize) {
            throw std::out_of_range("Min packet size cannot be greater than max packet size");
        }
    }

    int GenerateRandomPacketSize() {
        return static_cast<int>(std::uniform_int_distribution<int>(minPacketSize, maxPacketSize)(std::mt19937()));
    }

    double GenerateRandomInterarrivalTime(double mean, double stdDev) {
        std::normal_distribution<double> distribution(mean, stdDev);
        return distribution(std::mt19937());
    }

    std::vector<std::pair<int, double>> SimulateTraffic(int durationInMilliseconds, int packetSizeMean, double packetSizeStdDev, double interarrivalTimeMean, double interarrivalTimeStdDev) {
        std::vector<std::pair<int, double>> trafficData;
        std::mt19937 generator;
        for (int i = 0; i < durationInMilliseconds; i++) {
            int packetSize = GenerateRandomPacketSize();
            double interarrivalTime = GenerateRandomInterarrivalTime(interarrivalTimeMean, interarrivalTimeStdDev);
            trafficData.emplace_back(packetSize, interarrivalTime);
        }
        return trafficData;
    }

    double CalculateAverageThroughput(int durationInMilliseconds) {
        std::vector<std::pair<int, double>> trafficData = SimulateTraffic(durationInMilliseconds, 0, 0, 0, 0);
        int totalPackets = 0;
        for (const auto& packet : trafficData) {
            totalPackets += 1;
        }
        return static_cast<double>(totalPackets) / durationInMilliseconds * 1000.0;
    }

    std::string toString() {
        return "NetworkTrafficSimulator: minPacketSize=" + std::to_string(minPacketSize) +
               ", maxPacketSize=" + std::to_string(maxPacketSize) +
               ", meanInterarrivalTime=" + std::to_string(meanInterarrivalTime) +
               ", standardDeviation=" + std::to_string(stdDeviation);
    }
};
