import java.util.ArrayList;
import java.util.List;

public class StringHasher {
    private static final int MAX_ATTEMPTS = 3;
    private static final int BACKOFF_MILLIS = 500; // in milliseconds

    public List<String> processStrings(List<String> strings) throws IOException, InterruptedException {
        List<String> hashedStrings = new ArrayList<>();
        for (String string : strings) {
            if (string == null || string.isEmpty()) {
                continue;
            }
            try {
                String md5Hash = hashString(string);
                hashedStrings.add(md5Hash);
            } catch (Exception e) {
                logger.error("Error hashing string: " + string, e);
            }
        }
        return hashedStrings;
    }

    private String hashString(String input) throws IOException, InterruptedException {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] bytes = input.getBytes();
            byte[] hashBytes = md.digest(bytes);
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(Integer.toHexString((b & 0xff) | 0x100).substring(1));
            }
            return sb.toString();
        } catch (NoSuchAlgorithmException e) {
            // handle error
        }
    }

    private static final java.util.logging.Logger logger = java.util.logging.Logger.getLogger(StringHasher.class.getName());
}
