std::vector<NFAPI_Control_PDU_T> initConfigNetworkInterfaces(
    const std::vector<std::string>& interfaces,
    bool ipv4, bool ipv6, int vlan_range_start, int vlan_range_end)
{
    // Initialize vector to store configuration results
    std::vector<NFAPI_Control_PDU_T> configResults;

    for (const auto& interface : interfaces) {
        NFAPI_Control_PDU_T control_pdu;
        if (!ipv4 && !ipv6) {
            // IPv4 and IPv6 configurations are mutually exclusive, so only one will be set
            if (ipv4) {
                control_pdu.ipv4_config = true;
                control_pdu.mac_address = generateMACAddress();
                control_pdu.ip_address = generateIPv4Address();
                control_pdu.subnet_mask = generateSubnetMask();
            } else if (ipv6) {
                control_pdu.ipv6_config = true;
                control_pdu.mac_address = generateMACAddress();
                control_pdu.ip_address = generateIPv6Address();
                control_pdu.subnet_mask = generateSubnetMask();
            }
        }

        // Set VLAN range
        control_pdu.vlan_range_start = vlan_range_start;
        control_pdu.vlan_range_end = vlan_range_end;

        configResults.push_back(control_pdu);
    }

    return configResults;
}

