#include <iostream>
#include <vector>
#include <string>
#include <memory>
#include <json/json.h>

class Task {
public:
    int id;
    int priority;
    int timeout;

    Task(int id, int priority, int timeout) : id(id), priority(priority), timeout(timeout) {}
};

class TaskStatus {
public:
    int id;
    bool executed;
    int result;

    TaskStatus(int id, bool executed, int result) : id(id), executed(executed), result(result) {}
};

std::vector<TaskStatus> executeTasks(std::vector<std::string>& tasks, bool syncExec = false) {
    std::vector<Task> taskList;
    for (const auto& taskJson : tasks) {
        Json::Value jsonTask;
        jsonTask["id"] = Json::valueFromtask(taskJson);
        jsonTask["priority"] = Json::valueFromtask(taskJson, "priority");
        jsonTask["timeout"] = Json::valueFromtask(taskJson, "timeout");

        taskList.push_back(Task(jsonTask["id"].asInt(), jsonTask["priority"].asInt(), jsonTask["timeout"].asInt()));
    }

    if (syncExec) {
        // Synchronous execution
        for (auto& task : taskList) {
            std::this_thread::sleep_for(std::chrono::milliseconds(task.timeout));
            std::cout << "Task " << task.id << " executed.\n";
        }
    } else {
        // Asynchronous execution
        std::vector<std::thread> threads;
        for (auto& task : taskList) {
            threads.emplace_back([&task] {
                std::this_thread::sleep_for(std::chrono::milliseconds(task.timeout));
                std::cout << "Task " << task.id << " executed.\n";
            });
        }
        for (auto& thread : threads) thread.join();
    }

    std::vector<TaskStatus> statusList;
    for (auto& task : taskList) {
        TaskStatus status(task.id, true, 0);
        statusList.push_back(status);
    }

    return statusList;
}

int main() {
    // Example usage
    std::vector<std::string> tasks = {
        "{\"id\":1,\"priority\":2,\"timeout\":5000}",
        "{\"id\":2,\"priority\":3,\"timeout\":3000}",
        "{\"id\":3,\"priority\":1,\"timeout\":1000}"
    };

    std::vector<TaskStatus> statusList = executeTasks(tasks, false);

    // Print task statuses
    for (const auto& status : statusList) {
        std::cout << "Task " << status.id << ": Executed: " << (status.executed ? "true" : "false") << ", Result: " << status.result << "\n";
    }

    return 0;
}
```

