<?php
function authenticateViaOAuth($client_id, $client_secret, $code) {
    // Include necessary libraries and dependencies
    require_once 'vendor/autoload.php';
    use OAuth\OAuthStorage;
    use OAuth\OAuthClient;

    // Initialize the OAuth client with provided client ID, secret, and code
    $oauth = new OAuthClient($client_id, $client_secret);
    $access_token = $oauth->getAccessToken($code);

    // Store the access token in a secure session variable
    $_SESSION['access_token'] = $access_token;

    // Fetch user information using the access token
    $user_info_url = 'https://api.example.com/user-info';
    $response = json_decode($oauth->fetch($user_info_url, null, true), true);

    // Cache essential user information for future requests
    $cache_duration = 3600; // 1 hour
    $_SESSION['user_info'] = serialize(array(
        'username' => $response['username'],
        'email' => $response['email']
    ));

    // Dynamically select the cipher mode based on user input and application needs
    $cipher_mode = openssl_cipher_get_algorithms();
    $selected_cipher_mode = array_key_first($cipher_mode);

    // Return a pointer to the selected cipher mode
    return openssl_get_cipher_by_name($selected_cipher_mode);
}

// Example usage:
$access_token = authenticateViaOAuth('your_client_id', 'your_client_secret', 'code');
