class Task {
public:
    int id;
    int priority;
    int timeout;
};

class TaskStatus {
public:
    int id;
    bool completed;
    int executionTime;
};

std::vector<TaskStatus> executeTasks(std::vector<Json> tasks, bool synchronous) {
    std::vector<TaskStatus> statuses;
    std::priority_queue<Task*, std::vector<Task*>, std::greater<Task*>> taskQueue;

    for (const auto& task : tasks) {
        Task* t = new Task();
        t->id = task["id"].GetInt();
        t->priority = task["priority"].GetInt();
        t->timeout = task["timeout"].GetInt();

        taskQueue.push(t);
    }

    while (!taskQueue.empty()) {
        Task* task = taskQueue.top();
        taskQueue.pop();

        if (synchronous) {
            // Synchronous execution
            int startTime = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            // Execute the task
            // ...
            int endTime = std::chrono::high_resolution_clock::now().time_since_epoch().count();
            TaskStatus status;
            status.id = task->id;
            status.completed = true;
            status.executionTime = endTime - startTime;

            statuses.push_back(status);
        } else {
            // Asynchronous execution
            // Create a thread to execute the task
            // ...
        }
    }

    return statuses;
}
