DynamicArray* create_dynamic_array(int max_size) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) {
        return NULL;
    }
    array->size = 0;
    array->capacity = max_size;
    array->data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    if (!array) return;
    free(array->data);
    free(array);
}

int get_random_crcflag() {
    return rand() & 0x1;
}

void log_error(int error_code, const char *fmt, ...) {
    static pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&log_lock);
    va_list args;
    va_start(args, fmt);
    vsnprintf(error_log_file, sizeof(error_log_file), fmt, args);
    va_end(args);
    pthread_mutex_unlock(&log_lock);
}

void manage_crc_indication_array(int max_size) {
    DynamicArray* array = create_dynamic_array(max_size);
    if (!array) {
        log_error(1, "Failed to allocate memory for CRC indication array");
        return;
    }

    for (int i = 0; i < max_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = {0};
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand();
        pdu.CRC_INDICATION_REL8_TAG = rand();
        if (i % LOG_FLUSH_THRESHOLD == 0) {
            log_error(2, "Processed %d CRC indication PDUs");
        }
        array->data[i] = pdu;
    }

    destroy_dynamic_array(array);
}
