class Task {
public:
    int id;
    std::string dataSource;
    int priority;
};

class SensorDataProcessor {
private:
    std::vector<Task> tasks;
    std::priority_queue<Task, std::vector<Task>, decltype(&compareTasks)> taskQueue(compareTasks);
    std::mutex lock;
    std::condition_variable cv;

public:
    void addTask(Task t) {
        lock.lock();
        tasks.push_back(t);
        taskQueue.push(t);
        lock.unlock();
        cv.notify_one();
    }

    std::vector<TaskStatus> processTasks() {
        std::vector<TaskStatus> results;
        while (!taskQueue.empty()) {
            Task t = taskQueue.top();
            taskQueue.pop();
            // Process the task and get the result
            TaskStatus status = processTask(t);
            results.push_back(status);
        }
        return results;
    }

private:
    bool compareTasks(const Task& a, const Task& b) {
        return a.priority > b.priority;
    }

    TaskStatus processTask(Task t) {
        // Implement task processing logic here
        return {t.id, "Processed", true};
    }
};

// Define the DataProcessingStatus struct
struct DataProcessingStatus {
