import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;

public class StringHasher {
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_MILLIS = 1000L; // 1 second

    public List<String> hashStrings(List<String> inputStrings) {
        List<String> hashedStrings = new ArrayList<>();
        MessageDigest messageDigest;

        for (String inputString : inputStrings) {
            if (inputString == null || inputString.isEmpty()) {
                continue;
            }

            try {
                messageDigest = MessageDigest.getInstance("SHA-256");
                byte[] hashBytes = messageDigest.digest(inputString.getBytes());
                String hashString = bytesToHexString(hashBytes);
                hashedStrings.add(hashString);

                // Log the successful hashing operation
                log.info("Hashed string: " + inputString);
            } catch (NoSuchAlgorithmException e) {
                // Log and retry up to MAX_RETRIES times
                if (!handleError(e, MAX_RETRIES, BACKOFF_MILLIS)) {
                    hashedStrings.add(null); // Mark as failed
                }
            }
        }

        return hashedStrings;
    }

    private String bytesToHexString(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private boolean handleError(Throwable t, int maxRetries, long backoffMillis) {
        if (t != null) {
            log.error("Error hashing string: " + t.getMessage());
        }

        // Implement retry logic with exponential backoff
        for (int i = 0; i < maxRetries; i++) {
            try {
                // Simulate the external hashing service
                Thread.sleep(backoffMillis);
                messageDigest = MessageDigest.getInstance("SHA-256");
                // ...
                return true;
            } catch (InterruptedException | NoSuchAlgorithmException e) {
                log.error("Error retrying: " + e.getMessage());
            }
        }

        return false; // Max retries exceeded, consider further error handling
    }
}
