// Structure for record
typedef struct {
    int value;
} Record;

// Function to manage memory for three arrays
void* mem_manager(int num_records, char** filenames) {
    // Allocate memory for offset array
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) return NULL;  // Handle memory allocation failure

    // Initialize offset array with consecutive integers starting from 0
    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
    }

    // Allocate memory for key array
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) return NULL;  // Handle memory allocation failure

    // Initialize key array with unique integers chosen randomly from a specified range
    srand(time(NULL));  // Seed random number generator
    int min_key = 0, max_key = 100;
    for (int i = 0; i < num_records; i++) {
        while (1) {
            int key = rand() % (max_key - min_key + 1) + min_key;
            bool is_unique = true;
            for (int j = 0; j < i; j++) {
                if (keys[j] == key) {
                    is_unique = false;
                    break;
                }
            }
            if (is_unique) {
                keys[i] = key;
                break;
            }
        }
    }

    // Allocate memory for record array
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) return NULL;  // Handle memory allocation failure

    // Populate modified filename for each record
    char** modified_filenames = malloc(num_records * sizeof(char*));
    if (!modified_filenames) return NULL;  // Handle memory allocation failure

    for (int i = 0; i < num_records; i++) {
        char* original_filename = filenames[i];
        size_t len = strlen(original_filename);
        char* random_sequence = malloc(len + 1);  // +1 for null-terminator
        if (!random_sequence) return NULL;  // Handle memory allocation failure
        for (size_t j = 0; j < len; j++) {
            random_sequence[j] = 'a' + rand() % 26;
        }
        random_sequence[len] = '\0';
        time_t timestamp = time(NULL);
        char timestamp_str[15];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y%m%d%H%M%S", localtime(&timestamp));
        char* modified_filename = malloc(strlen(original_filename) + len + strlen(timestamp_str) + 1);
        if (!modified_filename) return NULL;  // Handle memory allocation failure
        strcpy(modified_filename, original_filename);
        strcat(modified_filename, random_sequence);
        strcat(modified_filename, timestamp_str);
        free(random_sequence);

        records[i].value = rand() % 100;

        modified_filenames[i] = modified_filename;
    }

    // Release all allocated memory when done
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; i++) {
        free(modified_filenames[i]);
    }
    free(modified_filenames);

    return records;
}
