class NFAPIControlPDU {
public:
    uint16_t vlanId;
    std::string ipVersion;
    std::string ipAddres;
    std::string subnetMask;
    std::string macAddress;

    NFAPIControlPDU(uint16_t vlanId, std::string ipVersion, std::string ipAddres,
                     std::string subnetMask, std::string macAddress)
        : vlanId(vlanId), ipVersion(ipVersion), ipAddres(ipAddres),
          subnetMask(subnetMask), macAddress(macAddress) {}
};

class HashingModule {
public:
    enum class HashingMode { ECB, EDE, EDE3, CFB };

    HashingModule(HashingMode mode, int keySize)
        : hashingMode(mode), keySize(keySize), md5Hashes() {}

    void addString(const std::string& str) {
        if (str.empty()) return;
        uint8_t* hash = nullptr;
        switch (hashingMode) {
            case HashingMode::ECB:
                hash = ecbHash(str);
                break;
            case HashingMode::EDE:
                hash = edeHash(str);
                break;
            case HashingMode::EDE3:
                hash = ede3Hash(str);
                break;
            case HashingMode::CFB:
                hash = cfbHash(str);
                break;
        }
        if (hash) {
            md5Hashes.push_back(std::string((char*)hash, 16));
            delete[] hash;
        }
    }

    std::vector<std::string> getMD5Hashes() { return md5Hashes; }

private:
    uint8_t* ecbHash(const std::string& str) {
        // ECB hashing implementation
    }

    uint8_t* edeHash(const std::string& str) {
        // EDE hashing implementation
    }

    uint8_t* ede3Hash(const std::string& str) {
        // EDE3 hashing implementation
    }

    uint8_t* cfbHash(const std::string& str) {
        // CFB hashing implementation
    }

    HashingMode hashingMode;
    int keySize;
    std::vector<std::string> md5Hashes;
};

NFAPIControlPDU_T createNFAPIControlPDU(uint16_t vlanId, std::string ipVersion,
                                          std::string ipAddres, std::string subnetMask,
                                          std::string macAddress) {
    NFAPIControlPDU_T pdu;
    pdu.vlanId = vlanId;
    pdu.ipVersion = ipVersion;
    pdu.ipAddres = ipAddres;
    pdu.subnetMask = subnetMask;
    pdu.macAddress = macAddress;
    return pdu;
}

int main() {
    // Create a set of network interfaces
    std::vector<NFAPIControlPDU_T> nfapiCtrlPDUs;

    NFAPIControlPDU_T pdu1 = createNFAPIControlPDU(100, "IPv4", "192.168.0.1",
                                                     "255.255.255.0", "00:11:22:33:44");
    NFAPIControlPDU_T pdu2 = createNFAPIControlPDU(200, "IPv6", "fc00::123",
                                                    "ffff:ffff:ffff:ffff:0000:0000:0000:0001", "55:66:77:88:99");

    nfapiCtrlPDUs.push_back(pdu1);
    nfapiCtrlPDUs.push_back(pdu2);

    // Initialize the hashing module
    HashingModule hashingModule(HashingMode::ECB, 128);

    // Add strings for hashing
    hashingModule.addString("Hello");
    hashingModule.addString("World");

    // Get the MD5 hashes
    std::vector<std::string> md5Hashes = hashingModule.getMD5Hashes();

    return 0;
}
