import java.util.*;

public class LogSummary {
    public static Summary processLogEntries(List<String> logEntries) {
        Summary summary = new Summary();
        Map<String, Long> hourlyEvents = new HashMap<>();
        Map<String, Integer> hourlyEventTypeCounts = new HashMap<>();

        for (String logEntry : logEntries) {
            String[] fields = logEntry.split(",");
            String timestamp = fields[0];
            String eventType = fields[2];

            int hour = Integer.parseInt(timestamp.substring(11, 13));
            if (!hourlyEvents.containsKey(String.valueOf(hour))) {
                hourlyEvents.put(String.valueOf(hour), 1L);
                hourlyEventTypeCounts.put(String.valueOf(hour), new HashMap<>());
            }
            long eventCount = hourlyEvents.get(String.valueOf(hour)) + 1;
            hourlyEvents.put(String.valueOf(hour), eventCount);

            if (!hourlyEventTypeCounts.get(String.valueOf(hour)).containsKey(eventType)) {
                hourlyEventTypeCounts.get(String.valueOf(hour)).put(eventType, 1);
            } else {
                int count = hourlyEventTypeCounts.get(String.valueOf(hour)).get(eventType) + 1;
                hourlyEventTypeCounts.get(String.valueOf(hour)).put(eventType, count);
            }

            // calculate average events per minute and most frequent event type
            if (eventCount > 0) {
                long minutes = eventCount / 60;
                int averageEventsPerMinute = (int) Math.round((double) minutes / eventCount * 60);
                String mostFrequentEventType = getMostFrequentEventType(hourlyEventTypeCounts.get(String.valueOf(hour)));
                summary.addHourlySummary(timestamp, eventCount, averageEventsPerMinute, mostFrequentEventType);
            }
        }

        return summary;
    }

    private static String getMostFrequentEventType(Map<String, Integer> eventTypeCounts) {
        Map.Entry<String, Integer> maxEntry = null;

        for (Map.Entry<String, Integer> entry : eventTypeCounts.entrySet()) {
            if (maxEntry == null || entry.getValue() > maxEntry.getValue()) {
                maxEntry = entry;
            }
        }

        return maxEntry != null ? maxEntry.getKey() : "";
    }
}

class Summary {
    private List<HourlySummary> hourlySummaries;

    public void addHourlySummary(String timestamp, long eventCount, int averageEventsPerMinute, String mostFrequentEventType) {
        HourlySummary summary = new HourlySummary(timestamp, eventCount, averageEventsPerMinute, mostFrequentEventType);
        if (hourlySummaries == null) {
            hourlySummaries = new ArrayList<>();
        }
        hourlySummaries.add(summary);
    }

