}

void manage_crc_indications(int N, int* crc_flags) {
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_indications) {
        fprintf(stderr, "Memory allocation failed for CRC indications.\n");
        return;
    }

    for (int i = 0; i < N; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand();
        crc_indications[i].RNTI = rand();
        crc_indications[i].CRC_INDICATION_REL8_TAG = rand();
        crc_indications[i].CRCFLAG = crc_flags[rand() % 2];
    }

    free(crc_indications);
}

void manage_error_log(int max_errors, char* error_log_file) {
    static int cached_errors = 0;
    static int flush_threshold = 100;

    while (cached_errors >= flush_threshold) {
        // Write errors to log file
        FILE* error_log = fopen(error_log_file, "a");
        if (!error_log) {
            fprintf(stderr, "Error writing to error log file.\n");
            return;
        }

        va_list ap;
        va_start(ap);
        for (int i = 0; i < cached_errors; i++) {
            // Format and write error message
            vfprintf(error_log, "%s\n", va_arg(ap, char*));
        }
        va_end(ap);

        fclose(error_log);

        cached_errors -= flush_threshold;
    }

    if (cached_errors > 0) {
        // Cache remaining errors for next flush
        printf("Cached %d error(s).\n", cached_errors);
    } else {
        printf("Error log file closed.\n");
    }
}

int main() {
    int n_long = 10, n_int = 5, max_records = 100;
    int N = 20;

    initialize_arrays(n_long, n_int, max_records);

    int crc_flags[N];
    for (int i = 0; i < N; i++) {
        crc_flags[i] = rand() % 2;
    }

    manage_crc_indications(N, crc_flags);

    manage_error_log(max_errors, error_log_file);

    return 0;
}
