char* compute_md5_hash(const char* input_string, int num_records) {
    MD5_CTX ctx;
    unsigned char buffer[16];
    char* hash = NULL;

    if (!input_string || strlen(input_string) > INT_MAX) {
        return NULL;
    }

    MD5_Init(&ctx);
    MD5_Update(&ctx, input_string, strlen(input_string));
    MD5_Final(buffer, &ctx);

    hash = (char*)malloc(33 * sizeof(char));
    sprintf(hash, "%02x%02x%02x%02x%02x%02x", buffer[0], buffer[1], buffer[2], buffer[3], buffer[4], buffer[5]);

    return hash;
}

