```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <md5.h>

#define MAX_RECORDS 1000
#define MAX_STRING_LENGTH 101
#define WARNING_LOG_SIZE 10

struct record {
    int key;
    long offset;
    char string[MAX_STRING_LENGTH];
};

struct warning_log_entry {
    time_t timestamp;
    const char *message;
};

typedef struct {
    struct record *records;
    struct warning_log_entry **warning_logs;
    int success;
} process_records_result;

process_records_result process_records(int num_records, char *string1, char *string2) {
    process_records_result result = {0};
    time_t current_time = time(NULL);

    // Allocate and initialize the records array
    struct record *records = malloc(num_records * sizeof(struct record));
    if (records == NULL) {
        return (process_records_result){NULL, NULL, 0};
    }

    for (int i = 0; i < num_records; i++) {
        // Generate random key and offset value
        records[i].key = rand() % 100;
        records[i].offset = (long) (records[i].key * 5);

        // Initialize the record string
        sprintf(records[i].string, "%s%s", string1, string2);
    }

    // Compute MD5 hash of provided strings and initialize warning log entries
    if (string1 == NULL || strlen(string1) > MAX_STRING_LENGTH - 1) {
        result.success = 0;
        result.warnings = realloc(result.warnings, WARNING_LOG_SIZE * sizeof(struct warning_log_entry));
        *(result.warnings++) = (struct warning_log_entry){current_time, "Warning: string1 is null or too long"};
    }

    if (string2 == NULL || strlen(string2) > MAX_STRING_LENGTH - 1) {
        result.success = 0;
        *result.warnings++ = (struct warning_log_entry){current_time, "Warning: string2 is null or too long"};
    }

    // Initialize the MD5 hash of concatenated strings
    char md5_string[MAX_STRING_LENGTH];
    sprintf(md5_string, "%s%s", string1, string2);
    unsigned char *md5_hash = MD5((unsigned char *)md5_string, strlen(md5_string), NULL);

    // Update the record offset values based on the MD5 hash
    for (int i = 0; i < num_records; i++) {
        records[i].offset += (long) *(md5_hash + i % MD5_DIGEST_LENGTH);
    }

    // Deallocate resources and return the result
    if (result.warnings - result.warning_logs > WARNING_LOG_SIZE) {
        for (int i = 0; i < WARNING_LOG_SIZE; i++) {
            free(result.warning_logs[i]);
        }
        free(result.warning_logs);
        result.warning_logs = NULL;
    } else {
        *result.warning_logs++ = (struct warning_log_entry){current_time, "All records processed successfully"};
    }

    return result;
}']

