        records[i].offset = (long)(records[i].key * 5);
        sprintf(records[i].string, "Record %d: key=%d offset=%ld", i+1, records[i].key, records[i].offset);
    }

    return records;
}

warning_log_entry* allocate_warning(int num_warnings) {
    warning_log_entry* warnings = (warning_log_entry*)malloc(num_warnings * sizeof(warning_log_entry));
    if (!warnings) return NULL;

    for (int i = 0; i < num_warnings; i++) {
        time_t timestamp = time(NULL);
        sprintf(warnings[i].description, "Warning %d: unknown error", i+1);
        warnings[i].timestamp = timestamp;
    }

    return warnings;
}

struct process_records_result process_records(int num_records, char* input_string1, char* input_string2) {
    struct process_records_result result;

    // Allocate and initialize the array of record structures
    record** records = allocate_record(num_records);
    if (!records) return (struct process_records_result){NULL, NULL, 0};

    // Compute the MD5 hash of the provided string
    unsigned char* md5_hash = (unsigned char*)md5(input_string1 ? input_string1 : "default_input_string", strlen(input_string1 ? input_string1 : "default_input_string"));
    if (!md5_hash) return (struct process_records_result){NULL, NULL, 0};

    // Initialize the log of warnings
    warning_log_entry** warnings = allocate_warning(num_warnings);
    int num_warnings = 0;

    result.records = records;
    result.warnings = warnings;
    result.success = 1;

    return result;
}
