struct record {
    int key;
    long offset;
    char str[101];
};

typedef struct warning_log_entry {
    time_t timestamp;
    const char* description;
} warning_log_entry;

int process_records(int key_range_start, int key_range_end, long offset_range_start, long offset_range_end,
                     const char* string1, const char* string2) {
    // Initialize MD5 context
    unsigned char md5[16];

    // Initialize record array and log array
    struct record* records = (struct record*)malloc(10 * sizeof(struct record));
    warning_log_entry* warnings = (warning_log_entry*)malloc(1000 * sizeof(warning_log_entry));

    int num_records = 0;
    for (int i = 0; i < 10; i++) {
        // Generate random key and offset
        records[i].key = rand() % (key_range_end - key_range_start) + key_range_start;
        if (records[i].key % 5 != 0)
            records[i].offset = ((records[i].key / 5) * 5) * 2;
        else
            records[i].offset = ((records[i].key / 5) * 5);

        // Concatenate strings
        char str[100];
        sprintf(str, "%s%s", string1, string2);
        strcpy(records[i].str, str);

        num_records++;
    }

    // Compute MD5 hash of concatenated strings
    unsigned char* concat_str = (unsigned char*)malloc((num_records * 101) + 1);
    for (int i = 0; i < num_records; i++) {
        strcat(concat_str, records[i].str);
    }
    MD5(concat_str, strlen(concat_str), md5);

    // Free concatenated string
    free(concat_str);

    // Initialize log entry array pointers
    warning_log_entry* current_warning = warnings;
    int num_warnings = 0;

    return (struct {
        struct record* records;
        warning_log_entry** warnings;
        int success;
    }) { .records = records, .warnings = &current_warning, .success = 1 };
}
