record** init_profiles(int num_profiles, int max_preferences) {
    // Dynamically allocate memory for arrays of records
    record** profiles = (record**)malloc(num_profiles * sizeof(record*));

    // Initialize each profile with random values
    for (int i = 0; i < num_profiles; i++) {
        profiles[i] = (record*)malloc(sizeof(record));

        // Assign a unique ID to the profile
        profiles[i]->id = rand() % 100 + 1;

        // Generate a random username and email
        sprintf(profiles[i]->username, "User-%d", i);
        sprintf(profiles[i]->email, "user%d@example.com", i);

        // Allocate memory for preferences array
        profiles[i]->preferences = (int*)malloc(max_preferences * sizeof(int));

        // Initialize preferences with random values
        for (int j = 0; j < max_preferences; j++) {
            profiles[i]->preferences[j] = rand() % 10;
        }
    }

    return profiles;
