    for (i = 0; i < numRecords; i++) {
        offsets[i] = rand() % maxOffset;
        keys[i] = rand() % maxKey;
        temperatures[i] = minTemp + (rand() / (double)RAND_MAX) * (maxTemp - minTemp);
        records[i].integer = rand() % 1000;
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].temperature = temperatures[i];
    }

    // Return the allocated memory
    return (int*)records;
}

int main() {
    int numRecords = 1000; // Specify the number of records to create
    int maxOffset = 1000000; // Specify the maximum offset value
