int insert_table_entry(table_entry_t** array, int num_entries, table_entry_t* entry) {
    // Check for uniqueness constraints for table_id and column_name
    for (int i = 0; i < num_entries; i++) {
        if (array[i]->table_id == entry->table_id || strcmp(array[i]->column_name, entry->column_name) == 0) {
            return -1;
        }
    }

    // Check for hash collisions during table_id generation
    int new_table_id = generate_table_id(num_entries);
    while (new_table_id % RESIZE_THRESHOLD < num_entries) {
        new_table_id = generate_table_id(num_entries + 1);
