typedef enum {
    INSERT_SUCCESS,
    INSERT_FAILURE_DUPLICATE_ID,
    INSERT_FAILURE_DUPLICATE_NAME
} insert_result_t;

void* fs_array = NULL;
size_t fs_capacity = 0;
size_t fs_size = 0;
file_entry_t** fs_entries = NULL;

insert_result_t insert_file_entry(file_entry_t* entry) {
    // hash function for file_id generation
    uint64_t id = (uint64_t)entry->file_name[0] * (1ull << 32) + entry->file_size;

    if (fs_size >= fs_capacity) {
        resize_fs_array();
    }

    for (size_t i = 0; i < fs_size; i++) {
        if (!strcmp(fs_entries[i]->file_name, entry->file_name)) {
            return INSERT_FAILURE_DUPLICATE_NAME;
        }
        if (id == fs_entries[i]->file_id) {
            return INSERT_FAILURE_DUPLICATE_ID;
        }
    }

    fs_entries[fs_size++] = entry;
    return INSERT_SUCCESS;
}

file_entry_t* search_file_entry_by_id(uint64_t id) {
    for (size_t i = 0; i < fs_size; i++) {
        if (id == fs_entries[i]->file_id) {
            return fs_entries[i];
        }
    }
    return NULL;
}

