    for (size_t i = 0; i < fs_size; i++) {
        if (!strcmp(fs_entries[i]->file_name, name)) {
            return fs_entries[i];
        }
    }
    return NULL;
}

void deallocate_fs_array() {
    for (size_t i = 0; i < fs_size; i++) {
        free(fs_entries[i]);
    }
    free(fs_entries);
    free(fs_array);
}

void resize_fs_array() {
    size_t new_capacity = fs_capacity * FILE_SYSTEM_GROWTH_FACTOR;
    file_entry_t** new_entries = (file_entry_t**)realloc(fs_entries, new_capacity * sizeof(file_entry_t*));
    void* new_array = realloc(fs_array, new_capacity * sizeof(file_entry_t));

    if (!new_entries || !new_array) {
        // handle error
    }

    fs_entries = new_entries;
    fs_array = new_array;
    fs_capacity = new_capacity;
}

int main(int argc, char* argv[]) {
    // parse command-line arguments: input file name, output file name, and rules string

    // allocate initial memory for file_entry_t array
    fs_array = malloc(FILE_ENTRY_ARRAY_INITIAL_CAPACITY * sizeof(file_entry_t));
    fs_entries = (file_entry_t**)malloc(FILE_ENTRY_ARRAY_INITIAL_CAPACITY * sizeof(file_entry_t*));

    fs_capacity = FILE_ENTRY_ARRAY_INITIAL_CAPACITY;
    fs_size = 0;

    // read binary input file, parse its contents, and apply transformation rules
    int input_fd = open(argv[1], O_RDONLY);
    if (input_fd < 0) {
        // handle error
    }

    size_t total_file_size = lseek(input_fd, 0, SEEK_END);

    char* buffer = malloc(total_file_size);
    read(input_fd, buffer, total_file_size);

    // implement parsing and transformation logic

    int output_fd = open(argv[2], O_WRONLY | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (output_fd < 0) {
        // handle error
    }

