        // Generate random values
        profiles[i].id = rand() % 100 + 1;
        strcpy(profiles[i].username, "User");
        sprintf(profiles[i].email, "user.%d@example.com", rand() % 100 + 1);

        // Initialize offsets and keys arrays
        offsets[i] = i * 10;
        keys[i] = i;
    }

    // Log information for each profile
    FILE *log_file = fopen("profile_log.txt", "w");
    if (log_file) {
        for (int i = 0; i < num_profiles; i++) {
            fprintf(log_file, "Profile %d: ID %d, Username %s, Email %s\n",
                    i + 1, profiles[i].id, profiles[i].username, profiles[i].email);
        }
        fclose(log_file);
    }

    // Free allocated memory
    free(profiles);
    free(offsets);
    free(keys);
}
