    float *data;
    int size;
} Vector;

// Function to initialize memory structures with provided sizes and seed the random number generator
int init_memory(int float_size, int vector_size) {
    // Initialize random number generator
    srand(time(NULL));

    // Allocate memory for float precision values
    float *float_values = (float *)malloc(float_size * sizeof(float));
    if (!float_values) return -1;

    // Allocate memory for vector objects
    Vector *vectors = (Vector *)malloc(vector_size * sizeof(Vector));
    if (!vectors) {
        free(float_values);
        return -2;
    }

    // Initialize vectors with random values
    for (int i = 0; i < vector_size; i++) {
        vectors[i].size = 10; // Initialize size to 10
        vectors[i].data = (float *)malloc(vectors[i].size * sizeof(float));
        if (!vectors[i].data) {
            free(float_values);
            for (int j = 0; j < i; j++) free(vectors[j].data);
            free(vectors);
            return -3;
        }

        // Set vector elements to random values within a specified range
        for (int j = 0; j < vectors[i].size; j++) {
            vectors[i].data[j] = (float)(rand() / (RAND_MAX / 10.0));
        }
    }

    return 0;
}

// Function to support dynamic resizing of vectors and manage memory efficiently
void resize_vector(Vector *vector, int new_size) {
    // Allocate new memory for the vector
    float *new_data = (float *)malloc(new_size * sizeof(float));
    if (!new_data) return; // If allocation fails, do nothing

    // Copy existing data to new memory block
    memcpy(new_data, vector->data, vector->size * sizeof(float));

    // Free old memory block
    free(vector->data);

    // Update vector's size and data pointer
    vector->size = new_size;
    vector->data = new_data;
}

// Function to support explicit deallocation of resources
void deallocate_memory(Vector **vectors, int vector_size) {
    for (int i = 0; i < vector_size; i++) {
        free(vectors[i]->data);
    }

    free(vectors);
}
