typedef struct {
    char username[64];
    char email[128];
    int preferences;
} UserProfile;

// Custom allocator for vectors with power-of-two strategy
void* custom_malloc(size_t size) {
    return malloc((size + 7) & ~7);
}

void custom_free(void* ptr) {
    free(ptr);
}

// Memory pool to reuse memory blocks for better performance and reduced allocation overhead
struct MemoryPool {
    void** blocks;
    int num_blocks;
    int block_size;
};

void* memory_pool_alloc(struct MemoryPool* mp, size_t size) {
    // Allocate a new block if necessary
    if (mp->num_blocks == 0 || size > mp->block_size - sizeof(void*)) {
        mp->blocks = realloc(mp->blocks, (mp->num_blocks + 1) * sizeof(void*) + mp->block_size);
        mp->num_blocks++;
    }
    // Return a block from the pool or allocate new memory if necessary
    return *(void**)(mp->blocks + (size / (int)(sizeof(void*))) % mp->num_blocks);
}

// Read-write lock for thread safety
pthread_rwlock_t rwlock;

void init_rwlock() {
    pthread_rwlock_init(&rwlock, NULL);
}

void lock_rwlock() {
    pthread_rwlock_wrlock(&rwlock);
}

void unlock_rwlock() {
    pthread_rwlock_unlock(&rwlock);
}

// Manual deallocation function to prevent memory leaks
void manual_deallocate(void* ptr) {
    custom_free(ptr);
}

// External memory management library with automatic garbage collection and memory leak detection
#include <mymemory.h>

int main() {
    // Initialize the memory pool and read-write lock
    struct MemoryPool mp;
    mp.blocks = NULL;
    mp.num_blocks = 0;
    mp.block_size = 1024;
    init_rwlock();

