    return malloc(size);
}

void* my_realloc(void* ptr, size_t size) {
    return realloc(ptr, size);
}

void my_free(void* ptr) {
    free(ptr);
}

// Initialize memory management structures with provided sizes and seed random number generator
int init_memory_management(int float_values_size, int vector_sizes[], int num_vectors) {
    // Seed the random number generator for consistent randomness across function calls
    srand(time(NULL));

    // Initialize float values structure
    FloatValues* float_values = (FloatValues*)malloc(sizeof(FloatValues));
    if (!float_values) return -1;  // Allocation failed
    float_values->values = (float*)malloc(float_values_size * sizeof(float));
    if (!float_values->values) {
        free(float_values);
        return -2;  // Allocation failed
    }
    float_values->size = float_values_size;

    // Initialize vector structures
    Vector* vectors = (Vector*)calloc(num_vectors, sizeof(Vector));
    if (!vectors) {
        free(float_values->values);
        free(float_values);
        return -3;  // Allocation failed
    }

    for (int i = 0; i < num_vectors; i++) {
        int vector_size = vector_sizes[i];
        Vector* vector = &vectors[i];

        // Initialize vector elements with random values within a specified range
        vector->elements = (float*)malloc(vector_size * sizeof(float));
        if (!vector->elements) {
            for (int j = 0; j < i; j++) {
                my_free(vectors[j].elements);
            }
            free(vectors);
            free(float_values->values);
            free(float_values);
            return -4;  // Allocation failed
        }
        vector->size = 0;
        vector->capacity = vector_size;

        // Set random values for each element in the vector
        for (int j = 0; j < vector_size; j++) {
            vector->elements[j] = (float)(rand() / (RAND_MAX + 1.0) * 10.0 - 5.0);
        }
    }

    return 0;
}

// Dynamic resizing of vectors
void resize_vector(Vector* vector, int new_capacity) {
    float* old_elements = vector->elements;
    int old_size = vector->size;

    // Reallocate memory for the vector's elements
    vector->elements = (float*)my_realloc(vector->elements, new_capacity * sizeof(float));
    if (!vector->elements) return;  // Allocation failed

    // Update the vector's size and capacity
    vector->size = old_size;
    vector->capacity = new_capacity;

    // Copy data from old memory to new memory
    for (int i = 0; i < old_size; i++) {
        vector->elements[i] = old_elements[i];
    }

    my_free(old_elements);
}

// Memory pooling implementation
void* pool_malloc(size_t size) {
    return malloc(size);
}

void pool_free(void* ptr) {
    free(ptr);
}

