    return records;
}

char* generate_random_extension(int length) {
    static char random_string[256];
    for (int i = 0; i < length; i++) {
        srand(time(NULL) + i);
        int rand_val = rand() % 52;
        if (rand_val < 26)
            sprintf(&random_string[i], "%c", 'a' + rand_val);
        else
            sprintf(&random_string[i], "%c", '0' + (rand_val - 26));
    }
    return random_string;
}

void release_records(Record* records, int num_records) {
    for (int i = 0; i < num_records; i++) {
        free(filenames[i]);
    }
    free(filenames);
    free(offsets);
    free(keys);
    free(records);
}
