#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t table_id;
    char* column_name;
    size_t data_size;
} table_entry_t;

typedef struct {
    table_entry_t** entries;
    size_t capacity;
    size_t used;
} table_entry_array_t;

table_entry_array_t* create_table_entry_array(size_t initial_capacity) {
    table_entry_array_t* array = (table_entry_array_t*)malloc(sizeof(table_entry_array_t));
    array->entries = (table_entry_t**)malloc(initial_capacity * sizeof(table_entry_t*));
    array->capacity = initial_capacity;
    array->used = 0;
    return array;
}

void resize_table_entry_array(table_entry_array_t* array, size_t new_capacity) {
    table_entry_array_t* new_array = create_table_entry_array(new_capacity);
    for (size_t i = 0; i < array->capacity; i++) {
        if (array->entries[i] != NULL) {
            new_array->entries[new_array->used++] = array->entries[i];
        }
    }
    free(array->entries);
    array->entries = new_array->entries;
    array->capacity = new_capacity;
}

table_entry_t* insert_table_entry(table_entry_array_t* array, table_entry_t* entry) {
    if (array->used == array->capacity) {
        resize_table_entry_array(array, array->capacity * 2);
    }
    for (size_t i = 0; i < array->used; i++) {
        if (array->entries[i]->table_id == entry->table_id || strcmp(array->entries[i]->column_name, entry->column_name) == 0) {
            free(entry->column_name);
            return NULL;
        }
    }
    array->entries[array->used++] = entry;
    return entry;
}

table_entry_t* search_table_entry_by_table_id(table_entry_array_t* array, uint32_t table_id) {
    for (size_t i = 0; i < array->used; i++) {
        if (array->entries[i]->table_id == table_id) {
            return array->entries[i];
        }
    }
    return NULL;
}

void deallocate_table_entry_array(table_entry_array_t* array) {
    for (size_t i = 0; i < array->capacity; i++) {
        free(array->entries[i]->column_name);
        free(array->entries[i]);
    }
    free(array->entries);
    free(array);
}
