#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_TITLE_LENGTH 256
#define INITIAL_CAPACITY 16
#define RESIZE_THRESHOLD 0.75

typedef struct {
    int media_id;
    char title[MAX_TITLE_LENGTH];
    time_t release_date;
    int duration;
} media_item_t;

media_item_t* media_items = NULL;
int num_media_items = 0;

void* allocate(int size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

void deallocate(void* ptr) {
    free(ptr);
}

media_item_t* resize_media_items() {
    media_item_t* new_items = (media_item_t*)allocate(sizeof(media_item_t) * INITIAL_CAPACITY * 2);
    if (!new_items) {
        return NULL;
    }
    memcpy(new_items, media_items, sizeof(media_item_t) * num_media_items);
    deallocate(media_items);
    media_items = new_items;
    return media_items;
}

media_item_t* insert_media_item(const char* title, time_t release_date, int duration) {
    if (num_media_items >= INITIAL_CAPACITY * RESIZE_THRESHOLD) {
        resize_media_items();
    }

    for (int i = 0; i < num_media_items; i++) {
        if (!strcmp(media_items[i].title, title)) {
            printf("Media item with this title already exists\n");
            return NULL;
        }
    }

    media_item_t* new_item = &media_items[num_media_items++];
    new_item->media_id = (int)hash(title);
    strcpy(new_item->title, title);
    new_item->release_date = release_date;
    new_item->duration = duration;

    return &media_items[num_media_items - 1];
}

media_item_t* search_media_item(int media_id) {
    for (int i = 0; i < num_media_items; i++) {
        if (media_items[i].media_id == media_id) {
            return &media_items[i];
        }
    }
    printf("Media item not found\n");
    return NULL;
}

void deallocate_media_items() {
    for (int i = 0; i < num_media_items; i++) {
        deallocate(media_items[i].title);
    }
    deallocate(media_items);
}

int hash(const char* str) {
    int result = 0;
    while (*str) {
        result ^= *str++;
    }
    return result;
}
