int init_memory(unsigned int sizes[], size_t count, unsigned int custom_seed) {
    void* ptrs[count];

    if (custom_seed > 0) {
        srand(custom_seed);
    } else {
        srand(time(NULL));
    }

    for (size_t i = 0; i < count; i++) {
