            case 0:
                ptrs[i] = malloc(sizes[0]);
                break;
            case 1:
                ptrs[i] = malloc(sizeof(char*) * sizes[1]);
                break;
            case 2:
                ptrs[i] = malloc(sizes[2] * sizeof(node_t));
                break;
            default:
                ptrs[i] = malloc(sizes[3]);
                break;
        }

        if (ptrs[i] == NULL) {
            for (size_t j = 0; j < i; j++) {
                free(ptrs[j]);
            }
            return -1;
        }
    }

    // Initialize data structures
    node_t* nodes = ptrs[2];

    for (size_t i = 0; i < sizes[2]; i++) {
        nodes[i].str = (char*) malloc((rand() % 10) + 1);
        strcpy(nodes[i].str, "Random string");

