        free(flags_allocated);

        return -1; // Error code indicating peak memory consumption reached
    } else {
        // No peak memory consumption, report and return
        printf("Peak memory consumption: %zu bytes\n", total_bytes_allocated);
        return 0; // Success code
    }
}

// Function to release all allocated memory and reset the random number generator
