            for (int i = 0; i < NUM_EVENTS; i++) {
                if (regexec(&old_testament_regexes[i], text, MAX_TIMESTAMP, NULL, 0)) {
                    book_frequency[i]++;
                    break;
                }
            }
        }
        text++;
    }

    // Release allocated memory and return frequency object
    for (int i = 0; i < num_events; i++) {
        free((void*)nodes[i]->string);
        free((void*)nodes[i]->event);
        free((void*)nodes[i]);
    }
    free(timestamps);
    free(strings);
    free(nodes);
    free(status_flags);
    free(events);
    free(old_testament_regexes);
    return book_frequency;
