#include <string.h>
#include <openssl/md5.h>

typedef struct {
    long offset;
    int key;
    char string[256];
} record;

typedef struct {
    time_t timestamp;
    const char* description;
} warning_log_entry;

struct result {
    record** records;
    warning_log_entry** warnings;
    int success;
};

record** manage_records(int num_records, int max_key_range, int min_offset_range, int max_offset_range, const char* input_string, unsigned int custom_seed) {
    srand(custom_seed);

    struct result result = {0};

    record** records = (record**)malloc(num_records * sizeof(record*));
    if (!records) return NULL;

    warning_log_entry** warnings = (warning_log_entry**)malloc(256 * sizeof(warning_log_entry*));
    if (!warnings) {
        free(records);
        return NULL;
    }

    for (int i = 0; i < num_records; i++) {
        record* r = (record*)malloc(sizeof(record));
        if (!r) {
            result.success = 0;
            for (int j = 0; j < i; j++) {
                free(records[j]);
            }
            free(records);
            for (int k = 0; k < i; k++) {
                free(warnings[k]);
            }
            free(warnings);
            return &result;
        }

        r->offset = (rand() % (max_offset_range - min_offset_range)) + min_offset_range;
        r->key = rand() % max_key_range;

        char str[256];
        sprintf(str, "random_string_%d", i);
        strcpy(r->string, str);

        records[i] = r;
    }

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, input_string, strlen(input_string));
    MD5_Final(md5, &ctx);

    for (int i = 0; i < 16; i++) {
        char c = md5[i];
        if (c > '9' || c < '0') {
            warn("Non-digit found in MD5 hash\n");
            warning_log_entry* w = (warning_log_entry*)malloc(sizeof(warning_log_entry));
            w->timestamp = time(NULL);
            sprintf(w->description, "Non-digit found at position %d", i);
            warnings[i % 256] = w;
        }
    }

    result.records = records;
    result.warnings = warnings;
    result.success = 1;

    return &result;
}
