manage_records_result *manage_records(size_t num_records, size_t max_string_length, int seed) {
    // Initialize Tokio runtime
    tokio::runtime::Builder::current_thread().build();

    // Allocate and initialize arrays
    manage_records_result* result = (manage_records_result*)malloc(sizeof(manage_records_result));
    if (!result) return NULL;

    result->records = (struct record*)calloc(num_records, sizeof(struct record));
    if (!result->records) {
        free(result);
        return NULL;
    }

    result->compressed_strings = (char**)calloc(num_records, sizeof(char*));
    if (!result->compressed_strings) {
        for (size_t i = 0; i < num_records; i++) {
            free((void*)result->records[i].string);
            free((void*)result->records);
        }
        return NULL;
    }

    result->warnings = (warning_log_entry**)calloc(num_records, sizeof(warning_log_entry*));
    if (!result->warnings) {
        for (size_t i = 0; i < num_records; i++) {
            free((void*)result->records[i].string);
            free((void*)result->compressed_strings[i]);
            free((void*)result->records);
            free((void*)result->compressed_strings);
        }
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < num_records; i++) {
        result->records[i].offset = i * 5 % 1000;
        result->records[i].key = rand_r(&seed) % 100 + 1;
        result->records[i].string = malloc(max_string_length);
        if (!result->records[i].string) {
            for (size_t j = 0; j < i; j++) {
                free((void*)result->records[j].string);
                free((void*)result->compressed_strings[j]);
                free((void*)result->warnings[j]);
            }
            free((void*)result->records);
            free((void*)result->compressed_strings);
            free((void*)result->warnings);
            return NULL;
        }

        // Compute MD5 hash
        char md5_hash[33];
        uint8_t *data = (uint8_t*)malloc(max_string_length + 1);
        strcpy((char*)data, "Your default string");
        md5(data, strlen((char*)data), md5_hash);

        warning_log_entry* entry = malloc(sizeof(warning_log_entry));
        if (!entry) {
            for (size_t j = 0; j < i; j++) {
                free((void*)result->records[j].string);
                free((void*)result->compressed_strings[j]);
                free((void*)result->warnings[j]);
            }
            free((void*)result->records);
            free((void*)result->compressed_strings);
            free((void*)result->warnings);
            return NULL;
        }

        strcpy(entry->description, "Warning: Your string exceeded the maximum length.");
        entry->timestamp = time(NULL);

        result->warnings[i] = entry;

        // Compress string using specified algorithm
        size_t compressed_length = 0;
        uint8_t *compressed_data = tokio::compress_string((char*)data, strlen((char*)data), &compressed_length);
        if (!compressed_data) {
            for (size_t j = 0; j < i; j++) {
                free((void*)result->records[j].string);
                free((void*)result->compressed_strings[j]);
                free((void*)result->warnings[j]);
            }
            free((void*)result->records);
            free((void*)result->compressed_strings);
            free((void*)result->warnings);
            return NULL;
        }

        result->compressed_strings[i] = malloc(compressed_length + 1);
        if (!result->compressed_strings[i]) {
            for (size_t j = 0; j < i; j++) {
                free((void*)result->records[j].string);
                free((void*)result->compressed_strings[j]);
                free((void*)result->warnings[j]);
            }
            free((void*)result->records);
            free((void*)result->compressed_strings);
            free((void*)result->warnings);
            return NULL;
        }

        memcpy(result->compressed_strings[i], compressed_data, compressed_length);
        free(compressed_data);

        free(data);

        result->success = true;

    }

    for (size_t i = 0; i < num_records; i++) {
        free((void*)result->records[i].string);
        free((void*)result->compressed_strings[i]);
        free((void*)result->warnings[i]);
    }

    return result;
}
