typedef struct {
    long offset;
    int key;
    char *str;
} record;

typedef struct {
    time_t timestamp;
    const char *description;
} warning_log_entry;

struct result {
    record **records;
    warning_log_entry **log_entries;
    char **compressed_strings;
    bool success;
};

record* manage_records(int num_records, int key_range_start, int key_range_end,
                        int offset_range_start, int offset_range_end, const char *seed_string,
                        const char *algorithm, char *encoding, int max_compression_level) {
    // Initialize Tokio runtime
    tokio::runtime::Runtime::new_multi_thread();

    // Seed random number generator
    srand((unsigned)time(NULL));

    // Allocate memory for records
    record **records = (record **)malloc(num_records * sizeof(record *));
    if (!records) return NULL;

    // Initialize array of records with default values
    for (int i = 0; i < num_records; i++) {
        records[i] = (record *)malloc(sizeof(record));
        if (!records[i]) {
            // Release memory and return error code on failure
            while (--i >= 0) free(records[i]);
            free(records);
            return NULL;
        }
        records[i]->key = rand() % (key_range_end - key_range_start + 1) + key_range_start;
        records[i]->offset = i * 5 + rand() % (offset_range_end - offset_range_start + 1) + offset_range_start;
    }

    // Allocate memory for warning log entries
    warning_log_entry **log_entries = (warning_log_entry **)malloc(num_records * sizeof(warning_log_entry *));
    if (!log_entries) return NULL;

    // Initialize array of warning log entries with default values
    for (int i = 0; i < num_records; i++) {
        log_entries[i] = (warning_log_entry *)malloc(sizeof(warning_log_entry));
        if (!log_entries[i]) {
            // Release memory and return error code on failure
            while (--i >= 0) free(log_entries[i]);
            free(log_entries);
            for (int j = 0; j < i + 1; j++) free(records[j]);
            free(records);
            return NULL;
        }
    }

    // Allocate memory for compressed strings
    char **compressed_strings = (char **)malloc(num_records * sizeof(char *));
    if (!compressed_strings) return NULL;

    // Initialize array of compressed strings with default values
    for (int i = 0; i < num_records; i++) {
        compressed_strings[i] = (char *)malloc(max_compression_level + 1);
        if (!compressed_strings[i]) {
            // Release memory and return error code on failure
            while (--i >= 0) free(compressed_strings[i]);
            free(compressed_strings);
            for (int j = 0; j < i + 1; j++) free(records[j]->str);
            for (int j = 0; j <= i; j++) free(log_entries[j]);
            return NULL;
        }
    }

    // Initialize result struct
    struct result result;
    result.records = records;
    result.log_entries = log_entries;
    result.compressed_strings = compressed_strings;
    result.success = true;

    return &result;
}
