    try {
        offset_memory = malloc(offset_size * sizeof(long));
        if (!offset_memory) {
            throw "Offset allocation failed";
        }
        key_memory = malloc(key_size * sizeof(int));
        if (!key_memory) {
            free(offset_memory);
            throw "Key allocation failed";
        }
        record_memory = malloc(record_size * sizeof(struct record));
        if (!record_memory) {
            free(offset_memory);
            free(key_memory);
            throw "Record allocation failed";
        }

        for (size_t i = 0; i < offset_size; i++) {
            ((long*)offset_memory)[i] = rand() % (max_value - min_value + 1) + min_value;
        }
        for (size_t i = 0; i < key_size; i++) {
            ((int*)key_memory)[i] = rand() % (max_value - min_value + 1) + min_value;
        }
        for (size_t i = 0; i < record_size; i++) {
            ((struct record*)record_memory)[i].value = rand() % (max_value - min_value + 1) + min_value;
        }

        free(offset_memory);
        free(key_memory);
        free(record_memory);

        return 0;

    } catch(const char* message) {
        if (offset_memory) {
            free(offset_memory);
        }
        if (key_memory) {
            free(key_memory);
        }
        if (record_memory) {
            free(record_memory);
