#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int key;
    long offset;
} Record;

Record* createRecord(int key, long offset) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->offset = offset;
    return record;
}

void deleteRecord(Record* record) {
    free(record);
}

int findRecordKey(Record* records, int key, size_t len) {
    for (size_t i = 0; i < len; i++) {
        if (records[i]->key == key)
            return i;
    }
    return -1;
}

void insertRecord(Record** records, int key, long offset, size_t* len) {
    Record* newRecord = createRecord(key, offset);
    (*len)++;
    *records = realloc(*records, sizeof(Record*) * (*len));
    (*records)[*len - 1] = newRecord;
}

void updateRecord(Record** records, int key, long offset, size_t* len) {
    size_t idx = findRecordKey(*records, key, *len);
    if (idx != -1) {
        Record* record = (*records)[idx];
        deleteRecord(record);
        record->offset = offset;
        insertRecord(records, key, offset, len);
    }
}

void clearUnusedRecords(Record** records, size_t* len, size_t threshold) {
    for (size_t i = 0; i < *len; i++) {
        if ((*records)[i]->key == -1) {
            Record* record = (*records)[i];
            deleteRecord(record);
            memmove(&(*records)[i], &(*records)[i + 1], sizeof(Record*) * (*len - i - 1));
            (*len]--;
            i--;
        } else if ((*records)[i]->key > threshold) {
            Record* record = (*records)[i];
            deleteRecord(record);
            memmove(&(*records)[i], &(*records)[i + 1], sizeof(Record*) * (*len - i - 1));
            (*len]--;
            i--;
        }
    }
}

void printRecords(Record* records, size_t len) {
    for (size_t i = 0; i < len; i++) {
        printf("Key: %d Offset: %ld\n", records[i]->key, records[i]->offset);
    }
}

int main() {
    Record* records = NULL;
    size_t len = 0;

    // Test the function
    insertRecord(&records, 1, 100, &len);
    insertRecord(&records, 2, 200, &len);
    insertRecord(&records, 3, 300, &len);
    updateRecord(&records, 1, 150, &len);
    clearUnusedRecords(&records, &len, 2);
    printRecords(records, len);

    // Free memory
    for (size_t i = 0; i < len; i++) {
        deleteRecord(records[i]);
    }
    free(records);

    return 0;
}
