["Here is the C code for the scalable library:

```c
#include <stdlib.h>
#include <stdio.h>

// Define the structure for storing record information
typedef struct {
    int key;
    long offset;
} Record;

// Define the structure for managing records in memory
typedef struct {
    Record* records;  // Pointer to array of records
    size_t capacity;   // Capacity of the array (i.e., number of slots)
    size_t count;      // Current number of used slots
    size_t threshold;  // Performance threshold in bytes
} RecordStore;

// Function to create a new record store with initial capacity and threshold
RecordStore* record_store_new(size_t initial_capacity, size_t threshold) {
    RecordStore* rs = (RecordStore*)malloc(sizeof(RecordStore));
    rs->records = (Record*)calloc(initial_capacity, sizeof(Record));
    rs->capacity = initial_capacity;
    rs->count = 0;
    rs->threshold = threshold;
    return rs;
}

// Function to free a record store and its associated memory
void record_store_free(RecordStore* rs) {
    if (rs == NULL)
        return;

    // Free the records array
    if (rs->records != NULL)
        free(rs->records);

    // Free the record store itself
    free(rs);
}

// Function to insert a new record into the store, efficiently handling memory allocation and deallocation
void record_store_insert(RecordStore* rs, int key, long offset) {
    // Check if there's room for another record without exceeding threshold
    if (rs->count >= rs->capacity && (rs->threshold - (size_t)(sizeof(Record)) * (rs->capacity + 1)) < sizeof(Record)) {
        // Resize the array and update capacity
        size_t new_capacity = rs->capacity * 2;
        Record* new_records = (Record*)realloc(rs->records, sizeof(Record) * new_capacity);
        rs->records = new_records;
        rs->capacity = new_capacity;
    }

    // Insert the record
    Record* pos = &(rs->records[rs->count]);
    pos->key = key;
    pos->offset = offset;
    rs->count++;
}

// Function to update an existing record in the store, efficiently handling memory allocation and deallocation
void record_store_update(RecordStore* rs, int key, long new_offset) {
    // Find the record with matching key
    for (size_t i = 0; i < rs->count; i++) {
        if (rs->records[i].key == key) {
            // Update the offset and return
            rs->records[i].offset = new_offset;
            return;
        }
    }

    // Record not found, handle error or ignore
}

// Function to retrieve a record by its integer key, handling cases where the record may not exist
Record* record_store_lookup(RecordStore* rs, int key) {
    for (size_t i = 0; i < rs->count; i++) {
        if (rs->records[i].key == key)
            return &(rs->records[i]);
    }
    return NULL;
}

// Function to delete a record by its integer key
void record_store_remove(RecordStore* rs, int key) {
    // Find the record with matching key
    for (size_t i = 0; i < rs->count; i++) {
        if (rs->records[i].key == key) {
            // Shift remaining records and adjust count
            memmove(&(rs->records[i]), &(rs->records[i + 1]), sizeof(Record) * (rs->count - i));
            rs->count--;
            return;
        }
    }

    // Record not found, handle error or ignore
}

int main() {
    RecordStore* rs = record_store_new(16, 1024);
    // Use the record store as needed...
    return 0;
}
