void manage_memory() {
    srand(time(NULL)); // set seed for reproducibility

    // initialize arrays
    double* d = (double*)malloc(10000 * sizeof(double));
    Complex* c = (Complex*)malloc(5000 * sizeof(Complex));
    Record* r = (Record*)malloc(2000 * sizeof(Record));
    Transaction* t = NULL;

    for (int i = 0; i < 5000; i++) {
        c[i].re = (double)rand() / RAND_MAX;
        c[i].im = &d[rand() % 10000];
    }

    for (int i = 0; i < 2000; i++) {
        r[i].value = rand() % 1000;
    }

    // initialize hashmap
    // ...

    while (1) {
        t = insert_transaction(t, "transaction");
        if (t == NULL) break;

        t->timestamp = time(NULL);
        if (strcmp(t->data, "") == 0) break; // handle empty strings

        filter_transactions(t);

        free_transaction(t);

        if (t != NULL) {
            int max_weight = 0;
            char* max_id = "";
            Transaction* temp = t;
            while (temp != NULL) {
                if (temp->timestamp < time(NULL) - 3) break; // handle transactions older than 3 seconds
                double weight = (double)r[temp->index].value + c[temp->index].re;
                if (weight > max_weight) {
                    max_weight = weight;
                    max_id = temp->data;
                }
                temp = temp->next;
            }

            printf("Max weighted sum: %f, ID: %s\n", max_weight, max_id);

            free_transaction(t);
        }
    }

    free(d);
    free(c);
    free(r);
