        offsets[i] = (long)i;
        keys[i] = i % 100;
    }

    // Allocate memory for records, aligned to ALIGNMENT
    size_t recordSize = sizeof(record);
    size_t alignmentOffset = recordSize % ALIGNMENT;
    size_t totalRecordSize = numRecords * recordSize + alignmentOffset;

    char* recordMemory = (char*)malloc(totalRecordSize);

    if (!recordMemory) {
        printf("Memory allocation failed.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Align memory
    void* alignedRecord = (void *)((size_t)recordMemory + alignmentOffset);

    record* records = (record*)alignedRecord;

    // Initialize records
    for (int i = 0; i < numRecords; i++) {
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

