typedef struct {
    int value;
} record;

void initialize_records(long** offset_values, int** keys, record*** records, int max_records) {
    if (*records != NULL) return; // Ensure memory is not reallocated unnecessarily

    // Allocate memory for the arrays
    *offset_values = (long*)malloc(sizeof(long) * max_records);
    *keys = (int*)malloc(sizeof(int) * max_records);
    *records = (record**)malloc((max_records + RECORD_ALIGNMENT / sizeof(record)) * sizeof(record*));

    if (*offset_values == NULL || *keys == NULL || *records == NULL) {
        // Handle allocation failure gracefully
        free(*offset_values);
        free(*keys);
        free(*records);
        return;
    }

    // Initialize the record structures with random values within a specified range
    int min_value = 0, max_value = 100;
    srand(time(NULL));
    for (int i = 0; i < max_records; i++) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Handle allocation failure gracefully
            for (int j = 0; j <= i; j++) free((*records)[j]);
            return;
        }
        (*records)[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return;
}
