int init_list(struct Node** head, int max_size) {
    *head = NULL;
    int total_allocated = 0;

    for(int i = 0; i < max_size; i++) {
        void* temp = allocate_node();
        if(temp == NULL || ((struct Node*)temp)->obj.value != 0.0) {
            free((struct Node*)temp);
            return -1;
        }
        struct Node* node = (struct Node*)temp;
        node->next = *head;
        *head = node;
        total_allocated += sizeof(struct Node);
    }

    return total_allocated;
}

