#include <stdlib.h>
#include <stdio.h>

// Define the 'struct element' type
typedef struct {
    int i;
    float f;
    struct shared_data *s;
} struct_element;

// Define the 'node' structure
typedef struct node {
    struct_element *e;
    int index;
    char label;
    struct node *next;
} node;

void init_nodes(int max_size) {
    // Allocate memory for arrays
    double *doubles = (double *)malloc(max_size * sizeof(double));
    char *chars = (char *)malloc(max_size * sizeof(char));
    struct_element **elements = (struct_element **)malloc(max_size * sizeof(struct_element *));
    node **nodes = (node **)malloc(max_size * sizeof(node *));

    // Initialize arrays
    for (int i = 0; i < max_size; i++) {
        doubles[i] = 0.0;
        chars[i] = '\0';
        elements[i] = NULL;
        nodes[i] = NULL;
    }

    // Free allocated memory
    free(doubles);
    free(chars);
    free(elements);
    free(nodes);
}

void insert_node(node **head, int index, char label) {
    node *new_node = (node *)malloc(sizeof(node));
    new_node->e = NULL;
    new_node->index = index;
    new_node->label = label;

    if (*head == NULL || (*head)->next == NULL) {
        // If the list is empty or only contains one node, set the head
        *new_node->next = *head;
        *head = new_node;
    } else {
        // Find the last node in the list and append the new node
        node *last_node = *head;
        while (last_node->next) {
            last_node = last_node->next;
        }
        last_node->next = new_node;
    }
}

void delete_node(node **head, int index) {
    if (*head == NULL || (*head)->index != index) {
        return; // Node not found
    }

    node *current = *head;
    node *previous = NULL;

    while (current && current->index != index) {
        previous = current;
        current = current->next;
    }

    if (current == NULL || current->index != index) {
        return; // Node not found
    }

    if (previous == NULL) {
        // If the node to be deleted is the head, update the head
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

// Function to handle memory allocation failures
void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}
