    if (!offsets) return NULL;

    int* keys = malloc((size / 2) * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    record* records = malloc(size * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return NULL;
