    for (int i = 0; i < size / 2; i++) {
        keys[i] = rand() % 1000;
    }
    for (int i = 0; i < size; i++) {
        record r;
        do {
            r.value = rand() % 1000;
        } while (i > 0 && findKey(keys, i / 2) == r.value);
        records[i] = r;
    }

    return records;
}

int findKey(int* keys, int index) {
    if (index < 0 || index >= size / 2)
        return -1;
    return keys[index];
}

void printArrays(long* offsets, int* keys, record* records, int size) {
    for (int i = 0; i < size; i++) {
        printf("offset: %ld, key: %d, record: %d\n", offsets[i], keys[i / 2], records[i].value);
    }
}

