    srand(time(NULL));
    int size = 10;
    record* records = initializeArrays(size);
    if (records) {
        printArrays((long*)malloc(size * sizeof(long)), malloc((size / 2) * sizeof(int)), records, size);
        free(records);
    }
    return 0;
