sensor* generate_sensors(int size, char** locations) {
    sensor* sensors = (sensor*)malloc(size * sizeof(sensor));
    if (!sensors) return NULL;

    srand(time(NULL));

    for (int i = 0; i < size; i++) {
        sensors[i].temp = (double)(rand() % 170 - 50);
        int location_index = i % ((size / 3) + 1);
        if (!locations[location_index]) {
            locations[location_index] = (char*)malloc(16 * sizeof(char));
            sprintf(locations[location_index], "Location_%d", i);
        }
        sensors[i].timestamp = time(NULL) + i;
    }

    return sensors;
}

void print_data(double* temperatures, sensor* sensors, char** locations, int size) {
    for (int i = 0; i < size; i++) {
        printf("Temperature: %.2f°C, Location: %s, Timestamp: %d (%02d:%02d:%02d)\n",
               temperatures[i], locations[i], sensors[i].timestamp,
               sensors[i].timestamp / 3600 / 60, (sensors[i].timestamp / 3600) % 60,
               (sensors[i].timestamp / 60) % 60);
    }
}

