    int size;
    printf("Enter the size of the arrays: ");
    scanf("%d", &size);

    double* temperatures = (double*)malloc(size * sizeof(double));
    if (!temperatures) return 1;

    char** locations = (char**)calloc((size / 3), sizeof(char*));
    for (int i = 0; i < size / 3; i++) {
        locations[i] = NULL;
    }

    sensor* sensors = generate_sensors(size, locations);
    if (!sensors) {
        free(temperatures);
        for (int i = 0; i < size / 3; i++) {
            if (locations[i]) free(locations[i]);
        }
        free(locations);
        return 1;
