    srand(time(NULL));
    for (i = 0; i < size; i++) {
        temperatures[i] = gaussian_temperature(25, 15);
    }

    // Allocate memory for sensors array and initialize each sensor with random temperature value
    sensor *sensors = (sensor *)malloc(size * sizeof(sensor));
    if (!sensors) {
        free(temperatures);
        return NULL;
    }
    for (i = 0; i < size; i++) {
        sensors[i].temperature = temperatures[i];
        sensors[i].timestamp = time(NULL) + i;
    }

    // Allocate memory for locations array and initialize each location with a random value
    char **locations = (char **)malloc(location_size * sizeof(char *));
    if (!locations) {
        free(temperatures);
        free(sensors);
        return NULL;
    }
    int j = 0;
    for (i = 0; i < size; i++) {
        locations[j] = strcpy(malloc(strlen(locations[0]) + 1), locations[i % 4]);
        if (!locations[j]) {
            for (int k = 0; k <= j; k++) {
                free(locations[k]);
            }
            free(temperatures);
            free(sensors);
            return NULL;
        }
        j++;
    }

    // Allocate memory for event log array
    int event_log_size = size / 10;
    event_log *event_log = (event_log *)malloc(event_log_size * sizeof(event_log));
    if (!event_log) {
        for (int k = 0; k <= location_size; k++) {
            free(locations[k]);
        }
        free(temperatures);
        free(sensors);
        return NULL;
    }

    // Populate event log array
    for (i = 0; i < event_log_size; i++) {
        event_log[i].temperature = temperatures[i];
        strcpy(event_log[i].location, locations[i % location_size]);
        event_log[i].timestamp = sensors[i].timestamp;
        event_log[i].error_flag = rand() % 2;

    }

    return sensors;
}

int main() {
    int size;
    printf("Enter the size of arrays: ");
    scanf("%d", &size);

    sensor *sensors = generate_arrays(size);
    if (!sensors) {
        printf("Error allocating memory. Returning NULL.\n");
    } else {
        print_arrays(sensors, temperatures, locations, event_log);
    }

    return 0;
}
