Sensor* validateSensors(Sensor* sensors, int numSensors) {
    // Iterate over the array of sensors
    for (int i = 0; i < numSensors - 1; i++) {
        // Check if two consecutive sensors have the same location
        if (!strcmp(sensors[i].temperature)) {
            // Round temperature to nearest valid value
            sensors[i].temperature = fmin(fmax(-50.0, sensors[i].temperature), 120.0);
        }
    }
    return sensors;
}

