void printSensors(Sensor* sensors, int numSensors) {
    // Iterate over the array of sensors
    for (int i = 0; i < numSensors; i++) {
        printf("Temperature: %f, Timestamp: %d\n", sensors[i].temperature, sensors[i].timestamp);
    }
}

// Function to get current time and increment by one second
time_t getCurrentTimeAndIncrement() {
    time_t currentTime = time(NULL);
    if (currentTime == -1) {
        printf("Error getting current time. Using default start time.\n");
        return 0;
    } else {
        return currentTime + 1;
    }
}

// Main function to allocate memory and initialize arrays
int main() {
    int temperaturesSize = 0; // Get size from user input

    // Calculate initial buffer for temperatures array
    temperaturesSize += (int)round(temperaturesSize * 0.10);

    double* temperatures = (double*)malloc(sizeof(double) * temperaturesSize);
    if (!temperatures) {
        printf("Error allocating memory for temperatures.\n");
        return NULL;
    }

    // Calculate initial buffer for sensors array
    int numSensors = temperaturesSize + (int)round(temperaturesSize * 0.20);
    Sensor* sensors = (Sensor*)malloc(sizeof(Sensor) * numSensors);
    if (!sensors) {
        free(temperatures); // Free previously allocated memory
        return NULL;
    }

    // Calculate initial buffer for locations array
    int locationsSize = temperaturesSize / 3;
    char** locations = (char**)malloc(sizeof(char*) * locationsSize);
    if (!locations) {
        free(sensors); // Free previously allocated memory
        return NULL;
    }

    // Initialize sensors and timestamps
    time_t currentTimeAndIncremented = getCurrentTimeAndIncrement();
    for (int i = 0; i < numSensors; i++) {
        sensors[i].temperature = fmin(fmax(-50.0, rand() / (RAND_MAX + 1.0)), 120.0);
        sensors[i].timestamp = time(NULL) - currentTimeAndIncremented + i;
    }

    // Print sensor data for debugging
    printSensors(sensors, numSensors);

    return 0;
}
