#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    double temperature;
    int timestamp;
} sensor;

typedef struct {
    double value;
} event_log;

void generate_data(int size, double* temperatures, char** locations, sensor** sensors, event_log** log, int num_locations) {
    srand(time(NULL));

    // Initialize configuration
    double lower_bound = 0.0;
    double upper_bound = 0.0;
    int frequency = 0;
    int max_delay = 0;

    // Validate and configure parameters
    if (size <= 0 || frequency < 1 || max_delay < 0) {
        printf("Invalid configuration.\n");
        return;
    }

    // Generate temperatures
    for (int i = 0; i < size; i++) {
        double temp = (rand() / (double)RAND_MAX * 30.0 + 25.0); // Random temperature between 25 and 55 degrees Celsius
        if (temp < lower_bound || temp > upper_bound) {
            printf("Temperature %f out of range.\n", temp);
            return;
        }
        temperatures[i] = temp;
    }

    // Generate sensors with timestamps
    for (int i = 0; i < size; i++) {
        sensor* current_sensor = &sensors[i];
        int timestamp = time(NULL) + rand() % max_delay;
        current_sensor->temperature = temperatures[i];
        current_sensor->timestamp = timestamp;

        // Reuse location identifiers
        int location_id = i % num_locations;
        for (int j = 0; j < size; j++) {
            if (i == j) continue;
            if (locations[j] == NULL || !strcmp(locations[i], locations[j])) {
                location_id = j % num_locations;
                break;
            }
        }

        current_sensor->location = locations[location_id];
    }

    // Initialize event log
    int log_size = size / 10 + 1;
    for (int i = 0; i < log_size; i++) {
        event_log* current_log = &log[i];
        current_log->value = temperatures[i % size];
        current_log->error = rand() % 2 ? 0 : 1;
    }

    // Print data
    for (int i = 0; i < size; i++) {
        printf("Temperature: %f, Location: %s, Timestamp: %ld\n", temperatures[i], sensors[i].location, (long long)sensors[i].timestamp);
    }

    // Print event log summary
    int successful_readings = 0;
    int failed_readings = 0;
    for (int i = 0; i < log_size; i++) {
        if (log[i]->error == 0) {
            successful_readings++;
        } else {
            failed_readings++;
        }
    }
    printf("Event Log: Successful Readings: %d, Failed Readings: %d\n", successful_readings, failed_readings);
}

int main() {
    int size = 10;
    double* temperatures = (double*)malloc(size * sizeof(double));
    char** locations = (char**)malloc((size / 3 + 1) * sizeof(char*));
    sensor** sensors = (sensor**)malloc(size * sizeof(sensor));
    event_log** log = (event_log**)malloc((size / 10 + 1) * sizeof(event_log));

    // Initialize locations and generate random location identifiers
    for (int i = 0; i < size / 3 + 1; i++) {
        locations[i] = (char*)malloc(strlen("Location ") + strlen("123456789") + 1);
        sprintf(locations[i], "Location %s", "123456789"[i % strlen("123456789")]);
    }

    // Generate and print data
    generate_data(size, temperatures, locations, sensors, log, size / 3 + 1);

    // Free allocated memory
    for (int i = 0; i < size / 3 + 1; i++) {
        free(locations[i]);
    }
    free(locations);
    free(sensors);
    free(log);
    free(temperatures);

    return 0;
}

