#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

struct record {
    float sensor_reading;
    long timestamp;
    int device_identifier;
    int status_flag;
};

struct sensor_metadata {
    char sensor_name[33]; // 32 for the string and 1 for null terminator
    double calibration_factor;
};

void print_arrays(long num_records, struct record* records, struct sensor_metadata* metadata) {
    for (long i = 0; i < num_records; i++) {
        printf("Record %ld:\n", i);
        printf("Sensor reading: %.2f\n", records[i].sensor_reading);
        printf("Timestamp: %s\n", ctime(&records[i].timestamp));
        printf("Device identifier: %d\n", records[i].device_identifier);
        printf("Status flag: %d\n", records[i].status_flag);
        printf("Sensor metadata: Name - %s, Calibration factor - %.2lf\n", 
               metadata[i].sensor_name, metadata[i].calibration_factor);
        printf("\n");
    }
}

void* validate_records(long num_records, struct record* records) {
    for (long i = 0; i < num_records; i++) {
        if (records[i].device_identifier == records[i+1].device_identifier) {
            return NULL;
        }
        if (records[i].sensor_reading < -100 || records[i].sensor_reading > 200) {
            records[i].sensor_reading = roundf(records[i].sensor_reading);
        }
    }
    return records;
}

long* get_timestamps(long num_records, long start_time) {
    long* timestamps = (long*)malloc((num_records + 1) * sizeof(long));
    if (!timestamps) {
        return NULL;
    }
    time_t current_time = time(NULL);
    if (current_time == -1) {
        printf("Warning: Unable to get the current system time.\n");
        current_time = 0;
    }
    for (long i = 0; i < num_records; i++) {
        timestamps[i] = start_time + (i * 1000);
    }
    timestamps[num_records] = '\0';
    return timestamps;
}

void seed_random() {
    srand(12345); // Custom seed
}

int main() {
    long num_records = 10;
    long* timestamps = get_timestamps(num_records, 0);
    if (!timestamps) {
