    struct sensor_metadata* metadata = (struct sensor_metadata*)malloc(num_records * sizeof(struct sensor_metadata));
    if (!metadata) {
        free(records);
        free(timestamps);
        return -1;
    }

    char** sensor_names = (char**)malloc((num_records / 2 + 1) * sizeof(char*));
    for (long i = 0; i < num_records / 2; i++) {
        sensor_names[i] = (char*)malloc(33 * sizeof(char));
        if (!sensor_names[i]) {
            for (long j = 0; j <= i; j++) {
                free(sensor_names[j]);
            }
            free(metadata);
            free(records);
            free(timestamps);
            return -1;
        }
    }

    // Initialize arrays

    seed_random();

