#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int value;
    char* str;
} Record;

struct HashTable {
    long* keys;
    Record** records;
    int size;
};

void hash_table_init(struct HashTable* table, int size) {
    table->size = size;
    table->keys = (long*)malloc(sizeof(long) * size);
    table->records = (Record**)malloc(sizeof(Record*) * size);

    for(int i = 0; i < size; i++) {
        table->keys[i] = -1;
        table->records[i] = NULL;
    }
}

void hash_table_insert(struct HashTable* table, long key, int value, char* str) {
    if(table->size <= (table->size >> 1)) {
        // resize the hash table
        table->keys = (long*)realloc(table->keys, sizeof(long) * (table->size << 1));
        table->records = (Record**)realloc(table->records, sizeof(Record*) * (table->size << 1));

        for(int i = 0; i < table->size; i++) {
            table->keys[i] = -1;
            table->records[i] = NULL;
        }
    }

    int index = key % table->size;

    if(table->keys[index] == -1) {
        // allocate a new record
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = value;
        record->str = strdup(str);

        table->keys[index] = key;
        table->records[index] = record;
    } else if(table->keys[index] != key) {
        // the slot is already occupied, need to rehash
        for(int i = 0; i < table->size; i++) {
            if(table->keys[i] == -1) {
                index = i;
                break;
            }
        }

        table->keys[index] = key;
        table->records[index] = (Record*)malloc(sizeof(Record));
        ((table->records[index])->value = value;
        ((table->records[index])->str = strdup(str);
    } else {
        // the slot is already occupied and the key matches, just update the record
        (table->records[index]->value = value;
        (table->records[index]->str = str;
    }
}
