#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int antenna_gain;
    int bandwidth;
    int frequency;
    int channel_mask;
} LTE_PHY_RX_CONFIG_T;

typedef struct {
    int RX_POWER_LEVEL;
    float SINR;
    float BER;
} PHY_RX_STATS_T;

typedef struct {
    long* keys;
    void** values;
    int size;
    int capacity;
} HashTable;

void hash_table_init(HashTable* table, int N) {
    table->keys = (long*)malloc(N * sizeof(long));
    table->values = (void**)malloc(N * sizeof(void*));
    table->size = 0;
    table->capacity = N;
}

int hash_function(long key, HashTable* table) {
    return key % table->capacity;
}

void insert(HashTable* table, long key, void* value) {
    int index = hash_function(key, table);
    if (table->keys[index] != 0) {
        // Handle collision
        for (int i = 0; i < table->size; i++) {
            if (table->keys[i] == key) {
                free(table->values[i]);
                table->values[i] = value;
                return;
            }
        }
        // Resize the hash table
        int new_capacity = table->capacity * 2;
        HashTable* new_table = (HashTable*)malloc(sizeof(HashTable));
        hash_table_init(new_table, new_capacity);
        for (int i = 0; i < table->size; i++) {
            insert(&new_table, table->keys[i], table->values[i]);
        }
        free(table->keys);
        free(table->values);
        *table = *new_table;
    } else {
        table->keys[index] = key;
        table->values[index] = value;
        table->size++;
    }
}

LTE_PHY_RX_CONFIG_T* lte_phy_rx_config_init(int N) {
    LTE_PHY_RX_CONFIG_T* config = (LTE_PHY_RX_CONFIG_T*)malloc(N * sizeof(LTE_PHY_RX_CONFIG_T));
    for (int i = 0; i < N; i++) {
        srand(time(NULL));
        config[i].antenna_gain = rand() % 100;
        config[i].bandwidth = rand() % 100;
        config[i].frequency = rand() % 1000 + 100;
        config[i].channel_mask = rand() % 100;
    }
    return config;
}

PHY_RX_STATS_T* phy_rx_stats_init(int N) {
    PHY_RX_STATS_T* stats = (PHY_RX_STATS_T*)malloc(N * sizeof(PHY_RX_STATS_T));
    for (int i = 0; i < N; i++) {
        srand(time(NULL));
        stats[i].RX_POWER_LEVEL = rand() % 100;
        stats[i].SINR = (float)rand() / RAND_MAX;
        stats[i].BER = (float)rand() / RAND_MAX;
    }
    return stats;
}

int main() {
    int N = 10;
    HashTable table;
    hash_table_init(&table, N);

    LTE_PHY_RX_CONFIG_T* config = lte_phy_rx_config_init(N);
    PHY_RX_STATS_T* stats = phy_rx_stats_init(N);

    // Use the hash table and other functions as needed

    free(config);
    free(stats);
    return 0;
}
