    if (size <= 0 || (hash_table = malloc(sizeof(record_t*) * size)) == NULL) {
        perror("Error initializing hash table");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < size; i++) {
        hash_table[i] = NULL;
    }
}

void insert_key_value(int key, record_t* value) {
    int index = key % N;
    if (hash_table[index] == NULL || (hash_table[index] = malloc(sizeof(record_t))) == NULL) {
        perror("Error allocating memory for new entry");
        exit(EXIT_FAILURE);
    }
    hash_table[index]->value = value->value;
    hash_table[index]->str = value->str;
    hash_table[index]->stats = value->stats;
}

