function updateUIComponents(store, typesToWatch) {
  store.subscribe(() => {
    const currentState = store.getState();
    Object.keys(currentState).forEach((componentKey) => {
      const componentState = currentState[componentKey];
      if (typesToWatch.includes(componentState.componentType)) {
        store.dispatch({ type: 'UPDATE_COMPONENT', componentKey });
      }
    });
  });

  function handleUpdateComponentAction(action) {
    const { componentKey } = action;
    if (!store.getState()[componentKey]) return; // Handle stale data
    store.dispatch({ type: 'FETCH_DATA', componentKey });
  }

  store.subscribe(() => {
    const currentState = store.getState();
    Object.keys(currentState).forEach((componentKey) => {
      const componentState = currentState[componentKey];
      if (componentState.isFetching && !store.getState()[componentKey].data) return; // Handle asynchronous updates
      store.dispatch({ type: 'UPDATE_COMPONENT_SUCCESS', componentKey });
    });
  });

