Node** create_nodes(int num_nodes, int max_events_per_node) {
    Node** nodes = (Node**)calloc(num_nodes, sizeof(Node*));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = create_node(max_events_per_node);
    }
    return nodes;
}

void free_nodes(Node** nodes, int num_nodes) {
    for (int i = 0; i < num_nodes; i++) {
        free_node(nodes[i]);
    }
    free(nodes);
