function paginatedDOMTraversal(doc, selector, queryType = 'css', sortCriteria = [], loadMoreThreshold = 50) {
  const results = [];
  let offset = 0;
  let limit = 10;

  async function loadAndProcessNodes() {
    try {
      const nodes = await doc.querySelectorAll(selector);
      for (const node of nodes) {
        if (!sortCriteria.length) {
          results.push(node);
        } else {
          const sortBy = sortCriteria[0].key;
          const sortOrder = sortCriteria[0].order;
          const sortedNodes = [...nodes].sort((a, b) => {
            if (sortBy === 'text') {
              return a.textContent.localeCompare(b.textContent, 'en-US', { sensitivity: 'base' });
            } else if (sortBy === 'attribute') {
              return a.getAttribute(sortBy).localeCompare(b.getAttribute(sortBy), 'en-US', { sensitivity: 'base' });
            }
            return 0;
          }).slice().reverse();
          for (const node of sortedNodes) {
            results.push(node);
          }
        }
      }
    } catch (error) {
      console.error('Error processing nodes:', error);
    }

    if (results.length >= loadMoreThreshold) {
      const moreButton = document.createElement('button');
      moreButton.textContent = 'Load More';
      moreButton.addEventListener('click', async () => {
        offset += limit;
        await loadAndProcessNodes();
      });
      results.forEach((node, index) => {
        if (index >= loadMoreThreshold && index < offset + limit) {
          const clone = node.cloneNode(true);
          document.body.appendChild(clone);
        }
      });
    }

    return results.slice(offset, offset + limit);
  }

  while (true) {
    const chunk = await loadAndProcessNodes();
    yield chunk;
  }
}

const doc = new DOMParser().parseFromString('<html><body>...</body></html>');
const pagination = paginatedDOMTraversal(doc, '.my-selector', 'css', [{ key: 'text', order: 'asc' }]);
for (let page of pagination) {
  console.log(page);
}
