// Function to dynamically allocate memory and initialize arrays and linked list
void init_arrays_and_linked_list(int num_records) {
    // Allocate memory for arrays in chunks to minimize peak memory consumption
    long* offsets = malloc(4 * sizeof(long));
    int* keys = malloc(num_records * sizeof(int));
    double* metrics = malloc(num_records * sizeof(double));
    Record** records = malloc(num_records * sizeof(Record*));

    // Initialize linked list head
    Node* head = NULL;

    // Initialize random seed for record values
    srand(time(NULL));

    // Read data from external source (e.g., file, database) and populate arrays
    int chunk_size = 1000; // adjust as needed based on dataset size and memory constraints
    for (int i = 0; i < num_records; i += chunk_size) {
        int chunk_num_records = (i + chunk_size > num_records) ? num_records - i : chunk_size;
        // Read data from external source, process it, and populate arrays
        // For demonstration purposes, generate random keys and calculate metrics
        for (int j = 0; j < chunk_num_records; j++) {
            int key = rand() % 10000; // adjust as needed based on desired key range
            double metric = (double)key / 100.0; // example metric calculation
            Record* record = malloc(sizeof(Record));
            record->value = rand() % 100; // adjust as needed based on desired value range
            strcpy(record->name, "record_name"); // adjust as needed for actual naming
            record->metric = metric;
            records[i + j] = record;

            // Asynchronously log data retrieval and memory allocation progress
            logging_framework_log_info("Retrieved key %d and calculated metric %.2f", key, metric);
        }
    }

    // Initialize linked list with records
    Node* current = NULL;
    for (int i = 0; i < num_records; i++) {
        Node* new_node = malloc(sizeof(Node));
        new_node->record = records[i];
        new_node->next = NULL;

        if (!head) {
            head = new_node;
        } else {
            current->next = new_node;
            current = new_node;
        }
    }

    // Release allocated memory
    free(offsets);
    free(keys);
    free(metrics);
    for (int i = 0; i < num_records; i++) {
        free(records[i]);
    }
    free(records);

    return head;
}
