function recursiveTraverseDOM(root, selector, testFunction, maxDepth = 10) {
    const results = [];
    (function traverse(node, currentDepth) {
        if (currentDepth > maxDepth) return; // prevent stack overflow
        Array.from(node.children).forEach((child) => {
            if (testFunction(child, selector)) {
                results.push(child);
                traverse(child, currentDepth + 1); // recursively traverse child nodes
            } else if (Array.from(child.childNodes).some((grandchild) => {
                return testFunction(grandchild, selector);
            })) {
                traverse(child, currentDepth + 1); // traverse deeper if no matches at this level
            }
        });
    })(root, 0);
    return results;
}
