function findMatchingElements(root, selector, testFn, maxDepth = 10, cache = {}, pagination = 0) {
  const result = [];
  const stack = [root];

  (function traverse() {
    while (stack.length > 0) {
      const node = stack.pop();
      if (!node || node.nodeType !== 1) continue;

      const matches = node.matches(selector);
      for (let i = 0; i < matches.length; i++) {
        const element = matches[i];
        const result = testFn(element);

        if (result) {
          result.forEach(matched => {
            result.push({ ...element, data: matched });
          });
        }

        if (element.children && element.children.length > 0) {
          stack.unshift(...element.children);
        }
      }

      if (node.children.length === 0 || node.children.length <= pagination) {
        // Reached the end of a page or reached the limit
        pagination++;
      } else if (pagination < maxDepth) {
        // Fetch more data, update pagination and continue traversal
        fetchAndUpdate(node.children.slice(0, pagination)).then(newPage => {
          stack.unshift(...newPage);
        });
      }
    }

    return result;
  })();

  function cacheFetch(url) {
    if (cache[url]) return Promise.resolve(cache[url]);
    return fetch(url).then(response => response.json()).then(data => {
      cache[url] = data;
      return data;
    });
  }

  function fetchAndUpdate(elements, pagination = 0) {
    const promise = new Promise((resolve, reject) => {
      (async () => {
        for (let i = 0; i < elements.length; i++) {
          if (pagination > 0 && i >= pagination) break;
          const element = elements[i];
          if (!element || !element.id) continue;

          const url = `https://example.com/${element.id}`;
          cacheFetch(url).then(data => {
            await updateElement(element, data);
            resolve();
          }).catch(error => reject(error));
        }
      })();
    });
    return promise;
  }

  function updateElement(element, data) {
    // Update the element's data
  }
}
