function traverseDOM(tree, selector, callback) {
  const cache = {};
  let depth = 0;
  let chunkSize = 10;

  async function recursiveTraversal(node) {
    if (!node) return;
    ++depth;

    try {
      for (const child of node.childNodes) {
        await recursiveTraversal(child);
      }

      const matches = Array.from(node.querySelectorAll(selector));
      for (const match of matches) {
        if (match.getAttribute("data-loaded")) continue;

        await callback(match);

        cache[match.id] = true;

        --depth;
        if (!depth) break;
      }
    } catch (err) {
      console.error(err);
      --depth;
      if (!depth) break;
    }

    if (depth >= chunkSize && node.parentNode) {
      const paginationThreshold = 0.5;

      async function loadMore() {
        await new Promise(resolve => setTimeout(resolve, 500));

        for (let i = depth - chunkSize; i < depth; ++i) {
          await callback(node.querySelectorAll(selector)[i]);
        }
      }

      if (!cache[node.id] && node.querySelector("span[data-loaded]") !== null) {
        if (Math.random() > paginationThreshold) {
          await loadMore();
        } else {
          await new Promise(resolve => setTimeout(resolve, 2000));
        }
      }
    }
  }

  recursiveTraversal(tree);
}
