@paginate(page_size=1000)
def filter_catalog(catalog: Dict[str, Any], filters: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    result = []
    for product in catalog['products']:
        if all(all(filter.get(key) == value or key not in product for key, value in filter.items()) for filter in filters):
