    }

    // Allocate memory for key array
    *keys = (int*)malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        printf("Error: Unable to allocate memory for key array.\n");
        free(*offsets);
        return;
    }

    // Initialize key array with random values
    for (int i = 0; i < num_records; i++) {
        (*keys)[i] = rand() % 10000;
    }

    // Allocate memory for record structures
    record_t** records = (record_t**)malloc(num_records * sizeof(record_t*));
    if (records == NULL) {
        printf("Error: Unable to allocate memory for record array.\n");
        free(*offsets);
        free(*keys);
        return;
