#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int value;
    char* string;
    PHY_RX_STATS_T stats;
} RECORD;

typedef struct {
    RECORD** records;
    int capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} TABLE;

TABLE* table_create(int initial_capacity) {
    TABLE* table = malloc(sizeof(TABLE));
    table->records = malloc(initial_capacity * sizeof(RECORD*));
    for (int i = 0; i < initial_capacity; i++) {
        table->records[i] = NULL;
    }
    table->capacity = initial_capacity;
    pthread_mutex_init(&table->mutex, NULL);
    pthread_cond_init(&table->cond, NULL);
    return table;
}

void table_destroy(TABLE* table) {
    for (int i = 0; i < table->capacity; i++) {
        RECORD* record = table->records[i];
        if (record != NULL) {
            free(record->string);
            free(record);
        }
    }
    free(table->records);
    pthread_mutex_destroy(&table->mutex);
    pthread_cond_destroy(&table->cond);
    free(table);
}

int table_hash(TABLE* table, long key) {
    return (int)(key % table->capacity);
}

RECORD* table_insert(TABLE* table, long key, int value, char* string, PHY_RX_STATS_T stats) {
    int index = table_hash(table, key);
    RECORD* record = malloc(sizeof(RECORD));
    record->value = value;
    record->string = strdup(string);
    record->stats = stats;

    // handle resize if necessary
    if (table->records[index] == NULL || table->capacity <= index) {
        int new_capacity = table->capacity * 2 + 1;
        RECORD** new_records = realloc(table->records, new_capacity * sizeof(RECORD*));
        for (int i = table->capacity; i < new_capacity; i++) {
            new_records[i] = NULL;
        }
        table->records = new_records;
        table->capacity = new_capacity;
    }

    // replace or insert record
    if (table->records[index] != NULL) {
        RECORD* old_record = table->records[index];
        free(old_record->string);
        free(old_record);
    }
    table->records[index] = record;

    return record;
}

RECORD* table_lookup(TABLE* table, long key) {
    int index = table_hash(table, key);
    pthread_mutex_lock(&table->mutex);
    RECORD* record = table->records[index];
    pthread_mutex_unlock(&table->mutex);

    return record;
}
