import { useDispatch, useStore } from 'react-redux';
import { throttle } from 'lodash';

const updateComponents = (componentTypes) => {
  const dispatch = useDispatch();
  const store = useStore();

  // Throttle the function to prevent excessive updates
  const debouncedUpdate = throttle(() => {
    // Get all UI components in the current render cycle
    const componentKeys = Object.keys(store.getState());

    // Iterate through each component key
    componentKeys.forEach((key) => {
      const component = store.getStore()[key];

      // Check if the component type matches any of the specified types to update
      if (componentTypes.includes(component.type)) {
        // Ensure the component is stable and not in the process of re-rendering
        if (!component.isRendering && !component.hasErrors) {
          // Dispatch an action to the Redux store with the component key only if the component is deemed stable
          dispatch({ type: 'UPDATE_COMPONENT', payload: { key } });
        }
      }
    });
  }, 100);

  return debouncedUpdate;
};
