import { useSelector, useDispatch } from 'react-redux';
import { updateComponents } from './actions';

const updateComponentsByType = (componentTypes) => {
  const dispatch = useDispatch();
  const storeState = useSelector((state) => state);
  const queue = [];

  for (let i = 0; i < componentTypes.length; i++) {
    const componentType = componentTypes[i];
    const currentComponentKeys = Object.keys(storeState.components);

    for (let j = 0; j < currentComponentKeys.length; j++) {
      const key = currentComponentKeys[j];

      if (
        storeState.components[key].type === componentType &&
        !storeState.components[key].isUpdating
      ) {
        queue.push({ key, type: componentType });
      }
    }
  }

  // Debounce updates and handle concurrent requests
  setTimeout(() => {
    for (let i = 0; i < queue.length; i++) {
      const { key, type } = queue[i];
      dispatch(updateComponents(key));
    }
    queue.length = 0;
  }, 100);
};

export default updateComponentsByType;
