    new_metadata->timestamp = timestamp;
    new_metadata->status = status;
    return new_metadata;
}

node_t *insert_node(node_t *head, record_t *record) {
    node_t *new_node = create_node(record);
    if (head == NULL) {
        return new_node;
    }
    new_node->next = head;
    return new_node;
}

void remove_node(node_t **head, record_t *record) {
    node_t *current = *head;
    node_t *previous = NULL;
    while (current != NULL && current->record != record) {
        previous = current;
        current = current->next;
    }
    if (current == NULL) {
        return; // Record not found
    }
    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }
    free_node(current);
}

void release_memory(node_t **head) {
    while (*head != NULL) {
        node_t *temp = *head;
        *head = (*head)->next;
        free_node(temp);
    }
}
