  const components = useSelector((state) => state.components);

  if (!components) return;

  for (const component in components) {
    const { type, isStable } = components[component];
    if (isStable && componentTypes.includes(type)) {
      dispatch(updateComponents({ [component]: true }));
    }
  }
};

export default dynamicUpdateFunction;
