    char type[16];
    double amount;
    time_t timestamp;
} operation;

account* create_account() {
    account* acc = (account*)malloc(sizeof(account));
    acc->balance = 0;
    acc->lastUpdated = time(NULL);
    return acc;
}

operation* create_operation(char* type, double amount) {
    operation* op = (operation*)malloc(sizeof(operation));
    strcpy(op->type, type);
    op->amount = amount;
    op->timestamp = time(NULL);
    return op;
}

void free_account(account* acc) {
    for(int i = 0; i < acc->trans.size; i++) {
        free(acc->transactions[i]);
    }
    free(acc);
}

void log_transaction(account* acc, operation* op, int status) {
    FILE* log_file = fopen("transaction_log.txt", "a");
    if(log_file == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(log_file, "[%s] %f @ %ld: status %d\n", op->type, op->amount, op->timestamp, status);
    fclose(log_file);
}

int main() {
    // Initialize pending array with consecutive integers starting from 0
    int* pending = (int*)malloc(10000 * sizeof(int));
    for(int i = 0; i < 10000; i++) {
        pending[i] = i;
    }

    // Create a dynamic collection of 'transaction' structures
    account* acc = create_account();
    operation* op1 = create_operation("DEPOSIT", 10.5);
    operation* op2 = create_operation("WITHDRAWAL", -3.7);
    acc->transactions[0] = op1;
    acc->transactions[1] = op2;

    // Iterate over all transactions and update their status
    for(int i = 0; i < acc->trans.size; i++) {
        if(acc->transactions[i]->amount > 0) {
            log_transaction(acc, acc->transactions[i], 1);
        } else {
            log_transaction(acc, acc->transactions[i], 2);
        }
    }

    free_account(acc);

    return 0;
}
