import os
import time
import hashlib
from flask import request, session, g
from functools import wraps
from redis import Redis
from rq import Queue

redis = None
rq_queue = None

def setup_redis():
    global redis, rq_queue
    redis = Redis(host='localhost', port=6379, db=0)
    rq_queue = Queue(connection=redis)

def get_session_id(request):
    return hashlib.sha256(str(request.remote_addr).encode()).hexdigest()[:16]

def session_manager(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        session_id = get_session_id(request)
        if not redis.get(session_id):
            session_start_time = time.time()
            session.set_expires(3600)  # 1 hour
            redis.setex(session_id, 86400, '1')  # 24 hours
            rq_queue.enqueue_at(session_start_time + 300, func, *args, **kwargs)
        return func(*args, **kwargs)
    return wrapper

@session_manager
def authenticate_user(username, password):
    if username == 'admin' and password == 'password':
        session['logged_in'] = True
        session['username'] = username
        return {'message': 'User authenticated successfully'}
    else:
        return {'message': 'Invalid credentials'}

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or not data.get('username') or not data.get('password'):
        return {'message': 'Invalid request'}, 400
    result = authenticate_user(data['username'], data['password'])
    if isinstance(result, dict):
        session['logged_in'] = True
        session['username'] = data['username']
        return result
    else:
        return result

@app.route('/logout', methods=['POST'])
def logout():
    if 'logged_in' in session and session.get('logged_in'):
        session.pop('logged_in')
        session.pop('username')
    return {'message': 'User logged out successfully'}

@app.route('/session_info', methods=['GET'])
def get_session_info():
    if 'logged_in' not in session or not session.get('logged_in'):
        return {'message': 'User not logged in'}, 401
    return {
        'logged_in': session['logged_in'],
        'username': session['username']
    }

if __name__ == '__main__':
    setup_redis()
    app.run(debug=True)
