typedef struct {
    long int key;
    void* value;
} NETWORK_CONFIG_T;

typedef struct {
    float packet_loss;
    float jitter;
    float available_bandwidth;
} NETWORK_STATS_T;

void network_config_init(NETWORK_CONFIG_DB** db, int n) {
    *db = (NETWORK_CONFIG_DB*)malloc(sizeof(NETWORK_CONFIG_DB));
    (*db)->config = (NETWORK_CONFIG_T**)malloc(n * sizeof(NETWORK_CONFIG_T*));
    for (int i = 0; i < n; i++) {
        (*db)->config[i] = (NETWORK_CONFIG_T*)malloc(sizeof(NETWORK_CONFIG_T));
        (*db)->config[i]->key = rand();
    }
}

void network_config_insert(NETWORK_CONFIG_DB* db, long int key, void* value) {
    for (int i = 0; i < db->size; i++) {
        if (db->config[i]->key == key) {
            free(db->config[i]->value);
            db->config[i]->value = value;
            return;
        }
    }
    db->config[db->size].key = key;
    db->config[db->size++]->value = value;
}

void network_config_update(NETWORK_CONFIG_DB* db, long int key, void* value) {
    for (int i = 0; i < db->size; i++) {
        if (db->config[i]->key == key) {
            free(db->config[i]->value);
            db->config[i]->value = value;
            return;
        }
    }
}

void network_config_delete(NETWORK_CONFIG_DB* db, long int key) {
    for (int i = 0; i < db->size; i++) {
        if (db->config[i]->key == key) {
            free(db->config[i]->value);
            for (int j = i + 1; j < db->size; j++) {
                db->config[j - 1] = db->config[j];
            }
            db->size--;
            return;
        }
    }
}

void network_stats_init(NETWORK_STATS_DB** stats, int n) {
    *stats = (NETWORK_STATS_DB*)malloc(sizeof(NETWORK_STATS_DB));
    (*stats)->stats = (NETWORK_STATS_T**)malloc(n * sizeof(NETWORK_STATS_T*));
    for (int i = 0; i < n; i++) {
        (*stats)->stats[i] = (NETWORK_STATS_T*)malloc(sizeof(NETWORK_STATS_T));
        (*stats)->stats[i]->packet_loss = rand() / (float)RAND_MAX;
        (*stats)->stats[i]->jitter = rand() / (float)RAND_MAX;
        (*stats)->stats[i]->available_bandwidth = rand() % 100 + 1;
    }
}

void network_stats_update(NETWORK_STATS_DB* stats, int index, float packet_loss, float jitter, float available_bandwidth) {
    if (index < 0 || index >= stats->size) {
        printf("Error: Invalid statistics index.\n");
        return;
    }
    free(stats->stats[index]);
    stats->stats[index] = (NETWORK_STATS_T*)malloc(sizeof(NETWORK_STATS_T));
    stats->stats[index]->packet_loss = packet_loss;
    stats->stats[index]->jitter = jitter;
    stats->stats[index]->available_bandwidth = available_bandwidth;
}

void error_log_flush(ERROR_LOG_DB* log, int threshold) {
    if (log->size >= threshold) {
        for (int i = 0; i < log->size; i++) {
            printf("%s\n", log->errors[i]);
        }
        free(log->errors);
        log->size = 0;
    }
}

void network_config_db_init(NETWORK_CONFIG_DB** db, int n) {
    *db = (NETWORK_CONFIG_DB*)malloc(sizeof(NETWORK_CONFIG_DB));
