#define MAX_RECORDS 1000
#define LOG_BUFFER_SIZE 1024

typedef struct record {
    int value;
} Record;

typedef struct worker_thread_args {
    int start;
    int end;
    pthread_mutex_t* log_lock;
} WorkerThreadArgs;

void* create_records(void* args) {
    WorkerThreadArgs* wargs = (WorkerThreadArgs*)args;
    pthread_mutex_lock(wargs->log_lock);
    printf("Creating records from %d to %d...\n", wargs->start, wargs->end);
    pthread_mutex_unlock(wargs->log_lock);

    // Create and log records
    for (int i = wargs->start; i <= wargs->end; ++i) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = rand() % 100;
        // Check if the value is consecutive to existing records
        while (true) {
            bool is_consecutive = false;
            for (int j = i - 1; j >= 0 && j < MAX_RECORDS; --j) {
                Record* prev_record = get_prev_record(j);
                if (prev_record->value + 1 == record->value) {
                    is_consecutive = true;
                    break;
                }
            }
            if (!is_consecutive) {
                break;
            }
            free(record);
            record = (Record*)malloc(sizeof(Record));
            record->value = rand() % 100;
        }

        // Log the creation of the record
        pthread_mutex_lock(wargs->log_lock);
        printf("Created record with value %d at index %d\n", record->value, i);
        pthread_mutex_unlock(wargs->log_lock);

        // Add the record to the active list
        add_active_record(record);
    }

    return NULL;
}

void* update_records(void* args) {
    WorkerThreadArgs* wargs = (WorkerThreadArgs*)args;

    // Update and log records
    for (int i = wargs->start; i <= wargs->end; ++i) {
        Record* record = get_active_record(i);
        if (record != NULL) {
            // Update the record value
            record->value = rand() % 100;

            // Log the update of the record
            pthread_mutex_lock(wargs->log_lock);
            printf("Updated record with value %d at index %d\n", record->value, i);
            pthread_mutex_unlock(wargs->log_lock);

            // Mark the record as updated in the active list
            mark_record_updated(i);
        }
    }

    return NULL;
}

void* delete_records(void* args) {
    WorkerThreadArgs* wargs = (WorkerThreadArgs*)args;

    // Delete and log records
    for (int i = wargs->start; i <= wargs->end; ++i) {
        Record* record = get_active_record(i);
        if (record != NULL) {
            // Delete the record from memory
            free(record);

            // Log the deletion of the record
            pthread_mutex_lock(wargs->log_lock);
            printf("Deleted record at index %d\n", i);
            pthread_mutex_unlock(wargs->log_lock);

            // Remove the record from the active list
            remove_active_record(i);
        }
    }

    return NULL;
}

void* worker_thread(void* args) {
    WorkerThreadArgs* wargs = (WorkerThreadArgs*)args;

    pthread_mutex_lock(wargs->log_lock);
    printf("Worker thread %d started...\n", pthread_getsid(pthread_self()));
    pthread_mutex_unlock(wargs->log_lock);

    if (wargs->start < MAX_RECORDS) {
        create_records(args);
        update_records(args);
        delete_records(args);
    }

    pthread_mutex_lock(wargs->log_lock);
    printf("Worker thread %d finished...\n", pthread_getsid(pthread_self()));
    pthread_mutex_unlock(wargs->log_lock);

    return NULL;
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    // Create a pool of worker threads
    int num_threads = 4;
    pthread_t threads[num_threads];
    WorkerThreadArgs* wargs = (WorkerThreadArgs*)malloc(num_threads * sizeof(WorkerThreadArgs));
    pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < num_threads; ++i) {
        wargs[i].start = i * MAX_RECORDS / num_threads;
        wargs[i].end = (i + 1) * MAX_RECORDS / num_threads - 1;
        wargs[i].log_lock = &log_lock;
        pthread_create(&threads[i], NULL, worker_thread, &wargs[i]);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}

