void resize_hash_table(int new_size) {
    void** new_hash_table = (void**)malloc(new_size * sizeof(void*));
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE_NP);
    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&hash_table_lock);
        new_hash_table[i] = hash_table[i];
        pthread_mutex_unlock(&hash_table_lock);
    }
    free(hash_table);
    hash_table = new_hash_table;
}

void insert_record(int key, long timestamp, float value) {
    if (num_records >= MAX_RECORDS) {
        int new_size = MAX_RECORDS * 2;
        if (new_size > MAX_HASH_TABLE_SIZE)
            new_size = MAX_HASH_TABLE_SIZE;
        resize_hash_table(new_size);
    }
    record_t* new_record = (record_t*)malloc(sizeof(record_t));
    new_record->timestamp = timestamp;
    new_record->value = value;
    new_record->status_flag = STATUS_FLAG_FALSE;
    pthread_mutex_lock(&hash_table_lock);
    hash_table[key] = new_record;
    num_records++;
    pthread_mutex_unlock(&hash_table_lock);
}

void set_float_values() {
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        record_t* record = records[i];
        if (record) {
            float value = (float)rand() / RAND_MAX * FLOAT_RANGE;
            if (value > 5.0f)
                record->status_flag = STATUS_FLAG_TRUE;
            else
                record->status_flag = STATUS_FLAG_FALSE;
            record->value = value;
        }
    }
}

int main() {
    for (int i = 0; i < MAX_RECORDS; i++) {
        insert_record(i, i * 100, (float)i);
    }
    set_float_values();
