#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct {
    long timestamp;
    float value;
    char status;
} record;

// Define the hash table structure
typedef struct {
    int size;
    pthread_mutex_t mutex;
    record **records;
    long *offsets;
} hashtable;

// Function to create a new record with random value and status
record* createRecord() {
    record* r = (record*)malloc(sizeof(record));
    r->timestamp = time(NULL);
    r->value = (float)(rand() / (RAND_MAX / 1.0));
    if (r->value > 0.5) {
        r->status = 'A';
    } else {
        r->status = 'B';
    }
    return r;
}

// Function to create a new hashtable with initial size and capacity
hashtable* createHashtable(int initialSize, int capacity) {
    hashtable* h = (hashtable*)malloc(sizeof(hashtable));
    h->size = initialSize;
    h->records = (record**)malloc(h->size * sizeof(record*));
    h->offsets = (long*)malloc((h->size + 1) * sizeof(long));
    pthread_mutex_init(&h->mutex, NULL);
    return h;
}

// Function to insert a record into the hashtable
void insertRecord(hashtable* h, int key, record* r) {
    pthread_mutex_lock(&h->mutex);
    if (h->size <= h->offsets[h->size]) {
        // Resize the array if necessary
        long* newOffsets = (long*)realloc(h->offsets, (h->size * 2 + 1) * sizeof(long));
        record** newRecords = (record**)realloc(h->records, (h->size * 2 + 1) * sizeof(record*));
        h->offsets = newOffsets;
        h->records = newRecords;
    }
    int index = key % h->size;
    long* offset = &h->offsets[index];
    while (*offset != -1 && *offset < h->offsets[h->size]) {
        if (index + 1 >= h->size) {
            // Handle collision by moving the existing record to the end
            long temp = *offset;
            record* oldR = h->records[temp % h->size];
            *offset = -1;
            int newIndex = temp % h->size;
            while (h->offsets[newIndex] != -1) {
                newIndex = (newIndex + 1) % h->size;
            }
            h->offsets[newIndex] = temp;
            h->records[newIndex] = oldR;
        } else {
            // Move the existing record to the end
            long temp = *offset;
            int newIndex = index + 1;
            while (h->offsets[newIndex] != -1) {
                newIndex = (newIndex + 1) % h->size;
            }
            h->offsets[newIndex] = temp;
            h->records[newIndex] = h->records[index];
        }
    }
    *offset = key;
    h->records[index] = r;
    pthread_mutex_unlock(&h->mutex);
}

// Function to retrieve a record from the hashtable
record* getRecord(hashtable* h, int key) {
    pthread_mutex_lock(&h->mutex);
    int index = key % h->size;
    long offset = &h->offsets[index];
    while (*offset != -1 && *offset < h->offsets[h->size]) {
        if (index == *offset % h->size) {
            record* r = h->records[*offset % h->size];
            pthread_mutex_unlock(&h->mutex);
            return r;
        }
        index = (index + 1) % h->size;
    }
    pthread_mutex_unlock(&h->mutex);
    return NULL;
}

// Function to free the hashtable
void freeHashtable(hashtable* h) {
    pthread_mutex_lock(&h->mutex);
    for (int i = 0; i < h->size; i++) {
        if (h->offsets[i] != -1) {
            record* r = h->records[h->offsets[i]];
            free(r);
        }
    }
    free(h->offsets);
    free(h->records);
    pthread_mutex_unlock(&h->mutex);
}
