void* allocate_and_init_records(int num_records, int seed, int max_value, bool prioritize_speed) {
    // Dynamically allocate memory for an array of long offsets and an array of int keys
    size_t size = sizeof(long) * num_records;
    long* offsets = (long*)malloc(size);
    if (!offsets) {
        fprintf(stderr, "Memory allocation failure for offsets!\n");
        return NULL;
    }

    // Initialize the array of record structures
    record** records = (record**)calloc(num_records, sizeof(record));
    if (!records) {
        free(offsets);
        fprintf(stderr, "Memory allocation failure for records!\n");
        return NULL;
    }

    for (int i = 0; i < num_records; ++i) {
        records[i] = init_record(seed, max_value);
    }

    // Implement caching strategies to reduce redundant memory allocations
    size_t cache_size = sizeof(record*) * num_records;
    record** cache = (record**)malloc(cache_size);
    if (!cache) {
        free(offsets);
        for (int i = 0; i < num_records; ++i) {
            free(records[i]);
        }
        free(records);
        fprintf(stderr, "Memory allocation failure for cache!\n");
        return NULL;
    }

    // Implement error handling and logging for memory management events
