        free(manager);
        return NULL; // out of memory
    }
    for (size_t i = 0; i < offset_size; i++) {
        manager->offset[i] = 0;
    }

    manager->keys = calloc(key_size, sizeof(int));
    if (!manager->keys) {
        free(manager->offset);
