    for (size_t i = 0; i < key_size; i++) {
        manager->keys[i] = (rand() % 256); // random keys
    }

    manager->records = calloc(offset_size, sizeof(struct { long* ptr; int val; }));
    if (!manager->records) {
        free(manager->offset);
        free(manager->keys);
        free(manager);
