#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Configuration settings
int max_memory_pool_size = 1024 * 1024; // 1MB default
int record_range_start = 0;
int record_range_end = 100;

// Structure for a single record
typedef struct {
    int value;
} Record;

// Structure for a 'record' list node
typedef struct Node {
    Record data;
    struct Node* next;
} Node;

// Global variables and structures
Node* head = NULL;
Node* tail = NULL;
int active_records = 0;
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void* record_generator(void* arg) {
    // Generate a random number within the specified range
    int value = rand() % (record_range_end - record_range_start + 1) + record_range_start;

    // Create a new record with the generated value
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->value = value;

    // Update active records count and logging
    pthread_mutex_lock(&log_mutex);
    active_records++;
    printf("Created record %d\n", value);
    pthread_mutex_unlock(&log_mutex);

    return new_record;
}

void delete_record(void* arg) {
    Node* current = (Node*)arg;
    Node* next = current->next;

    // Update active records count and logging
    pthread_mutex_lock(&log_mutex);
    active_records--;
    printf("Deleted record %d\n", current->data.value);
    free(current);
    pthread_mutex_unlock(&log_mutex);

    if (next) {
        head = next;
    } else {
        tail = NULL;
    }
}

void* worker_thread(void* arg) {
    int batch_size = 10; // Default batch size
    Node** record_list = (Node**)malloc(batch_size * sizeof(Node));

    for (int i = 0; i < batch_size; i++) {
        Record* new_record = record_generator(NULL);
        record_list[i] = (Node*)new_record;
    }

    // Process records in parallel using multiple threads
    pthread_t thread[batch_size];
    for (int i = 0; i < batch_size; i++) {
        pthread_create(&thread[i], NULL, delete_record, record_list[i]);
    }

    // Wait for all worker threads to finish
    for (int i = 0; i < batch_size; i++) {
        pthread_join(thread[i], NULL);
    }

    free(record_list);

    return NULL;
}

int main() {
    srand(time(NULL));

    // Create a separate thread pool for processing records in parallel
    pthread_t worker[5]; // Default worker count
    for (int i = 0; i < 5; i++) {
        pthread_create(&worker[i], NULL, worker_thread, NULL);
    }

    // Wait for all worker threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(worker[i], NULL);
    }

    return 0;
}
