    char* log_messages = (char*)malloc(log_messages_size);

    for (int i = 0; i < log_messages_size; i++) {
        log_messages[i] = 'A' + i % 26;
    }

    // Initialize linked list of log_entry structures
    log_entry* log_entries = (log_entry*)malloc(total_logs * sizeof(log_entry));

    // Initialize hash table for log_id mappings
    int** log_id_mappings = (int**)malloc((total_logs / 2 + 1) * sizeof(int*));
    for (int i = 0; i < total_logs / 2 + 1; i++) {
        log_id_mappings[i] = (int*)malloc(sizeof(int));
    }

    // Release allocated memory
    free(timestamps);
    free(log_messages);
    for (int i = 0; i < total_logs / 2 + 1; i++) {
