    int i;
    for(i = 0; i < offsetSize; i++) {
        printf("Offset: %d - ", i);

        // Print all values in the record
        int j;
        for(j = 0; j < keySize; j++) {
            printf("%d ", records[i][j].value);
        }
        printf("\n");
    }
}

