#include <pthread.h>

#define MAX_RECORDS 1000
#define MAX_TEXT_LENGTH 100000
#define REGEX_OLD_TESTAMENT "^(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclasiastes|SongOfSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)$"

typedef struct {
    int value;
} record;

record *records = NULL;
int records_size = 0;
pthread_mutex_t records_lock = PTHREAD_MUTEX_INITIALIZER;

record *add_record(record **head, int value) {
    record *new_record = (record *)malloc(sizeof(record));
    new_record->value = value;

    if (*head == NULL || records_size >= MAX_RECORDS) {
        return *head; // Memory limit reached or no free space
    }

    new_record->next = *head;
    *head = new_record;
    records_size++;

    return *head;
}

int parse_text(char *text, record **record_head) {
    pthread_mutex_lock(&records_lock);

    regex_t old_testament_regex;
    regcomp(&old_testament_regex, REGEX_OLD_TESTAMENT, REG_OPTION_DOT | REG_EXTENDED);

    char *token = strtok(text, " ");
    while (token != NULL) {
        if (regexec(&old_testament_regex, token, 0, NULL, 0) == 0) {
            record_head = &add_record(record_head, rand() % 100 + 1); // Assign random value
        }

        token = strtok(NULL, " ");
    }

    regfree(&old_testament_regex);
    pthread_mutex_unlock(&records_lock);
}

void *monitor_memory(void *arg) {
    int peak_usage = 0;
    while (1) {
        int current_usage = sysconf(_SC_PAGE_SIZE) / sysconf(_SC_PHYS_PAGES);

        if (current_usage > peak_usage) {
            peak_usage = current_usage;
        }

        sleep(5); // Monitor every 5 seconds
    }

    return NULL;
}

int main() {
    pthread_t monitor_thread;

    pthread_create(&monitor_thread, NULL, monitor_memory, NULL);

    for (int i = 0; i < 10; i++) { // Run the function multiple times in parallel
        record *record_head = NULL;

        char text[] = "Genesis is a book of the Bible. Exodus mentions Moses.";
        parse_text(text, &record_head);

        // Process other texts here...
    }

    pthread_join(monitor_thread, NULL);

    return 0;
}
