#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define OLD_TESTAMENT_BOOKS_MAX_LENGTH 50

typedef struct {
    int key;
    long offset;
    record_t data;
} record_t;

record_t* create_records(int num_records, int seed) {
    record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
    if (!records) {
        return NULL; // memory allocation failed
    }

    for (int i = 0; i < num_records; i++) {
        record_t* record = &records[i];
        int random_value = rand_r(&seed);
        record->key = random_value % 100;
        record->offset = (long)random_value * 2;
        record->data.value = (int)random_value;
    }

    return records;
}

record_t* parse_text(const char* text, pthread_mutex_t* mutex, int num_records, int seed) {
    static const char* old_testament_books[] = {"Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy", "Joshua", "Judges", "Ruth", "1Samuel", "2Samuel", "1Kings", "2Kings", "1Chronicles", "2Chronicles", "Ezra", "Nehemiah", "Esther", "Job", "Psalms", "Proverbs", "Ecclesiastes", "SongOfSolomon", "Isaiah", "Jeremiah", "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel", "Amos", "Obadiah", "Jonah", "Micah", "Nahum", "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi"};
    static const char* book_regex[] = {"Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|SongOfSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi"};
    record_t* result = create_records(num_records, seed);
    pthread_mutex_lock(mutex);

    for (int i = 0; i < num_records; i++) {
        const char* text_copy = strdup(text);
        int matches = 0;
        for (int j = 0; j < sizeof(old_testament_books) / sizeof(old_testament_books[0]); j++) {
            regex_t re;
            regcomp(&re, book_regex[j], REG_EXTENDED | REG_NEWLINE);
            regmatch_t match;
            int reti;

            while (regexec(&re, text_copy, 1, &match, 0) == 0) {
                matches++;
                free(text_copy);
                text_copy = strdup(text + match.rm_so);

                break; // Matched
            }

            if (!reti && regexec(&re, text_copy, 1, &match, REG_NOTBOL)) {
                matches++;
                free(text_copy);
                text_copy = strdup(text + match.rm_eo);
            }
        }

        if (matches > 0) {
            record_t* record = &result[i];
            int value = rand_r(&seed) % 100;
            record->key = value;
            record->offset = (long)value * 2;
            record->data.value = value;
        } else {
            free(text_copy);
        }

        pthread_mutex_unlock(mutex);

        return result;
    }
}

int main() {
    pthread_mutex_t mutex;
    int num_records = MAX_RECORDS;
    int seed = time(NULL);

    record_t* records = parse_text("Genesis is the first book of the Bible.\n" "Exodus describes the Israelites' exodus from Egypt.", &mutex, num_records, seed);

    for (int i = 0; i < num_records; i++) {
        printf("%d: Key=%d Offset=%ld Data=%d\n", i, records[i].key, records[i].offset, records[i].data.value);
    }

    return 0;
}
