Record* init_records(int initial_size) {
    Record* records = (Record*)malloc(initial_size * sizeof(Record));
    for (int i = 0; i < initial_size; i++) {
        // Initialize each record with default values
        records[i].offset = i;
        records[i].key = malloc(strlen("default_key") + 1);
        strcpy(records[i].key, "default_key");
    }
    return records;
}

// Dynamically resize the array as needed
void resize_records(Record** records, int new_size) {
    Record* new_records = (Record*)malloc(new_size * sizeof(Record));
    for (int i = 0; i < *records ? (*records)[0].offset : 0; i++) {
        // Copy existing data to the new array
        new_records[i] = (*records)[i];
    }
    free(*records);
    *records = new_records;
}
