        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(keys);
    free(offsets);

    return records;
}

void printRecords(Record* records, int numRecords) {
    printf("Printing Records:\n");
    for (int i = 0; i < numRecords; i++) {
        printf("Key: %d, Offset: %ld\n", records[i].key, records[i].offset);
    }
}

void freeRecords(Record* records) {
    if (!records)
        return;
    free(records);
}

