// Define the particle structure
typedef struct {
    double value;
    Vector *vector;
} Particle;

// Function to initialize and allocate memory for particles, vectors, and strings
Particle* initParticles(int count) {
    srand(time(NULL)); // seed random number generator

    Particle *particles = (Particle *)malloc(count * sizeof(Particle));
    if (!particles) return NULL; // handle allocation failure

    Vector *vectors = (Vector *)malloc(count * sizeof(Vector));
    if (!vectors) {
        free(particles);
        return NULL;
    }

    char **strings = (char **)malloc(count * sizeof(char *));
    if (!strings) {
        free(particles);
        free(vectors);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        particles[i].value = (double)(rand() % 10000) / 100.0; // random value between 0 and 99.9
        particles[i].vector = &vectors[i];

        vectors[i].x = (float)((rand() % 2) ? -1 : 1) * ((float)(rand() % 10)) / 5.0;
        vectors[i].y = (float)((rand() % 2) ? -1 : 1) * ((float)(rand() % 10)) / 5.0;
        vectors[i].z = (float)((rand() % 2) ? -1 : 1) * ((float)(rand() % 10)) / 5.0;

        strings[i] = (char *)malloc(16 * sizeof(char));
        if (!strings[i]) {
            for (int j = i; j >= 0; j--) free(strings[j]);
            free(particles);
            free(vectors);
            return NULL;
        }
    }

    free(vectors);
    free(strings);

    return particles;
}

// Function to serialize particle data
void serializeParticles(Particle *particles, int count) {
    FILE *file = fopen("particle_data.bin", "wb");
    if (!file) return; // handle file operation failure

    for (int i = 0; i < count; i++) {
        fwrite(&particles[i].value, sizeof(double), 1, file);
        fwrite(&particles[i].vector->x, sizeof(float), 1, file);
        fwrite(&particles[i].vector->y, sizeof(float), 1, file);
        fwrite(&particles[i].vector->z, sizeof(float), 1, file);
    }

    fclose(file);
}

// Function to deserialize particle data
Particle* deserializeParticles(int *count) {
    FILE *file = fopen("particle_data.bin", "rb");
    if (!file || fread(NULL, 0, 1, file) <= 0) return NULL; // handle file operation failure

    int fileSize = (int)fseek(file, 0, SEEK_END);
    rewind(file);

    Particle *particles = (Particle *)malloc((fileSize / sizeof(Particle)) * sizeof(Particle));
    if (!particles) {
        fclose(file);
        return NULL;
    }

    for (int i = 0; i < fileSize / sizeof(Particle); i++) {
        particles[i].value = *(double*)fread(&particles[i].value, sizeof(double), 1, file);
        fread(&particles[i].vector->x, sizeof(float), 1, file);
        fread(&particles[i].vector->y, sizeof(float), 1, file);
        fread(&particles[i].vector->z, sizeof(float), 1, file);
    }

    fclose(file);

    return particles;
}
