// Structure for particle system
typedef struct {
    double value;
    struct vector3 {
        float x, y, z;
    } vec;
} Particle;

// Function to initialize and allocate memory for particles
void initParticles(int numParticleSystems, int numParticlesPerSystem) {
    // Allocate memory for particle systems
    Particle* particles = (Particle*)malloc(numParticleSystems * sizeof(Particle));

    if (!particles) {
        printf("Error: Out of memory.\n");
        return;
    }

    // Initialize and allocate memory for each particle system
    for (int i = 0; i < numParticleSystems; i++) {
        particles[i].value = rand() / (double)RAND_MAX * 100.0;  // Initialize value with random number within range [0, 100]

        // Allocate memory for particles in each system
        Particle* particleSystem = &particles[i];

        for (int j = 0; j < numParticlesPerSystem; j++) {
            particleSystem->vec.x = rand() / (double)RAND_MAX;
            particleSystem->vec.y = rand() / (double)RAND_MAX;
            particleSystem->vec.z = rand() / (double)RAND_MAX;

            particleSystem++;
        }
    }

    // Free allocated memory
    free(particles);
}

// Function to serialize particle data for persistence
void serializeParticles(int numParticleSystems, int numParticlesPerSystem) {
    // Initialize file pointer and buffers
    FILE* file = fopen("particle_data.bin", "wb");
    if (!file) {
        printf("Error: Unable to open file.\n");
        return;
    }

    for (int i = 0; i < numParticleSystems; i++) {
        Particle* particles = &particles[i];

        // Serialize particle data
        for (int j = 0; j < numParticlesPerSystem; j++) {
            fwrite(&particles->value, sizeof(double), 1, file);
            fwrite(&particles->vec.x, sizeof(float), 1, file);
            fwrite(&particles->vec.y, sizeof(float), 1, file);
            fwrite(&particles->vec.z, sizeof(float), 1, file);

            particles++;
        }
    }

    // Close and free allocated memory
    fclose(file);
}

// Function to deserialize particle data from persistence
void deserializeParticles(int numParticleSystems, int numParticlesPerSystem) {
    // Initialize file pointer and buffers
    FILE* file = fopen("particle_data.bin", "rb");
    if (!file) {
        printf("Error: Unable to open file.\n");
        return;
    }

    Particle* particles = (Particle*)malloc(numParticleSystems * numParticlesPerSystem * sizeof(Particle));

    if (!particles) {
        printf("Error: Out of memory.\n");
        fclose(file);
        return;
    }

    for (int i = 0; i < numParticleSystems; i++) {
        // Deserialize particle data
        Particle* particleSystem = particles + i * numParticlesPerSystem;

        for (int j = 0; j < numParticlesPerSystem; j++) {
            fread(&particleSystem->value, sizeof(double), 1, file);
            fread(&particleSystem->vec.x, sizeof(float), 1, file);
            fread(&particleSystem->vec.y, sizeof(float), 1, file);
            fread(&particleSystem->vec.z, sizeof(float), 1, file);

            particleSystem++;
        }
    }

    // Free allocated memory
    free(particles);

    fclose(file);
}

int main() {
    int numParticleSystems = 10;
    int numParticlesPerSystem = 1000;

    // Initialize random number generator
    srand(time(NULL));

    initParticles(numParticleSystems, numParticlesPerSystem);
    serializeParticles(numParticleSystems, numParticlesPerSystem);

    return 0;
}
