    int value;
} CacheEntry;

typedef struct {
    unsigned long seed;
    pthread_mutex_t lock;
    size_t capacity;
    size_t current_size;
    CacheEntry** entries;
    int max_queue_size;
    int queue_front, queue_rear;
} CacheManager;

void cache_init(CacheManager* manager, int capacity, int max_queue_size, int seed);
int cache_insert(CacheManager* manager, char* key, int value);
int cache_get(CacheManager* manager, char* key);
void cache_flush(CacheManager* manager);

CacheEntry** new_entry_array(size_t size) {
    return (CacheEntry**)malloc(sizeof(CacheEntry*) * size);
}

CacheManager* new_cache_manager(int capacity, int max_queue_size, int seed) {
    CacheManager* manager = (CacheManager*)malloc(sizeof(CacheManager));
    manager->seed = seed;
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = capacity;
    manager->current_size = 0;
    manager->entries = new_entry_array(capacity);
    manager->max_queue_size = max_queue_size;
    manager->queue_front = 0;
    manager->queue_rear = 0;

    return manager;
}

void cache_init(CacheManager* manager, int capacity, int max_queue_size, int seed) {
    // Initialize hash table with given capacity
    manager->entries = new_entry_array(capacity);

    // Set the initial seed for hashing
    srandom(seed);

    // Initialize queue parameters
    manager->max_queue_size = max_queue_size;
    manager->queue_front = 0;
    manager->queue_rear = 0;

    printf("Cache initialized with capacity %d, maximum queue size %d, and seed %d.\n", 
           capacity, max_queue_size, seed);
}

int cache_insert(CacheManager* manager, char* key, int value) {
    // Check if the cache is full
    if (manager->current_size >= manager->capacity) {
        printf("Cache is full. Cannot insert new entry.\n");
        return -1;
    }

    // Find an empty slot in the hash table
    size_t index = random() % manager->capacity;

    // Check if there's a collision
    while (manager->entries[index] != NULL) {
        index = (index + 1) % manager->capacity;
    }

    // Insert new entry into the cache
    CacheEntry* new_entry = (CacheEntry*)malloc(sizeof(CacheEntry));
    new_entry->key = key;
    new_entry->value = value;
    manager->entries[index] = new_entry;

    // Increment current size of the cache
    manager->current_size++;

    printf("Inserted entry with key %s and value %d into cache.\n", key, value);

    return 0;
}

int cache_get(CacheManager* manager, char* key) {
    // Search for the given key in the hash table
    size_t index = random() % manager->capacity;

    while (manager->entries[index] != NULL && strcmp(manager->entries[index]->key, key) != 0) {
        index = (index + 1) % manager->capacity;
    }

    if (manager->entries[index] == NULL || strcmp(manager->entries[index]->key, key) != 0) {
        printf("Key not found in cache.\n");
        return -1;
    } else {
        printf("Found entry with key %s and value %d in cache.\n", key, manager->entries[index]->value);
        return manager->entries[index]->value;
    }
}

void cache_flush(CacheManager* manager) {
    // Flush all entries from the cache
    for (size_t i = 0; i < manager->capacity; i++) {
        if (manager->entries[i] != NULL) {
            free(manager->entries[i]);
            manager->entries[i] = NULL;
        }
    }

    printf("Flushed entire cache.\n");
}

int main() {
    // Initialize the cache with a capacity of 100, maximum queue size of 50, and seed of 42
    CacheManager* manager = new_cache_manager(100, 50, 42);

    // Insert entries into the cache
    char* key1 = "key1";
    int value1 = 10;
    char* key2 = "key2";
    int value2 = 20;

    cache_insert(manager, key1, value1);
    cache_insert(manager, key2, value2);

    // Retrieve entries from the cache
    int result1 = cache_get(manager, key1);
    int result2 = cache_get(manager, key2);

    // Flush the cache
    cache_flush(manager);

    return 0;
}
