    long* offsets = NULL;
    int* keys = NULL;

    try {
        records = (record*)malloc(numRecords * sizeof(record));
        if (!records) {
            callback("Failed to allocate memory for records");
            return NULL;
        }

        offsets = (long*)malloc(numRecords * sizeof(long));
        if (!offsets) {
            free(records);
            callback("Failed to allocate memory for offsets");
            return NULL;
        }

        keys = (int*)malloc(numRecords * sizeof(int));
        if (!keys) {
            free(offsets);
            free(records);
            callback("Failed to allocate memory for keys");
            return NULL;
        }

        srand(time(NULL)); // initialize random seed

        for (int i = 0; i < numRecords; i++) {
            records[i].integer = rand() % 100 + 1; // populate with unique random values
            offsets[i] = i * sizeof(int); // initialize offset values
            keys[i] = i; // initialize key values

            // ensure no two records share the same key
            for (int j = 0; j < i; j++) {
                if (keys[j] == keys[i]) {
                    callback("Error: duplicate key");
                    return NULL;
                }
            }
        }

        free(keys);
