void add_session(int user_id, char* token) {
    // Allocate a new session struct
    Session* new_session = (Session*)malloc(sizeof(Session));

    if (!new_session) {
        printf("Error: Failed to allocate memory for new session.\n");
        return;
    }

    new_session->user_id = user_id;
    new_session->token = token;
    new_session->last_activity = time(NULL);
    new_session->connection_status = 1; // Initial connection status

    // Add the new session to the list
    sessions = (Session**)realloc(sessions, (num_sessions + 1) * sizeof(Session*));
    if (!sessions) {
        printf("Error: Failed to allocate memory for session list.\n");
        free(new_session);
        return;
    }

    sessions[num_sessions] = new_session;
    num_sessions++;
}

void remove_session(char* token) {
    int i;
    for (i = 0; i < num_sessions; i++) {
        if (strcmp(sessions[i]->token, token) == 0) {
            // Mark the session as removed
            sessions[i]->connection_status = 0;

            // If this is the last session in the list, remove it
            if (--num_sessions == 0) {
                free(sessions);
                sessions = NULL;
            } else {
                // Reallocate the session list to reduce memory fragmentation
                sessions = (Session**)realloc(sessions, num_sessions * sizeof(Session*));
            }

            // Free the removed session struct
            free(sessions[i]);
            return;
        }
    }
}

void query_session(char* token) {
    int i;
    for (i = 0; i < num_sessions; i++) {
        if (strcmp(sessions[i]->token, token) == 0) {
            printf("User ID: %d, Last Activity Timestamp: %lu, Connection Status: %d\n", sessions[i]->user_id, sessions[i]->last_activity, sessions[i]->connection_status);
            return;
        }
    }
    printf("Session not found.\n");
}

void expire_inactive_sessions() {
    int i;
    time_t current_time = time(NULL);

    for (i = 0; i < num_sessions; i++) {
        if (current_time - sessions[i]->last_activity > 60) { // Expire inactive sessions after 1 minute
            remove_session(sessions[i]->token);
        }
    }
}

