    const char *algorithm = "AES-256-CBC";
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1; // Handle error

    if (EVP_CipherInit_ex(ctx, NULL, NULL, NULL, 0, 0) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Process the command line option
    const char *cipherText = cmdLineOption;
    unsigned char cipher[256]; // Allocate memory for the cipher text
    int cipherLen = strlen(cipherText);

    if (EVP_CipherUpdate(ctx, cipher, &cipherLen) <= 0) {
        EVP_CIPHER_CTX_free(ctx);
        return -1;
    }

    // Clean up and return
    EVP_CIPHER_CTX_free(ctx);
    return records; // Return the pointer to the record array
