// Define the configuration structures
typedef struct {
    int value;
} config_t;

typedef struct {
    float param;
    char* setting;
} extended_config_t;

typedef struct {
    config_t* configs;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} multi_config_t;

// Initialize the multi-config structure
void init_multi_config(multi_config_t* mc) {
    mc->size = 0;
    mc->configs = NULL;
    pthread_mutex_init(&mc->mutex, NULL);
    pthread_cond_init(&mc->cond, NULL);
}

// Add a configuration to the multi-config structure
int add_config(multi_config_t* mc, config_t* config) {
    // Resize the array if necessary
    if (mc->size >= mc->configs) {
        mc->configs = realloc(mc->configs, (mc->size * 3 + 1) * sizeof(config_t));
    }

    // Add the configuration and notify waiting threads
    pthread_mutex_lock(&mc->mutex);
    mc->configs[mc->size] = *config;
    mc->size++;
    pthread_cond_signal(&mc->cond);
    pthread_mutex_unlock(&mc->mutex);

    return 0;
}

// Process network request headers
int process_request_header(char* header) {
    // Parse and validate the header
    char* ip_addr = strtok(header, ":");
