    char* proto = strtok(NULL, " ");
    char* user_agent = strtok(NULL, "\n");
    char* content_type = strtok(NULL, "\n");

    // Log the request and validate its integrity
    printf("Received request from IP address %s, port %d, protocol %s\n", ip_addr, port, proto);

    // Extract critical information and handle errors
    if (ip_addr == NULL || port < 0 || proto == NULL) {
        printf("Invalid header: %s\n", header);
        return -1;
    }

    // Configure logging to track successful and failed requests
    int log_level = 2; // Debug level
    char* log_message = "Received request from IP address ";
    strcat(log_message, ip_addr);
    strcat(log_message, " on port ");
    itoa(port, log_message + strlen(log_message), 10);

    // Integrate with centralized logging system
    printf("%s\n", log_message);

    return 0;
}
