void fillArraysAndRecords(int** offsets, long** values, Record** records, int* recordCount, FILE* file) {
    json_object* root = json_object_from_file(file);
    if (!root) {
        return; // handle error
    }

    json_object_iter* iter;
    json_object_iter_init(root);

    int offsetCount = 0;
    int keyCount = 0;

    while ((iter = json_object_iter_next(iter))) {
        if (strcmp(iter->key, "offsets") == 0) {
            offsetCount = iter->value.json_array->len;
        } else if (strcmp(iter->key, "keys") == 0) {
            keyCount = iter->value.json_array->len;
        }
    }

    *offsets = (int*)malloc(offsetCount * sizeof(int));
    *values = (long*)malloc(offsetCount * sizeof(long));

    int i = 0;
    json_object_iter* iterOffset;
    json_object_iter_init(root);

    while ((iterOffset = json_object_iter_next(iterOffset))) {
        if (strcmp(iterOffset->key, "offsets") == 0) {
            for (json_object_iter* innerIter = iterOffset->value.json_array->iter; innerIter != NULL; innerIter = json_object_iter_next(innerIter)) {
                (*values)[i] = atol(innerIter->value.json_value->buf);
                (*offsets)[i] = atoi(innerIter->value.json_value->buf);
                i++;
            }
        }
    }

    *records = (Record*)malloc(keyCount * sizeof(Record));
    for (int j = 0; j < keyCount; j++) {
        records[j].value = j;
    }

    json_object_iter_free(iter);
}
