Record* initRecords(int numRecords, int seed) {
    // Initialize random number generator with custom seed if provided
    srand(seed);

    // Dynamically allocate memory for records and their metadata
    Record* records = (Record*)malloc(numRecords * sizeof(Record));
    long* offsets = (long*)malloc(numRecords * sizeof(long));
    int* keys = (int*)malloc(numRecords * sizeof(int));

    // Initialize record metadata with random values
    for (int i = 0; i < numRecords; i++) {
        records[i].key = rand() % 100;
        offsets[i] = rand();
        records[i].value = rand() % 100;
    }

    // Return allocated memory and its metadata
    return records;
}

// Function to add a new record request with optional custom seed
void addRecord(Record* records, int numRecords, int key, long offset) {
    // Allocate new memory for the record structure
    Record* newRecord = (Record*)malloc(sizeof(Record));

    // Initialize the new record with provided metadata and random value
    newRecord->key = key;
    newRecord->offset = offset;
    newRecord->value = rand() % 100;

    // Insert the new record at the end of the array, ensuring thread safety
    int i;
    for (i = numRecords - 1; i >= 0; i--) {
        records[i + 1] = records[i];
    }
    records[0] = *newRecord;
}

// Function to process text file line by line and print results
void processTextFile(char* filePath) {
    // Initialize variables for logging and peak memory consumption tracking
    int peakMemoryUsage = 0;

    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Process the line and calculate average of last two fields
        int sum = 0;
        int fieldCount = 0;
        for (char* token = strtok(line, ","); token != NULL; token = strtok(NULL, ",")) {
            if (fieldCount >= 2) {
                sum += atoi(token);
            }
            fieldCount++;
        }
        printf("%s", line);
        if (fieldCount > 1) {
            printf(", %d\n", sum / 2);
        } else {
            printf("\n");
        }

        // Monitor memory usage and track peak consumption
        int currentMemoryUsage = sysconf(_SC_PAGE_SIZE) * 3; // Assuming three pages for stack, heap, and other data
        if (currentMemoryUsage > peakMemoryUsage) {
            peakMemoryUsage = currentMemoryUsage;
        }
    }

    fclose(file);
    printf("Peak memory usage: %d\n", peakMemoryUsage);

    return;
}

// Function to handle memory allocation failures and provide error messages
void handleMemError() {
    printf("Memory allocation failure. Please adjust your system settings or reduce the request size.\n");
}

int main(int argc, char* argv[]) {
    // Initialize random number generator with custom seed if provided
    srand(time(NULL));

    // Initialize data structures for records and their metadata
    int numRecords = 10000;
    Record* records = initRecords(numRecords, time(NULL));

    // Process text file line by line and print results
    processTextFile("input.txt");

    return 0;
}

