#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct for key-value pairs
typedef struct {
    char* key;
    double value;
} KvPair;

// Define the hash table structure
typedef struct {
    int capacity;
    int size;
    KvPair** buckets;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} HashTable;

// Initialize a new hash table with a given initial capacity
HashTable* init_hash_table(int capacity) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->capacity = capacity;
    table->size = 0;
    table->buckets = (KvPair**)calloc(capacity, sizeof(KvPair*));
    pthread_mutex_init(&table->lock, NULL);
    pthread_cond_init(&table->cond, NULL);
    return table;
}

// Insert a new key-value pair into the hash table
void insert_hash_table(HashTable* table, char* key, double value) {
    int index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->lock);
    KvPair* pair = (KvPair*)malloc(sizeof(KvPair));
    pair->key = strdup(key);
    pair->value = value;
    if (table->buckets[index] == NULL) {
        table->size++;
    }
    table->buckets[index] = pair;
    pthread_mutex_unlock(&table->lock);
}

// Retrieve the value associated with a given key from the hash table
double get_hash_table(HashTable* table, char* key) {
    int index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->lock);
    KvPair* pair = table->buckets[index];
    if (pair != NULL && strcmp(pair->key, key) == 0) {
        double value = pair->value;
        pthread_mutex_unlock(&table->lock);
        return value;
    } else {
        pthread_mutex_unlock(&table->lock);
        return -1.0; // Key not found
    }
}

// Custom hash function for string keys
int hash_function(char* key, int capacity) {
    unsigned long hash = 0;
    while (*key != '\0') {
        hash = (hash * 31 + *key) % capacity;
        key++;
    }
    return (int)hash;
}

// Log each operation in the hash table
void log_operation(HashTable* table, char* op) {
    // Log the operation here
}

// Free resources allocated by the hash table
void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->capacity; i++) {
        KvPair* pair = table->buckets[i];
        while (pair != NULL) {
            KvPair* next = pair;
            pair = pair->next;
            free(next);
        }
    }
    free(table->buckets);
    free(table);
}

// Main function
int main() {
    // Initialize the hash table with an initial capacity of 1000
    HashTable* table = init_hash_table(1000);

    // Insert key-value pairs into the hash table
    for (int i = 0; i < 100000; i++) {
        char* key = malloc(10);
        sprintf(key, "%d", i);
        double value = (double)i;
        insert_hash_table(table, key, value);
        free(key);
    }

    // Retrieve values from the hash table
    for (int i = 0; i < 100000; i++) {
        char* key = malloc(10);
        sprintf(key, "%d", i);
        double value = get_hash_table(table, key);
        if (value == -1.0) {
            printf("Key not found: %s\n", key);
        } else {
            printf("Value for %s is %f\n", key, value);
        }
        free(key);
    }

    // Free resources allocated by the hash table
    free_hash_table(table);

    return 0;
}
