// Define hash table node structure
typedef struct {
    Config* config;
    pthread_mutex_t lock;
} Node;

// Hash function to calculate index from key
int hash(char* key) {
    unsigned int hash = 0;
    for(int i = 0; i < strlen(key); i++) {
        hash += (unsigned int)(key[i]);
    }
    return hash % 256;
}

// Create new node and initialize mutex
Node* create_node(Config* config) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->config = config;
    pthread_mutex_init(&node->lock, NULL);
    return node;
}

// Hash table structure to manage configurations
typedef struct {
    Node** buckets;
    int size;
} ConfigHashTable;

// Create new hash table with initial capacity
ConfigHashTable* create_hash_table(int capacity) {
    ConfigHashTable* table = (ConfigHashTable*)malloc(sizeof(ConfigHashTable));
    table->buckets = (Node**)malloc((capacity + 1)*sizeof(Node*));
    for(int i = 0; i <= capacity; i++) {
        table->buckets[i] = NULL;
    }
    table->size = capacity;
    return table;
}

// Function to manage dynamic configuration storage system
void config_storage_system(ConfigHashTable** table, Config* new_config) {
    int index = hash(new_config->key);
    Node* node = (Node*)malloc(sizeof(Node));
    node->config = new_config;
    pthread_mutex_init(&node->lock, NULL);

    if(table[index] == NULL) {
        table[index] = node;
    } else {
        // Resize table when reaching capacity
        int new_size = (*table)->size * 2;
        ConfigHashTable* new_table = create_hash_table(new_size);
        for(int i = 0; i <= (*table)->size; i++) {
            if((*table)->buckets[i] != NULL) {
                node = (*table)->buckets[i];
                while(node->config != NULL) {
                    int newIndex = hash(node->config->key);
                    new_table->buckets[newIndex] = node;
                    node = node->next;
                }
            }
        }
        free((*table));
        *table = new_table;
    }
}

