        new_node->next = head;
        head = new_node;
    }

    // Handle memory allocation and initialization
    if (!head) {
        printf("Memory exhausted. Notifying the user.\n");
        (*memory_exhausted)(void);
        return;
    }

    // Perform asynchronous data retrieval from external sources using callback function
    for (int i = 0; i < offset; i++) {
        if ((*callback)(metadata_array, head->entry) == -1) {
