Record* initializeArrays(size_t size) {
    // Calculate the total number of elements required for each array
    size_t offsetSize = size * sizeof(long);
    size_t keySize = size * sizeof(int);
    size_t recordSize = size * sizeof(Record);

    // Allocate memory for the arrays and ensure proper alignment
    long* offsets = (long*)malloc(offsetSize + (size - 1) % alignof(long));
    int* keys = (int*)malloc(keySize + (size - 1) % alignof(int));
    Record* records = (Record*)malloc(recordSize);

    // Check for memory allocation failures
    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    // Initialize the offset and key arrays with sequential numbers starting from 0
    pthread_t thread;
    pthread_create(&thread, NULL, initializeArraysThread, &size);
    pthread_join(thread);

    // Randomly generate initial values for the Record array elements within a specified range
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        records[i].value = rand() % 100;
    }

    // Validate the integrity of all allocated memory blocks and ensure that no uninitialized data exists in the Record array
    for (int i = 0; i < size; i++) {
        if (!records[i].value) {
            printf("Error: Uninitialized value detected in the Record array.\n");
            return NULL;
        }
    }

    // Deallocate memory blocks
    free(offsets);
    free(keys);
    free(records);

    return records;
}

void* initializeArraysThread(void* arg) {
    size_t* size = (size_t*)arg;
    for (int i = 0; i < *size; i++) {
        offsets[i] = i;
        keys[i] = i;
    }
    pthread_exit(NULL);
