#include <stdlib.h>
#include <stdio.h>

#define MAX_OFFSET_SIZE 1024 * 1024 * 1024LL // 1TB
#define OFFSET_ARRAY_ALIGN 64
#define KEY_ARRAY_THRESHHOLD 1048576 // 1MB
#define RECORD_STRUCT_ALIGN 64

typedef struct {
    long* offset;
    int* key;
    record* records;
} data_structure;

typedef struct {
    long ptr;
    int key_id;
} record;

void init_data(struct data_structure** data, long max_offset) {
    long size = (max_offset + OFFSET_ARRAY_ALIGN - 1) / OFFSET_ARRAY_ALIGN * sizeof(long);
    size += KEY_ARRAY_THRESHHOLD;
    size /= 2; // assume half the size for keys
    size = (size + 31) & ~31; // align to 32-byte boundary

    *data = malloc(sizeof(data_structure));
    (*data)->offset = aligned_alloc(OFFSET_ARRAY_ALIGN, size);
    (*data)->key = aligned_alloc(OFFSET_ARRAY_ALIGN, size / 2);
    (*data)->records = NULL;

    for (long i = 0; i < max_offset; i++) {
        if ((i + 1) * sizeof(long) > size) {
            size *= 2;
            (*data)->offset = realloc((*data)->offset, size);
            (*data)->key = realloc((*data)->key, size / 2);
        }
    }
}

void destroy_data(struct data_structure* data) {
    free(data->offset);
    free(data->key);
    if (data->records)
        free(data->records);
    free(data);
}

long offset_get(struct data_structure* data, long idx) {
    return data->offset[idx];
}

int key_get(struct data_structure* data, long idx) {
    return data->key[idx];
}

void record_set(struct data_structure* data, long idx, long ptr, int key_id) {
    data->records[idx].ptr = ptr;
    data->records[idx].key_id = key_id;
}

long serialize_data(const struct data_structure* data, char** buffer) {
    // Serialize offset array
    *buffer = realloc(*buffer, sizeof(long) * (data->offset ? data->offset_size : 0));
    for (long i = 0; i < data->offset_size; i++)
        *((long*)((*buffer) + i * sizeof(long))) = data->offset[i];

    // Serialize key array
    *buffer = realloc(*buffer, sizeof(int) * (data->key_size ? data->key_size : 0));
    for (long i = 0; i < data->key_size; i++)
        *((int*)((*buffer) + i * sizeof(long))) = data->key[i];

    // Serialize records array
    *buffer = realloc(*buffer, sizeof(record) * data->offset_size);
    for (long i = 0; i < data->offset_size; i++) {
        record* rec = &data->records[i];
        *((record*)((*buffer) + i * sizeof(record))) = *rec;
    }

    return *buffer;
}

void deserialize_data(struct data_structure** data, const char* buffer) {
    // Deserialize offset array
    (*data)->offset_size = (long)(buffer_size(buffer) / sizeof(long));
    (*data)->offset = aligned_alloc(OFFSET_ARRAY_ALIGN, (*data)->offset_size * sizeof(long));
    memcpy((*data)->offset, buffer, (*data)->offset_size * sizeof(long));

    // Deserialize key array
    (*data)->key_size = (*data)->offset_size;
    (*data)->key = aligned_alloc(OFFSET_ARRAY_ALIGN, (*data)->key_size * sizeof(int));
    memcpy((*data)->key, buffer + (*data)->offset_size * sizeof(long), (*data)->key_size * sizeof(int));

    // Deserialize records array
    (*data)->records = aligned_alloc(64, (*data)->offset_size * sizeof(record));
    memcpy((*data)->records, buffer + (*data)->offset_size * sizeof(long) + (*data)->key_size * sizeof(int),
           (*data)->offset_size * sizeof(record));

    buffer += (*data)->offset_size * sizeof(long) + (*data)->key_size * sizeof(int) + (*data)->offset_size * sizeof(record);
}

