#include <pthread.h>

// Define the configuration structures
typedef struct {
    int id;
    char* key;
    bool active;
    enum priority { LOW, MEDIUM, HIGH } priority;
} config_t;

typedef struct {
    float param1;
    char* setting1;
} extended_config_t;

typedef struct {
    int size;
    config_t** configs;
} multi_config_t;

// Define the hash table structure
typedef struct {
    int capacity;
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    config_t** configs;
} hashtable_t;

hashtable_t* configure_init(int capacity);
int configure_set(hashtable_t*, config_t*);
config_t* configure_get(hashtable_t*, char*);
void configure_free(hashtable_t*);

// Initialize the configuration storage system
hashtable_t* configure_init(int capacity) {
    hashtable_t* table = (hashtable_t*)malloc(sizeof(hashtable_t));
    table->capacity = capacity;
    table->size = 0;
    pthread_mutex_init(&table->mutex, NULL);
    pthread_cond_init(&table->cond, NULL);
    table->configs = (config_t**)calloc(capacity, sizeof(config_t*));
    return table;
}

// Set a configuration value
int configure_set(hashtable_t* table, config_t* config) {
    // Hash the key to determine the index
    int index = hash_function(config->key, table->capacity);
    pthread_mutex_lock(&table->mutex);
    if (table->size >= table->capacity * 0.65) {
        // Resize the array if it reaches capacity
        table->configs = (config_t**)realloc(table->configs, table->capacity * 3 * sizeof(config_t*));
        table->capacity *= 3;
    }
    config_t** configs = (config_t**)(table->configs + index);
    configs[table->size] = config;
    table->size++;
    pthread_mutex_unlock(&table->mutex);
    return 0;
}

// Get a configuration value
config_t* configure_get(hashtable_t* table, char* key) {
    int index = hash_function(key, table->capacity);
    pthread_mutex_lock(&table->mutex);
    config_t** configs = (config_t**)(table->configs + index);
    for (int i = 0; i < table->size; i++) {
        if (strcmp(configs[i]->key, key) == 0) {
            return configs[i];
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return NULL;
}

// Free the configuration storage system
void configure_free(hashtable_t* table) {
    for (int i = 0; i < table->size; i++) {
        free(table->configs[i]);
    }
    free(table->configs);
    pthread_cond_destroy(&table->cond);
    pthread_mutex_destroy(&table->mutex);
    free(table);
}

// Hash function to determine the index
int hash_function(char* key, int capacity) {
    // Simple hash function using ASCII values and modulo operation
    int hash = 0;
    for (int i = 0; i < strlen(key); i++) {
        hash += key[i];
    }
    return hash % capacity;
}
