#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <json-c/json.h>

typedef struct {
    char* name;
    double* data;
} processingNode;

int configureDataProcessingPipeline(const char* configFilePath) {
    // Load JSON configuration file
    json_object* config = json_load_file(configFilePath, NULL);

    if (!config) {
        return -1;  // Error loading configuration file
    }

    // Initialize dynamic memory allocation cache
    size_t cacheSize = 1024;
    void** cache = (void**)malloc(cacheSize * sizeof(void*));
    int cacheCount = 0;

    // Initialize processing nodes array
    int numNodes = json_object_get_array_size(config, "nodes");
    processingNode* nodes = (processingNode*)malloc(numNodes * sizeof(processingNode));

    for (int i = 0; i < numNodes; i++) {
        json_object* nodeConfig = json_object_object_get(config, "node");

        // Initialize processing node
        char** strings = json_object_get_array_elements(nodeConfig, "strings");
        int index = json_object_get_int_value(nodeConfig, "index");
        processingNode node;
        node.name = strings[rand() % json_object_get_array_size(nodeConfig, "strings")];
        node.data = (double*)malloc(sizeof(double));
        *node.data = 0.5 + i;  // Initialize data with random values
        node.count = 1;

        // Add node to cache if not already present
        int found = 0;
        for (int j = 0; j < cacheCount; j++) {
            if (!strcmp(node.name, (char*)cache[j])) {
                found = 1;
                break;
            }
        }
        if (!found) {
            cache[cacheCount++] = &node;
            if (cacheCount >= cacheSize) {
                cacheSize *= 2;
                void** tempCache = (void**)malloc(cacheSize * sizeof(void*));
                memcpy(tempCache, cache, cacheSize / 2 * sizeof(void*));
                free(cache);
                cache = tempCache;
            }
        }

        // Add node to processing nodes array
        nodes[i] = node;
    }

    // Free configuration object and memory allocation cache
    json_object_free(config);
    for (int i = 0; i < cacheCount; i++) {
        free((void*)cache[i]);
    }
    free(cache);

    return 1;  // Successful initialization
}
