int dynamicMemoryAllocationAndInitialization(long offsets[], int keys[], int numOffsets) {
    // Initialize random seed for generating random numbers
    srand(time(NULL));

    long maxInts = 0;
    for (int i = 0; i < numOffsets; i++) {
        if (offsets[i] > maxInts) {
            maxInts = offsets[i];
        }
    }

    int totalInts = 0;
    for (int i = 0; i < numOffsets; i++) {
        totalInts += offsets[i];
    }

    // Check if the total size of all 'int' arrays combined exceeds 1000 elements
    if (totalInts > 1000) {
        return -1; // Error: Total number of 'int' elements exceeds 1000
    }

    int* recordPtrs[numOffsets];
    for (int i = 0; i < numOffsets; i++) {
        int* intArr = malloc(offsets[i] * sizeof(int));
        if (!intArr) {
            return -1; // Error: Memory allocation failed
        }
        recordPtrs[i] = intArr;
        for (int j = 0; j < offsets[i]; j++) {
            intArr[j] = rand() % 100; // Generate random 'int' values within the range [0, 99]
        }
    }

    return 0; // Success
}

// Function to free dynamically allocated memory
void cleanup(int** recordPtrs, long* offsets, int numOffsets) {
    for (int i = 0; i < numOffsets; i++) {
        if (recordPtrs[i]) {
            free(recordPtrs[i]);
        }
    }
}
