int free_node(Node* node) {
    if (!node) return 1;
    Node* current = node;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    log_operation("Deallocated", sizeof(Node), 0);
    return 1;
}

Node* create_node(int range_min, int range_max) {
    Node* new_node = my_calloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->value = rand() % (range_max - range_min + 1) + range_min;
    while (new_node->value == node->value && node != NULL) {
        new_node->value = rand() % (range_max - range_min + 1) + range_min;
        if (!node->next) break;
        node = node->next;
    }
    return new_node;
}

Node* create_list(int max_size, int range_min, int range_max) {
    Node* head = NULL;
    Node* tail = NULL;
    for (int i = 0; i < max_size; i++) {
        if (check_memory_limit()) {
            log_operation("Memory Limit Exceeded", sizeof(Node), i);
            return head;
        }
        Node* new_node = create_node(range_min, range_max);
        if (!new_node) break;
        if (i == 0) head = new_node;
        else tail->next = new_node;
        tail = new_node;
    }
    log_operation("List Created", sizeof(Node), max_size);
    return head;
}

void destroy_list(Node* list) {
