struct mem_allocator {
    size_t total_alloc;
    pthread_mutex_t mutex;
};

record** alloc_records(size_t count, struct mem_allocator* allocator) {
    record** records = (record**)malloc(count * sizeof(record*));
    for (size_t i = 0; i < count; i++) {
        records[i] = (record*)malloc(sizeof(record));
        pthread_mutex_lock(&allocator->mutex);
        allocator->total_alloc += sizeof(record);
        pthread_mutex_unlock(&allocator->mutex);
    }
    return records;
}

char** alloc_strings(size_t count, struct mem_allocator* allocator) {
    char** strings = (char**)malloc(count * sizeof(char*));
    for (size_t i = 0; i < count; i++) {
        size_t str_len = strlen("string") + 1;
        strings[i] = (char*)malloc(str_len);
        strcpy(strings[i], "string");
        pthread_mutex_lock(&allocator->mutex);
        allocator->total_alloc += str_len;
        pthread_mutex_unlock(&allocator->mutex);
    }
    return strings;
}

void* alloc_offset(size_t count, struct mem_allocator* allocator) {
    long* offsets = (long*)malloc(count * sizeof(long));
    for (size_t i = 0; i < count; i++) {
        pthread_mutex_lock(&allocator->mutex);
        allocator->total_alloc += sizeof(long);
        pthread_mutex_unlock(&allocator->mutex);
    }
    return offsets;
}

void* alloc_key(size_t count, struct mem_allocator* allocator) {
    int* keys = (int*)malloc(count * sizeof(int));
    for (size_t i = 0; i < count; i++) {
        pthread_mutex_lock(&allocator->mutex);
        allocator->total_alloc += sizeof(int);
        pthread_mutex_unlock(&allocator->mutex);
    }
    return keys;
}

void check_limit(struct mem_allocator* allocator, size_t alloc_size) {
    if (allocator->total_alloc + alloc_size > sysconf(_SC_PAGE_SIZE)) {
        printf("Memory limit exceeded. Attempting to free up resources.\n");
        // Implement memory deallocation logic here
    }
}

record** manage_memory(size_t record_count, size_t string_count, size_t offset_count, size_t key_count) {
    struct mem_allocator allocator;
    pthread_mutex_init(&allocator.mutex, NULL);
    allocator.total_alloc = 0;

    record** records = alloc_records(record_count, &allocator);
    char** strings = alloc_strings(string_count, &allocator);
    long* offsets = (long*)alloc_offset(offset_count, &allocator);
    int* keys = (int*)alloc_key(key_count, &allocator);

    check_limit(&allocator, sizeof(long) * offset_count + sizeof(int) * key_count + record_count * sizeof(record));

    return records;
}
