    enum RecordStatus* status_indicators = (enum RecordStatus*)malloc(total_size * sizeof(enum RecordStatus));

    for (size_t i = 0; i < total_size; i++) {
        records[i].value = generate_random_value();
        if (i > 0) {
            // Ensure no two consecutive records have the same value
            while (records[i].value == records[i - 1].value) {
                records[i].value = generate_random_value();
            }
        }

        status_indicators[i] = PENDING; // Initialize all records as pending
    }

    free_ unused_records();
    return malloced_memory;
}

void update_record(size_t resource_id, int key, RequestBody* updated_data) {
    if (pthread_mutex_lock(&record_lock)) {
        perror("Failed to lock record mutex");
        exit(1);
    }

    Record* target_record = find_record(resource_id);

    // Update the record
    target_record->value = updated_data->new_value;

    if (!target_record->is_pending) {
        transition_status_to_active(target_record);
    }

    pthread_mutex_unlock(&record_lock);
}

void delete_resource(size_t resource_id, RequestBody* request_body) {
    if (pthread_mutex_lock(&record_lock)) {
        perror("Failed to lock record mutex");
        exit(1);
    }

    Record* target_record = find_record(resource_id);

    // Delete the record
    transition_status_to_deleted(target_record);

    pthread_mutex_unlock(&record_lock);
}
