record* manage_memory(int offsets_size, int keys_size, int minValue, int maxValue, bool paginated) {
    if (offsets_size <= 0 || offsets_size > 1000 || keys_size <= 0 || keys_size > 500) {
        printf("Invalid size. Sizes must be between 1 and 1000.\n");
        return NULL;
    }
    if (keys_size > offsets_size / 2) {
        printf("Invalid size. Keys size cannot exceed half of offsets size.\n");
        return NULL;
    }
    if (minValue >= maxValue || minValue < 0) {
        printf("Invalid value range. MinValue must be less than maxValue and non-negative.\n");
        return NULL;
    }

    int num_records = (paginated ? (offsets_size + keys_size) : (offsets_size > keys_size ? offsets_size : keys_size));
    record* records = paginated ? malloc((num_records / 2) * sizeof(record)) : malloc(num_records * sizeof(record));
    if (!records) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int* offsets = paginated ? malloc((num_records / 2) * sizeof(int)) : malloc(offsets_size * sizeof(int));
    if (!offsets) {
        free(records);
        records = NULL;
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int* keys = paginated ? malloc((num_records / 2) * sizeof(int)) : malloc(keys_size * sizeof(int));
    if (!keys) {
        free(offsets);
        offsets = NULL;
        free(records);
        records = NULL;
        printf("Memory allocation failed.\n");
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < (paginated ? num_records / 2 : num_records); i++) {
        int random_value = rand() % ((maxValue - minValue) + 1) + minValue;
        records[i].value = random_value;

        if (i < (paginated ? num_records / 2 : offsets_size)) {
            offsets[i] = i;
        }
        if (i < (paginated ? num_records / 2 : keys_size)) {
            keys[i] = rand() % ((maxValue - minValue) + 1) + minValue;
        }
    }

    // Free allocated memory
    free(offsets);
    free(keys);

    return records;
}
