    // Validate input sizes
    if (offsetsSize < 1 || offsetsSize > 1000 ||
        keysSize < 1 || keysSize > 500 || // Ensure keys size does not exceed half of offsets size
        offsetsSize > INT_MAX / sizeof(record) ||
        keysSize > INT_MAX / sizeof(int)) {
        printf("Invalid input sizes. Aborting.\n");
        return NULL;
    }

    // Allocate and initialize arrays
    int* offsets = (int*)malloc(offsetsSize * sizeof(int));
    int* keys = (int*)malloc(keysSize * sizeof(int));

    if (!offsets || !keys) {
        printf("Memory allocation failed. Aborting.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    // Initialize arrays
    for (int i = 0; i < offsetsSize; i++) {
        offsets[i] = i * 2; // Example initialization
    }
    for (int i = 0; i < keysSize; i++) {
        keys[i] = i % 2; // Example initialization
    }

    // Validate record size and allocate memory
    int recordsSize = (offsetsSize > keysSize) ? keysSize : offsetsSize;
    if (recordsSize > INT_MAX / sizeof(struct record)) {
        printf("Record allocation failed. Aborting.\n");
        free(offsets);
        free(keys);
        return NULL;
    }

    struct record* records = (struct record*)malloc(recordsSize * sizeof(struct record));

