import json
import random

class DataStructuresManager:
    def __init__(self, paginated=False):
        self.registry = {}
        self.random_seed = 42
        random.seed(self.random_seed)
        self.paginated = paginated

    def register_factory(self, id, factory):
        if not callable(factory):
            raise ValueError("Factory function must be callable")
        self.registry[id] = factory

    def create_from_json(self, json_string):
        try:
            data = json.loads(json_string)
            return self.create(data['id'], **data.get('args', {}))
        except (json.JSONDecodeError, KeyError) as e:
            raise ValueError(f"Invalid JSON: {e}")

    def to_json(self, instance):
        return json.dumps(instance.__dict__)

    def create(self, id, **kwargs):
        if id not in self.registry:
            raise ValueError("Unknown data structure ID")
        factory = self.registry[id]
        try:
            instance = factory(**kwargs)
            if self.paginated:
                size = instance.get_size()
                allocated = random.randint(0, size - 1) if random.random() < 0.5 else size
                return instance.allocate(allocated), allocated
            else:
                return instance.allocate(size), size
        except Exception as e:
            raise ValueError(f"Failed to create data structure: {e}")
        finally:
            self.free_memory(instance)

    def free_memory(self, instance):
        if hasattr(instance, 'free'):
            instance.free()
