#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define RECORD_THRESHOLD 100
#define MEMORY_LIMIT 1048576 // in bytes (1MB)

typedef struct {
    int value;
} record_t;

record_t* records = NULL;
int num_records = 0;
int total_bytes = 0;
int* keys = NULL;
long* offsets = NULL;
FILE* log_file = NULL;

void free_memory() {
    if (total_bytes > MEMORY_LIMIT) {
        size_t oldest_record_size = sizeof(record_t);
        for (size_t i = 0; i < num_records / 2; ++i) {
            record_t* temp = records + i;
            records[i] = records[num_records - i - 1];
            free(temp);
        }
    }
}

void* allocate_memory(size_t size) {
    if (total_bytes + size > MEMORY_LIMIT) {
        free_memory();
    }
    void* ptr = malloc(size);
    total_bytes += size;
    return ptr;
}

int random_value(int min, int max) {
    srand(time(NULL));
    return rand() % ((max + 1) - min) + min;
}

void initialize_arrays() {
    offsets = allocate_memory(sizeof(long) * RECORD_THRESHOLD);
    keys = allocate_memory(sizeof(int) * RECORD_THRESHOLD);
    records = allocate_memory(sizeof(record_t) * RECORD_THRESHOLD);

    for (int i = 0; i < RECORD_THRESHOLD; ++i) {
        long offset = i;
        int key = random_value(1, 100);
        record_t* record = records + i;
        record->value = random_value(key, key + 10); // ensure no consecutive equal values
        offsets[i] = offset;
        keys[i] = key;
    }
}

