#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_NODE_SIZE 256
#define BUFFER_SIZE 1024
#define MEMORY_THRESHOLD 1024*1024*10 // 10MB

typedef struct node {
    char buffer[MAX_NODE_SIZE];
    struct node* prev;
    struct node* next;
} node;

void* alloc_array(size_t size) {
    return malloc(size);
}

void free_array(void* ptr, size_t size) {
    free(ptr);
}

int main() {
    // Offset array
    offset_t* offsets = (offset_t*)alloc_array(sizeof(offset_t)*4);
    for(int i=0; i<4; i++) {
        offsets[i] = i;
    }

    // Identifier array
    uint32_t* identifiers = (uint32_t*)alloc_array(sizeof(uint32_t)*4);
    for(int i=0; i<4; i++) {
        identifiers[i] = i;
    }

    // Initialize linked list
    node* head = NULL;
    node* tail = NULL;

    for(int i=0; i<10; i++) {
        node* new_node = (node*)malloc(sizeof(node));
        if(new_node == NULL) {
            printf("Error: Memory allocation failed\n");
            exit(-1);
        }

        // Fill buffer with random data
        char str[MAX_NODE_SIZE];
        for(int j=0; j<MAX_NODE_SIZE; j++) {
            int num = rand() % 256;
            if(num < 33) { // Special characters
                str[j] = (char)num;
            } else if(num < 58) { // Uppercase letters
                str[j] = 'A' + (num-33);
            } else { // Digits and lowercase letters
                str[j] = 'a' + (num-58)%26;
            }
        }

        strcpy(new_node->buffer, str);

        if(head == NULL) {
            head = new_node;
            tail = new_node;
        } else {
            new_node->prev = tail;
            tail->next = new_node;
            tail = new_node;
        }
    }

    // Initialize circular buffer
    char* buffer = (char*)alloc_array(BUFFER_SIZE);
    for(int i=0; i<BUFFER_SIZE; i++) {
        buffer[i] = 'X'; // Fill with arbitrary data
    }

    // Free all memory
    free_array(identifiers, sizeof(uint32_t)*4);
    free_array(offsets, sizeof(offset_t)*4);
    free_array(buffer, BUFFER_SIZE);

    return 0;
}
