    void* ptr = realloc(memory_pool, size);
    if (ptr == NULL) {
        printf("Memory allocation failed!\n");
        return -1;
    }
    memory_pool = ptr;
    return 0;
}

int initialize_weather_entries(int num_entries) {
    struct weather_entry* weathers = memory_pool;
    srand(time(NULL));
    for (int i = 0; i < num_entries; i++) {
        weathers[i].temperature = (float)rand() / RAND_MAX * 100.0f;
        weathers[i].condition = (char)(rand() % 2); // 0 or 1
        weathers[i].timestamp = time(NULL);
    }
    return 0;
}

void log_weather_entries(int num_entries, char* file_path) {
    pthread_mutex_lock(pthread_mutex_t*)mutex; // assume mutex exists
    FILE* f = fopen(file_path, "a");
    if (f == NULL) {
        printf("Failed to open the log file!\n");
        return;
    }
    for (int i = 0; i < num_entries; i++) {
        fprintf(f, "%f %c %ld\n", weathers[i].temperature, weathers[i].condition, weathers[i].timestamp);
    }
    fclose(f);
    pthread_mutex_unlock(mutex);
}

void validate_weather_entries(int num_entries) {
    for (int i = 0; i < num_entries; i++) {
        if (weathers[i].temperature < -100.0f || weathers[i].temperature > 100.0f) {
            printf("Invalid temperature at index %d!\n", i);
        }
        if (weathers[i].condition != '0' && weathers[i].condition != '1') {
            printf("Invalid weather condition at index %d!\n", i);
        }
    }
}

int main() {
    int num_entries = 100;
    if (allocate_weather_entries(num_entries) < 0) {
        return -1;
    }
    initialize_weather_entries(num_entries);
    log_weather_entries(num_entries, "weather_log.txt");
    validate_weather_entries(num_entries);
    return 0;
}
