#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000000
#define RECORD_POOL_SIZE 10000
#define KEY_RANGE 100
#define VALUE_RANGE 500

typedef struct {
    int key;
    long offset;
    int value;
} record_t;

record_t* records = NULL;
int records_count = 0;
int records_pool_size = 0;
int records_pool_used = 0;
int records_pool_head = 0;
int records_pool_tail = 0;
int *keys = NULL;
long *offsets = NULL;

void release_memory() {
    if (records) {
        free(records);
        records = NULL;
    }
    if (keys) {
        free(keys);
        keys = NULL;
    }
    if (offsets) {
        free(offsets);
        offsets = NULL;
    }
}

int get_random_value(int min, int max) {
    return rand() % (max - min + 1) + min;
}

record_t* alloc_record() {
    record_t* new_rec = NULL;
    if (records_pool_used < RECORD_POOL_SIZE) {
        if (records_pool_head >= records_pool_tail) {
            if (!records) {
                records = (record_t*)malloc(RECORD_POOL_SIZE * sizeof(record_t));
                records_count = RECORD_POOL_SIZE;
                records_pool_size = RECORD_POOL_SIZE;
                records_pool_used = 0;
            }
            new_rec = &records[records_pool_head];
        } else {
            new_rec = &records[records_pool_tail];
            records_pool_tail = (records_pool_tail + 1) % records_pool_size;
        }
    }
    return new_rec;
}

void free_record(record_t* rec) {
    if (rec && records_pool_used < RECORD_POOL_SIZE) {
        if (records_pool_head <= records_pool_tail) {
            records_pool_head = (records_pool_head + 1) % records_pool_size;
        } else {
            records_pool_head = 0;
            records_pool_tail = records_pool_used % records_pool_size;
        }
    }
}

void insert_record(int key, long offset) {
    record_t* new_rec = alloc_record();
    if (new_rec) {
        new_rec->key = key;
        new_rec->offset = offset;
        new_rec->value = get_random_value(0, VALUE_RANGE);
        records[records_count++] = *new_rec;
        free_record(new_rec);
    }
}

int lookup_record(int key) {
    int hash = key % RECORD_POOL_SIZE;
    if (hash >= 0 && hash < records_pool_size) {
        for (int i = 0; i < records_pool_size; i++) {
            int j = (i + hash) % RECORD_POOL_SIZE;
            if (records[j].key == key) {
                return j;
            }
        }
    }
    return -1;
}

void init() {
    srand(time(NULL));
    keys = (int*)malloc(RECORD_POOL_SIZE * sizeof(int));
    offsets = (long*)malloc(RECORD_POOL_SIZE * sizeof(long));
    records_pool_size = RECORD_POOL_SIZE;
    records_pool_used = 0;
}
