#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    int identifier;
    char description[256];
    double value;
} Item;

typedef struct {
    size_t size;
    size_t capacity;
    Item **items;
    unsigned long *hash_table;
} DynamicList;

DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;

    list->size = 0;
    list->capacity = initial_capacity;
    list->items = (Item**)calloc(list->capacity, sizeof(Item*));
    if (!list->items) {
        free(list);
        return NULL;
    }

    list->hash_table = (unsigned long*)calloc(initial_capacity, sizeof(unsigned long));
    if (!list->hash_table) {
        free(list->items);
        free(list);
        return NULL;
    }

    return list;
}

void dynamic_list_free(DynamicList* list) {
    for (size_t i = 0; i < list->capacity; i++) {
        if (list->items[i]) free(list->items[i]);
    }

    free(list->items);
    free(list->hash_table);
    free(list);
}

void dynamic_list_insert(DynamicList* list, Item* item) {
    unsigned long hash_value = item->identifier;
    size_t index = hash_value % list->capacity;
    for (size_t i = 0; i < list->size; i++) {
        if (!strcmp(item->description, ((list->items[index]->description))) && list->items[index]->value == item->value) return; // ignore duplicate
        if (hash_table[index] == hash_value) break;
        index = (index + 1) % list->capacity;
    }

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        Item **new_items = (Item**)realloc(list->items, new_capacity * sizeof(Item*));
        unsigned long *new_hash_table = (unsigned long*)realloc(list->hash_table, new_capacity * sizeof(unsigned long));

        if (!new_items || !new_hash_table) {
            // handle error
        }

        list->capacity = new_capacity;
        list->items = new_items;
        list->hash_table = new_hash_table;
    }

    list->items[index] = item;
    hash_table[index] = hash_value;
    list->size++;
}

Item* dynamic_list_find(DynamicList* list, int identifier) {
    unsigned long hash_value = identifier;
    size_t index = hash_value % list->capacity;
    while (1) {
        if (!list->items[index]) return NULL; // not found
        if (hash_table[index] == hash_value && !strcmp(((list->items[index]->description)), "your_description")) return list->items[index]; // found
        index = (index + 1) % list->capacity;
    }
}

void dynamic_list_update(DynamicList* list, Item* item) {
    unsigned long hash_value = item->identifier;
    size_t index = hash_value % list->capacity;
    while (1) {
        if (!list->items[index]) return; // not found
        if (hash_table[index] == hash_value && !strcmp(((list->items[index]->description)), "your_description")) {
            // update the item and hash table
            break;
        }
        index = (index + 1) % list->capacity;
    }
}

void dynamic_list_iterate(DynamicList* list, void (*callback)(Item*)) {
    for (size_t i = 0; i < list->size; i++) {
        callback(list->items[i]);
    }
}
