            while(temp->next != NULL) {
                temp = temp->next;
            }
            temp->next = new_node;
        }
    }

    // Initialize circular buffer
    char_buffer_element* buffer = (char_buffer_element*)malloc(100 * sizeof(char_buffer_element));
    for(int i = 0; i < 10; i++) {
