    for(int i = 0; i < 10000; i++) {
        if(hash_table == NULL) {
            init_error = 1;
            break;
        }
        hash_table[i] = NULL;
    }

    // Resize circular buffer dynamically
    int total_elements = 10;
    while(total_elements <= 20) {
        if(buffer == NULL || (char_buffer_element*)realloc(buffer, (total_elements + 10) * sizeof(char_buffer_element)) == NULL) {
            init_error = 1;
            break;
        }
        total_elements += 10;
    }

    // Manage memory deallocation
    free(head);
    for(int i = 0; i < total_elements; i++) {
        free(&buffer[i]);
    }
    free(buffer);
    for(int i = 0; i < 10000; i++) {
        if(hash_table[i] != NULL) {
            free(hash_table[i]);
        }
    }
    free(hash_table);

    // Limit total memory usage to specified threshold
    long max_memory_usage = 1024 * 1024;
    int total_allocated_memory = sizeof(offset_array) + sizeof(identifier_array) + head->offset + sizeof(char_buffer_element) * total_elements + sizeof(entry*) * 10000;
    if(total_allocated_memory > max_memory_usage) {
        init_error = 1;
    }

    return NULL;
}
