        users[i].name = (char*)malloc((strlen("User ") + 10) * sizeof(char));
        strcpy(users[i].name, "User ");
        int len = rand() % 10 + 1;
        for (int j = 0; j < len; j++) {
            users[i].name[j] = (char)(rand() % 26 + 97);
        }
        users[i].name[len] = '\0';
        users[i].roles = (char**)malloc(max_roles * sizeof(char*));
        for (int j = 0; j < max_roles; j++) {
            users[i].roles[j] = (char*)malloc((strlen("Role ") + 10) * sizeof(char));
            strcpy(users[i].roles[j], "Role ");
            int len2 = rand() % 5 + 1;
            for (int k = 0; k < len2; k++) {
                users[i].roles[j][k] = (char)(rand() % 26 + 97);
            }
            users[i].roles[j][len2] = '\0';
        }
        users[i].permissions = (char**)malloc(max_permissions * sizeof(char*));
        for (int j = 0; j < max_permissions; j++) {
            users[i].permissions[j] = (char*)malloc((strlen("Permission ") + 10) * sizeof(char));
            strcpy(users[i].permissions[j], "Permission ");
            int len3 = rand() % 5 + 1;
            for (int k = 0; k < len3; k++) {
                users[i].permissions[j][k] = (char)(rand() % 26 + 97);
            }
            users[i].permissions[j][len3] = '\0';
        }
    }

    // Periodically log the user profiles to a distributed key-value store
    for (int i = 0; i < num_users; i++) {
        printf("User ID: %d, Name: %s, Roles: ", users[i].id, users[i].name);
        for (int j = 0; j < max_roles; j++) {
            printf("%s ", users[i].roles[j]);
        }
        printf(", Permissions: ");
        for (int j = 0; j < max_permissions; j++) {
            printf("%s ", users[i].permissions[j]);
        }
        printf("\n");
    }

    // Validate the integrity of the user profiles at regular intervals
    int num_inconsistencies = 0;
    for (int i = 0; i < num_users; i++) {
        if (users[i].id < 0 || strlen(users[i].name) > 10 || 
            strlen(users[i].roles[0]) > 5 || strlen(users[i].permissions[0]) > 5) {
            printf("Inconsistency found: User %d\n", users[i].id);
            num_inconsistencies++;
        }
    }

    // Handle memory deallocation and logging
    for (int i = 0; i < num_users; i++) {
        free(users[i].name);
        for (int j = 0; j < max_roles; j++) {
            free(users[i].roles[j]);
        }
        for (int j = 0; j < max_permissions; j++) {
            free(users[i].permissions[j]);
        }
    }
    free(users);

    if (num_inconsistencies > 0) {
        printf("Total inconsistencies: %d\n", num_inconsistencies);
    } else {
        printf("No inconsistencies found.\n");
    }
}
