    // Log the error with the specified level and destination
    // ...
}

Transaction* create_transaction(int value, char* string) {
    Transaction* transaction = (Transaction*)malloc(sizeof(Transaction));
    transaction->value = value;
    strcpy(transaction->string, string);
    return transaction;
}

Item* create_item(char* data, int value) {
    Item* item = (Item*)malloc(sizeof(Item));
    strcpy(item->data, data);
    item->value = value;
    item->next = NULL;
    item->prev = NULL;
    return item;
}

void free_transactions(Transaction** transactions) {
    Transaction* current = *transactions;
    Transaction* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *transactions = NULL;
}

void free_items(Item** items) {
    Item* current = *items;
    Item* next;

    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    *items = NULL;
}
