#define MAX_RECORDS 10000000
#define TIMESTAMP_WINDOW 1000 // in milliseconds
#define STRING_MAX_LENGTH 512
#define JSON_KEY_NAME_MAX_LENGTH 32

typedef struct {
    float value;
    char string[STRING_MAX_LENGTH + 1];
} data_record;

void manage_memory(int num_records) {
    // Allocate memory for timestamp array
    long* timestamps = (long*)malloc(num_records * sizeof(long));
    if (!timestamps) {
        fprintf(stderr, "Failed to allocate memory for timestamps.\n");
        return;
    }

    // Initialize timestamps with unique values within the specified window
    time_t current_time = time(NULL);
    for (int i = 0; i < num_records; i++) {
        timestamps[i] = current_time + (rand() % TIMESTAMP_WINDOW);
    }

    // Allocate memory for double precision floating-point array
    double* doubles = (double*)malloc(num_records * sizeof(double));
    if (!doubles) {
        fprintf(stderr, "Failed to allocate memory for double precision floating-point array.\n");
        free(timestamps); // Free previously allocated memory
        return;
    }

    // Initialize double precision floating-point array with random values between 0.0 and 1.0
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        doubles[i] = (double)rand() / RAND_MAX;
    }

    // Allocate memory for char string array
    char** strings = (char**)malloc(num_records * sizeof(char*));
    if (!strings) {
        fprintf(stderr, "Failed to allocate memory for char string array.\n");
        free(timestamps);
        free(doubles); // Free previously allocated memory
        return;
    }

    // Initialize char string array with unique identifiers based on the index of each record
    for (int i = 0; i < num_records; i++) {
        strings[i] = (char*)malloc(JSON_KEY_NAME_MAX_LENGTH + 1);
        sprintf(strings[i], "record_%d", i);
    }

    // Allocate memory for data_record array
    data_record* records = (data_record*)malloc(num_records * sizeof(data_record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for data record array.\n");
        free(timestamps);
        free(doubles);
        for (int i = 0; i < num_records; i++) {
            free(strings[i]);
        }
        free(strings); // Free previously allocated memory
        return;
    }

    // Initialize data_record array with random values and unique identifiers
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        records[i].value = (float)rand() / RAND_MAX;
        sprintf(records[i].string, "record_%d", i);
    }

    // Free allocated memory
    free(timestamps);
    free(doubles);
    for (int i = 0; i < num_records; i++) {
        free(strings[i]);
    }
    free(strings);

    return;
}
