void manage_memory_allocation_and_initialization(int *offsets_size, int *keys_size, int *records_size,
                                                    int min_key_value, int max_key_value) {
    int* offsets = (int*)malloc(*offsets_size * sizeof(int));
    if (!offsets) {
        printf("Error: Memory allocation for offsets failed.\n");
        return;
    }

    int* keys = (int*)malloc(*keys_size * sizeof(int));
    if (!keys) {
        printf("Error: Memory allocation for keys failed. Freeing previously allocated memory...\n");
        free(offsets);
        return;
    }

    record_t* records = (record_t*)malloc(*records_size * sizeof(record_t));
    if (!records) {
        printf("Error: Memory allocation for records failed. Freeing previously allocated memory...\n");
        free(offsets);
        free(keys);
        return;
    }

    // Initialize keys and records
    for (int i = 0; i < *keys_size; ++i) {
        keys[i] = min_key_value + i % (max_key_value - min_key_value + 1);
    }
    for (int i = 0; i < *records_size; ++i) {
        records[i].data = min_key_value + i % (max_key_value - min_key_value + 1);
    }

    // Populate offsets
    int offset_index = 0;
    for (int i = 0; i < *offsets_size; ++i) {
        if (i % (*keys_size) == 0 && i > 0) {
            offset_index++;
        }
        offsets[i] = i / (*keys_size);
    }

    // Release allocated memory
    free(records);
    free(keys);
}
