typedef struct {
    int value;
} record;

record* array_create(size_t size) {
    record* arr = (record*)malloc(sizeof(record) * size);
    for (size_t i = 0; i < size; i++) {
        arr[i].value = rand() % 100;
    }
    return arr;
}

void array_resize(record** arr, size_t new_size) {
    if (!*arr) {
        *arr = (record*)malloc(sizeof(record) * new_size);
    } else {
        record* temp = (record*)malloc(sizeof(record) * new_size);
        for (size_t i = 0; i < (*arr)->size; i++) {
            temp[i] = (*arr)[i];
        }
        free(*arr);
        *arr = temp;
    }
}

void array_free(record** arr) {
    if (*arr) {
        free(*arr);
        *arr = NULL;
    }
}

int main() {
    // Initialize random seed
    srand(time(NULL));

    record* records = array_create(10);
    int keys[] = {0, 1, 2};
    long offset[] = {1, 2, 3};

    // Print initial arrays
    printf("Records:\n");
    for (size_t i = 0; i < 10; i++) {
        printf("%d ", records[i].value);
    }
    printf("\nKeys: ");
    for (int i = 0; i < 3; i++) {
        printf("%d ", keys[i]);
    }
    printf("\nOffsets: ");
    for (size_t i = 0; i < 3; i++) {
        printf("%ld ", offset[i]);
    }
    printf("\n");

    // Resize arrays
    array_resize(&records, 20);
    int new_keys[] = {4, 5, 6};
    long new_offsets[] = {4, 5, 6};
    array_free(&keys);
    array_free(&offset);

    keys = (int*)malloc(sizeof(int) * 3);
    offset = (long*)malloc(sizeof(long) * 3);
    for (size_t i = 0; i < 3; i++) {
        keys[i] = new_keys[i];
        offset[i] = new_offsets[i];
    }

    // Print resized arrays
    printf("Resized Records:\n");
    for (size_t i = 0; i < 20; i++) {
        printf("%d ", records[i].value);
    }
    printf("\nResized Keys: ");
    for (int i = 0; i < 3; i++) {
        printf("%d ", keys[i]);
