    record* records = (record*)malloc(count * RECORD_SIZE);
    if (!records) {
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        record temp = {rand() % offset_range + 1, rand() % key_range};
        memcpy(&records[i], &temp, RECORD_SIZE);
    }

    return records;
