// Function prototypes
void* allocArray(size_t size);
void initRecordArray(record*, size_t);
int resizeArrays(void** arrays, size_t*** arraySizes, size_t new_size);

// Initialize memory and data structures
void memoryManagerInit(int offsetSize, int keySize, int recordSize) {
    // Allocate memory for the arrays
    void* offsets = allocArray(offsetSize * sizeof(long));
    void* keys = allocArray(keySize * sizeof(int));
    void** records = (void**)malloc(recordSize * sizeof(void*));

    // Initialize each element in the 'record' array to a random value within a specified range
    initRecordArray((record*)records, recordSize);

    // Set array sizes for dynamic resizing
    int*** arraySizes = (int***)malloc(3 * sizeof(int*));
    arraySizes[0] = &offsetSize;
    arraySizes[1] = &keySize;
    arraySizes[2] = &recordSize;

    return offsets, keys, records, arraySizes;
}

// Deallocate memory and reset data structures
void memoryManagerFree(void* offsets, void* keys, void** records, int*** arraySizes) {
    // Deallocate the arrays
    free(offsets);
    free(keys);
    for (int i = 0; i < *arraySizes[2]; i++) {
        free((void*)records[i]);
    }
    free(records);

    // Reset array sizes
    for (int i = 0; i < 3; i++) {
        free(arraySizes[i]);
    }
    free(arraySizes);
}

// Allocate memory for an array
void* allocArray(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed!\n");
        exit(1);
    }
    return ptr;
}

// Initialize each element in the 'record' array to a random value within a specified range
void initRecordArray(record* records, size_t recordSize) {
    srand(time(NULL));
    for (int i = 0; i < recordSize; i++) {
        records[i].value = rand() % 100;
    }
}

// Resize the arrays based on new size and maintain data consistency
int resizeArrays(void** arrays, int*** arraySizes, size_t newSize) {
    // Calculate the number of elements to copy
    size_t copySize = newSize - *arraySizes[0];
    if (copySize < 0) {
        printf("Array resized too small!\n");
        return 1;
    }

    // Resize the arrays
    void* newOffsets = allocArray(newSize * sizeof(long));
    void* newKeys = allocArray(newSize * sizeof(int));
    void** newRecords = (void**)malloc(newSize * sizeof(void*));

    // Copy data from old to new arrays
    for (int i = 0; i < copySize; i++) {
        memcpy((char*)newOffsets + i * sizeof(long), (char*)arrays[0], sizeof(long));
        memcpy((char*)newKeys + i * sizeof(int), (char*)arrays[1], sizeof(int));
        for (int j = 0; j < recordSize; j++) {
            memcpy((char*)newRecords[j] + i * sizeof(int), (char*)arrays[2][j], sizeof(int));
        }
    }

    // Update array sizes and pointers
    free((void*)arrays[0]);
    free((void*)arrays[1]);
    for (int i = 0; i < recordSize; i++) {
        free((void*)arrays[2][i]);
    }
    free((void**)arrays[2]);
    arrays[0] = newOffsets;
    arrays[1] = newKeys;
    arrays[2] = newRecords;
    *arraySizes[0] = newSize;
    *arraySizes[1] = newSize;
    *arraySizes[2] = recordSize;

    return 0;
}

int main() {
    int offsetSize, keySize, recordSize;

    // Initialize data structures and memory
    offsets, keys, records, arraySizes) = memoryManagerInit(offsetSize, keySize, recordSize);

    // Use the arrays...

    // Deallocate memory and reset data structures
    memoryManagerFree(offsets, keys, records, arraySizes);

    return 0;
}
