typedef struct {
    int id;
    time_t timestamp;
    char category[20];
} transaction_metadata;

void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
        exit(-1);
    }
    return ptr;
}

void my_free(void *ptr) {
    free(ptr);
}

double* initialize_transactions(double* transactions, int num_transactions) {
    for (int i = 0; i < num_transactions; i++) {
        transactions[i] = (double)rand() / RAND_MAX;
    }
    return transactions;
}

transaction_metadata* initialize_metadata(transaction_metadata* metadata, int num_transactions) {
    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        metadata[i].id = rand();
        metadata[i].timestamp = time(NULL);
        char category[] = "Transaction";
        strcpy(metadata[i].category, category);
    }
    return metadata;
}

void resize_arrays(double** transactions, int* transaction_size, transaction_metadata** metadata, int* metadata_size) {
    *transaction_size *= 2;
    *metadata_size *= 2;

    double* new_transactions = (double*)my_malloc(*transaction_size * sizeof(double));
    transaction_metadata* new_metadata = (transaction_metadata*)my_malloc(*metadata_size * sizeof(transaction_metadata));

    for (int i = 0; i < *transaction_size / 2; i++) {
        new_transactions[i] = transactions[i];
    }

    for (int i = 0; i < *metadata_size / 2; i++) {
        new_metadata[i] = metadata[i];
    }

    free(*transactions);
    free(*metadata);

    *transactions = new_transactions;
    *metadata = new_metadata;
}

void serialize_data(double* transactions, int transaction_size, transaction_metadata* metadata, int metadata_size) {
    FILE* file = fopen("data.bin", "wb");
    if (!file) {
        printf("Failed to open file for writing.\n");
        return;
    }

    fwrite(&transaction_size, sizeof(int), 1, file);
    fwrite(transactions, sizeof(double), transaction_size, file);

    fwrite(&metadata_size, sizeof(int), 1, file);
    fwrite(metadata, sizeof(transaction_metadata), metadata_size, file);

    fclose(file);
}

int main() {
    int num_transactions = 100;
    double* transactions = (double*)my_malloc(num_transactions * sizeof(double));
    initialize_transactions(transactions, num_transactions);
    transaction_metadata* metadata = (transaction_metadata*)my_malloc(num_transactions * sizeof(transaction_metadata));
    initialize_metadata(metadata, num_transactions);

    // Perform some operations on the data

    serialize_data(transactions, num_transactions, metadata, num_transactions);

    free(transactions);
    free(metadata);

    return 0;
}
