        for (int j = 0; j < 10; j++) {
            profiles[i].preferences[j] = rand() % 100;
        }

        offset_values_ptr[i] = i;
        keys_ptr[i] = i;
        records_ptr[i] = &records[i];
    }

    return profiles;
}

// Define function to filter Old Testament books
int* filter_old_testament_books(char* text, regex_t* old_testament_book_regexes[], int num_books) {
    // Initialize array for book frequencies
    int* frequencies = (int*)malloc(num_books * sizeof(int));

    // Loop through each book
    for (int i = 0; i < num_books; i++) {
        // Compile regular expression for current book
        regcomp(old_testament_book_regexes[i], "whole word", REG_EXTENDED | REG_NOSUB);

        // Search for matches in text
        int count = 0;
        regex_t* match = NULL;
        while (regexec(old_testament_book_regexes[i], text, 100, &match, 0) == 0) {
            count++;
        }

        // Update frequency array
        frequencies[i] = count;

        // Release memory for current book's regular expression
        regfree(match);
    }

    return frequencies;
}

