    if (id >= max_nodes) {
        printf("Error: Node ID exceeds maximum allowed.\n");
        return NULL;
    }

    // Allocate memory for new node
    void* node = malloc(sizeof(void));
    *(void**)nodes[id] = node;

    return node;
}

