void configureServiceEnvironment(int num_nodes, long* offsets, int* keys,
                                   struct record** records, enum status* statuses,
                                   char*** env_vars, struct node** nodes, struct event** events,
                                   struct old_testament_book_freq* books) {
    // Initialize variables
    pthread_mutex_init(&mutex, NULL);
    regex_t* regexs = (regex_t*)malloc(sizeof(regex_t) * 5);

    int i;
    for (i = 0; i < 5; i++) {
        regcomp(&regexs[i], "^(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclasiastes|SongOfSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Nahum|Habakkuk|Zephaniah|Haggai|Zechariah|Malachi)$", REG_EXTENDED);
    }

    // Loop through nodes
    for (i = 0; i < num_nodes; i++) {
        node_t* node = &nodes[i];
        node->offset = offsets[i];
        node->key = keys[i];
        node->record = &records[i];
        node->status = statuses[i];

        // Load environment variables
        char* env_var = getenv(env_vars[i]);
        if (env_var != NULL) {
            // Check for matches using regular expressions
            for (int j = 0; j < 5; j++) {
                regmatch_t match;
                regexec(&regexs[j], env_var, 0, &match, 0);
                if (!regexec(&regexs[j], env_var + match.rm_so, 0, &match, 0)) {
                    // Increment frequency
                    for (int k = 0; k < 5; k++) {
                        if (strcmp(env_var + match.rm_so, books[k].book) == 0) {
                            books[k].freq++;
                            break;
                        }
                    }
                }
            }
        }

        // Add node to queue
        pthread_mutex_lock(&mutex);
        nodes_queue_enqueue(node);
        pthread_mutex_unlock(&mutex);

        if (pthread_create(&thread, NULL, thread_func, node) != 0) {
            perror("Error creating thread");
        }
    }

    // Wait for threads to finish
    pthread_mutex_lock(&mutex);
    for (i = 0; i < num_nodes; i++) {
        pthread_join(thread, NULL);
    }
    pthread_mutex_unlock(&mutex);

    // Free resources
    free(regexs);
    for (i = 0; i < num_nodes; i++) {
        free(env_vars[i]);
        free(records[i]->value);
    }

    return;
}

int main() {
    int num_nodes = 5;
    long* offsets = (long*)malloc(sizeof(long) * num_nodes);
    int* keys = (int*)malloc(sizeof(int) * num_nodes);
    struct record** records = (struct record**)malloc(sizeof(struct record*) * num_nodes);
    enum status* statuses = (enum status*)malloc(sizeof(enum status) * num_nodes);
    char*** env_vars = (char***)malloc(sizeof(char*) * num_nodes);
    struct node** nodes = (struct node**)malloc(sizeof(struct node*) * num_nodes);
    struct event** events = (struct event**)malloc(sizeof(struct event*) * num_nodes);
    struct old_testament_book_freq* books = (struct old_testament_book_freq*)malloc(sizeof(struct old_testament_book_freq) * 5);

    configureServiceEnvironment(num_nodes, offsets, keys, records, statuses, env_vars, nodes, events, books);

    // Free memory
