```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RECORDS 1000
#define MIN_FLOAT_VALUE 0.0f
#define MAX_FLOAT_VALUE 1.0f
#define STATUS_FLAG_GOOD 0
#define STATUS_FLAG_BAD 1

typedef struct {
    long timestamp;
    float value;
    char status;
} Record;

Record* records = NULL;
long* offsets = NULL;
int* keys = NULL;
int record_count = 0;
int max_records = MAX_RECORDS;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = NULL;

void init_database(int max_offset) {
    if (records != NULL) free(records);
    records = (Record*)malloc(max_records * sizeof(Record));
    offsets = (long*)malloc(max_records * sizeof(long));
    keys = (int*)malloc(max_records * sizeof(int));
}

void add_record(int key, long offset, float value) {
    pthread_mutex_lock(&mutex);
    if (record_count >= max_records) {
        // Resize the database
        max_records *= 2;
        records = (Record*)realloc(records, max_records * sizeof(Record));
        offsets = (long*)realloc(offsets, max_records * sizeof(long));
        keys = (int*)realloc(keys, max_records * sizeof(int));
    }
    Record* record = &records[record_count];
    record->timestamp = offset;
    record->value = value;
    if (offset % 2 == 0) {
        record->status = STATUS_FLAG_GOOD;
    } else {
        record->status = STATUS_FLAG_BAD;
    }
    offsets[record_count] = offset;
    keys[record_count] = key;
    record_count++;
    pthread_mutex_unlock(&mutex);
}

void log_message(const char* message, int level) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        if (level == 1) {
            // Verbose logging
            time_t now = time(NULL);
            fprintf(log_file, "Logged at %s\n", ctime(&now));
        }
    }
}

void* thread_function(void* arg) {
    int key = *(int*)arg;
    for (int i = 0; i < 10; i++) {
        add_record(key, (long)i * 1000, (float)(rand() / (float)RAND_MAX));
    }
    return NULL;
}

void start_thread(int key) {
    pthread_t thread;
    int* arg = &key;
    pthread_create(&thread, NULL, thread_function, arg);
}

int main() {
    srand(time(NULL));
    init_database(MAX_RECORDS);
    for (int i = 0; i < 10; i++) {
        start_thread(i);
    }
    return 0;
}
