    time_t timestamp;
    char category[20];
} TransactionMetadata;

void manage_transactions(int num_transactions, double *transactions, TransactionMetadata *metadata) {
    // Allocate memory for transactions and metadata arrays
    transactions = (double *)malloc(num_transactions * sizeof(double));
    metadata = (TransactionMetadata *)malloc(num_transactions * sizeof(TransactionMetadata));

    // Initialize transaction values with random floating-point numbers within a specified range
    srand(time(NULL));
    for (int i = 0; i < num_transactions; i++) {
        transactions[i] = ((double)rand()) / RAND_MAX;
    }

    // Initialize metadata structures
    for (int i = 0; i < num_transactions; i++) {
        metadata[i].transaction_id = i;
        time_t timestamp = time(NULL);
        metadata[i].timestamp = timestamp;
        strcpy(metadata[i].category, "Transaction");
    }

    // Serialize transactions and metadata to a file
    FILE *file = fopen("transactions.bin", "wb");
    if (file != NULL) {
        fwrite(transactions, sizeof(double), num_transactions, file);
        fwrite(metadata, sizeof(TransactionMetadata), num_transactions, file);
        fclose(file);
    } else {
        printf("Error opening file for serialization\n");
    }
}

int main() {
    int num_transactions = 100;
    double *transactions = NULL;
    TransactionMetadata *metadata = NULL;

    manage_transactions(num_transactions, transactions, metadata);

    // Deserialize transactions and metadata from the file
    FILE *file = fopen("transactions.bin", "rb");
    if (file != NULL) {
        transactions = (double *)malloc(num_transactions * sizeof(double));
        metadata = (TransactionMetadata *)malloc(num_transactions * sizeof(TransactionMetadata));

        fread(transactions, sizeof(double), num_transactions, file);
        fread(metadata, sizeof(TransactionMetadata), num_transactions, file);

        fclose(file);

        // Print deserialized data
        for (int i = 0; i < num_transactions; i++) {
            printf("Transaction %d: %.2f\n", metadata[i].transaction_id, transactions[i]);
        }
    } else {
        printf("Error opening file for deserialization\n");
    }

    return 0;
}
