memory_pool *create_memory_pool(size_t initial_capacity) {
    memory_pool *mp = malloc(sizeof(memory_pool));
    mp->pool = malloc(initial_capacity * sizeof(void *));
    mp->capacity = initial_capacity;
    mp->current_size = 0;
    return mp;
}

void *allocate_from_memory_pool(memory_pool *mp, size_t size) {
    void **new_ptr;
    if (mp->current_size >= mp->capacity / 2) {
        // Realloc pool when it's half full
        mp->pool = realloc(mp->pool, mp->capacity * 2 * sizeof(void *));
        mp->capacity *= 2;
    }
    new_ptr = &mp->pool[mp->current_size];
    return *new_ptr;
}

void deallocate_from_memory_pool(memory_pool *mp, void *ptr) {
    // Simply increment the current size
    mp->current_size++;
}

// Function to manage memory allocation and lifecycle for two separate data structures: an array of 'double' values representing financial transactions and an array of 'transaction metadata' structures
void *manage_memory_allocation(size_t transaction_size, size_t metadata_size) {
    // Initialize random number generator
    srand(time(NULL));

