    transaction_metadata *metadata = allocate_from_memory_pool(create_memory_pool(1000), metadata_size);

    for (int i = 0; i < transaction_size; i++) {
        transactions[i] = RAND_FLOAT();
    }

    for (int i = 0; i < metadata_size; i++) {
        metadata[i].id = i;
        metadata[i].timestamp = time(NULL);
        strcpy(metadata[i].category, "Category");
    }

    deallocate_from_memory_pool(create_memory_pool(1000), transactions);
    deallocate_from_memory_pool(create_memory_pool(1000), metadata);

    return NULL;
}

// Function to serialize the data structures
