void* financial_transactions(int num_transactions, double range_min, double range_max) {
    // Allocate memory for array of double values representing transactions
    double* transactions = (double*)malloc(num_transactions * sizeof(double));

    // Allocate memory for array of transaction_metadata structures
    transaction_metadata* metadata = (transaction_metadata*)malloc(num_transactions * sizeof(transaction_metadata));

