        transactions[i] = (double)rand() / RAND_MAX * (range_max - range_min) + range_min;

        // Initialize metadata structure with random transaction ID, timestamp, and category
        metadata[i].tid = rand();
        metadata[i].timestamp = time(NULL);
        strcpy(metadata[i].category, "Transaction Category");
    }

    return transactions;
}

