    if (key < 0 || key > RECORD_SCHEMA_MAX_KEY) {
        return -1; // invalid key
    }
    return 0; // valid key
}

void* thread_func(void* arg) {
    int num_records = *(int*)arg;
    record_t* records = allocate_records(num_records);
    if (!records) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize records with data from external source
    for (int i = 0; i < num_records; i++) {
        int key, value;
        // Acquire data from external source
        // ...

        if (validate_key(key) == -1) {
            printf("Invalid key\n");
            continue;
        }
        init_record(&records[i], key, value);
    }

    // Periodically check and reclaim unused memory regions
    while (1) {
        // Check for unused memory regions
        // ...

        sleep(10); // periodic check every 10 seconds
    }
}

int main() {
    pthread_t threads[2];
    int num_records[] = {5000, 5000};

