    // Check for error
    if (systems == NULL) {
        return NULL;
    }

    // Loop through each record and initialize the particle system
    for (int i = 0; i < num_records; i++) {
        systems[i].mem = malloc(sizeof(particle_record_t));

        // Initialize the record data
        particle_record_t* record = systems[i].mem;
        record->offset = get_offset_from_external_data();
        record->key = get_key_from_external_data();
        record->value = get_value_from_external_data();
    }

    return systems;
}

// Function to retry data acquisition for partially filled records
void retry_data_acquisition(int num_records, particle_system_t* systems) {
    // Loop through each record and check if it's partially filled
    for (int i = 0; i < num_records; i++) {
        particle_record_t* record = systems[i].mem;

        // Check if the record is partially filled
        if (record->key == -1 || record->value == -1) {
            // Retry data acquisition and update the record
            record->offset = get_offset_from_external_data();
            record->key = get_key_from_external_data();
            record->value = get_value_from_external_data();

