typedef struct {
    int value;
    char *buffer;
} record;

record* initRecords(int numRecords, int keySize, int stringSize, long offsetMax) {
    // Validate input sizes and ranges
    if (numRecords <= 0 || keySize <= 0 || stringSize <= 0 || offsetMax < 0) {
        return NULL;
    }

    record *records = malloc(numRecords * sizeof(record));
    if (!records) {
        return NULL;
    }

    long *offsets = malloc(numRecords * sizeof(long));
    int *keys = malloc(numRecords * sizeof(int));

    // Populate offset and key arrays
    for (int i = 0; i < numRecords; i++) {
        offsets[i] = rand() % (offsetMax + 1);
        keys[i] = rand() % (keySize + 1);
    }

    // Initialize records array
    srand(time(NULL));
    for (int i = 0; i < numRecords; i++) {
        record *recordPtr = &records[i];
        recordPtr->value = rand() % (keySize + 1); // Random value within key range
        char *buffer = malloc(stringSize);
        if (!buffer) {
            free(records);
            free(offsets);
            free(keys);
            return NULL;
        }
        strcpy(buffer, "User-provided string"); // Initialize with a user-specified string
        recordPtr->buffer = buffer;
    }

    // Update pointer to first element in records array
    record *firstRecord = &records[0];
    free(offsets);
    free(keys);

    return firstRecord;
}
