pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int num_settings = 0;

void initialize_setting(setting_t* s) {
    pthread_mutex_lock(&mutex);
    // Initialize the setting here
    pthread_mutex_unlock(&mutex);
}

int get_num_settings() {
    return num_settings;
}

void add_setting(char* name, char description[], int priority, data_type_t type, void* data_value) {
    if (num_settings >= SETTINGS_MAX) {
        printf("Maximum number of settings exceeded.\n");
        return;
    }

    setting_t* s = &settings[num_settings];
    s->name = name;
    strcpy(s->description, description);
    s->priority = priority;

    switch (type) {
        case DATA_TYPE_LONG:
            s->data.l = *(long*)data_value;
            break;
        case DATA_TYPE_FLOAT:
            s->data.f = *(float*)data_value;
            break;
        case DATA_TYPE_VOID:
            s->data.v = data_value;
            break;
    }

    initialize_setting(s);
    num_settings++;
}

int main() {
    // Initialize the settings array here
    return 0;
}
