Record** createDynamicList(int numRecords, int minValue, int maxValue) {
    Record** list = NULL;
    size_t totalSize = 0;

    // Calculate the required memory size
    for (int i = 0; i < numRecords; i++) {
        size_t recordSize = sizeof(Record);
        totalSize += recordSize;
    }

    if ((list = malloc(totalSize)) == NULL) {
        printf("Failed to allocate memory.\n");
        return NULL;
    }

    for (int i = 0; i < numRecords; i++) {
        size_t recordSize = sizeof(Record);
        Record* record = (Record*)malloc(recordSize);

        if (record == NULL) {
            printf("Failed to allocate memory.\n");
            free(list);
            return NULL;
        }

        // Initialize the record with a random value
        record->value = rand() % (maxValue - minValue + 1) + minValue;

        list[i] = record;
    }

    return list;
}

void destroyDynamicList(Record** list, int numRecords) {
    for (int i = 0; i < numRecords; i++) {
        free(list[i]);
    }
    free(list);
}
