typedef struct {
    char* name;
    double value;
} item;

void init_item(item* i) {
    i->name = NULL;
    i->value = 0.0;
}

int item_count = 0;
item** items = NULL;

void add_item(char* name, double value) {
    item* new_item = (item*)malloc(sizeof(item));
    init_item(new_item);
    new_item->name = malloc(strlen(name) + 1);
    strcpy(new_item->name, name);
    new_item->value = value;

    if (!items) {
        items = malloc(2 * sizeof(item*));
        items[0] = new_item;
    } else {
        int i;
        for (i = item_count; i > 0; --i) {
            items[i] = items[i - 1];
        }
        items[i] = new_item;
    }

    ++item_count;
}

void print_items() {
    for (int i = 0; i < item_count; ++i) {
        printf("Name: %s, Value: %.2f\n", items[i]->name, items[i]->value);
    }
}

void free_items() {
    for (int i = 0; i < item_count; ++i) {
        if (items[i]->name)
            free(items[i]->name);
        free(items[i]);
    }

    free(items);
}
