} MemoryBlock;

// Initialize the custom memory pool with an initial allocation of 1024 bytes
MemoryBlock init_pool() {
    MemoryBlock pool = { malloc(1024), 1024, 1 };
    return pool;
}

// Deallocate a single block from the custom memory pool
void free_block(MemoryBlock* pool) {
    if (pool->refs > 0) {
        --pool->refs;
        if (pool->refs == 0 && pool->size != 0) {
            free(pool->block);
            pool->block = NULL;
            pool->size = 0;
        }
    }
}

// Reallocate a single block from the custom memory pool
MemoryBlock* reallocate_block(MemoryBlock* pool, size_t size) {
    if (pool->size < size || pool->refs > 0) {
        MemoryBlock new_pool = { malloc(size), size, 1 };
        free_block(pool);
        return &new_pool;
    }
    return pool;
}

// Dynamic memory allocation for the three arrays
void* dynamic_allocation(int* sizes) {
    int max_size = 10000; // Set maximum size for offsets array
    int key_max_size = 5000; // Set maximum size for keys array

    // Initialize arrays with custom memory pool
    MemoryBlock offset_pool = init_pool();
    MemoryBlock key_pool = init_pool();
    MemoryBlock record_pool = init_pool();

    long* offsets = NULL;
    int* keys = NULL;
    record_t* records = NULL;

    // Initialize arrays and allocate memory
    offsets = (long*)reallocate_block(&offset_pool, max_size * sizeof(long));
    keys = (int*)reallocate_block(&key_pool, key_max_size * sizeof(int));
    records = (record_t*)reallocate_block(&record_pool, sizes[2] * sizeof(record_t));

    // Initialize and set values for the three arrays
    int offset_index = 0;
    for (int i = 0; i < sizes[0]; i++) {
        offsets[i] = i + 1; // Set value for each offset
    }

    int key_index = 0;
    for (int i = 0; i < sizes[1]; i++) {
        keys[i] = i % sizes[0]; // Set value for each key
    }

    // Initialize records array with random values and corresponding offsets
    for (int i = 0; i < sizes[2]; i++) {
        record_t* record = &records[i];
        int offset;
        if (i < sizes[1]) {
            offset = keys[i];
        } else {
            offset = NULL; // Set to NULL for records without matching key
        }
        // Randomly set the value of each record's 'int' field within a specified range
        record->value = rand() % 100; // Replace with actual random number generation
        record->offset = &offsets[offset]; // Set offset pointer
    }

    return records;
}
