// Hash table structure
typedef struct {
    int size;
    long* offsets;
    int* keys;
    Record** records;
} RecordMap;

// Function to initialize the record map
RecordMap* init_record_map(int capacity) {
    RecordMap* map = (RecordMap*)malloc(sizeof(RecordMap));
    map->size = 0;
    map->offsets = (long*)malloc(capacity * sizeof(long));
    map->keys = (int*)malloc(capacity * sizeof(int));
    map->records = (Record**)malloc(capacity * sizeof(Record*));
    return map;
}

// Function to free the record map
void free_record_map(RecordMap* map) {
    if (!map) return;
    for (int i = 0; i < map->size; i++) {
        free(map->records[i]);
    }
    free(map->offsets);
    free(map->keys);
    free(map->records);
    free(map);
}

// Function to insert a record into the map
void insert_record(RecordMap* map, int key, Record* record) {
    long idx = (long)(key % map->size);
    while (idx >= map->size) {
        idx -= map->size;
    }
    for (int i = 0; i <= idx; i++) {
        if (!map->records[i]) break;
    }
    if (i == idx + 1) {
        map->size++;
        map->offsets = (long*)realloc(map->offsets, (map->size + 1) * sizeof(long));
        map->keys = (int*)realloc(map->keys, (map->size + 1) * sizeof(int));
        map->records = (Record**)realloc(map->records, (map->size + 1) * sizeof(Record*));
    }
    map->offsets[idx] = i;
    map->keys[idx] = key;
    map->records[idx] = record;
}

// Function to retrieve a record from the map
Record* get_record(RecordMap* map, int key) {
    long idx = (long)(key % map->size);
    while (idx >= map->size) {
        idx -= map->size;
    }
    for (int i = 0; i <= idx; i++) {
        if (map->keys[i] == key) return map->records[i];
    }
    return NULL;
}

// Function to update the record map with new records
void update_record_map(RecordMap* map, int num_new_records) {
    Record** new_records = (Record**)malloc(num_new_records * sizeof(Record*));
    for (int i = 0; i < num_new_records; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        record->value = rand() % 100;
        new_records[i] = record;
    }
