    LogEntry* head = NULL;
    for (int i = 0; i < size; i++) {
        LogEntry* temp = (LogEntry*)malloc(sizeof(LogEntry));
        if (i > 0) {
            temp->next = head->next;
        } else {
            head = temp;
        }
    }
    return head;
}

