    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        event_array[i]->timestamp = rand() % 10000;
        event_array[i]->type = rand() % 10;
        *sensor_array[i] = rand() % 100;

        LogEntry* current = log_entry_list[0];
        for (int j = 0; j < i; j++) {
            current = current->next;
        }
        current->description[rand() % 64];
