    for (int i = 0; i < size; i++) {
        LogEntry* current = log_entry_list[0];
        for (int j = 0; j <= i; j++) {
            LogEntry* temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(log_entry_list);

    for (int i = 0; i < size; i++) {
        free(&event_array[i]);
    }
    free(event_array);
}

