    Event* event_array = create_event_array(size);
    int** sensor_array = create_sensor_array(size);
    LogEntry* log_entry_list = create_log_entry_list(size);

    populate_data(event_array, sensor_array, log_entry_list, size);

    free_memory(event_array, sensor_array, log_entry_list, size);

    return 0;
}
