#define MAX_JOBS 1000
#define MAX_PRIORITY 10
#define LOG_LEVEL_INFO

typedef struct {
    char* name;
    int priority;
    time_t timestamp;
} job;

job_queue* job_queue_create() {
    job_queue* queue = (job_queue*)malloc(sizeof(job_queue));
    if (!queue) {
        return NULL;
    }
    pthread_mutex_init(&queue->mutex, NULL);
    queue->head = NULL;
    queue->tail = NULL;
    queue->size = 0;
    queue->max_jobs = MAX_JOBS;
    return queue;
}

void job_queue_destroy(job_queue* queue) {
    while (queue->head) {
        job* temp = queue->head;
        queue->head = temp->next;
        free(temp);
    }
    free(queue);
}

int job_queue_enqueue(job_queue* queue, job* new_job) {
    if (queue->size >= queue->max_jobs) {
        return -1; // Queue full
    }
    pthread_mutex_lock(&queue->mutex);
    new_job->next = NULL;
    if (!queue->head) {
        queue->head = queue->tail = new_job;
    } else {
        job* temp = queue->tail;
        temp->next = new_job;
        queue->tail = new_job;
    }
    queue->size++;
    pthread_mutex_unlock(&queue->mutex);
    return 0; // Job enqueued successfully
}

job* job_queue_dequeue(job_queue* queue) {
    if (queue->head) {
        pthread_mutex_lock(&queue->mutex);
        job* temp = queue->head;
        queue->head = temp->next;
        if (!queue->head) {
            queue->tail = NULL;
        }
        queue->size--;
        pthread_mutex_unlock(&queue->mutex);
        return temp;
    } else {
        return NULL; // Queue empty
    }
}

