log_t* allocate_log(int num_events) {
    log_t* log = (log_t*)malloc(sizeof(log_t));
    if(log == NULL) {
        return NULL;
    }
    log->head = (struct event*)malloc(sizeof(struct event));
    log->tail = log->head;
    for(int i = 0; i < num_events; i++) {
        struct event* event = (struct event*)malloc(sizeof(struct event));
        event->timestamp = time(NULL);
        event->action_type = rand() % 2;
        log->tail->next = event;
        log->tail = event;
    }
    return log;
}

task_t* allocate_task(int num_resources) {
    task_t* task = (task_t*)malloc(sizeof(task_t));
    if(task == NULL) {
        return NULL;
    }
    task->resources = (resource_t*)calloc(num_resources, sizeof(resource_t));
    task->log = allocate_log(10);
    return task;
}

int init_tasks(int num_tasks) {
    tasks = (task_t**)malloc(sizeof(task_t*) * num_tasks);
    for(int i = 0; i < num_tasks; i++) {
        tasks[i] = allocate_task(rand() % 5 + 1);
    }
    return 0;
}

node_t* allocate_node(char* buffer) {
    node_t* node = (node_t*)malloc(sizeof(node_t));
    if(node == NULL) {
        return NULL;
    }
    strcpy(node->buffer, buffer);
    return node;
}

int main() {
    srand(time(NULL));
    init_tasks(10);
    // Initialize the offset and identifier arrays
    int* offsets = (int*)malloc(sizeof(int) * 1000);
    for(int i = 0; i < 1000; i++) {
        offsets[i] = rand();
    }
    int* identifiers = (int*)malloc(sizeof(int) * 500);
    for(int i = 0; i < 500; i++) {
        identifiers[i] = rand();
    }
    // Initialize the linked list of nodes
    node_t* head = NULL;
    node_t* current = NULL;
    for(int i = 0; i < 100; i++) {
        char buffer[256];
        sprintf(buffer, "Node %d", i);
        node_t* node = allocate_node(buffer);
        if(current == NULL) {
            head = node;
            current = node;
        } else {
            current->next = node;
            current = node;
        }
    }
    // Track the total memory usage
    size_t total_memory_usage = 0;
    for(int i = 0; i < num_tasks; i++) {
        total_memory_usage += sizeof(task_t) + sizeof(resource_t) * tasks[i]->num_resources + sizeof(log_t);
    }
    total_memory_usage += sizeof(node_t) * 100 + sizeof(node_t*) * 2;
    printf("Total memory usage: %zu\n", total_memory_usage);
    return 0;
}
