        }

        unsigned char hash[EVP_MAX_MD_SIZE];
        int len = 0;

        if (processString(str, input, strlen(input), &md, hash, &len) == 1) {
            // Add the hash to the vector of results
            std::string hashStr = "";

            for (int i = 0; i < len; ++i)
                hashStr += static_cast<char>(hash[i]);

            hashResults.push_back(hashStr);
        } else {
            // Handle error hashing operation
            return {};
        }
    }

    return hashResults;
}

// Helper function to process a string using the selected hash mode and key size

int processString(const char* str, const unsigned char* input, int length, const EVP_MD* md, unsigned char* output, int* outputLength) {
    // Create an EVP_M HASH CONTEXT
    EVP_MD_CTX ctx;

    if (EVP_DigestInit_ex(&ctx, md, NULL)) {
        EVP_DigestUpdate(&ctx, input, length);

        // Perform hashing operation
        int result = EVP_DigestFinal_ex(&ctx, output, outputLength);

        return result;
    } else {
        // Handle error during hash initialization
        return -1;
    }
}

