typedef struct {
    int *offsets;
    char **keys;
    struct record **records;
} db_t;

typedef struct {
    time_t timestamp;
    int key;
    // Add more fields as needed
} record_t;

void init_db(db_t *db, int num_records) {
    db->offsets = (int *)malloc((num_records + 1) * sizeof(int));
    db->keys = (char **)malloc((num_records + 1) * sizeof(char *));
    db->records = (record_t **)malloc((num_records + 1) * sizeof(record_t *));

    for (int i = 0; i <= num_records; i++) {
        db->offsets[i] = -1;
        db->keys[i] = NULL;
        db->records[i] = NULL;
    }
}

void add_record(db_t *db, int key, record_t *record) {
    for (int i = 0; i <= db->num_records; i++) {
        if (db->offsets[i] == -1) {
            db->keys[db->num_records + 1] = record;
            db->offsets[db->num_records + 1] = i;
            return;
        }
    }
}

void remove_record(db_t *db, int key) {
    for (int i = 0; i <= db->num_records; i++) {
        if (strcmp(db->keys[i], (const char *)key) == 0) {
            free(db->keys[i]);
            db->keys[i] = NULL;
            db->offsets[i] = -1;
            return;
        }
    }
}

int get_record_key(db_t *db, int offset) {
    if (offset < 0 || offset >= db->num_records + 1) {
        return -1; // Error
    }
    return db->keys[offset];
}

void export_db(db_t *db, const char *filename) {
    FILE *file = fopen(filename, "w");
    for (int i = 0; i <= db->num_records; i++) {
        if (db->offsets[i] != -1) {
            record_t *record = db->records[db->offsets[i]];
            fprintf(file, "%d %s\n", record->key, record->data);
        }
    }
    fclose(file);
}
