// Dynamic key sizes for hashing
std::vector<uint8_t> dynamic_keys = {56, 64, 80, 96, 112};

// Function to initialize and configure network interfaces
void init_config(std::vector<NFAPI_CONTROL_PDU_T>& config) {
    // Initialize network interfaces with default values
    for (auto& intf : config) {
        intf.mac[0] = intf.mac[1] = intf.mac[2] = intf.mac[3] = intf.mac[4] = intf.mac[5] = 0;
        intf.ip = 0;
        intf.subnet_mask = 0;
        intf.vlan_id = 0;
    }
}

// Function to hash a string using MD5
std::string hash_string(const std::string& str, HASHING_MODE mode) {
    // Load the hashing library dynamically at runtime
    void* libHandle = dlopen("libmd5.so", RTLD_LAZY);
    if (!libHandle) {
        throw std::runtime_error("Error loading MD5 library");
    }

    int (*hash_func)(const char*, size_t, uint8_t*) = (int (*)(const char*, size_t, uint8_t*)) dlsym(libHandle, "md5");
    if (!hash_func) {
        throw std::runtime_error("Error finding MD5 function");
    }

    // Initialize the hash context with the chosen mode and key
    uint8_t* ctx = (uint8_t*)malloc(sizeof(uint8_t) * dynamic_keys[mode]);
    hash_func(str.c_str(), str.length(), ctx);

    // Convert the binary hash to a hexadecimal string
    std::string hash_hex;
    for (size_t i = 0; i < 16; i++) {
        char hex[3];
        sprintf(hex, "%02x", ((uint8_t*)ctx)[i]);
        hash_hex += std::string(hex);
    }

    free(ctx);

    dlclose(libHandle);

    return hash_hex;
}

// Function to manage multiple concurrent data streams
void process_data(std::vector<std::thread> threads) {
    for (auto& thread : threads) {
        thread.join();
    }
}

