void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

LTE_TRANSPORT_CONTEXT_T** lte_transport_context_array_create(int num_elements) {
    LTE_TRANSPORT_CONTEXT_T** arr = (LTE.Transport.Context*)my_malloc(num_elements * sizeof(LTE.TRANSPORT_CONTEXT_T));

    for (int i = 0; i < num_elements; i++) {
        arr[i] = (LTE.TRANSPORT_CONTEXT_T*)my_malloc(sizeof(LTE_TRANSPORT_CONTEXT_T));

        // Dynamically computed values based on network load conditions
        arr[i]->transport_layer_id = i;
        arr[i]->tx_power_level = rand() % 100;
        arr[i]->channel_usage_pattern = i % 3;
    }

    return arr;
}

void lte_transport_context_array_resize(LTE_TRANSPORT_CONTEXT_T** arr, int new_size) {
    if (new_size <= 0) {
        for (int i = 0; i < *arr; i++) {
            my_free(arr[i]);
        }

        my_free(*arr);
        *arr = NULL;
        return;
    }

    LTE_TRANSPORT_CONTEXT_T** new_arr = (LTE.TRANSPORT_CONTEXT_T**)my_malloc(new_size * sizeof(LTE.TRANSPORT_CONTEXT_T*));

    if (*arr != NULL) {
        int i = 0;
        for (; i < *new_arr; i++) {
            new_arr[i] = arr[i];
        }

        for (int j = *arr; j > i; j--) {
            my_free(arr[j]);
        }

        my_free(*arr);
    }

    *arr = new_arr;
}

void lte_transport_context_array_reset(LTE_TRANSPORT_CONTEXT_T** arr) {
    if (*arr != NULL) {
        for (int i = 0; i < *arr; i++) {
            free(arr[i]);
        }

        free(*arr);
        *arr = NULL;
    }
}

int main() {
    int num_elements = 10;

    LTE_TRANSPORT_CONTEXT_T** arr = lte_transport_context_array_create(num_elements);

    // Use the array
    printf("Array created with %d elements.\n", num_elements);

    // Resize the array to double its size
    lte_transport_context_array_resize(arr, num_elements * 2);

    // Reset the array
    lte_transport_context_array_reset(arr);

    return 0;
}
