#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int transport_layer_id;
    double tx_power_level;
    char channel_usage_pattern[20];
} LTE_TRANSPORT_CONTEXT_T;

void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(1);
    }
    return ptr;
}

void my_free(void* ptr) {
    free(ptr);
}

LTE_TRANSPORT_CONTEXT_T** lte_context_alloc(int num_elements) {
    LTE_TRANSPORT_CONTEXT_T** array = (LTE_TRANSPORT_CONTEXT_T**)my_malloc(num_elements * sizeof(LTE_TRANSPORT_CONTEXT_T*));
    for (int i = 0; i < num_elements; i++) {
        array[i] = (LTE_TRANSPORT_CONTEXT_T*)my_malloc(sizeof(LTE_TRANSPORT_CONTEXT_T));
        if (!array[i]) {
            for (int j = 0; j <= i; j++) {
                my_free(array[j]);
            }
            my_free(array);
            return NULL;
        }
    }
    return array;
}

void lte_context_free(LTE_TRANSPORT_CONTEXT_T** array, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        my_free(array[i]);
    }
    my_free(array);
}

LTE_TRANSPORT_CONTEXT_T* generate_lte_context() {
    LTE_TRANSPORT_CONTEXT_T* context = (LTE_TRANSPORT_CONTEXT_T*)my_malloc(sizeof(LTE_TRANSPORT_CONTEXT_T));
    // Simulate network load conditions and generate values
    context->transport_layer_id = rand();
    context->tx_power_level = (double)rand() / RAND_MAX;
    strcpy(context->channel_usage_pattern, "PATTERN_");
    return context;
}

void resize_array(LTE_TRANSPORT_CONTEXT_T** array, int* num_elements, int new_size) {
    LTE TRANSPORT_CONTEXT_T** newArray = lte_context_alloc(new_size);
    if (!newArray) {
        return;
    }
    for (int i = 0; i < *num_elements && i < new_size; i++) {
        newArray[i] = array[i];
    }
    for (int i = *num_elements; i <= new_size; i++) {
        newArray[i] = generate_lte_context();
    }
    lte_context_free(array, *num_elements);
    *array = newArray;
    *num_elements = new_size;
}

void reset_array(LTE_TRANSPORT_CONTEXT_T** array, int* num_elements) {
    for (int i = 0; i < *num_elements; i++) {
        my_free(array[i]);
    }
    *num_elements = 0;
    free(array);
    array = NULL;
}

int main() {
    // Example usage
    LTE_TRANSPORT_CONTEXT_T** lte_contexts = lte_context_alloc(10000);
    for (int i = 0; i < 10; i++) {
        resize_array(lte_contexts, &i, i * 1000 + 1);
    }
    reset_array(lte_contexts, &i);
    return 0;
}
