#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int session_id;
    time_t active_time_stamp;
    time_t last_activity_time;
    int connection_status;
} USER_SESSION_T;

// Function to initialize and manage the dynamic linked list
USER_SESSION_T* manage_session_list(int num_sessions) {
    if (num_sessions <= 0) {
        printf("Invalid number of sessions. Please provide a positive integer.\n");
        return NULL;
    }

    // Initialize head pointer
    USER_SESSION_T* head = NULL;

    for (int i = 0; i < num_sessions; i++) {
        // Allocate memory for new session
        USER_SESSION_T* new_session = (USER_SESSION_T*)malloc(sizeof(USER_SESSION_T));

        if (!new_session) {
            printf("Memory allocation failed. Exiting.\n");
            return NULL;
        }

        // Generate simulated user activity patterns
        int session_id = i;
        time_t active_time_stamp = time(NULL);
        time_t last_activity_time = active_time_stamp - (rand() % 60); // Simulated activity pattern
        int connection_status = rand() % 2; // Randomly generate connection status

        new_session->session_id = session_id;
        new_session->active_time_stamp = active_time_stamp;
        new_session->last_activity_time = last_activity_time;
        new_session->connection_status = connection_status;

        if (i == 0) {
            head = new_session; // Initialize head pointer
        } else {
            USER_SESSION_T* current = head;
            while (current->next) {
                current = current->next;
            }
            current->next = new_session;
        }
    }

    return head;
}

// Function to add a new session to the list
void add_session(USER_SESSION_T** head, int session_id, time_t active_time_stamp, time_t last_activity_time, int connection_status) {
    // Allocate memory for new session
    USER_SESSION_T* new_session = (USER_SESSION_T*)malloc(sizeof(USER_SESSION_T));

    if (!new_session) {
        printf("Memory allocation failed. Exiting.\n");
        return;
    }

    new_session->session_id = session_id;
    new_session->active_time_stamp = active_time_stamp;
    new_session->last_activity_time = last_activity_time;
    new_session->connection_status = connection_status;

    if (*head == NULL) {
        *head = new_session; // New session is the first in the list
    } else {
        USER_SESSION_T* current = *head;
        while (current->next) {
            current = current->next;
        }
        current->next = new_session;
    }
}

// Function to update an existing session in the list
void update_session(USER_SESSION_T** head, int session_id, time_t active_time_stamp, time_t last_activity_time, int connection_status) {
    USER_SESSION_T* current = *head;

    while (current) {
        if (current->session_id == session_id) {
            current->active_time_stamp = active_time_stamp;
            current->last_activity_time = last_activity_time;
            current->connection_status = connection_status;
            return;
        }
        current = current->next;
    }

    printf("Session not found. Cannot update.\n");
}

// Function to remove a session from the list
void remove_session(USER_SESSION_T** head, int session_id) {
    USER_SESSION_T* current = *head;

    if (current && current->session_id == session_id) {
        *head = current->next;
        free(current);
        return;
    }

    while (current && current->next) {
        if (current->next->session_id == session_id) {
            USER_SESSION_T* temp = current->next;
            current->next = temp->next;
            free(temp);
            return;
        }
        current = current->next;
    }

    printf("Session not found. Cannot remove.\n");
}

// Function to reset the list to its initial state
void reset_list(USER_SESSION_T** head) {
    USER_SESSION_T* current = *head;

    while (current) {
        free(current);
        current = current->next;
    }
    *head = NULL;
}
