// Define structure for transaction
typedef struct {
    int id;
    time_t timestamp;
    float amount;
} Transaction;

// Define structure for account
typedef struct {
    int id;
    float balance;
    time_t lastUpdated;
    int numTransactions;
    Transaction* transactions;
} Account;

// Define structure for operation
typedef struct {
    int id;
    char type[10];
    float amount;
    time_t timestamp;
} Operation;

// Function to manage memory for a dynamic collection of transaction structures
void manageMemory(int numTransactions, int size) {
    // Allocate memory for array of transactions
    Transaction* transactions = (Transaction*)malloc(numTransactions * sizeof(Transaction));

    // Initialize 'pending' array with consecutive integers starting from 0
    int* pending = (int*)malloc((numTransactions + 1) * sizeof(int));
    for (int i = 0; i <= numTransactions; i++) {
        pending[i] = i;
    }

    // Allocate memory for array of operations
    Operation* operations = (Operation*)malloc(size * sizeof(Operation));

    // Initialize 'history' array with unique historical transaction IDs
