  const queue = [];
  let recursionDepth = 0;
  let offset = 0;

  function collectElements() {
    if (recursionDepth > 5) return; // limit recursion depth

    try {
      const elements = document.querySelectorAll(selector);
      for (const element of elements) {
        const metadata = enrichElement(element); // enrich with additional metadata
        cache.set(element, metadata);
        queue.push({ element, offset });
      }
    } catch (error) {
      console.error(`Error while traversing: ${error}`);
    }

    if (queue.length > 0) {
      offset = queue.shift().offset;
      collectElements();
    }
  }

  function enrichElement(element) {
    // implement enrichment logic here
  }

  const paginatedData = [];
  let fetchDataIntervalId;

  async function fetchData() {
    clearTimeout(fetchDataIntervalId);
    fetchDataIntervalId = setTimeout(async () => {
      const data = await fetch('/api/data'); // simulate asynchronous data fetching
      paginatedData.push(...data);
      collectElements();
    }, 500); // wait for 500ms before fetching next page
  }

  function updateCache() {
    cache.forEach((metadata, element) => {
      metadata.offset = offset;
      element.dataset.metadata = JSON.stringify(metadata);
    });
  }

  window.addEventListener('DOMSubtreeModified', () => {
    updateCache();
  });

  collectElements();

  return paginatedData;
}
