void* manageMemory(void* arg) {
    int* limit = (int*)arg;
    while (numRecords < *limit && pthread_mutex_lock(RecordsMutex)) {
        // allocate memory for new record
        Record* newRecord = (Record*)malloc(sizeof(Record));
        if (!newRecord) {
            // handle memory allocation failure
            printf("Memory allocation failed\n");
            return NULL;
        }
        // initialize new record with random value
        newRecord->offset = rand() % 1000;
        newRecord->key = (char*)malloc(10);
        sprintf(newRecord->key, "%d", newRecord->offset);
        newRecord->record = rand() % 100;

        // add new record to array and increment count
        records[numRecords++] = *newRecord;
    }
    pthread_mutex_unlock(RecordsMutex);
    free(newRecord);
}

int main() {
    int numThreads = 4; // number of threads for concurrent memory management
    pthread_t threads[numThreads];

    // initialize seed for random number generator
    srand(time(NULL));

    for (int i = 0; i < numThreads; i++) {
        pthread_create(&threads[i], NULL, manageMemory, &numRecords);
    }

    for (int i = 0; i < numThreads; i++) {
        pthread_join(threads[i], NULL);
    }

    // monitor peak memory consumption
    int peakMemUsage = 0;
    for (int i = 0; i < numRecords; i++) {
        Record* record = &records[i];
        if (record->offset > peakMemUsage) peakMemUsage = record->offset;
    }
    printf("Peak memory usage: %d\n", peakMemUsage);

    // process multiple input texts in parallel
    pthread_t textProcessingThreads[4];
