function traverseDOM(rootNode, selector, predicate, maxDepth = 1000) {
  const cache = new Map();
  const result = [];

  async function recursiveTraversal(node, depth = 0) {
    if (depth > maxDepth) return;

    if (!node) return;

    const matchesSelector = node.matches(selector);
    if (!matchesSelector) return;

    const attributes = await getAttributes(node);
    const classes = await getNodeClasses(node);

    if (predicate(attributes, classes)) {
      result.push(node);
    }

    for (const child of node.children) {
      await recursiveTraversal(child, depth + 1);
    }
  }

  async function getAttributes(node) {
    return Promise.all(
      [...node.attributes].map((attribute) => {
        return attribute.value;
      })
    );
  }

  async function getNodeClasses(node) {
    return Promise.all(
      [...node.classList].map((className) => {
        return className.toLowerCase();
      })
    );
  }

  await recursiveTraversal(rootNode);

  return result;

}

