        timestamp_window = datetime.now() - timedelta(minutes=30)  # adjust the time window
        if self.deduplication_cache[reading['location']].get(reading['timestamp']) is None:
            self.deduplication_cache[reading['location']][reading['timestamp']] = True
            return False

        return True

    def aggregate_reading(self, reading):
        aggregation_window = datetime.now() - timedelta(hours=1)  # adjust the time window
        if not self.aggregated_data.get(reading['location']):
            self.aggregated_data[reading['location']] = {'min': None, 'max': None, 'average': None}

        if reading['temperature'] < self.aggregated_data[reading['location']]['min']:
            self.aggregated_data[reading['location']]['min'] = reading['temperature']

        if reading['temperature'] > self.aggregated_data[reading['location']]['max']:
            self.aggregated_data[reading['location']]['max'] = reading['temperature']

        if not self.aggregated_data[reading['location']]['average']:
            self.aggregated_data[reading['location']]['average'] = reading['temperature']
        else:
            self.aggregated_data[reading['location']]['average'] += (reading['temperature'] - self.aggregated_data[reading['location']]['average']) / 2

    def process_reading(self, reading):
        if not self.deduplicate_reading(reading):
            return False
        if not self.insert_reading(reading):
            return False
        self.aggregate_reading(reading)
        return True

    def query_readings(self, location=None, timestamp_range=(datetime.now() - timedelta(days=1), datetime.now()), aggregation_window=None):
        try:
            with self.conn.cursor() as cursor:
                query = "SELECT * FROM sensor_readings WHERE "
                if location:
                    query += f"location = '{location}' AND "
                query += "timestamp >= ? AND timestamp <= ?"
                if aggregation_window:
                    query += f" AND timestamp >= {aggregation_window[0]} AND timestamp <= {aggregation_window[1]}"
                cursor.execute(query, (timestamp_range[0], timestamp_range[1]))
                results = cursor.fetchall()
            return [dict(zip([name[0] for name in self.conn.cursor().description], row)) for row in results]
        except Exception as e:
            print(f"Error querying sensor readings: {e}")
            return []

