        try:
            with self.conn.cursor() as cursor:
                query = "SELECT * FROM aggregated_data WHERE location = ?"
                cursor.execute(query, (location,))
                results = cursor.fetchall()
            return [dict(zip([name[0] for name in self.conn.cursor().description], row)) for row in results]
        except Exception as e:
            print(f"Error querying aggregated data: {e}")
            return []

    def start_processing(self):
        while True:
            try:
                with self.lock:
                    if not self.conn:
                        self.connect()
                    readings = []  # TO DO: implement batch processing and add readings to this list
                    for reading in readings:
