                    if location.lower() == 'all':
                        location = None
                    timestamp_range = (datetime.now() - timedelta(days=1), datetime.now())
                    aggregation_window = None  # TO DO: implement aggregation window
                    results = self.query_readings(location, timestamp_range, aggregation_window)
                    for reading in results:
