    entry->data = (Data*)malloc(sizeof(Data));
    entry->metadata = (Metadata*)malloc(sizeof(Metadata));
    entry->messages = NULL;
    return entry;
}

void addMessageToEntry(Entry* entry, char* message) {
    MessageNode* newNode = (MessageNode*)malloc(sizeof(MessageNode));
    newNode->message = message;
    newNode->next = entry->data->messages;
    entry->data->messages = newNode;
}

void updateMetadata(Entry** entries, int count) {
    for(int i = 0; i < count; i++) {
        Entry* current = entries[i];
        if(current != NULL) {
            // Update metadata based on conditions
            // For example:
            if(current->data->priority > 5) {
                current->metadata->timestamp += 1;
