            for(int j = 0; j < current->metadata->tagCount; j++) {
                if(strncmp(current->metadata->tags[j], "condition", strlen("condition")) == 0) {
                    // Perform some action
                }
            }
        }
    }
}

void freeEntries(Entry** entries, int count) {
