function traverseDOM(root, selector, testFunc, skipRootPredicate = () => false, maxResults = Infinity, prioritizeFunc = () => 0) {
  const resultCache = {};
  let results = [];
  let skippedNodes = 0;

  function traverse(node, depth = 0) {
    if (!node) return;

    const isMatch = testFunc(node);
    const shouldSkip = skipRootPredicate(node);

    if (isMatch && !shouldSkip) {
      const result = { node, selector: getSelector(node) };

      // Cache the matched element
      resultCache[getCacheKey(result)] = true;

      results.push(result);

      // Limit depth for large DOM trees
      if (depth < 5) {
        traverse(node.firstElementChild, depth + 1);
        traverse(node.lastElementChild, depth + 1);

        // Traverse all siblings
        let current = node.previousSibling;
        while (current) {
          traverse(current, depth + 1);
          current = current.previousSibling;
        }
      }
    } else if (!shouldSkip && !resultCache[getCacheKey({ node })]) {
      skippedNodes++;
      traverse(node.firstElementChild, depth + 1);
      traverse(node.lastElementChild, depth + 1);

      // Traverse all siblings
      let current = node.previousSibling;
      while (current) {
        traverse(current, depth + 1);
        current = current.previousSibling;
      }
    } else if (!shouldSkip && !resultCache[getCacheKey({ node })]) {
      skippedNodes++;
    }

    // Prioritize results
    results.sort((a, b) => prioritizeFunc(b.node) - prioritizeFunc(a.node));
  }

  function getSelector(node) {
    const [namespace, selector] = (node.getAttribute('data-selector') || '').split(':');
    return namespace ? `${namespace} ${selector}` : selector;
  }

  function getCacheKey({ node }) {
    return `${node.tagName.toLowerCase()}${node.id || ''}`;
  }

  traverse(root);
  return results.slice(0, Math.min(results.length, maxResults));
}
