// Define the 'node' structure
typedef struct node {
    data_t* data;
    struct node* next;
} node_t;

// Define a mutex for thread safety
pthread_mutex_t nodes_lock = PTHREAD_MUTEX_INITIALIZER;

// Create a new node and initialize its data structure
node_t* create_node() {
    node_t* node = (node_t*)malloc(sizeof(node_t));
    node->data = (data_t*)malloc(sizeof(data_t));
    node->next = NULL;
    return node;
}

// Add an event to a node's event array without causing memory fragmentation
void add_event(node_t* node, event_t* event) {
    // Resize the events array if necessary
    if (node->data->num_events == 0) {
        node->data->events = (event_t*)malloc(sizeof(event_t));
    } else if (node->data->num_events < 10) { // adjust this value based on your needs
        event_t* new_events = (event_t*)realloc(node->data->events, sizeof(event_t) * (node->data->num_events + 1));
        node->data->events = new_events;
    }
    node->data->events[node->data->num_events++] = event;
}

// Update the status of a node based on a given condition
void update_status(node_t* node, int condition) {
    // Critical section: lock access to the node's data
    pthread_mutex_lock(&nodes_lock);
    if (condition) {
        node->data->status = 1; // assume status updates are atomic
    } else {
        node->data->status = 0;
    }
    pthread_mutex_unlock(&nodes_lock);
}

// Remove a node from the dynamic collection based on its timestamp
void remove_node(node_t** head, time_t timestamp) {
    node_t* current = *head;
    node_t* previous = NULL;

    // Find the node with the matching timestamp
    while (current && current->data->timestamp != timestamp) {
        previous = current;
        current = current->next;
    }

    if (!current) return; // node not found

    // Remove the node from the list
    if (previous) {
        previous->next = current->next;
    } else {
        *head = current->next;
    }
    free(current->data);
    free(current);

    // Rebalance memory allocation after removing nodes to prevent fragmentation
    rebalance_memory_allocation();
}

