import pyodbc
from multiprocessing import Pool
import random
import os
import logging
import time
from datetime import datetime

class SensorDataModule:
    def __init__(self, db_config):
        self.db_config = db_config
        self.conn = None
        self.cursor = None
        self.pool = None

    def connect_to_db(self):
        try:
            self.conn = pyodbc.connect(**self.db_config)
            self.cursor = self.conn.cursor()
        except Exception as e:
            logging.error(f"Error connecting to database: {str(e)}")

    def commit_data(self, data):
        if not self.conn or not self.cursor:
            self.connect_to_db()
        try:
            for row in data:
                self.cursor.execute("INSERT INTO sensor_readings (timestamp, location, temperature, humidity, pressure) VALUES (?, ?, ?, ?, ?)", 
                                    row[:5])
                self.conn.commit()
        except Exception as e:
            logging.error(f"Error committing data: {str(e)}")
            self.conn.rollback()

    def deduplicate_and_aggregate(self):
        if not self.conn or not self.cursor:
            self.connect_to_db()
        try:
            self.cursor.execute("SELECT timestamp, location, AVG(temperature) AS avg_temp, AVG(humidity) AS avg_humidity, AVG(pressure) AS avg_pressure FROM sensor_readings GROUP BY timestamp, location")
            results = self.cursor.fetchall()
            return results
        except Exception as e:
            logging.error(f"Error aggregating data: {str(e)}")

    def close_connection(self):
        if self.conn and not self.conn.closed:
            self.conn.close()

