    EVENT_TYPE_B,
    EVENT_TYPE_C
} USER_EVENT_T;

struct HashEntry {
    int id;
    char* str;
    USER_EVENT_T event;
};

struct DynamicHashTable {
    struct HashEntry** buckets;
    int size;
    int num_elements;
    pthread_mutex_t lock;
};

struct DynamicHashTable* dynamic_hash_table_create(int initial_size) {
    struct DynamicHashTable* table = (struct DynamicHashTable*)malloc(sizeof(struct DynamicHashTable));
    table->size = initial_size;
    table->num_elements = 0;
    table->buckets = (struct HashEntry**)malloc(initial_size * sizeof(struct HashEntry*));
    for (int i = 0; i < initial_size; i++) {
        table->buckets[i] = NULL;
    }
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

void dynamic_hash_table_insert(struct DynamicHashTable* table, int id, char* str, USER_EVENT_T event) {
    int bucket_index = id % table->size;
    pthread_mutex_lock(&table->lock);
    if (table->buckets[bucket_index] == NULL) {
        table->buckets[bucket_index] = (struct HashEntry*)malloc(sizeof(struct HashEntry));
        table->buckets[bucket_index]->id = id;
        table->buckets[bucket_index]->str = str;
        table->buckets[bucket_index]->event = event;
    } else {
        // handle collision
    }
    pthread_mutex_unlock(&table->lock);
}

