#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class Task {
public:
    int id;
    std::string dataSource;
    int priority;

    Task(int id, std::string dataSource, int priority) : id(id), dataSource(dataSource), priority(priority) {}
};

class DataProcessingStatus {
public:
    int status;
    std::vector<Task> tasks;

    DataProcessingStatus(int status, std::vector<Task> tasks) : status(status), tasks(tasks) {}
};

class Scheduler {
private:
    std::priority_queue<Task*, std::vector<Task*>, decltype(&Task::compare)>
        taskQueue;
    std::mutex mtx;
    std::condition_variable cv;
    bool isAsync;

public:
    Scheduler(bool isAsync) : isAsync(isAsync) {}

    void scheduleTasks(std::vector<Task> tasks, std::function<void()> callback = nullptr) {
        for (Task& task : tasks) {
            taskQueue.push(&task);
        }
        if (isAsync) {
            while (!taskQueue.empty()) {
                Task* task = taskQueue.top();
                taskQueue.pop();
                // Process task
                callback();
            }
        } else {
            while (!taskQueue.empty()) {
                Task* task = taskQueue.top();
                taskQueue.pop();
                // Process task synchronously
            }
        }
    }

    DataProcessingStatus processBatch(std::vector<Task> tasks) {
        std::vector<DataProcessingStatus> results;
        for (Task& task : tasks) {
            DataProcessingStatus status;
            // Process task and update status
            results.push_back(status);
        }
        return results;
    }
};

