import pyodbc
from multiprocessing import Pool
import random
import datetime
import time
import os

class SensorDataModule:
    def __init__(self, server='localhost', database='database_name'):
        self.server = server
        self.database = database
        self.conn = None
        self.cursor = None
        self.data_buffer = []

    def connect(self):
        try:
            self.conn = pyodbc.connect('DRIVER={ODBC Driver 17 for SQL Server};SERVER='+self.server+';DATABASE='+self.database+';UID=your_username;PWD=your_password')
            self.cursor = self.conn.cursor()
        except Exception as e:
            print(f"Error connecting to database: {e}")

    def disconnect(self):
        if self.conn:
            self.conn.close()

    def get_unique_readings(self, query):
        try:
            self.cursor.execute(query)
            rows = self.cursor.fetchall()
            unique_reads = []
            for row in rows:
                if row not in unique_reads:
                    unique_reads.append(row)
            return unique_reads
        except Exception as e:
            print(f"Error executing query: {e}")
            return []

    def aggregate_readings(self, start_date=None, end_date=None):
        try:
            if start_date and end_date:
                query = f"SELECT timestamp, AVG(temperature) AS avg_temp, AVG(humidity) AS avg_humi FROM sensor_data WHERE timestamp >= '{start_date}' AND timestamp <= '{end_date}' GROUP BY timestamp"
            else:
                query = "SELECT timestamp, AVG(temperature) AS avg_temp, AVG(humidity) AS avg_humi FROM sensor_data GROUP BY timestamp"
            self.cursor.execute(query)
            rows = self.cursor.fetchall()
            aggregated_data = []
            for row in rows:
                aggregated_data.append({
                    'timestamp': row[0],
                    'avg_temperature': row[1],
                    'avg_humidity': row[2]
                })
            return aggregated_data
        except Exception as e:
            print(f"Error aggregating readings: {e}")
            return []

    def store_readings(self, data):
        try:
            self.cursor.executemany("INSERT INTO sensor_data VALUES (?, ?, ?, ?, ?)", data)
            self.conn.commit()
        except Exception as e:
            print(f"Error storing readings: {e}")

    def process_batch(self, batch_size=1000):
        if not self.data_buffer:
            return
        try:
            self.store_readings(self.data_buffer[:batch_size])
            self.data_buffer = self.data_buffer[batch_size:]
        except Exception as e:
            print(f"Error processing batch: {e}")
            time.sleep(1)
            self.process_batch(batch_size)

    def start_processing_loop(self, interval=60):
        while True:
            try:
                if not self.data_buffer:
                    break
                self.process_batch()
                time.sleep(interval)
            except Exception as e:
                print(f"Error in processing loop: {e}")
                time.sleep(1)

def manage_theme_and_data_sources(key_array_size, record_count):
    key_arrays = [random.randint(0, 100) for _ in range(key_array_size)]
    record_arrays = [[random.randint(1, 100) for _ in range(record_count)] for _ in range(key_array_size)]

    return key_arrays, record_arrays
