class SensorReader:
    def __init__(self, db_config):
        self.db_config = db_config
        self.conn = None

    def connect(self):
        try:
            self.conn = pyodbc.connect(**self.db_config)
        except Exception as e:
            print(f"Error connecting to database: {e}")

    def disconnect(self):
        if self.conn is not None:
            self.conn.close()
            self.conn = None

    def read_sensor_data(self):
        try:
            cursor = self.conn.cursor()
            cursor.execute("SELECT * FROM sensor_readings")
            rows = cursor.fetchall()
            return rows
        except Exception as e:
            print(f"Error reading sensor data: {e}")
            return []

    def insert_sensor_reading(self, reading):
        try:
            cursor = self.conn.cursor()
            query = "INSERT INTO sensor_readings (timestamp, location, temperature, humidity, pressure) VALUES (?, ?, ?, ?, ?)"
            cursor.execute(query, reading)
            self.conn.commit()
        except Exception as e:
            print(f"Error inserting sensor reading: {e}")

    def aggregate_sensor_data(self):
        try:
            cursor = self.conn.cursor()
            query = "SELECT AVG(temperature), AVG(humidity), AVG(pressure) FROM sensor_readings"
            result = cursor.execute(query).fetchone()
            return result
        except Exception as e:
            print(f"Error aggregating sensor data: {e}")
            return None

    def start_processing(self):
        while True:
            try:
                readings = self.read_sensor_data()
                for reading in readings:
                    self.insert_sensor_reading(reading)
                aggregated_data = self.aggregate_sensor_data()
                if aggregated_data is not None:
                    print(f"Average temperature: {aggregated_data[0]}, Average humidity: {aggregated_data[1]}, Average pressure: {aggregated_data[2]}")
