#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} record;

record* initializeArrays(size_t numRecords, size_t* errCode) {
    int* keys = (int*)malloc(numRecords * sizeof(int));
    if (!keys) {
        *errCode = 1;
        return NULL;
    }

    long* offsets = (long*)malloc(numRecords * sizeof(long));
    if (!offsets) {
        free(keys);
        *errCode = 2;
        return NULL;
    }

    record* records = (record*)malloc(numRecords * sizeof(record));
    if (!records) {
        free(keys);
        free(offsets);
        *errCode = 3;
        return NULL;
    }

    srand(time(NULL));

    for (size_t i = 0; i < numRecords; i++) {
        keys[i] = rand() % (numRecords - 1);
        offsets[i] = rand();
        records[i].key = keys[i];
        records[i].offset = offsets[i];
    }

    free(keys);
    free(offsets);

    return records;
}
