#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define N 1000 // Maximum size of dynamic array
#define MAX_KEY 1000 // Maximum hash key value
#define THRESHOLD 10 // Threshold for flushing cached errors to the log

typedef struct {
    int antenna_gain;
    int bandwidth;
    int frequency;
    char* channel_mask;
} LTE_PHY_RX_CONFIG_T;

typedef struct {
    long key;
    int value;
    LTE_PHY_RX_STATS_T stats;
    char* record_str;
} RECORD_T;

void insert_key_value(RECORD_T** hash_table, int slot_count) {
    // Initialize dynamic array and error log
    *hash_table = (RECORD_T**)malloc(slot_count * sizeof(RECORD_T*));
    if (*hash_table == NULL) {
        printf("Error: Memory allocation failed.\n");
        return;
    }

    for (int i = 0; i < slot_count; i++) {
        (*hash_table)[i] = (RECORD_T*)malloc(sizeof(RECORD_T));
        if ((*hash_table)[i] == NULL) {
            printf("Error: Memory allocation failed.\n");
            free(*hash_table);
            *hash_table = NULL;
            return;
        }
    }

    // Initialize LTE_PHY_RX_CONFIG_T structures
    for (int i = 0; i < slot_count; i++) {
        (*hash_table)[i]->record_str = malloc(10 * sizeof(char));
        if ((*hash_table)[i]->record_str == NULL) {
            printf("Error: Memory allocation failed.\n");
            free(*hash_table);
            *hash_table = NULL;
            return;
        }
        strcpy((*hash_table)[i]->record_str, "Default Channel Mask");

        // Initialize LTE_PHY_RX_STATS_T structures
        (*hash_table)[i]->stats.RX_POWER_LEVEL = rand() % 10 + 1;
        (*hash_table)[i]->stats.SINR = rand() % 10 + 1;
        (*hash_table)[i]->stats.BER = (double)rand() / RAND_MAX;

        // Initialize random frequency values
        (*hash_table)[i]->record_str[9] = '\0';
        srand(time(NULL));
        sprintf((*hash_table)[i]->record_str, "%d", rand() % 10000);
    }
}

void resize_hash_table(RECORD_T** hash_table, int new_slot_count) {
