    // Initialize arrays
    int *keys = (int *)malloc(num_records * sizeof(int));
    long *offsets = (long *)malloc(num_records * sizeof(long));
    record_t *records = (record_t *)malloc(num_records * sizeof(record_t));

    if (!keys || !offsets || !records) {
        free(keys);
        free(offsets);
        free(records);
        return -1;
    }

    // Initialize keys and offsets
    for (i = 0; i < num_records; i++) {
        keys[i] = rand() % 100 + 1;
        offsets[i] = (long)i * 2;
    }

    // Initialize records
    for (i = 0; i < num_records; i++) {
        record_t temp = {keys[i], &offsets[i]};
        records[i] = temp;
    }

    // Resize arrays if necessary
    while (1) {
        pthread_mutex_lock(&lock);
        int new_size = num_records * 2;
        int *new_keys = (int *)realloc(keys, new_size * sizeof(int));
        long *new_offsets = (long *)realloc(offsets, new_size * sizeof(long));
        record_t *new_records = (record_t *)realloc(records, new_size * sizeof(record_t));

        if (!new_keys || !new_offsets || !new_records) {
            pthread_mutex_unlock(&lock);
            for (i = 0; i < num_records; i++) {
