                free((void **)&offsets[i]);
                free((void **)&records[i].offset);
            }
            free(keys);
            free(offsets);
            free(records);
            return -1;
        }

        pthread_mutex_unlock(&lock);

        // Update variables
        keys = new_keys;
        offsets = new_offsets;
        records = new_records;

        num_records *= 2;
    }

    // Free memory
    for (i = 0; i < num_records; i++) {
