// Modular C++ function to initialize and configure network interface settings
void initNetworkSettings(const std::vector<std::string>& configStrings, std::vector<NFAPI_CONTROL_PDU_T>& networkSettings) {
    // Process each configuration string
    for (const auto& configString : configStrings) {
        NFAPI_CONTROL_PDU_T config;

        // Parse IP address and subnet mask from config string
        size_t ipIndex = configString.find("ipAddress=");
        size_t subnetMaskIndex = configString.find("subnetMask=");
        if (ipIndex != std::string::npos && subnetMaskIndex != std::string::npos) {
            size_t ipAddressEnd = configString.find(";", ipIndex);
            size_t subnetMaskEnd = configString.find(";", subnetMaskIndex);

            // Extract IP address and subnet mask
            std::string ipAddress = configString.substr(ipIndex + 11, ipAddressEnd - (ipIndex + 11));
            std::string subnetMask = configString.substr(subnetMaskIndex + 12, subnetMaskEnd - (subnetMaskIndex + 12));

            // Validate IP address and subnet mask
            if (!validateIPAddress(ipAddress) || !validateSubnetMask(subnetMask)) {
                continue;
            }
        }

        // Parse VLAN ID range from config string
        size_t vlanIdRangeIndex = configString.find("vlanIdMin=");
        if (vlanIdRangeIndex != std::string::npos) {
            size_t vlanIdMaxEnd = configString.find(";", vlanIdRangeIndex);

            // Extract VLAN ID min and max
            int vlanIdMin = std::stoi(configString.substr(vlanIdRangeIndex + 11, vlanIdMaxEnd - (vlanIdRangeIndex + 11)));
            int vlanIdMax = std::stoi(configString.substr(vlanIdMaxEnd + 1));

            // Validate VLAN ID range
            if (vlanIdMin < 0 || vlanIdMax < 0 || vlanIdMin > vlanIdMax) {
                continue;
            }
        }

        config.macAddress = configString.substr(0, ipIndex - 1);
        config.ipAddress = ipAddress;
        config.subnetMask = subnetMask;
        config.vlanIdMin = vlanIdMin;
        config.vlanIdMax = vlanIdMax;

        // Add configuration to network settings
        networkSettings.push_back(config);
    }
}

