            rapidjson::FileReadStream is(endpoint_);
            rapidjson::Document d;
            d.ParseStream(is);
            callback_(d["data"]);
        }).detach();
    }

private:
    std::string endpoint_;
    std::function<void(rapidjson::Value)> callback_;
};

// Multi-Threading
class ThreadPool {
public:
    ThreadPool(int num_threads) : stop_(false), threads_(num_threads) {}

    void start() {
        for (int i = 0; i < threads_; ++i) {
            threads_.emplace_back([this]() { 
                while (!stop_) {
                    std::unique_lock<std::mutex> lock(mutex_);
                    condition_.wait(lock);
                    if (work_.empty()) break;
                    work_.front().reset();
                    work_.pop_front();
                }
            });
        }
    }

    void stop() {
        stop_ = true;
    }

    template <typename F>
    void enqueue(F&& f) {
        std::unique_lock<std::mutex> lock(mutex_);
        work_.emplace_back(new std::packaged_task<void()>(std::move(f)));
        condition_.notify_one();
    }

private:
    bool stop_;
    std::vector<std::thread> threads_;
    std::mutex mutex_;
    std::condition_variable condition_;
    std::deque<std::unique_ptr<std::function<void()>>> work_;
};

// Flexible Query Interface
