import pyodbc
from multiprocessing import Pool
import pandas as pd

class SensorDataProcessor:
    def __init__(self, db_url):
        self.conn = pyodbc.connect(db_url)

    def process_data(self, start_date, end_date):
        query = "SELECT * FROM sensor_readings WHERE timestamp BETWEEN ? AND ?"
        cursor = self.conn.cursor()
        records = []
        with Pool(processes=4) as pool:
            results = pool.starmap(self.process_record, [(start_date, end_date)])
        for result in results:
            records.extend(result)
        return pd.DataFrame(records)

    def process_record(self, start_date, end_date):
        cursor.execute(query, (start_date, end_date))
        records = []
        for row in cursor.fetchall():
            # process record and append to list
            records.append([row[0], row[1], row[2], row[3], row[4]])
        return records

    def close(self):
        self.conn.close()
