EVP_CIPHER_CTX* implement_ciphers(int key_size, enum cipher_mode mode) {
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_Cipher_init(ctx, EVP_des_ecb(), &key_size);

