// Structure representing an NFAPI_CRC_INDICATION_PDU_T variable-sized array
typedef struct {
    long timestamp;
    double crcFlag;
} data_record;

data_record* initializeNFAPIArray(int numRecords) {
    int i;
    FILE *logFile = fopen("error.log", "a");

    // Allocate memory for arrays of long and double values
    long* timestamps = (long*)malloc(numRecords * sizeof(long));
    double* crcFlags = (double*)malloc(numRecords * sizeof(double));

    if (!timestamps || !crcFlags) {
        fprintf(logFile, "Memory allocation failure\n");
        return NULL;
    }

    // Initialize arrays with unique timestamps and random CRC flags
    for (i = 0; i < numRecords; i++) {
        timestamps[i] = time(NULL) + (rand() % TIMESTAMP_WINDOW);
        crcFlags[i] = (double)rand() / RAND_MAX;
    }

    // Allocate memory for char strings of maximum length 512 and initialize with unique identifiers
    char** strings = (char**)malloc(numRecords * sizeof(char*));
    for (i = 0; i < numRecords; i++) {
        strings[i] = (char*)malloc(513); // Include space for null-terminator
        sprintf(strings[i], "record_%d", i);
    }

    // Allocate memory for data_record structures and initialize with random values
    data_record* records = (data_record*)malloc(numRecords * sizeof(data_record));
    for (i = 0; i < numRecords; i++) {
        records[i].timestamp = timestamps[i];
        records[i].crcFlag = crcFlags[i];

        // Initialize char string as part of a larger text
        sprintf(records[i].string, "%s: %f", strings[i], (float)rand() / RAND_MAX);
    }

    free(timestamps);
    free(crcFlags);

    for (i = 0; i < numRecords; i++) {
        free(strings[i]);
    }
    free(strings);

    return records;
}
