                   (config.mac[3] & 0xff), (config.mac[4] & 0xff), (config.mac[5] & 0xff));
            continue;
        }

        // Validate IP address
        if (!validate_ip_address(config.ipv4_ip || config.ipv6_ip)) {
            printf("Invalid IP address\n");
            continue;
        }

        // Validate subnet mask
        int subnet_mask = config.ipv4_subnet_mask | (config.ipv6_subnet_mask << 32);
        if (!validate_subnet_mask(subnet_mask, config.ipv4_ip || config.ipv6_ip)) {
            printf("Invalid subnet mask\n");
            continue;
