        // Dynamically adjust subnet mask based on number of devices
        int num_devices = get_num_devices_in_subnet(config.ipv4_ip || config.ipv6_ip, subnet_mask);
        if (num_devices > 254) { // Adjust subnet mask for large number of devices
            subnet_mask = (subnet_mask >> 1) | 0xffffff00;
        }

        // Apply configuration
        apply_network_configuration(&config);
    }
}

