#include <vector>
#include <memory>

void insertInt(std::vector<std::unique_ptr<int>>& vec, int val, int min_value, int max_value, int max_size) {
    if (val < min_value || val > max_value) {
        return; // error: value out of range
    }

    auto it = std::find_if(vec.begin(), vec.end(),
        [&](const auto& p){ return *p == val; });

    size_t idx = (it != vec.end()) ? vec.erase(it) : vec.size();
    if (idx >= max_size) {
        return; // error: vector exceeds maximum size
    }

    vec.insert(vec.begin() + idx, std::make_unique<int>(val));
}
