    // Initialize an array of NFAPI_CONTROL_PDU_T structures
    NFAPI_CONTROL_PDU_T* nfp = (NFAPI_CONTROL_PDU_T*)malloc(sizeof(NFAPI_CONTROL_PDU_T) * 10);
    if (!nfp) {
