        return NULL;
    }

    // Initialize the three arrays
    long* offset_values = (long*)malloc(sizeof(long) * 1000);
    int* key_array = (int*)malloc(sizeof(int) * 1000);
    double* metric_values = (double*)malloc(sizeof(double) * 1000);

    if (!offset_values || !key_array || !metric_values) {
        printf("Memory allocation failed.\n");
        free(nfp);
        return NULL;
    }

    // Read data from external source
    for (int i = 0; i < 10; i++) {
        pthread_mutex_lock(mutex);
        record_t* record = (record_t*)malloc(sizeof(record_t));
        if (!record) {
            printf("Memory allocation failed.\n");
            pthread_mutex_unlock(mutex);
            return NULL;
        }
        // Initialize the record
        record->key = rand() % 1000;
        record->metric = (double)(rand() % 1000) / 10.0;
        sprintf(record->name, "Record %d", i);

        // Validate MAC and IP addresses
        for (int j = 0; j < 6; j++) {
            nfp[i].mac[j] = rand() % 256;
        }
        sprintf(nfp[i].ipv4, "%d.%d.%d.%d", rand() % 256, rand() % 256, rand() % 256, rand() % 256);
        sprintf(nfp[i].ipv6, "%x:%x:%x:%x:%x:%x", rand() % 16, rand() % 16, rand() % 16, rand() % 16, rand() % 16, rand() % 16);
        nfp[i].subnet_mask = rand() % 256;
        nfp[i].vlan_id = rand() % 256;

        pthread_mutex_unlock(mutex);

        // Initialize the three arrays
        offset_values[i] = (long)(rand() % 1000);
        key_array[i] = record->key;
        metric_values[i] = record->metric;

        free(record);
    }

    // Release memory
    free(offset_values);
    free(key_array);
    free(metric_values);

    return nfp;
}
