import java.util.Random;
import java.net.InetAddress;
import java.net.UnknownHostException;

public class NFAPIControlPDU {
    public static void main(String[] args) {
        Random rand = new Random();
        int delayMin = 1000; // in milliseconds
        int delayMax = 5000;

        while (true) {
            try {
                Thread.sleep(rand.nextInt(delayMax - delayMin + 1) + delayMin);

                NFAPIControlPDU_T pdu = new NFAPIControlPDU_T();
                pdu.start_service();

                // Initialize and configure network interfaces
                for (int i = 0; i < 5; i++) {
                    NFAPIInterface interfaceConfig = new NFAPIInterface();
                    interfaceConfig.setMacAddress(InetAddress.getByName("00:11:22:" + i + ":33:44").getCanonicalHostName());
                    interfaceConfig.setIpAddress(InetAddress.getByName("192.168." + i + ".1"));
                    interfaceConfig.setSubnetMask(InetAddress.getByName("255.255.255.0"));

                    // Add VLAN support
                    for (int vlan = 100; vlan <= 200; vlan++) {
                        interfaceConfig.addVlan(vlan);
                    }

                    pdu.addInterface(interfaceConfig);
                }

                // Validate and apply network settings
                if (!pdu.validateAndApply()) {
                    System.out.println("Configuration failed. Aborting.");
                    break;
                }
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }

            pdu.stop_service();

            // Send a message to the messaging system when stopped
            try {
                MessageSender sender = new MessageSender();
                sender.send("NFAPI service stopped");
            } catch (Exception e) {
                System.out.println("Error sending message: " + e.getMessage());
            }
        }
    }
}
