    char encryptionSetting; // 'E' for enabled, 'D' for disabled
    char compressionSetting; // 'C' for compressed, 'U' for uncompressed
} BLOCK_DEVICE_PDU_T;

void manageVirtualDevices(BLOCK_DEVICE_PDU_T **devices, int *numDevices) {
    // Function to add a new device
    void addDevice(BLOCK_DEVICE_PDU_T **devices, int *numDevices) {
        if (*numDevices < 1000) { // Limit the number of devices for performance reasons
            *numDevices = *numDevices + 1;
            BLOCK_DEVICE_PDU_T* newDevice = (BLOCK_DEVICE_PDU_T*)malloc(sizeof(BLOCK_DEVICE_PDU_T));
            printf("Enter details for device %d:\n", *numDevices);
            scanf("%d %d %d %c %c %c", &newDevice->deviceId, &newDevice->blockSize, &newDevice->alignmentRequirement, 
                    &newDevice->accessMode, &newDevice->encryptionSetting, &newDevice->compressionSetting);
            devices[*numDevices-1] = newDevice;
        } else {
            printf("Maximum number of devices reached.\n");
        }
    }

    // Function to remove a device
    void removeDevice(BLOCK_DEVICE_PDU_T **devices, int *numDevices) {
        if (*numDevices > 0) {
            *numDevices = *numDevices - 1;
            free(devices[*numDevices]);
        } else {
            printf("No devices available.\n");
        }
    }

    // Function to resize a partition
    void resizePartition(BLOCK_DEVICE_PDU_T **devices, int *numDevices) {
        if (*numDevices > 0) {
            printf("Enter the device ID and new block size to resize:\n");
            scanf("%d %d", &deviceId, &newBlockSize);
            for (int i = 0; i < *numDevices; i++) {
                if (devices[i]->deviceId == deviceId) {
                    devices[i]->blockSize = newBlockSize;
                    break;
                }
            }
        } else {
            printf("No devices available.\n");
        }
    }

    // Function to change the access mode
    void changeAccessMode(BLOCK_DEVICE_PDU_T **devices, int *numDevices) {
        if (*numDevices > 0) {
            printf("Enter the device ID and new access mode (R/W):\n");
            scanf("%d %c", &deviceId, &newAccessMode);
            for (int i = 0; i < *numDevices; i++) {
                if (devices[i]->deviceId == deviceId) {
                    devices[i]->accessMode = newAccessMode;
                    break;
                }
            }
        } else {
            printf("No devices available.\n");
        }
    }

    // Function to handle device failures
    void handleDeviceFailure(BLOCK_DEVICE_PDU_T **devices, int *numDevices, int failedDeviceId) {
        for (int i = 0; i < *numDevices; i++) {
            if (devices[i]->deviceId == failedDeviceId) {
                free(devices[i]);
                break;
            }
        }
    }

    // Function to validate storage settings
    void validateStorageSettings(BLOCK_DEVICE_PDU_T **devices, int *numDevices) {
        for (int i = 0; i < *numDevices; i++) {
            if (devices[i]->blockSize > 1024 || devices[i]->alignmentRequirement > 8) {
                printf("Invalid storage settings. Block size and alignment requirement must not exceed 1024 and 8 respectively.\n");
                return;
            }
        }
    }

    // Function to ensure data consistency
    void ensureDataConsistency(BLOCK_DEVICE_PDU_T **devices, int *numDevices) {
        for (int i = 0; i < *numDevices; i++) {
            if (devices[i]->accessMode == 'W') {
                // Perform write operation and update metadata
                printf("Writing to device %d\n", devices[i]->deviceId);
            } else {
                // Perform read-only operation without updating metadata
                printf("Reading from device %d\n", devices[i]->deviceId);
            }
        }
    }

    int main() {
        BLOCK_DEVICE_PDU_T* devices[1000];
        int numDevices = 0;

        while (1) {
            printf("Enter the command:\n");
            printf("A - Add a new device, R - Remove a device, S - Resize a partition, C - Change access mode, F - Handle device failure, V - Validate storage settings, E - Ensure data consistency.\n");
            char command;
            scanf(" %c", &command);
            switch (command) {
                case 'A':
                    addDevice(&devices, &numDevices);
                    break;
                case 'R':
                    removeDevice(&devices, &numDevices);
                    break;
                case 'S':
                    resizePartition(&devices, &numDevices);
                    break;
                case 'C':
                    changeAccessMode(&devices, &numDevices);
                    break;
                case 'F':
                    printf("Enter the device ID that failed:\n");
                    scanf("%d", &failedDeviceId);
                    handleDeviceFailure(&devices, &numDevices, failedDeviceId);
                    break;
                case 'V':
                    validateStorageSettings(&devices, &numDevices);
                    break;
                case 'E':
                    ensureDataConsistency(&devices, &numDevices);
                    break;
            }
        }

        return 0;
    }']

