    int SESSION_ID;
    char UE_ID[16];
    int EPS_BEARER_ID;
    char PDUSessionState[128];
} PDU_SESSION_STATE_RECORD;

// Define function to manage dynamic list of PDU SESSION STATE RECORD structures
PDU_SESSION_STATE_RECORD **manageDynamicList(int *size, int maxSize) {
    PDU_SESSION_STATE_RECORD **list = (PDU_SESSION_STATE_RECORD **)malloc(maxSize * sizeof(PDU_SESSION_STATE_RECORD *));
    if (!list) {
        return NULL;
    }

    *size = 0;

    // Function to handle dynamic resizing
    void *reallocate(void *ptr, size_t oldSize, size_t newSize) {
        void *newPtr = realloc(ptr, newSize);
        if (!newPtr) {
            free(ptr);
            return NULL;
        }
        return newPtr;
    }

    // Function to add record to the list
    void addRecord(int sessionId, char* ueId, int epsBearerId, char* pduSessionState, PDU_SESSION_STATE_RECORD ***list, int *size) {
        if (*size >= maxSize) {
            *list = reallocate(*list, maxSize * sizeof(PDU_SESSION_STATE_RECORD *), (maxSize + 10) * sizeof(PDU_SESSION_STATE_RECORD *));
            if (!*list) {
                return;
            }
            maxSize *= 2;
        }

        PDU_SESSION_STATE_RECORD *record = (PDU_SESSION_STATE_RECORD *)malloc(sizeof(PDU_SESSION_STATE_RECORD));
        strcpy(record->UE_ID, ueId);
        record->SESSION_ID = sessionId;
        record->EPS_BEARER_ID = epsBearerId;
        strcpy(record->PDUSessionState, pduSessionState);

        (*list)[*size] = record;
        (*size)++;
    }

    // Function to remove record from the list
    void removeRecord(int index, PDU_SESSION_STATE_RECORD ***list, int *size) {
        if (index < 0 || index >= *size) {
            return;
        }

        free((*list)[index]);
        for (int i = index; i < *size - 1; i++) {
            (*list)[i] = (*list)[i + 1];
        }

        (*list)[*size - 1] = NULL;
        (*size)--;
    }

    return list;
}

// Example usage
int main() {
    int size = 0;
    int maxSize = 5000;

    PDU_SESSION_STATE_RECORD **list = manageDynamicList(&size, maxSize);

    addRecord(1234, "UE-1", 5, "UP", &list, &size);
    addRecord(5678, "UE-2", 10, "DOWN", &list, &size);

    printf("Size of the list: %d\n", size);

    removeRecord(0, &list, &size);

    return 0;
}

