import pyodbc
from multiprocessing import Pool
import random
from datetime import datetime

class SensorReader:
    def __init__(self, conn_str):
        self.conn_str = conn_str

    def read_sensors(self):
        cursor = pyodbc.connect(self.conn_str).cursor()
        cursor.execute("SELECT * FROM sensor_readings")
        rows = cursor.fetchall()

        return [(row[0], row[1], row[2], row[3], row[4]) for row in rows]

    def deduplicate_and_aggregate(self, readings):
        unique_readings = []
        for reading in readings:
            if reading not in unique_readings:
                unique_readings.append(reading)

        summary_stats = {}
        for reading in unique_readings:
            if reading[0] not in summary_stats:
                summary_stats[reading[0]] = [reading[1], reading[2], reading[3], reading[4]]
            else:
                summary_stats[reading[0]][0] += 1
                summary_stats[reading[0]][1] += reading[1]
                summary_stats[reading[0]][2] += reading[2]
                summary_stats[reading[0]][3] += reading[3]

        return summary_stats

    def process_readings(self, num_processes):
        pool = Pool(num_processes)
        readings = self.read_sensors()
        deduplicated_readings = pool.map(self.deduplicate_reading, readings)
        pool.close()

        return self.deduplicate_and_aggregate(deduplicated_readings)

class Cacher:
    def __init__(self, cache_size):
        self.cache = {}
        self.cache_size = cache_size

    def add_to_cache(self, key, value):
        if len(self.cache) < self.cache_size:
            self.cache[key] = value
        else:
            for k in list(self.cache.keys()):
                del self.cache[k]
            self.cache[key] = value

    def get_from_cache(self, key):
        return self.cache.get(key)

# Usage example
sensor_reader = SensorReader("DRIVER={ODBC Driver 17 for SQL Server};SERVER=localhost;DATABASE=mydb;UID=myuser;PWD=mypassword")
num_processes = 4
summary_stats = sensor_reader.process_readings(num_processes)
print(summary_stats)
