// Define the record structure
typedef struct {
    int value;
} Record;

int main() {
    // Set the size of the arrays
    int offset_size = 1000;
    int key_size = 500;
    int record_size = 100;

    // Allocate memory for the arrays
    long* offsets = (long*)malloc(offset_size * sizeof(long));
    int* keys = (int*)malloc(key_size * sizeof(int));
    Record** records = (Record**)malloc(record_size * sizeof(Record*));

    // Initialize the offset array with consecutive integers
    for (int i = 0; i < offset_size; i++) {
        offsets[i] = i;
    }

    // Populate the key array with unique random integers within a specified range
    srand(time(NULL));
    for (int i = 0; i < key_size; i++) {
        keys[i] = rand() % 10000;
    }

    // Assign random values to each record's 'int' field
    for (int i = 0; i < record_size; i++) {
        records[i] = malloc(sizeof(Record));
        records[i]->value = rand() % 100;
    }

    // Ensure no two records have the same key
    int* key_set = (int*)malloc(key_size * sizeof(int));
    for (int i = 0; i < record_size; i++) {
        int found = 0;
        for (int j = 0; j < key_size; j++) {
            if (keys[j] == records[i]->value) {
                found = 1;
                break;
            }
        }
        if (!found) {
            // Insert the new key into the set
            int k = rand() % key_size;
            while (key_set[k]) {
                k = (k + 1) % key_size;
            }
            keys[k] = records[i]->value;
        }
    }

    return 0;
}
