void* allocate_memory(size_t size) {
    void* ptr = NULL;
    if (size < sizeof(void*)) {
        // stack allocation for small sizes
        static char buffer[BUFFER_SIZE];
        ptr = &buffer[0];
    } else {
        // heap allocation for larger sizes
        ptr = malloc(size);
    }
    return ptr;
}

void deallocate_memory(void* ptr) {
    if (ptr != NULL && ((char*)ptr < &buffer[0])) {
        // stack deallocation for small sizes
        static char buffer[BUFFER_SIZE];
        ((char*)ptr)[0] = '\0';  // mark as freed
    } else {
        free(ptr);
    }
}

