    std::vector<SensorData> dataStreams;
    // populate data streams array

    std::vector<TaskStatus> results = processSensorData(dataStreams);
    for (auto& result : results) {
        if (!result.success) {
            // handle error
        }
    }

    return 0;
}

std::vector<TaskStatus> processSensorData(const std::vector<SensorData>& dataStreams) {
    DataProcessor processor;
    processor.start();

    std::vector<TaskStatus> results;
    for (auto& stream : dataStreams) {
        TaskStatus status = processor.processStream(stream);
        results.push_back(status);
    }

    processor.stop();
    return results;
}
