    NFAPI_CRC_INDICATION_PDU_T *list = NULL;
    int list_size = 0;
    int update_count = 0;
    int update_interval = 100; // Update interval in milliseconds
    int update_threshold = 5000; // Update threshold in milliseconds
    int max_list_size = 10000;

    // Initialize random number generator
    srand(time(NULL));

    while (update_count < num_updates) {
        if (list_size >= max_list_size) {
            // Resize list to accommodate more structures
            NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, (max_list_size + 1000) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!new_list) {
                printf("Error: Out of memory\n");
                return;
            }
            list = new_list;
            max_list_size += 1000;
        }

        NFAPI_CRC_INDICATION_PDU_T *structure = &list[list_size];
        structure->RX_UE_INFORMATION_TAG = rand() % 256;
        structure->RNTI = rand() % 256;
        structure->CRC_INDICATION_REL8_TAG = rand() % 256;
        structure->CRCFLAG = rand() % 2;

        // Update list size and update count
        list_size++;
        update_count++;

        if ((update_count * update_interval) > time(NULL)) {
            continue; // Wait for next update interval
        }

        if (list_size >= max_list_size / 4) {
            printf("Warning: List size exceeded threshold\n");
        }
    }

    free(list);
}

