        return -1;
    if (nfaapi_validate_config(config)) {
        *config = nfaapi_nic_config_init(config);
        pool->config_pool = realloc(pool->config_pool, (pool->count + 1) * sizeof(NFAPI_NIC_CONFIG));
        memcpy(pool->config_pool + pool->count++, config, sizeof(NFAPI_NIC_CONFIG));
        return 0;
    }
    return -2; // Invalid configuration
}

int nfaapi_delete_nic_config(NFAPINIC_POOL* pool, size_t index) {
    if (index >= pool->count)
        return -1;
    memmove(pool->config_pool + index, pool->config_pool + index + 1, sizeof(NFAPI_NIC_CONFIG) * (pool->count - index - 1));
    --pool->count;
    free(pool->config_pool + pool->count);
    return 0;
