typedef struct {
    NFAPI_CONFIG_T *configs;
    int config_count;
    int capacity;
} NFAPICONTROL_PDU_T;

NFAPICONTROL_PDU_T* nfapi_control_pdu_init(int initial_capacity) {
    NFAPICONTROL_PDU_T* pdu = (NFAPICONTROL_PDU_T*)malloc(sizeof(NFAPICONTROL_PDU_T));
    pdu->configs = (NFAPI_CONFIG_T*)calloc(initial_capacity, sizeof(NFAPI_CONFIG_T));
    pdu->capacity = initial_capacity;
    pdu->config_count = 0;
    return pdu;
}

void nfapi_control_pdu_free(NFAPICONTROL_PDU_T* pdu) {
    for(int i = 0; i < pdu->config_count; i++) {
        free(pdu->configs[i].mac);
        free(pdu->configs[i].ip_v4);
        free(pdu->configs[i].ip_v6);
        free(pdu->configs[i].vlan_ids);
    }
    free(pdu->configs);
    free(pdu);
}

int nfapi_control_pdu_add_config(NFAPICONTROL_PDU_T* pdu, uint8_t *mac, char *ip_v4, char *ip_v6, uint32_t subnet_mask, int *vlan_ids, int vlan_id_count) {
    if(pdu->config_count >= pdu->capacity) {
        // Reallocate and resize the config array
        pdu->configs = (NFAPI_CONFIG_T*)realloc(pdu->configs, (pdu->capacity + 1) * sizeof(NFAPI_CONFIG_T));
        pdu->capacity += 1;
    }
    NFAPI_CONFIG_T* new_config = &pdu->configs[pdu->config_count];
    new_config->mac = (uint8_t*)malloc(strlen((char *)mac)+1);
    strcpy((char *)new_config->mac, mac);
    new_config->ip_v4 = (char*)malloc(strlen(ip_v4)+1);
    strcpy(new_config->ip_v4, ip_v4);
    new_config->ip_v6 = (char*)malloc(strlen(ip_v6)+1);
    strcpy(new_config->ip_v6, ip_v6);
    new_config->subnet_mask = subnet_mask;
    new_config->vlan_ids = (int*)malloc(vlan_id_count * sizeof(int));
    memcpy(new_config->vlan_ids, vlan_ids, vlan_id_count * sizeof(int));
    new_config->vlan_id_count = vlan_id_count;
    pdu->config_count++;
    return 0;
}

void nfapi_control_pdu_delete_config(NFAPICONTROL_PDU_T* pdu, uint8_t *mac) {
    for(int i = 0; i < pdu->config_count; i++) {
        if(memcmp(pdu->configs[i].mac, mac, strlen((char *)mac)+1) == 0) {
            free(pdu->configs[i].mac);
            free(pdu->configs[i].ip_v4);
            free(pdu->configs[i].ip_v6);
            free(pdu->configs[i].vlan_ids);
            memmove(&pdu->configs[i], &pdu->configs[i+1], (pdu->config_count - i - 1) * sizeof(NFAPI_CONFIG_T));
            pdu->config_count--;
            return;
        }
    }
}

NFAPI_CONFIG_T* nfapi_control_pdu_get_config(NFAPICONTROL_PDU_T* pdu, uint8_t *mac) {
    for(int i = 0; i < pdu->config_count; i++) {
        if(memcmp(pdu->configs[i].mac, mac, strlen((char *)mac)+1) == 0) {
            return &pdu->configs[i];
        }
    }
    return NULL;
}

