typedef struct {
    int priority;
    int io_buffer_size;
    int scheduling_policy;
} PRCFG_DATA_T;

void* prcfg_alloc(int size) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static void* stack_top = NULL;
    static size_t heap_limit = 0x10000000; // 16 MB

    if (size <= 1024) { // small allocation, use stack
        void* ptr = alloca(size);
        return ptr;
    } else { // large allocation, use heap
        pthread_mutex_lock(&lock);

        if (stack_top + size > heap_limit) {
            heap_limit *= 2; // double the heap limit
            heap_limit = roundup(heap_limit, sizeof(pthread_t));
            void* new_heap = valloc(heap_limit);
            memcpy(new_heap, stack_top, size);
            free(stack_top);
            stack_top = new_heap;
        }

        void* ptr = stack_top + (size - sizeof(pthread_t));
        pthread_mutex_unlock(&lock);

        return ptr;
    }
}

void prcfg_free(void* ptr) {
    if ((char*)ptr < alloca(0)) { // on the stack
        free(ptr);
    } else { // on the heap
        pthread_mutex_lock(&lock);
        stack_top = (void*)((char*)ptr - sizeof(pthread_t));
        pthread_mutex_unlock(&lock);
    }
}

PRCFG_DATA_T* prcfg_get_config(int process_id) {
    PRCFG_DATA_T* config = prcfg_alloc(sizeof(PRCFG_DATA_T));
    // configure data based on process_id
    return config;
}

void prcfg_update_config(PRCFG_DATA_T* config, int process_id) {
    pthread_mutex_lock(&lock);
    // update configuration based on process_id
    pthread_mutex_unlock(&lock);
}
