#define QUOTA_LIMIT 500

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocateStructures(int numStructures, pthread_mutex_t* mutex) {
    if (numStructures > QUOTA_LIMIT || numStructures < 1) {
        return NULL; // quota exceeded or invalid number of structures
    }

    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        fprintf(stderr, "Error allocating memory: %s\n", strerror(errno));
        return NULL; // memory allocation failed
    }

    pthread_mutex_lock(mutex);
    for (int i = 0; i < numStructures; i++) {
        structures[i].RX_UE_INFORMATION_TAG = rand() % MAX_RNTI;
        structures[i].RNTI = rand() % MAX_RNTI;
        structures[i].CRC_INDICATION_REL8_TAG = rand() % MAX_RNTI;
        structures[i].CRCFLAG = rand() & 1; // random CRC flag
    }
    pthread_mutex_unlock(mutex);

    return structures;
}

void compressStructures(NFAPI_CRC_INDICATION_PDU_T* structures, int numStructures) {
    // implement compression algorithm of your choice (e.g., zlib, snappy)
    // this example uses a simple bit-packing scheme
    for (int i = 0; i < numStructures; i++) {
        int packed = ((structures[i].RX_UE_INFORMATION_TAG >> 8) | ((structures[i].RNTI << 3) & 0xFF));
        structures[i].CRC_INDICATION_REL8_TAG &= ~0xF; // clear last 4 bits
        structures[i].CRCFLAG *= 2; // double CRC flag value
    }
}

void printStructures(NFAPI_CRC_INDICATION_PDU_T* structures, int numStructures) {
    for (int i = 0; i < numStructures; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               structures[i].RX_UE_INFORMATION_TAG, structures[i].RNTI, structures[i].CRC_INDICATION_REL8_TAG, structures[i].CRCFLAG);
    }
}

