    TaskManager() : running_(false) {}

    // Start task processing
    void start(int numTasks, const std::vector<TaskSpec>& tasks) {
        running_ = true;
        threads_.reserve(numTasks);
        for (auto& task : tasks) {
            threads_.emplace_back([this, task]() {
                executeTask(task.id, task.priority, task.timeout, task.data);
