void phyMeasurementsFree(LTE_PHY_MEASUREMENTS* arr) {
    pthread_mutex_destroy(&arr->mutex);
    free(arr);
}

int phyMeasurementsGet(int arr[], int index) {
    if (index >= 0 && index < sizeof(LTE_PHY_MEASUREMENTS)/sizeof(LTE_PHY_MEASUREMENTS[0])) {
        return rand() % 100 + 1;
    } else {
        return -1;
    }
}

void phyMeasurementsClear(LTE_PHY_MEASUREMENTS* arr) {
    pthread_mutex_lock(&arr->mutex);
    for (int i = 0; i < sizeof(LTE_PHY_MEASUREMENTS)/sizeof(LTE_PHY_MEASUREMENTS[0]); i++) {
