async function readFileSync(dirPath, filePath) {
  try {
    const fs = require('fs').promises;
    const stat = await fs.stat(`${dirPath}/${filePath}`);
    if (!stat.isFile()) throw new Error(`File ${filePath} not found in directory ${dirPath}`);

    const fileStream = await fs.open(`${dirPath}/${filePath}`, 'r');
    try {
      const buffer = Buffer.alloc(stat.size);
      await fileStream.read(buffer, 0, stat.size);
      return buffer.toString('utf8');
    } finally {
      await fileStream.close();
    }
  } catch (err) {
    if (err.code === 'ENOENT') return `File not found: ${filePath}`;
    else return `Error reading file: ${err.message}`;
  }
}
