class TaskManager {
public:
    vector<TaskStatus> executeTasks(vector<string> tasks, bool async) {
        vector<TaskStatus> results;
        for (const auto& task : tasks) {
            TaskStatus status;
            if (async) {
                // Asynchronous execution
                status = asyncExecuteTask(task);
            } else {
                // Synchronous execution
                status = syncExecuteTask(task);
            }
            results.push_back(status);
        }
        return results;
    }

