function loadFiles(config) {
    let head = "";
    const scripts = {};
    config.forEach((file) => {
        if (!file.filePath || !file.identifier || !file.condition || !file.eventListenerType) {
            throw new Error("Configuration object missing required properties");
        }

        head += `<link rel="stylesheet" type="text/css" href="${file.filePath}" id="${file.identifier}-style">`;

        if (scripts[file.identifier]) {
            throw new Error(`Script with identifier "${file.identifier}" already loaded`);
        }
        scripts[file.identifier] = file;

        let script = document.createElement("script");
        script.src = file.filePath.replace(".css", ".js");
        script.id = `${file.identifier}-script`;

        if (file.condition) {
            script.onload = () => {
                try {
                    eval(file.eventListenerType)(file);
                } catch (error) {
                    console.error(error);
                }
            };
        }

        head += script.outerHTML;
    });

    return head;
}
