import pyodbc
import multiprocessing
import asyncio
import random
import os
import shutil
import gzip
import png

class SensorReadingModule:
    def __init__(self, db_url):
        self.db_url = db_url
        self.conn = None

    async def connect_db(self):
        try:
            self.conn = pyodbc.connect(self.db_url)
        except Exception as e:
            print(f"Error connecting to database: {e}")

    async def query_db(self, query):
        if not self.conn:
            await self.connect_db()
        cursor = self.conn.cursor()
        try:
            result = cursor.execute(query).fetchall()
            return result
        except pyodbc.Error as e:
            print(f"Error executing query: {e}")
            return None

    async def insert_reading(self, reading):
        if not self.conn:
            await self.connect_db()
        cursor = self.conn.cursor()
        try:
            cursor.execute("INSERT INTO sensor_readings (timestamp, location, temperature, humidity, pressure) VALUES (?, ?, ?, ?, ?)", 
                            (reading["timestamp"], reading["location"], reading["temperature"], reading["humidity"], reading["pressure"]))
            await self.conn.commit()
        except pyodbc.Error as e:
            print(f"Error inserting reading: {e}")

    async def get_readings(self, start_timestamp, end_timestamp):
        query = f"SELECT * FROM sensor_readings WHERE timestamp >= ? AND timestamp <= ?"
        result = await self.query_db(query, (start_timestamp, end_timestamp))
        return result

    async def aggregate_readings(self, start_timestamp, end_timestamp):
        query = f"""
            SELECT 
                AVG(temperature) AS avg_temperature,
                AVG(humidity) AS avg_humidity,
                AVG(pressure) AS avg_pressure
            FROM sensor_readings
            WHERE timestamp >= ? AND timestamp <= ?
        """
        result = await self.query_db(query, (start_timestamp, end_timestamp))
        return result

    async def handle_reading(self, reading):
        if reading["timestamp"] > start_timestamp and reading["timestamp"] < end_timestamp:
            await self.insert_reading(reading)

    async def process_readings(self, start_timestamp, end_timestamp):
        readings = await self.get_readings(start_timestamp, end_timestamp)
        for reading in readings:
            await self.handle_reading(reading)

    def run(self):
        start_timestamp = 1643723400
        end_timestamp = 1643809800
        asyncio.run(self.process_readings(start_timestamp, end_timestamp))

if __name__ == "__main__":
    module = SensorReadingModule("DRIVER={ODBC Driver 17 for SQL Server};SERVER=server_name;DATABASE=database_name;UID=user_id;PWD=password")
    module.run()
