    char label;
    struct node *next;
    node_list *list;
} node;

typedef struct node_list {
    node *head;
    node *tail;
    node_list *prev;
    node_list *next;
} node_list;

node_list* init_node_list(int num_nodes) {
    // Initialize the list
    node_list *n = (node_list*)malloc(sizeof(node_list));
    n->head = NULL;
    n->tail = NULL;
    n->prev = NULL;
    n->next = NULL;

    return n;
}

void free_node_list(node_list* l) {
    // Free the list
    node *cur = l->head;
    while (cur != NULL) {
        node *next = cur->next;
        free(cur);
        cur = next;
    }
    free(l);
}

node_list* insert_singly(node_list* l, int idx, char label, element* el) {
    // Insert a new node at the end of the list
    node *new_node = (node*)malloc(sizeof(node));
    new_node->el = el;
    new_node->idx = idx;
    new_node->label = label;
    new_node->next = NULL;

    if (l->tail == NULL) {
        l->head = new_node;
        l->tail = new_node;
    } else {
        l->tail->next = new_node;
        l->tail = new_node;
    }

    return l;
}

node_list* insert_doubly(node_list* l, int idx, char label, element* el) {
    // Insert a new node at the end of the list
    node *new_node = (node*)malloc(sizeof(node));
    new_node->el = el;
    new_node->idx = idx;
    new_node->label = label;
    new_node->next = NULL;

    if (l->tail == NULL) {
        l->head = new_node;
        l->tail = new_node;
    } else {
        node *cur = l->tail;
        cur->next = new_node;
        new_node->prev = cur;
        l->tail = new_node;
    }

    return l;
}

node_list* delete_singly(node_list* l, int idx) {
    // Delete a node from the list
    if (l->head == NULL) {
        return l;
    }

    node *cur = l->head;
    while (cur != NULL && cur->idx != idx) {
        cur = cur->next;
    }

    if (cur == NULL) {
        return l;
    }

    if (l->tail == cur) {
        l->tail = cur->prev;
    } else {
        cur->prev->next = cur->next;
    }

    free(cur);

    return l;
}

node_list* delete_doubly(node_list* l, int idx) {
    // Delete a node from the list
    if (l->head == NULL) {
        return l;
    }

    node *cur = l->head;
    while (cur != NULL && cur->idx != idx) {
        cur = cur->next;
    }

    if (cur == NULL) {
        return l;
    }

    if (l->tail == cur) {
        l->tail = cur->prev;
        l->tail->next = NULL;
    } else {
        cur->prev->next = cur->next;
        if (cur->next != NULL) {
            cur->next->prev = cur->prev;
        }
    }

    free(cur);

    return l;
}

node_list* traverse_singly(node_list* l) {
    // Traverse the list
    node *cur = l->head;
    while (cur != NULL) {
        printf("Node index: %d, label: %c\n", cur->idx, cur->label);
        cur = cur->next;
    }

    return l;
}

node_list* traverse_doubly(node_list* l) {
    // Traverse the list
    node *cur = l->head;
    while (cur != NULL) {
        printf("Node index: %d, label: %c\n", cur->idx, cur->label);
        cur = cur->next;
    }

    return l;
}

