#include <pthread.h>

typedef enum {
    LOG_ERROR,
    LOG_WARNING,
    LOG_INFO,
    LOG_DEBUG
} log_level;

typedef enum {
    LOG_CONSOLE,
    LOG_FILE,
    LOG_NETWORK
} log_output;

struct log_settings {
    log_level level;
    log_output output;
};

struct log_event {
    char *message;
    log_level priority;
};

void* log_thread(void* arg) {
    struct log_settings *settings = (struct log_settings*)arg;
    while(1) {
        pthread_mutex_lock(&mutex);
        // dequeue event from queue
        pthread_mutex_unlock(&mutex);
        if(settings->output == LOG_CONSOLE)
            printf("%s\n", event.message);
        else if(settings->output == LOG_FILE) {
            FILE *fp = fopen("log.txt", "a");
            fprintf(fp, "%s\n", event.message);
            fclose(fp);
        }
        else if(settings->output == LOG_NETWORK) {
            // send to network
        }
    }
}

void log_event(struct log_settings settings, char *event_message, int priority) {
    struct log_event event;
    event.message = event_message;
    event.priority = (log_level)priority;

    pthread_mutex_lock(&mutex);
    if(settings.level <= event.priority && settings.output != LOG_DISABLED) {
        // enqueue event to queue
        pthread_mutex_unlock(&mutex);

        // create a new thread for logging this event
        pthread_t thread;
        pthread_create(&thread, NULL, log_thread, &settings);
    }
    else {
        pthread_mutex_unlock(&mutex);
    }
}

void log_reconfigure(log_level new_level, log_output new_output) {
    pthread_mutex_lock(&mutex);
    settings.level = new_level;
    settings.output = new_output;
    pthread_mutex_unlock(&mutex);
}
