        keys[i] = rand() % 1000;
        records[i].value = rand() % 100;
        strcpy(records[i].stringField, generateRandomString(10));
        metadataRecords[i].timestamp = time(NULL);
        metadataRecords[i].isValid = (rand() % 2 == 1);
        metadataRecords[i].metadataType = (rand() % 5) + 1;

