        // Dynamically allocate memory for each array
        if(i >= numPDUs / 2) {
            numPDUs *= 2;
            offsetValues = (long*)realloc(offsetValues, numPDUs * sizeof(long));
            keys = (int*)realloc(keys, numPDUs * sizeof(int));
            records = (struct record*)realloc(records, numPDUs * sizeof(struct record));
            metadataRecords = (metadata*)realloc(metadataRecords, numPDUs * sizeof(metadata));
            extendedRecords = (extendedRecord*)realloc(extendedRecords, numPDUs * sizeof(extendedRecord));
            macAddresses = (uniqueMACAddress*)realloc(macAddresses, numPDUs * sizeof(uniqueMACAddress));
            networkConfigs = (networkConfig*)realloc(networkConfigs, numPDUs * sizeof(networkConfig));
