    NFAPI_CRC_INDICATION_PDU_T pdu;
    pdu.RNTI = keys[0];
    strcpy(pdu.RX_UE_INFORMATION_TAG, records[0].stringField);
    pdu.CRCFLAG = metadataRecords[0].CRCFLAG;

    return &pdu;
}

