void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
        exit(1);
    }
    return ptr;
}

int main() {
    // Initialize the random number generator
    srand(time(NULL));

    // Function to dynamically allocate and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
    void** create_crc_list(int n) {
        // Create an empty list with space for n elements
        void** list = safe_malloc(n * sizeof(void*));

        // Initialize the list size to 0
        int list_size = 0;

        // Function to safely allocate and populate each structure in the list
        void* create_crc_pdu() {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

            if (!pdu) {
                printf("Memory allocation failed\n");
                exit(1);
            }

            // Initialize each structure's members
            pdu->RX_UE_INFORMATION_TAG = rand() % 100;
            pdu->RNTI = (unsigned long)rand();
            for (int i = 0; i < 16; i++) {
                pdu->CRC_INDICATION_REL8_TAG[i] = (char)(rand() % 256);
            }
            pdu->CRCFLAG = rand() % 256;
            pdu->timestamp = time(NULL);
            pdu->id = ++list_size;

            return pdu;
        }

        // Populate the list with n structures
        for (int i = 0; i < n; i++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = create_crc_pdu();
            if (!pdu) break;
            list[i] = pdu;
            list_size++;
        }

        return list;
