class NetworkInterfaceConfigurator {
public:
    void configure(const std::vector<std::string>& configData);

private:
    void processConfig(const std::string& config);
    void validateConfig(const NFAPI_CONTROL_PDU_T& config) const;
};

void NetworkInterfaceConfigurator::configure(const std::vector<std::string>& configData) {
    for (const auto& config : configData) {
        if (config.empty()) continue; // ignore empty strings
        processConfig(config);
    }
}

void NetworkInterfaceConfigurator::processConfig(const std::string& config) {
    NFAPI_CONTROL_PDU_T pdu;
    std::stringstream ss(config);
    ss >> pdu.macAddress >> pdu.ipAddress >> pdu.subnetMask >> pdu.vlanId;

    validateConfig(pdu);

    // apply configuration
}

void NetworkInterfaceConfigurator::validateConfig(const NFAPI_CONTROL_PDU_T& config) const {
    if (config.macAddress > 0xAAAA || config.ipAddress > 0xFFFFFFFFLL || config.subnetMask > 0xFFFFFFFFLL)
        throw std::runtime_error("Invalid network configuration");
}

int main() {
    NetworkInterfaceConfigurator configurator;

    // test configurations
    configurator.configure({"00:11:22:33:44:55", "192.168.1.100", "255.255.255.0", "10"});
    configurator.configure({""});

    return 0;
}

