        do {
            rnti = static_cast<unsigned short>(gen() % USHRT_MAX);
        } while (!isValidRnti(rnti));

        if (uniqueRntiCount >= std::pow(USHRT_MAX, 2)) {
            // log warning
            std::cout << "Warning: Ran out of unique RNTI values." << std::endl;
            break; // no more structures to generate
        }

        unsigned int rxUeInformationTag = static_cast<unsigned int>(gen() % USIZE_MAX);
        bool crcFlag = crcFlagDist(gen);

        NFAPI_CRC_INDICATION_PDU_T structure {rxUeInformationTag, rnti, crcFlag, tagDist(gen)};

        structures_.push_back(structure);

        ++uniqueRntiCount;

        --numStructures;
    }
}

#include <gtest/gtest.h>

TEST(NfareceiverTest, TestGenerateStructures) {
    Nfareceiver receiver(1, 255);
    receiver.generateStructures(10);

    // assert the structures contain unique RNTI and RX_UE_INFORMATION_TAG
    for (size_t i = 0; i < receiver.structures_.size(); ++i) {
        for (size_t j = i + 1; j < receiver.structures_.size(); ++j) {
            EXPECT_NE(receiver.structures_[i].rxUeInformationTag, receiver.structures_[j].rxUeInformationTag);
            EXPECT_NE(receiver.structures_[i].rnti, receiver.structures_[j].rnti);
        }
    }

    // assert the CRC flag is within the range
    for (const auto& structure : receiver.structures_) {
        EXPECT_TRUE((structure.crcFlagDist.first <= structure.crcFlag) && (structure.crcFlag <= structure.crcFlagDist.second));
    }

    // assert the structures contain valid CRC_INDICATION_REL8_TAG
    // assume this test checks the validity of CRC_INDICATION_REL8_TAG
}

int main(int argc, char **argv) {
    ::testing::InitGoogle(&argc, argv);
    ::testing::TestRegistry& registry = ::testing::GetTestRegistry();
    ::testing::TestEventListeners& listeners = registry.listeners();

    return RUN_ALL_TESTS();
}
