#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure to represent a log entry
typedef struct {
    int id;
    long timestamp;
    int severityLevel;
    char* metadata;
} LogEntry;

// Define the maximum number of concurrent log messages
#define MAX_LOG_MESSAGES 500

// Define the maximum number of logging levels
#define MAX_LOGGING_LEVELS 10

// Define a structure to represent the logging system
typedef struct {
    pthread_mutex_t lock; // Mutex for synchronization
    int currentLoggingLevels[MAX_LOGGING_LEVELS];
    LogEntry* logEntries;
    size_t logEntriesSize;
} LoggingSystem;

// Function to initialize the logging system
void initLoggingSystem(LoggingSystem* loggingSystem) {
    // Initialize mutex
    pthread_mutex_init(&loggingSystem->lock, NULL);

    // Initialize current logging levels
    for (int i = 0; i < MAX_LOGGING_LEVELS; i++) {
        loggingSystem->currentLoggingLevels[i] = 1;
    }

    // Initialize log entries array with null values
    loggingSystem->logEntries = (LogEntry*)malloc(MAX_LOG_MESSAGES * sizeof(LogEntry));
    loggingSystem->logEntriesSize = 0;
}

// Function to add a log entry
void addLogEntry(LoggingSystem* loggingSystem, int id, long timestamp, int severityLevel, char* metadata) {
    // Acquire the mutex
    pthread_mutex_lock(&loggingSystem->lock);

    // Check if the system has reached its capacity
    if (loggingSystem->logEntriesSize >= MAX_LOG_MESSAGES) {
        printf("Error: System is at maximum capacity. Log entry not added.\n");
        pthread_mutex_unlock(&loggingSystem->lock);
        return;
    }

    // Create a new log entry and add it to the array
    LogEntry* newLogEntry = (LogEntry*)malloc(sizeof(LogEntry));
    newLogEntry->id = id;
    newLogEntry->timestamp = timestamp;
    newLogEntry->severityLevel = severityLevel;
    newLogEntry->metadata = metadata;

    loggingSystem->logEntries[loggingSystem->logEntriesSize++] = *newLogEntry;

    // Release the mutex
    pthread_mutex_unlock(&loggingSystem->lock);
}

// Function to update the current logging levels
void updateLoggingLevels(LoggingSystem* loggingSystem, int newLevel) {
    // Acquire the mutex
    pthread_mutex_lock(&loggingSystem->lock);

    // Update the current logging level
    for (int i = 0; i < MAX_LOGGING_LEVELS; i++) {
        if (newLevel <= loggingSystem->currentLoggingLevels[i]) {
            loggingSystem->currentLoggingLevels[i] = newLevel;
            break;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&loggingSystem->lock);
}

// Function to free allocated resources when a log entry is no longer in use
void freeLogEntry(LogEntry* logEntry) {
    if (logEntry == NULL) return;
    free(logEntry);
}

int main() {
    LoggingSystem loggingSystem;
    initLoggingSystem(&loggingSystem);

    // Add some log entries
    addLogEntry(&loggingSystem, 1, time(NULL), 2, "Metadata for log entry 1");
    addLogEntry(&loggingSystem, 2, time(NULL), 3, "Metadata for log entry 2");

    // Update the current logging levels
    updateLoggingLevels(&loggingSystem, 5);

    // Free allocated resources when a log entry is no longer in use
    freeLogEntry((LogEntry*)malloc(sizeof(LogEntry)));

    return 0;
}
