#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "openssl/err.h"
#include "openssl/des.h"

EVP_CIPHER_CTX* des_ciphers(int key_size, int mode, int num_passes) {
    // Create EVP_CIPHER_CTX structure for the chosen cipher
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    if (!ctx) {
        ERR_error_fp(stderr);
        return NULL;
    }

    // Initialize the EVP_CIPHER_CTX structure
    EVP_CIPHER_CTX_set_key_length(ctx, key_size / 8);

    switch (mode) {
        case EVP_ENCRYPTION:
            // Set the cipher mode to ECB
            EVP_CIPHER_CTX_set_cipher(ctx, EVP_des_ecb());
            break;
        case EVP_DES_EDE:
            // Set the cipher mode to EDE
            EVP_CIPHER_CTX_set_cipher(ctx, EVP_des_ede());
            break;
        case EVP_DES_EDE3:
            // Set the cipher mode to EDE3
            EVP_CIPHER_CTX_set_cipher(ctx, EVP_des_ede3());
            break;
        case EVP_CFB:
            // Set the cipher mode to CFB
            EVP_CIPHER_CTX_set_cipher(ctx, EVP_des_cfb());
            break;
    }

    if (num_passes > 0) {
        // Initialize the EVP_CIPHER_CTX structure for multi-pass encryption
        EVP_CIPHER_CTX_set_num_passes(ctx, num_passes);
    }

    return ctx;
}
