#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <getopt.h>

#define CONFIG_FILE "config.ini"
#define DEFAULT_DEBUG_MODE false
#define DEFAULT_OUTPUT_DIRECTORY "output"

typedef struct {
    char* key;
    int type; // 0: integer, 1: string, 2: boolean
    union {
        int i;
        char* s;
        bool b;
    } value;
} Setting;

void parse_config_file(FILE* file, Setting** settings) {
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        size_t pos = strlen(line) - 1;
        while (pos > 0 && line[pos-1] == '\n') pos--;
        line[pos] = '\0';
        Setting* setting = (Setting*)malloc(sizeof(Setting));
        char* token = strtok(line, "=");
        if (!token || strlen(token) < 2 || token[0] != '[') {
            free(setting);
            continue;
        }
        setting->key = strdup(token+1);
        token = strtok(NULL, ",");
        if (!token) {
            free(setting);
            continue;
        }
        int type;
        if (strcmp(token, "integer") == 0)
            type = 0;
        else if (strcmp(token, "string") == 0)
            type = 1;
        else if (strcmp(token, "boolean") == 0)
            type = 2;
        else {
            free(setting);
            continue;
        }
        token = strtok(NULL, ",");
        switch (type) {
        case 0:
            setting->value.i = atoi(token);
            break;
        case 1:
            setting->value.s = strdup(token);
            break;
        case 2:
            if (!strcmp(token, "true"))
                setting->value.b = true;
            else if (!strcmp(token, "false"))
                setting->value.b = false;
            else {
                free(setting);
                continue;
            }
            break;
        default:
            free(setting);
            continue;
        }
        *settings = realloc(*settings, (++(*settings) ? sizeof(Setting*) : 0));
        (*settings)->next = setting;
    }
}

void parse_command_line(int argc, char** argv, Setting** settings) {
    int c;
    while ((c = getopt(argc, argv, "hc:d:o:")) != -1) {
        switch (c) {
        case 'h':
            printf("Usage: %s [-h] [-c config_file] [-d debug_mode] [-o output_directory]\n", argv[0]);
            exit(0);
        case 'c':
            *settings = realloc(*settings, sizeof(Setting*));
            (*settings)->key = strdup(optarg);
            break;
        case 'd':
            if (!strcmp(optarg, "true"))
                DEFAULT_DEBUG_MODE = true;
            else if (!strcmp(optarg, "false"))
                DEFAULT_DEBUG_MODE = false;
            else {
                printf("Invalid debug mode: %s\n", optarg);
                exit(1);
            }
            break;
        case 'o':
            *settings = realloc(*settings, sizeof(Setting*));
            (*settings)->key = strdup(optarg);
            break;
        default:
            abort();
        }
    }
}

void validate_settings(Setting** settings) {
    Setting* setting = *settings;
    while (setting) {
        if (!setting->key || strlen(setting->key) < 2 || setting->key[0] != '[') {
            printf("Invalid setting key: %s\n", setting->key);
            exit(1);
        }
        switch (setting->type) {
        case 0:
            if (setting->value.i < INT_MIN || setting->value.i > INT_MAX) {
                printf("Integer value out of range: %d\n", setting->value.i);
                exit(1);
            }
            break;
        case 1:
            if (!setting->value.s) {
                printf("String value not set: %s\n", setting->key);
                exit(1);
            }
            break;
        case 2:
            if (setting->value.b == false && !strcmp(setting->key, "debug_mode")) {
                printf("Invalid boolean value for debug mode: %s\n", setting->key);
                exit(1);
            }
            break;
        default:
            printf("Unknown setting type: %s\n", setting->key);
            exit(1);
        }
        setting = setting->next;
    }
}

int main(int argc, char** argv) {
    Setting* settings = NULL;
    FILE* file = fopen(CONFIG_FILE, "r");
    if (!file) {
        printf("Cannot open config file: %s\n", CONFIG_FILE);
        exit(1);
    }
    parse_config_file(file, &settings);
    fclose(file);

    parse_command_line(argc, argv, &settings);

    validate_settings(&settings);

    // Apply settings to the application
    // ...
}
