public class MD5Hasher {

    private final int MAX_KEY_SIZE = 112; // in bits
    private final List<String> hashes = new ArrayList<>();

    public List<String> processBatch(List<String> strings, boolean logEnabled) {
        for (String s : strings) {
            if (s == null || s.isEmpty()) {
                continue;
            }

            try {
                MessageDigest md = MessageDigest.getInstance("MD5");

                // Validate the integrity of each input data stream
                byte[] inputBytes = s.getBytes();
                validateInput(inputBytes);

                // Perform hashing operation
                byte[] hashBytes = md.digest(inputBytes);
                StringBuilder sb = new StringBuilder();
                for (byte b : hashBytes) {
                    String hex = Integer.toHexString(b & 0xFF);
                    if (hex.length() < 2) {
                        sb.append('0');
                    }
                    sb.append(hex);
                }

                // Log the hashing operation
                if (logEnabled) {
                    System.out.println("Hashed string: " + s);
                    System.out.println("MD5 Hash: " + sb.toString());
                }

                hashes.add(sb.toString());

            } catch (Exception e) {
                // Handle memory allocation failure gracefully
                System.err.println("Error hashing input: " + e.getMessage());
            }
        }

        return hashes;
    }

    private void validateInput(byte[] inputBytes) {
        // TO DO: implement integrity validation logic here
    }

