        List<String> strings = ...; // your list of strings

        boolean logEnabled = true;
        List<String> hashes = md5.processBatch(strings, logEnabled);

        // Print the resulting hash values
        for (String s : hashes) {
            System.out.println(s);
        }
    }
}
