            // Configure IPv6
            control_pdu[i].ip_addr.ipv6 = generate_ipv6_address();
            control_pdu[i].subnet_mask.ipv6 = generate_subnet_mask();
        }

        if (is_dhcp_used()) {
            int dhcp_status = send_dhcp_request(control_pdu[i]);
            if (dhcp_status == DHCP_SUCCESS) {
                // DHCP succeeded, use assigned IP address
                control_pdu[i].ip_addr = get_assigned_ip_address();
            } else {
                // DHCP failed, fall back to static configuration
                control_pdu[i].ip_addr = generate_static_ip_address();
            }
        }

        validate_network_settings(&control_pdu[i]);
    }

    apply_network_settings(control_pdu, num_interfaces);

    free(control_pdu);
}

