typedef struct {
    int key;
    long offset;
    char *ptr;
} record;

void configureNetworkInterfacesAndManageMemory(int num_records) {
    // Initialize arrays
    record *records = (record *)malloc(num_records * sizeof(record));
    int *keys = (int *)calloc(num_records, sizeof(int));
    long *offsets = (long *)calloc(num_records, sizeof(long));

    if (!records || !keys || !offsets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize records
    srand(time(NULL));
    for (int i = 0; i < num_records; i++) {
        keys[i] = rand() % 100;
        offsets[i] = rand();
        records[i].key = keys[i];
        records[i].offset = offsets[i];
        records[i].ptr = "";
    }

    // Free allocated memory
    free(records);
    free(keys);
    free(offsets);

    // Parse XML document using XPath
    char *xml_document = "<root><item name='test'>hello</item></root>";
    xmlDocPtr doc = xmlReadDoc(BAD_CAST xml_document, NULL, NULL, 0);
    if (!doc) {
        xmlFreeDoc(doc);
        throw std::runtime_error("Failed to parse XML");
    }

    // Find the first element matching a given name
    xmlNode *element = xmlFirstElementChild(xmlDocGetRootElement(doc));
    if (element == NULL || xmlStrcmp(element->name, BAD_CAST "test")) {
        xmlFreeDoc(doc);
        throw std::runtime_error("Failed to find the desired element");
    }

    // Return the parsed XML element
    return xmlDocCopyNode(element, doc, 0);
}
