json_object_t* retrieve_json(const char* url) {
    if (time(NULL) - last_update < CACHE_TTL) {
        for (int i = 0; i < JSON_OBJECT_MAX_SIZE; i++) {
            if (!cache[i].type) {
                return &cache[i];
            }
        }
    }

    // Make API request here...

