    strcpy(result->values[0].value, "your-value");
    result->count = 1;

    // Store in cache
    for (int i = 0; i < JSON_OBJECT_MAX_SIZE; i++) {
        if (!cache[i].type) {
            memcpy(&cache[i], result, sizeof(json_object_t));
            last_update = time(NULL);
            return &cache[i];
        }
    }

    free(result);
    return NULL;
