#include <unordered_map>

class TaskProcessor {
public:
    enum class Mode { SCALE, SHIFT, FILTER };

    void process(int data, Mode mode) {
        // Transformation logic
        if (mode == Mode::SCALE)
            std::cout << "Scaled: " << data << std::endl;
        else if (mode == Mode::SHIFT)
            std::cout << "Shifted: " << data << std::endl;
        else if (mode == Mode::FILTER)
            std::cout << "Filtered: " << data << std::endl;
    }
};

class Session {
public:
    std::vector<TaskProcessor> processors;

    void addProcessor(TaskProcessor processor) {
        processors.push_back(processor);
    }

    void processTask(int data, TaskProcessor::Mode mode) {
        for (auto& processor : processors)
            processor.process(data, mode);
    }
};

class DataPipeline {
public:
    std::unordered_map<int, Session> sessions;

    void addSession(int sessionID) {
        sessions[sessionID] = Session();
    }

    void processTask(int data, int sessionID, TaskProcessor::Mode mode) {
        if (sessions.find(sessionID) != sessions.end()) {
            auto& session = sessions[sessionID];
            session.processTask(data, mode);
        }
    }

    void switchSession(int oldSessionID, int newSessionID) {
        if (oldSessionID >= 0 && newSessionID >= 0) {
            if (sessions.find(oldSessionID) != sessions.end()) {
                for (auto& processor : sessions[oldSessionID].processors)
                    sessions[newSessionID].addProcessor(processor);
                sessions.erase(oldSessionID);
            }
        }
    }

    void registerCustomAlgorithm(int sessionID, const std::string& algorithmName,
                                   const std::function<void(int, TaskProcessor::Mode)>& callback) {
        if (sessions.find(sessionID) != sessions.end()) {
            auto& session = sessions[sessionID];
            session.processors.push_back(TaskProcessor());
            for (auto& processor : session.processors)
                processor.callback = callback;
        }
    }

    void startProcessing(int sessionID, int dataCount) {
        std::thread processThread([&](int sessionID, int dataCount) {
            for (int i = 0; i < dataCount; ++i) {
                // Simulate processing time
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
                auto data = i;
                processTask(data, sessionID, TaskProcessor::Mode::SCALE);
            }
        }, sessionID, dataCount);
    }

    void stopProcessing(int sessionID) {
        // Stop the processing thread
    }
};

int main() {
    DataPipeline pipeline;

    pipeline.addSession(0);
    pipeline.addSession(1);

    pipeline.startProcessing(0, 1000000);

    return 0;
}

