void configure_network(NFAPI_CONTROL_PDU_T* config, int num_interfaces) {
    for (int i = 0; i < num_interfaces; i++) {
        // Initialize MAC address
        memcpy(config[i].mac, "unique_mac_address", 17);

        // Initialize IP address and subnet mask
        strcpy(config[i].ip, "10.10.10.");
