int create_session(int user_id) {
    pthread_mutex_lock(&session_lock);

    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (!session_pool[i].user_id) {
            session_pool[i].user_id = user_id;
            session_pool[i].auth_token = (char *)calloc(256, sizeof(char));
            session_pool[i].expiration_time = time(NULL) + 3600; // set expiration time to 1 hour
            max_session_id = user_id;
            return i;
        }
    }

    pthread_mutex_unlock(&session_lock);
    return -1;
}

void validate_session(int session_id) {
