    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (session_pool[i].user_id == session_id) {
            // validation logic here
            pthread_mutex_unlock(&session_lock);
            return;
        }
    }

    pthread_mutex_unlock(&session_lock);
}

void destroy_session(int session_id) {
    pthread_mutex_lock(&session_lock);

    for (int i = 0; i < SESSION_POOL_SIZE; i++) {
        if (session_pool[i].user_id == session_id) {
            free(session_pool[i].auth_token);
            session_pool[i] = (SESSION_T *)malloc(sizeof(SESSION_T));
            session_pool[i]->user_id = 0;
            pthread_mutex_unlock(&session_lock);
            return;
        }
    }

