vector<vector<string>> configureNetworkInterfaces(vector<string> batch) {
    // Initialize the configuration
    unordered_map<string, NFAPIControlPDU> configMap;

    for (const auto& batchItem : batch) {
        // Parse the network interface settings
        size_t delimiterPos = batchItem.find(":");
        if (delimiterPos == string::npos) continue;
        string key = batchItem.substr(0, delimiterPos);
        string value = batchItem.substr(delimiterPos + 1);

        // Configure the network interface based on the key-value pair
        NFAPIControlPDU pdu;
        if (key == "mac") {
            pdu.macAddress = value;
        } else if (key == "ip") {
            pdu.ipAddress = value;
        } else if (key == "mask") {
            pdu.subnetMask = value;
        } else if (key == "vlan") {
            pdu.vlanIds.push_back(value);
        }
        configMap[key] = pdu;
    }

    // Initialize the result vector
    vector<vector<string>> results;

    // Iterate over the configuration map and apply the settings to each network interface
    for (const auto& kv : configMap) {
        NFAPIControlPDU pdu = kv.second;
        vector<string> result;
        result.push_back(pdu.macAddress);
        result.push_back(pdu.ipAddress);
        result.push_back(pdu.subnetMask);
        for (const auto& vlanId : pdu.vlanIds) {
            result.push_back(vlanId);
        }
        results.push_back(result);
    }

    return results;
}

