#include <iostream>
#include <thread>
#include <vector>
#include <queue>
#include <functional>
#include <mutex>
#include <condition_variable>
#include <atomic>

class TaskProcessor {
public:
    virtual void process(const std::any& data) = 0;
    virtual ~TaskProcessor() {}
};

class DataTransformer : public TaskProcessor {
private:
    std::function<void(int)> scaleFunction;
    std::function<void(double)> filterFunction;

public:
    DataTransformer(std::function<void(int)> scale, std::function<void(double)> filter)
        : scaleFunction(scale), filterFunction(filter) {}

    void process(const std::any& data) override {
        if (data.type() == typeid(int)) {
            int value = std::any_cast<int>(data);
            scaleFunction(value);
        } else if (data.type() == typeid(double)) {
            double value = std::any_cast<double>(data);
            filterFunction(value);
        }
    }
};

class ValidationProcessor : public TaskProcessor {
private:
    std::function<bool(const int&)> validationFunction;

public:
    ValidationProcessor(std::function<bool(const int&)> validate)
        : validationFunction(validate) {}

    void process(const std::any& data) override {
        if (data.type() == typeid(int)) {
            int value = std::any_cast<int>(data);
            if (!validationFunction(value)) {
                // Handle invalid data
            }
        }
    }
};

class PipelineManager {
private:
    std::queue<TaskProcessor*> taskQueue;
    std::mutex queueMutex;
    std::condition_variable queueCondition;

public:
    void addTask(TaskProcessor* task) {
        std::unique_lock<std::mutex> lock(queueMutex);
        taskQueue.push(task);
        lock.unlock();
        queueCondition.notify_one();
    }

    void startProcessing() {
        while (true) {
            TaskProcessor* task;
            {
                std::unique_lock<std::mutex> lock(queueMutex);
                if (!taskQueue.empty()) {
                    task = taskQueue.front();
                    taskQueue.pop();
                } else {
                    queueCondition.wait(lock, [this] { return !taskQueue.empty(); });
                    continue;
                }
            }

            if (task) {
                try {
                    task->process(std::any()); // Process the task
                } catch (...) {
                    // Handle exceptions
                }
                delete task; // Release memory
            }
        }
    }
};

class DataPipe {
public:
    static PipelineManager& getInstance() {
        static PipelineManager instance;
        return instance;
    }

    void addTask(TaskProcessor* task) {
        getInstance().addTask(task);
    }

    void startProcessing() {
        getInstance().startProcessing();
    }
};

int main() {
    // Example usage
    DataPipe::getInstance().addTask(new DataTransformer([](int value) { return value * 2; }, [](double value) { return value > 5.0; }));
    DataPipe::getInstance().addTask(new ValidationProcessor([](const int& value) { return value > 10; }));

    DataPipe::getInstance().startProcessing();

    return 0;
}
