#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

std::vector<std::string> processBatch(const std::vector<std::string>& batch) {
    std::vector<std::string> result;
    for (const auto& str : batch) {
        if (!str.empty()) {
            // Generate MD5 hash
            const auto hash = generateMD5Hash(str);
            result.push_back(hash);
        }
    }
    return result;
}

std::string generateMD5Hash(const std::string& input) {
    // Initialize EVP context for MD5 hashing
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();

    // Set desired hash mode (ECB, EDE, EDE3, CFB)
    int mode = EVP_MODE_CBC;
    // Dynamic key size selection (56-bit to 112-bit keys)
    unsigned char* key = (unsigned char*)malloc(16);
    for (int i = 0; i < 16; i++) {
        key[i] = (unsigned char)i;
    }

    // Initialize EVP cipher context with chosen mode and key
    if (!EVP_CipherInit_ex(ctx, EVP_get_cipherbyname("md5"), NULL, key, 16, 1)) {
        std::cerr << "Error initializing MD5 hash." << std::endl;
        exit(1);
    }

    // Calculate MD5 hash of input string
    unsigned char* output = (unsigned char*)malloc(32);
    int len = 0;
    if (!EVP_CipherUpdate(ctx, output, &len, (const unsigned char*)input.c_str(), input.length())) {
        std::cerr << "Error calculating MD5 hash." << std::endl;
        exit(1);
    }

    // Convert hash to hexadecimal string
    std::string hashStr = "";
    for (int i = 0; i < len; i++) {
        char buffer[3];
        sprintf(buffer, "%02x", output[i]);
        hashStr += buffer;
    }

    // Clean up resources
    EVP_CIPHER_CTX_free(ctx);
    free(key);
    free(output);

    return hashStr;
}

int main() {
    std::vector<std::string> batch = {"Hello", "World", "", "This", "is", "a", "test"};
    auto result = processBatch(batch);
    for (const auto& str : result) {
        std::cout << str << std::endl;
    }
    return 0;
}
