std::vector<std::string> hashStrings(const std::vector<std::string>& input) {
    std::vector<std::string> output;
    std::random_device rd;  // obtain a random number from hardware
    std::mt19937 eng(rd()); // seed the generator

    for (const auto& str : input) {
        if (str.empty()) continue; // handle null or empty strings

        // Choose a hash mode randomly
        int hashMode = eng() % 4;

        if (hashMode == 0) { // ECB
            std::string md5Hash = getECBMD5(str);
        } else if (hashMode == 1) { // EDE
            std::string md5Hash = getEDEMD5(str);
        } else if (hashMode == 2) { // EDE3
            std::string md5Hash = getEDE3MD5(str);
        } else { // CFB
            std::string md5Hash = getCFBMD5(str);
        }

        output.push_back(md5Hash);
    }

    return output;
}

