    std::vector<unsigned char> processBatch(const std::vector<std::string>& batch, int mode = 0) {
        std::vector<unsigned char> hashes;
        EVP_CIPHER_CTX* ctx = NULL;

        for (const auto& str : batch) {
            if (str.empty()) continue;

            // Determine the required key size based on the chosen hash mode
            int keySize = getRequiredKeySize(mode);

            // Initialize and set the context for the selected cipher
            ctx = EVP_CIPHER_CTX_new();
            EVP_CIPHER_CTX_set_cipher(ctx, EVP_get_cipherbyname("aes-256-cfb"));
            EVP_CIPHER_CTX_set_key_length(ctx, keySize);
            EVP_CIPHER_CTX_set_iv_length(ctx, 16);

            // Perform the hashing operation using the chosen cipher mode
            unsigned char* hash = (unsigned char*)malloc(32);
            int hashLen;
            EVP_CipherInit_ex(ctx, NULL, NULL, NULL, NULL, 1);
            EVP_CipherUpdate(ctx, hash, &hashLen);
            EVP_CipherFinal_ex(ctx, hash, &hashLen);

            // Append the computed hash to the result vector
            hashes.push_back(hash);

            EVP_CIPHER_CTX_free(ctx);
        }

        return hashes;
    }

    int getRequiredKeySize(int mode) {
        switch (mode) {
            case 0: // ECB
                return 128 / 8; // 16 bytes for key size
            case 1: // EDE
                return 112 / 8; // 14 bytes for key size
            case 2: // EDE3
                return 168 / 8; // 21 bytes for key size
            case 3: // CFB
                return 128 / 8; // 16 bytes for key size
        }
    }

