// Define the RECORD structure
typedef struct {
    long timestamp;
    float value;
    char status;
} RECORD_T;

// Define the hash table node structure
typedef struct {
    int key;
    RECORD_T* record;
    struct __node* next;
} HASH_NODE_T;

// Define the hash table structure
typedef struct {
    HASH_NODE_T** buckets;
    int size;
    int num_elements;
    pthread_mutex_t lock;
} HASH_TABLE_T;

// Function to initialize the hash table
void init_hash_table(HASH_TABLE_T* table, int size) {
    table->size = size;
    table->num_elements = 0;
    table->buckets = (HASH_NODE_T**)malloc(size * sizeof(HASH_NODE_T*));
    pthread_mutex_init(&table->lock, NULL);
}

// Function to insert a record into the hash table
void insert_record(HASH_TABLE_T* table, int key, RECORD_T* record) {
    int index = key % table->size;
    HASH_NODE_T* node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            // Update existing record
            node->record = record;
            return;
        }
        node = node->next;
    }
    // Insert new record
    node = (HASH_NODE_T*)malloc(sizeof(HASH_NODE_T));
    node->key = key;
    node->record = record;
    node->next = table->buckets[index];
    table->buckets[index] = node;
    table->num_elements++;
}

// Function to retrieve a record from the hash table
RECORD_T* get_record(HASH_TABLE_T* table, int key) {
    int index = key % table->size;
    HASH_NODE_T* node = table->buckets[index];
    while (node) {
        if (node->key == key) {
            return node->record;
        }
        node = node->next;
    }
    return NULL;
}

// Function to resize the hash table
void resize_hash_table(HASH_TABLE_T* table, int new_size) {
    HASH_NODE_T** new_buckets = (HASH_NODE_T**)malloc(new_size * sizeof(HASH_NODE_T*));
    for (int i = 0; i < new_size; i++) {
        new_buckets[i] = NULL;
    }
    for (int i = 0; i < table->size; i++) {
        HASH_NODE_T* node = table->buckets[i];
        while (node) {
            int index = node->key % new_size;
            node->next = new_buckets[index];
            new_buckets[index] = node;
            node = node->next;
        }
    }
    free(table->buckets);
    table->size = new_size;
    table->buckets = new_buckets;
}

