```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to generate a certificate in PEM format from private key and certificate files
char* generate_certificate(char* oauth_request) {
    // Parse the OAuth request to extract the private key and certificate file paths
    char* private_key_file = strstr(oauth_request, "private_key=") + 13;
    char* certificate_file = strstr(oauth_request, "certificate=") + 10;

    // Open the private key and certificate files
    FILE* private_key_fd = fopen(private_key_file, "r");
    FILE* certificate_fd = fopen(certificate_file, "r");

    // Read the private key and certificate contents
    char* private_key_contents = NULL;
    size_t private_key_size = 0;
    while (fread(&private_key_contents[private_key_size], 1, 1024, private_key_fd) == 1024) {
        private_key_size += 1024;
    }
    fclose(private_key_fd);

    char* certificate_contents = NULL;
    size_t certificate_size = 0;
    while (fread(&certificate_contents[certificate_size], 1, 1024, certificate_fd) == 1024) {
        certificate_size += 1024;
    }
    fclose(certificate_fd);

    // Combine the private key and certificate contents into a single PEM file
    char* pem_file = malloc(private_key_size + certificate_size + 2);
    strcpy(pem_file, "-----BEGIN CERTIFICATE-----\n");
    strcat(pem_file, certificate_contents);
    strcat(pem_file, "\n-----END CERTIFICATE-----\n");

    free(private_key_contents);
    free(certificate_contents);

    return pem_file;
}
