        memcpy((char*) (packet_array + i * sizeof(struct NICP_PACKET)) + sizeof(MAC_HEADER), &payload, sizeof(MAC_PAYLOAD));
        memcpy((char*) (packet_array + i * sizeof(struct NICP_PACKET)) + sizeof(MAC_HEADER) + sizeof(MAC_PAYLOAD), &crc_result, sizeof(CRC_CHECK_RESULT));
    }

    for (int i = 0; i < packet_count; i++) {
        verify_nicp_packet(packet_array + i * sizeof(struct NICP_PACKET), i);
    }

    free(packet_array);

    return 0;
}

