// Hash table structure
typedef struct {
    uint64_t key;
    void *value;
} HashEntry;

typedef struct {
    int size;
    HashEntry **table;
} HashTable;

HashTable *hash_table_create(int size) {
    HashTable *table = (HashTable *)malloc(sizeof(HashTable));
    if (!table) return NULL;
    table->size = size;
    table->table = (HashEntry **)calloc(size, sizeof(HashEntry *));
    if (!table->table) {
        free(table);
        return NULL;
    }
    return table;
}

void hash_table_insert(HashTable *table, uint64_t key, void *value) {
    int index = key % table->size;
    HashEntry *entry = (HashEntry *)malloc(sizeof(HashEntry));
    if (!entry) return; // Handle memory allocation failure
    entry->key = key;
    entry->value = value;
    table->table[index] = entry;
}

