#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structures for memory management
typedef struct {
    void* ptr;
    size_t size;
} MemBlock;

typedef struct {
    MemBlock* pool;
    int capacity;
    pthread_mutex_t mutex;
} MemPool;

// Initialize memory pool
void mem_init(MemPool* pool, int capacity) {
    pool->pool = (MemBlock*)malloc(capacity * sizeof(MemBlock));
    pool->capacity = capacity;
    pthread_mutex_init(&pool->mutex, NULL);
}

// Allocate memory from the pool
void* mem_alloc(MemPool* pool, size_t size) {
    MemBlock* block;
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->pool[i].ptr == NULL && pool->pool[i].size >= size) {
            pool->pool[i].ptr = malloc(size);
            pool->pool[i].size = size;
            pthread_mutex_unlock(&pool->mutex);
            return pool->pool[i].ptr;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    return NULL; // Out of memory
}

// Deallocate memory from the pool
void mem_free(MemPool* pool, void* ptr) {
    MemBlock* block = NULL;
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->capacity; i++) {
        if (pool->pool[i].ptr == ptr) {
            free(ptr);
            pool->pool[i].ptr = NULL;
            block = &pool->pool[i];
            break;
        }
    }
    pthread_mutex_unlock(&pool->mutex);
    if (block != NULL) {
        block->size = 0; // Mark as free
    }
}

