    pub static ref REQUEST_SUCCESS_RATE: GaugeVec = gauge_vec!("request_success_rate", &["name"]);
    pub static ref REQUEST_FAILURE_RATE: GaugeVec = gauge_vec!("request_failure_rate", &["name"]);
    pub static ref AVERAGE_RESPONSE_TIME: Histogram = histogram!("average_response_time");
}

// Define the HTTP client with configurable options
pub async fn create_http_client(
    max_connections_per_host: u16,
    timeout_request_initiation: Duration,
    timeout_response_reception: Duration,
    custom_headers: Vec<(&str, &str)>,
    ca_bundle_path: Option<&str>,
) -> Arc<Client<TlsConnection>> {
    let tls_connector = HttpsConnector::new_full(ca_bundle_path).unwrap();
    let client = Client::builder()
        .timeout_request_initiation(timeout_request_initiation)
        .timeout_response_reception(timeout_response_reception)
        .default_header("User-Agent", "Your-Custom-User-Agent")
        .build_tls(tls_connector);

    // Initialize the connection pool with a maximum of max_connections_per_host
    let mut connections = Vec::with_capacity(max_connections_per_host as usize);
    for _ in 0..max_connections_per_host {
        connections.push(client.get().await.unwrap());
    }

    Arc::new(Client { client, connections })
}

// Implement request retry mechanism with exponential backoff
async fn retry_request(
    client: &Arc<Client<TlsConnection>>,
    url: &str,
    method: &str,
    body: Body,
    max_retries: u16,
) -> Result<(hyper::Response, hyper::Body), Box<dyn std::error::Error>> {
    let mut backoff = time::Duration::from_millis(100);
    for _ in 0..max_retries {
        match client.request(method, url, body).await {
            Ok(response) => return Ok((response, body)),
            Err(err) => {
                if err.is_timeout() || err.is_connection_refused() {
                    // Exponential backoff
                    tokio::time::sleep(backoff).await;
                    backoff *= 2;
                } else {
                    return Err(Box::new(err));
                }
            }
        }
    }
    Err(Box::new(anyhow!("Max retries reached")))
}

