#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTERFACES 16
#define MAX_CONFIG_ENTRIES 32
#define VLAN_ID_RANGE 4094

typedef struct {
    unsigned char mac[6];
    char ip_addr[17];
    char subnet_mask[17];
    int vlan_start;
    int vlan_end;
} nfapi_config_t;

nfapi_config_t config_entries[MAX_CONFIG_ENTRIES];

void load_config_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        printf("Error: Unable to open file\n");
        return;
    }

    int i = 0;
    while (i < MAX_INTERFACES && !feof(file)) {
        fscanf(file, "%02hhx:%02hhx:%02hhx:%02hhx:%02hhx:%02hhx %16s %16s %d-%d\n",
               config_entries[i].mac,
               config_entries[i].ip_addr,
               &config_entries[i].subnet_mask[0],
               &config_entries[i].vlan_start,
               &config_entries[i].vlan_end
               );
        i++;
    }
    fclose(file);
}

void validate_config_entry(int idx) {
    // Check for duplicate MAC addresses
    int j;
    for (j = 0; j < idx; j++) {
        if (memcmp(config_entries[j].mac, config_entries[idx].mac, 6) == 0) {
            printf("Error: Duplicate MAC address at entry %d\n", idx);
            return;
        }
    }

    // Check IP address and subnet mask
    in_addr_t ip_addr;
    in_addr_t subnet_mask;

    inet_pton(AF_INET, config_entries[idx].ip_addr, &ip_addr);
    inet_pton(AF_INET, config_entries[idx].subnet_mask, &subnet_mask);

    if (inet_cksum(&ip_addr) != 0 || inet_cksum(&subnet_mask) != 0) {
        printf("Error: Invalid IP address or subnet mask at entry %d\n", idx);
        return;
    }

    // Check VLAN ID range
    if (config_entries[idx].vlan_start < 1 || config_entries[idx].vlan_end > VLAN_ID_RANGE ||
        config_entries[idx].vlan_start > config_entries[idx].vlan_end) {
        printf("Error: Invalid VLAN ID range at entry %d\n", idx);
        return;
    }
}

void init_interfaces(void) {
    // Initialize interfaces
    int i;
    for (i = 0; i < MAX_INTERFACES; i++) {
        if (!config_entries[i].mac[0]) {
            break;
        }

        // Validate and initialize interface
        validate_config_entry(i);

        // Initialize NFAPI CONTROL PDU T structure
        NFAPI_CONTROL_PDU_T nfapi_pdu = {
            .mac_address = config_entries[i].mac,
            .ip_address = config_entries[i].ip_addr,
            .subnet_mask = config_entries[i].subnet_mask,
            .vlan_start = config_entries[i].vlan_start,
            .vlan_end = config_entries[i].vlan_end
        };

        // Initialize network interface using NFAPI_CONTROL_PDU_T structure
        if (nfapi_init(&nfapi_pdu) != 0) {
            printf("Error: Failed to initialize interface at entry %d\n", i);
        }
    }
}

void hotswap_config_entry(int idx, int action) {
    if (action == ADD_INTERFACE) {
        // Add new interface configuration
        if (idx >= MAX_INTERFACES) {
            printf("Error: Maximum number of interfaces reached\n");
            return;
        }

        config_entries[idx].mac[0] = '\0';  // Mark as unused

        // Validate and initialize new interface
        validate_config_entry(idx);

        // Initialize NFAPI CONTROL PDU T structure for new interface
        NFAPI_CONTROL_PDU_T nfapi_pdu = {
            .mac_address = config_entries[idx].mac,
            .ip_address = config_entries[idx].ip_addr,
            .subnet_mask = config_entries[idx].subnet_mask,
            .vlan_start = config_entries[idx].vlan_start,
            .vlan_end = config_entries[idx].vlan_end
        };

        // Initialize network interface using NFAPI_CONTROL_PDU_T structure for new interface
        if (nfapi_init(&nfapi_pdu) != 0) {
            printf("Error: Failed to initialize new interface at entry %d\n", idx);
        }
    } else if (action == REMOVE_INTERFACE) {
        // Remove existing interface configuration
        config_entries[idx].mac[0] = '\0';  // Mark as unused

        // Reinitialize interfaces
        init_interfaces();
    }
}

int main() {
    load_config_file("config.txt");  // Load configurations from file

    // Initialize network interfaces
    init_interfaces();

    return 0;
}
