typedef struct {
    long key;
    void *record;
} hash_table_t;

hash_table_t* init_hash_table(int size) {
    hash_table_t *table = (hash_table_t*)malloc(size * sizeof(hash_table_t));
    for (int i = 0; i < size; i++) {
        table[i].key = 0;
        table[i].record = NULL;
    }
    return table;
}

void insert_hash_table(hash_table_t *table, long key, void *record) {
    int index = hash(key) % table->size;
    if (table[index].key == 0) {
        table[index].key = key;
        table[index].record = record;
    } else {
        // resize the hash table
        int new_size = table->size * 2;
        hash_table_t *new_table = init_hash_table(new_size);
        for (int i = 0; i < table->size; i++) {
            if (table[i].key == key) {
                new_table[index].key = key;
                new_table[index].record = record;
                break;
            }
        }
        // free old hash table
        for (int i = 0; i < table->size; i++) {
            if (table[i].key != 0) {
                // free record
                free(table[i].record);
            }
        }
        free(table);
        table = new_table;
    }
}

