        std::cout << "Hash: ";
        for (int i = 0; i < EVP_MAX_MD_SIZE; i++) {
            std::cout << std::hex << (int)*((unsigned char*)hash + i);
        }
        std::cout << std::endl;
    }

    // Test the dynamicMemoryManagement function
