    // Get IPv4 and IPv6 addresses from the connection ID
    struct sockaddr_in4 ipv4_addr;
    struct sockaddr_in6 ipv6_addr;
    get_addresses(conn_id, &ipv4_addr, &ipv6_addr);

    // Perform TCP handshake for both IPv4 and IPv6 addresses
    int ipv4_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (ipv4_socket < 0) return NULL;

    int ipv6_socket = socket(AF_INET6, SOCK_STREAM, 0);
    if (ipv6_socket < 0) return NULL;

    connect_to_addr(ipv4_socket, &ipv4_addr);
    connect_to_addr(ipv6_socket, &ipv6_addr);

    // Monitor the connection and track metrics
    monitor_connection(conn_id);

