typedef struct Config {
    char* filename;
    ConfigSection* root_section;
    bool detailed_logging;
    FILE* log_file;
    uint32_t timeout_ms;
} Config;

Config config = {0};

void init_config(void) {
    config.filename = CONFIG_FILE;
    config.root_section = NULL;
    config.detailed_logging = false;
    config.log_file = NULL;
    config.timeout_ms = 1000; // 1 second
}

int parse_config_file(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (!file) return -1;

    ConfigSection* current_section = &config.root_section;
    while (fscanf(file, "# [%s]\n", config.filename) == 1) {
        current_section->name = strdup(config.filename);
        current_section++;
    }

    fclose(file);
    return 0;
}

void print_help_menu(void) {
    printf(HELP_MENU);
}

int main(int argc, char* argv[]) {
    init_config();

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-h")) {
            print_help_menu();
        } else if (!strcmp(argv[i], "-c")) {
            for (int j = i + 1; j < argc && *argv[j] != '-'; j++) {
                parse_config_file(argv[j]);
            }
        } else if (!strcmp(argv[i], "-d")) {
            config.detailed_logging = true;
        } else if (!strcmp(argv[i], "-o")) {
            config.log_file = fopen("config_log.txt", "w");
