#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <curl/curl.h>

#define MAX_URI_LENGTH 1024
#define MAX_RESPONSE_SIZE 1048576
#define MAX_REDIRECTS 5
#define MAX_RETRIES 4
#define RATE_LIMIT_WINDOW 900 // 15 minutes in seconds

typedef struct {
    char uri[MAX_URI_LENGTH];
    CURL* curl;
    CURLcode result;
    int retries;
    int redirects;
} HttpRequest;

HttpRequest* http_request_new(const char* uri) {
    HttpRequest* request = malloc(sizeof(HttpRequest));
    strcpy(request->uri, uri);
    request->curl = curl_easy_init();
    if (!request->curl) {
        return NULL;
    }
    request->result = CURLE_OK;
    request->retries = 0;
    request->redirects = 0;
    return request;
}

void http_request_free(HttpRequest* request) {
    if (request) {
        curl_easy_cleanup(request->curl);
        free(request);
    }
}

int http_request_setopt(HttpRequest* request, const char* option, const char* value) {
    CURLcode result = CURLE_OK;
    if (!request || !option || !value) {
        return -1; // invalid parameters
    }
    switch (strncasecmp(option, "uri", 3)) {
        case 0:
            strcpy(request->uri, value);
            break;
        default:
            result = curl_easy_setopt(request->curl, option, value);
            if (result != CURLE_OK) {
                return -1; // failed to set option
            }
    }
    return 0;
}

int http_request_perform(HttpRequest* request) {
    CURLcode result;
    int retries = 0;
    while ((result = curl_easy_perform(request->curl)) == CURLE_RETRY) {
        if (retries >= MAX_RETRIES) {
            break; // max retries exceeded
        }
        // exponential backoff
        sleep(retries * 2 + 1);
        request->retries++;
    }
    if (result != CURLE_OK) {
        return -1; // failed to perform request
    }
    request->result = result;
    return 0;
}

int http_request_get_response(HttpRequest* request, u_char** response, size_t* response_size) {
    *response = NULL;
    *response_size = 0;
    CURLcode result = CURLE_OK;
    if (request && request->curl) {
        char buffer[MAX_RESPONSE_SIZE];
        long length = 0;
        result = curl_easy_getinfo(request->curl, CURLINFO_EFFECTIVE_URL, &buffer);
        if (result == CURLE_OK) {
            size_t len = strlen(buffer);
            *response_size = len + 1; // include null terminator
            *response = malloc(*response_size);
            memcpy(*response, buffer, len);
            (*response)[len] = '\0';
        }
    }
    return result;
}

void http_request_log(HttpRequest* request) {
    // log the HTTP request and response here
}

int main() {
    HttpRequest* request = http_request_new("https://example.com");
    if (!request) {
        return -1; // failed to create request
    }
    int result = http_request_setopt(request, "uri", "https://example.com");
    if (result < 0) {
        http_request_free(request);
        return -1; // failed to set option
    }
    result = http_request_perform(request);
    if (result < 0) {
        http_request_log(request);
        http_request_free(request);
        return -1; // failed to perform request
    }
    u_char* response;
    size_t response_size;
    result = http_request_get_response(request, &response, &response_size);
    if (result != CURLE_OK) {
        http_request_log(request);
        free(response);
        http_request_free(request);
        return -1; // failed to get response
    }
    printf("%s\n", response);
    free(response);
    http_request_free(request);
    return 0;
}

