#define MAX_KEY_LENGTH 64
#define MAX_VALUE_LENGTH 256
#define CONFIG_FILE "config.ini"
#define DEFAULT_CONFIG_FILE "default_config.ini"

typedef struct {
    char key[MAX_KEY_LENGTH];
    char value[MAX_VALUE_LENGTH];
} ConfigItem;

typedef struct {
    int count;
    ConfigItem *items;
} ConfigFile;

ConfigFile config_file = {0};

void load_default_config() {
    FILE *file = fopen(DEFAULT_CONFIG_FILE, "r");
    if (file == NULL) {
        printf("Error: Unable to open default configuration file.\n");
        exit(1);
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        size_t pos = strcspn(line, "=");
        char key[MAX_KEY_LENGTH] = {0};
        strncpy(key, line, pos);
        key[pos] = '\0';

        pos = strlen(line) - 1;
        while (pos > 0 && line[pos] != ' ') {
            pos--;
        }
        pos++;
        size_t len = strlen(line + pos);
        char value[MAX_VALUE_LENGTH] = {0};
        strncpy(value, line + pos, len);
        value[len] = '\0';

        ConfigItem item;
        strcpy(item.key, key);
        strcpy(item.value, value);
        config_file.items = realloc(config_file.items, (config_file.count + 1) * sizeof(ConfigItem));
        config_file.items[config_file.count++] = item;
    }

    fclose(file);
}

void load_config(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error: Unable to open configuration file.\n");
        return;
    }

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        size_t pos = strcspn(line, "=");
