        strncpy(key, line, pos);
        key[pos] = '\0';

        pos = strlen(line) - 1;
        while (pos > 0 && line[pos] != ' ') {
            pos--;
        }
        pos++;
        size_t len = strlen(line + pos);
        char value[MAX_VALUE_LENGTH] = {0};
        strncpy(value, line + pos, len);
        value[len] = '\0';

        ConfigItem item;
        strcpy(item.key, key);
        strcpy(item.value, value);
        config_file.items = realloc(config_file.items, (config_file.count + 1) * sizeof(ConfigItem));
        config_file.items[config_file.count++] = item;
    }

    fclose(file);
}

void parse_command_line(int argc, char **argv) {
    for (int i = 1; i < argc; i++) {
        size_t pos = strcspn(argv[i], "=");
        char key[MAX_KEY_LENGTH] = {0};
        strncpy(key, argv[i], pos);
        key[pos] = '\0';

        pos = strlen(argv[i]) - 1;
        while (pos > 0 && argv[i][pos] != ' ') {
            pos--;
        }
        pos++;
        size_t len = strlen(argv[i] + pos);
        char value[MAX_VALUE_LENGTH] = {0};
        strncpy(value, argv[i] + pos, len);
        value[len] = '\0';

        ConfigItem item;
        strcpy(item.key, key);
        strcpy(item.value, value);
        config_file.items = realloc(config_file.items, (config_file.count + 1) * sizeof(ConfigItem));
        config_file.items[config_file.count++] = item;
    }
}

void save_config(char *filename) {
    FILE *file = fopen(filename, "w");
    if (file == NULL) {
        printf("Error: Unable to open configuration file.\n");
        return;
    }

    for (int i = 0; i < config_file.count; i++) {
        fprintf(file, "%s=%s\n", config_file.items[i].key, config_file.items[i].value);
    }

    fclose(file);
}

void validate_config() {
    for (int i = 0; i < config_file.count; i++) {
        // Validate key and value formats
        if (strlen(config_file.items[i].key) > MAX_KEY_LENGTH || strlen(config_file.items[i].value) > MAX_VALUE_LENGTH) {
            printf("Error: Configuration file contains invalid key or value.\n");
            exit(1);
        }
    }
}

int main(int argc, char **argv) {
    load_default_config();

    if (argc > 1) {
        parse_command_line(argc, argv);
    }

    save_config(CONFIG_FILE);

    validate_config();

    return 0;
}
