    log_manager->current_level = 0;
    return log_manager;
}

void insert_log(LOG_MANAGER *log_manager, LOG_ENTRY *entry) {
    // Resize the log array if necessary
    if (log_manager->log_count >= log_manager->max_logs) {
        log_manager->max_logs *= 2;
        log_manager->logs = realloc(log_manager->logs, log_manager->max_logs * sizeof(LOG_ENTRY));
    }
    // Insert the new log entry
    log_manager->logs[log_manager->log_count] = *entry;
    log_manager->log_count++;
}

int main() {
    LOG_MANAGER *log_manager = init_log_manager(MAX_LEVELS);
    // Use log_manager to manage logs and configuration
    return 0;
}
