#include <stdlib.h>
#include <string.h>
#include "logging_module.h"
#include "concurrency_control_library.h"

#define MAX_CELLS 1000
#define DEFAULT_MAX_TRANSMISSION_POWER 30
#define DEFAULT_REFERENCE_SIGNAL_POWER_LEVEL -20

typedef struct {
    uint32_t cell_identity;
    int8_t frequency_band;
    uint16_t time_alignment_timer;
    int16_t max_transmission_power;
    int16_t reference_signal_power_level;
} UTRAN_CELL;

void configure_utran_cells(int num_cells, UTRAN_CELL** cells) {
    // Initialize the dynamic array
    *cells = (URTAN_CELL**)malloc(num_cells * sizeof(URTAN_CELL*));
    if (*cells == NULL) {
        log_error("Memory allocation failed");
        return;
    }

    // Configure each cell instance with valid values and optional parameters
    for (int i = 0; i < num_cells; i++) {
        UTRAN_CELL* cell = &(*cells)[i];
        cell->cell_identity = i + 1;
        cell->frequency_band = (rand() % 2) * 10 - 5; // Randomly select a frequency band
        cell->time_alignment_timer = rand() % 256; // Randomly select a time alignment timer value
        if (i < num_cells / 2) {
            cell->max_transmission_power = DEFAULT_MAX_TRANSMISSION_POWER;
            cell->reference_signal_power_level = DEFAULT_REFERENCE_SIGNAL_POWER_LEVEL;
        } else {
            cell->max_transmission_power = rand() % 10 + 1; // Randomly select a maximum transmission power value
            cell->reference_signal_power_level = -rand() % 20; // Randomly select a reference signal power level value
        }
    }

    // Enforce the limit on the number of cells that can be configured
    if (num_cells > MAX_CELLS) {
        log_warning("Exceeding maximum allowed number of cells");
        for (int i = num_cells - 1; i >= MAX_CELLS; i--) {
            free(&(*cells)[i]);
        }
        *num_cells = MAX_CELLS;
    }

    // Provide a summary report on the configuration process
    log_info("Configured %d UTRAN cells successfully", *num_cells);
}
